window.QUIZ_BANKS=window.QUIZ_BANKS||{};window.QUIZ_BANKS["volume-3"]={"id": "volume-3", "version": 1, "questions": [{"n": 1, "page": 13, "stem": "Which single term best describes an increase in size produced by hyperplasia, hypertrophy and secretion of extracellular matrix?", "options": ["Growth", "Development", "Maturation", "Differentiation", "Remodelling"], "key": "A", "type": "sba", "explanation": "Growth is the anatomical increase in size; development is the physiological and behavioural progression towards maturity. Examiners use the distinction to test precision of language. (Companion Ch 4; Proffit Ch 2; Hbk 1.1)", "answerPage": 182, "block": "A"}, {"n": 2, "page": 13, "stem": "A 10-year-old girl attends for assessment. Which single measure is least useful in deciding when to begin functional appliance therapy?", "options": ["Cervical vertebral maturation stage", "Hand-wrist radiograph", "Chronological age", "Standing height velocity", "Tanner stage of sexual maturation"], "key": "C", "type": "sba", "explanation": "Chronological age correlates poorly with maturational status. Every clinically useful index of readiness is a maturational one. (Mosby ch. on growth; Hbk 1.2)", "answerPage": 182, "block": "A"}, {"n": 3, "page": 13, "stem": "At approximately what age does peak height velocity occur in girls?", "options": ["10 years", "8 years", "14 years", "16 years", "12 years"], "key": "E", "type": "sba", "explanation": "Peak height velocity occurs at approximately 12 years in girls and 14 years in boys, with wide individual variation. (Companion Ch 4; Hbk 1.3)", "answerPage": 182, "block": "A"}, {"n": 4, "page": 13, "stem": "A girl reports that menarche occurred 8 months ago. What does this tell you about her growth?", "options": ["The adolescent spurt has not yet begun", "Peak height velocity has already passed", "Peak height velocity is imminent", "Growth has entirely ceased", "Growth status cannot be inferred"], "key": "B", "type": "sba", "explanation": "Menarche follows peak height velocity by approximately one year, so a girl who has begun menstruating has largely passed the window for orthopaedic change. (Companion Ch 4; Hbk 1.3)", "answerPage": 182, "block": "A"}, {"n": 5, "page": 13, "stem": "A lateral cephalogram shows cervical vertebral maturation stage CS3. What is the correct interpretation?", "options": ["Peak height velocity is 2 years away", "Peak height velocity is 1 year away", "Peak height velocity passed 1 to 2 years ago", "Peak height velocity will occur during this year", "Growth is complete"], "key": "D", "type": "sba", "explanation": "CS3 (mean age 12.0 years) indicates the peak occurs within the current year. This is the window for growth modification. (Baccetti, Franchi and McNamara; Hbk 1.3)", "answerPage": 182, "block": "A"}, {"n": 6, "page": 14, "stem": "Which sequence correctly describes the order in which craniofacial dimensions complete their growth?", "options": ["Heights, then depths, then widths", "Depths, then widths, then heights", "Widths, then depths, then heights", "All three complete simultaneously", "Widths, then heights, then depths"], "key": "C", "type": "sba", "explanation": "Widths mature before depths, which mature before heights. This is why transverse problems are treated earliest. (Mosby ch. on growth; Proffit Ch 4; Hbk 1.5)", "answerPage": 182, "block": "A"}, {"n": 7, "page": 14, "stem": "Which statement about growth of the chin is correct?", "options": ["There is no distinct anteroposterior growth spurt of the chin", "There is a marked anteroposterior growth spurt of the chin at puberty", "The chin completes growth before the cranial base", "Chin growth is entirely determined by the nasal septum", "Chin prominence decreases throughout adolescence"], "key": "A", "type": "sba", "explanation": "A counter-intuitive but frequently examined point: there is no anteroposterior growth spurt of the chin. Apparent increases in chin projection are largely the result of vertical growth and rotation. (Mosby ch. on growth; Hbk 1.5)", "answerPage": 182, "block": "A"}, {"n": 8, "page": 14, "stem": "Which theory of growth control provides the intellectual basis for functional appliance therapy?", "options": ["Genetic theory of Brodie", "Sutural theory of Sicher", "Nasal septum theory of Scott", "Cybernetic theory of Petrovic", "Functional matrix theory of Moss"], "key": "E", "type": "sba", "explanation": "Moss proposed that bone grows in response to the soft tissue capsules and functional spaces it serves. Petrovic refined this into a servosystem model, but Moss is the theory usually named as the basis of functional appliances. (Companion Ch 4; Hbk 1.4)", "answerPage": 182, "block": "A"}, {"n": 9, "page": 14, "stem": "Which single statement about the condylar cartilage is correct?", "options": ["It is a primary growth centre comparable to an epiphyseal plate", "It ceases growing at 12 years in both sexes", "It is entirely genetically determined and cannot be modified", "It is a secondary, adaptive cartilage", "It grows by intramembranous ossification"], "key": "D", "type": "sba", "explanation": "The condyle is a secondary, adaptive cartilage responding to its functional environment. This is precisely why functional appliances can influence it at all, and why the influence is modest. (Companion Ch 4; Hbk 1.4)", "answerPage": 182, "block": "A"}, {"n": 10, "page": 14, "stem": "What is the correct distinction between a site and a centre of growth?", "options": ["A site is genetically controlled; a centre is not", "A site is a location where growth occurs; a centre is a location of independent, genetically controlled growth", "A centre is a location where growth occurs; a site is where it is controlled", "The terms are interchangeable", "A site refers to cartilage; a centre refers to bone"], "key": "B", "type": "sba", "explanation": "The distinction underlies the whole nasal septum versus sutures debate. Sutures are sites; whether they are centres was the substance of Sicher’s claim. (Companion Ch 4; Hbk 1.1)", "answerPage": 182, "block": "A"}, {"n": 11, "page": 14, "stem": "Which of the following is the best chairside proxy for the timing of the adolescent growth spurt in a boy?", "options": ["Chronological age", "Dental age from a panoramic radiograph", "Number of erupted permanent teeth", "Shoe size", "Standing height measured at successive visits"], "key": "E", "type": "sba", "explanation": "Serial height measurement gives height velocity, which is the direct measure. A single height is far less useful than a series. (Mosby ch. on growth; Hbk 1.2)", "answerPage": 182, "block": "A"}, {"n": 12, "page": 14, "stem": "Puberty is initiated by which single event?", "options": ["Increased adrenal androgen secretion", "Pulsatile release of gonadotrophin-releasing hormone from the hypothalamus", "Closure of the spheno-occipital synchondrosis", "A rise in circulating growth hormone alone", "Ossification of the sesamoid of the thumb"], "key": "B", "type": "sba", "explanation": "Puberty begins in the brain, with pulsatile GnRH release. The peripheral changes follow. (Proffit Ch 4; Hbk 1.3)", "answerPage": 182, "block": "A"}, {"n": 13, "page": 15, "stem": "Which statement best describes the cephalocaudal gradient of growth?", "options": ["Growth proceeds from the feet upwards", "Growth is uniform across all body segments", "The cranium and the mandible grow at identical rates", "Structures nearer the head mature earlier than those further from it", "Limb growth precedes cranial growth"], "key": "D", "type": "sba", "explanation": "The cephalocaudal gradient describes the earlier maturation of structures nearer the head, which is why the cranium is near adult size long before the mandible. (Proffit Ch 2; Hbk 1.1)", "answerPage": 182, "block": "A"}, {"n": 14, "page": 15, "stem": "At what mean age does cervical vertebral maturation stage CS4 occur, and what does it indicate?", "options": ["13.4 years; peak passed 1 to 2 years ago", "12.0 years; peak this year", "10.5 years; peak within 1 year", "9.7 years; peak 2 years away", "15.0 years; growth complete"], "key": "A", "type": "sba", "explanation": "CS4 has a mean age of 13.4 years and indicates that peak height velocity occurred 1 to 2 years previously. Growth modification is losing its power. (Baccetti, Franchi and McNamara; Hbk 1.3)", "answerPage": 182, "block": "A"}, {"n": 15, "page": 15, "stem": "Which single caveat should always accompany a statement about maturational staging?", "options": ["It is only valid in females", "It requires a CBCT", "None of the underlying principles is universally accepted", "It is more accurate than serial height measurement", "It predicts the amount of remaining growth precisely"], "key": "C", "type": "sba", "explanation": "Maturational indices tell you where in the curve the patient is, not how much growth remains, and none of the underlying principles is universally accepted. (Companion Ch 4; Hbk 1.3)", "answerPage": 183, "block": "A"}, {"n": 16, "page": 15, "stem": "Which is the correct definition of the pattern of growth?", "options": ["The absolute increase in size over time", "The timing of the adolescent spurt", "The variability of growth between individuals", "The proportional relationships between parts at a point in time, and their orderly change over time", "The rate of growth per unit time"], "key": "D", "type": "sba", "explanation": "Pattern refers to proportional relationships and their orderly change. Pattern, variability and timing are the three properties of growth. (Proffit Ch 2; Hbk 1.1)", "answerPage": 183, "block": "A"}, {"n": 17, "page": 15, "stem": "A juvenile growth spurt is typically observed at which age?", "options": ["3 to 4 years", "6 to 8 years", "10 to 11 years", "12 to 14 years", "It does not occur"], "key": "B", "type": "sba", "explanation": "A juvenile spurt occurs at about 6 to 8 years, followed by a prepubertal minimum and then the adolescent spurt. (Companion Ch 4; Hbk 1.3)", "answerPage": 183, "block": "A"}, {"n": 18, "page": 15, "stem": "Which statement about mandibular growth in Class III patients is correct?", "options": ["It ceases earlier than in Class I patients", "It follows the neural growth curve", "It is unaffected by sex", "It is complete by the time of menarche in both sexes", "It may continue into the twenties, particularly in males"], "key": "E", "type": "sba", "explanation": "Residual mandibular growth persists later in Class III patients and later in males, which is why surgery is deferred and confirmed by serial superimposition. (Companion Ch 13; Hbk 1.3)", "answerPage": 183, "block": "A"}, {"n": 19, "page": 15, "stem": "Which of the following growth curves best describes the growth of the cranial vault?", "options": ["Neural curve", "General somatic curve", "Lymphoid curve", "Genital curve", "Linear throughout life"], "key": "A", "type": "sba", "explanation": "The cranial vault follows the neural growth curve, being approximately 90 per cent complete by about age 5. This is why craniosynostosis presents early. (Proffit Ch 2; Hbk 2.2)", "answerPage": 183, "block": "A"}, {"n": 20, "page": 16, "stem": "Which single statement about adult craniofacial change is correct?", "options": ["Growth ceases entirely at 18 years", "Only the soft tissues change after 18 years", "Slow rotational growth continues throughout adult life in the individual’s original pattern", "Change occurs only in patients treated orthodontically", "The mandible resorbs uniformly after 25 years"], "key": "C", "type": "sba", "explanation": "Behrents demonstrated continued slow rotational growth throughout adult life, and the cumulative effect is described as surprisingly large. (Behrents 1985; Hbk 2.4)", "answerPage": 183, "block": "A"}, {"n": 21, "page": 16, "stem": "Dental age is most usefully assessed by which single method?", "options": ["Number of erupted teeth alone", "Stage of tooth formation on a radiograph", "Chronological age plus 6 months", "Hand-wrist radiograph", "Tanner staging"], "key": "B", "type": "sba", "explanation": "Stage of tooth formation, using Demirjian’s or Nolla’s stages, is more reliable than eruption alone, which is influenced by local factors. (Mosby ch. on growth; Hbk 1.2)", "answerPage": 183, "block": "A"}, {"n": 22, "page": 16, "stem": "Which statement about the spheno-occipital synchondrosis is correct?", "options": ["It is a suture and grows by apposition", "It is the principal site of mandibular growth", "It fuses at birth", "It grows endochondrally and fuses at approximately 13 to 15 years", "It fuses later in females than in males"], "key": "D", "type": "sba", "explanation": "The synchondroses of the cranial base grow endochondrally. The spheno-occipital synchondrosis fuses at about 13 to 15 years, earlier in girls. (Companion Ch 4; Hbk 2.2)", "answerPage": 183, "block": "A"}, {"n": 23, "page": 16, "stem": "Which is the most defensible position to state in an oral examination about the modifiability of mandibular growth?", "options": ["It can be modified within genetically determined limits, and the effect is modest and largely transient", "It can be modified without limit if treatment starts early enough", "It cannot be modified at all", "It can be modified only by surgery", "It can be modified only in females"], "key": "A", "type": "sba", "explanation": "This is the modern synthesis position, following Petrovic and supported by the randomised trial evidence on functional appliances. (Companion Ch 9; Hbk 1.4)", "answerPage": 183, "block": "A"}, {"n": 24, "page": 16, "stem": "Which single feature most reliably indicates that the adolescent growth spurt has been completed?", "options": ["A CS3 cervical vertebral maturation stage", "Eruption of the second permanent molars", "Cessation of increase in standing height on serial measurement", "Menarche in a girl", "Attaining the age of 16 years"], "key": "C", "type": "sba", "explanation": "Cessation of increase in serial standing height is the direct evidence. All the other options are indirect or unreliable. (Mosby ch. on growth; Hbk 1.2)", "answerPage": 183, "block": "A"}, {"n": 25, "page": 16, "stem": "Which of the following best describes the relationship between statural growth and mandibular growth?", "options": ["They are entirely independent", "Mandibular growth precedes statural growth by about 2 years", "Mandibular growth ceases at menarche", "Both cease at exactly the same time", "Statural growth slightly precedes mandibular growth, and mandibular growth continues after statural growth appears complete"], "key": "E", "type": "sba", "explanation": "Statural growth slightly precedes mandibular growth, and the mandible continues to grow after height appears to have stopped. This matters when timing surgery. (Companion Ch 4; Hbk 1.3)", "answerPage": 183, "block": "A"}, {"n": 26, "page": 17, "stem": "At which week of intrauterine development do the five facial processes appear around the stomodeum?", "options": ["Week 4", "Week 2", "Week 6", "Week 8", "Week 10"], "key": "A", "type": "sba", "explanation": "Five processes appear at week 4: the single frontonasal process and the paired maxillary and mandibular processes. (Companion Ch 3; Hbk 2.1)", "answerPage": 183, "block": "B"}, {"n": 27, "page": 17, "stem": "The upper lip is formed by fusion of which structures?", "options": ["Maxillary processes with the lateral nasal processes", "Frontonasal process with the mandibular processes", "Maxillary processes with the medial nasal processes", "The two palatine shelves", "Medial nasal processes with the lateral nasal processes"], "key": "C", "type": "sba", "explanation": "The upper lip is formed by fusion of the maxillary processes with the medial nasal processes, by week 8. Failure of this fusion produces cleft lip. (Companion Ch 3; Hbk 2.1)", "answerPage": 183, "block": "B"}, {"n": 28, "page": 17, "stem": "By which week is the human face complete?", "options": ["Week 4", "Week 6", "Week 12", "Week 10", "Week 8"], "key": "E", "type": "sba", "explanation": "The face is complete by week 8; the palate is complete by week 10. (Companion Ch 3; Hbk 2.1)", "answerPage": 183, "block": "B"}, {"n": 29, "page": 17, "stem": "Isolated cleft palate results from which single developmental failure?", "options": ["Failure of the maxillary process to fuse with the medial nasal process", "Failure of the palatine shelves to elevate or fuse, between weeks 6 and 10", "Failure of neural crest migration at week 3", "Failure of the mandibular processes to fuse in the midline", "Premature fusion of the incisive suture"], "key": "B", "type": "sba", "explanation": "Isolated cleft palate arises from failure of shelf elevation or fusion between weeks 6 and 10, a different failure at a different time from cleft lip. (Companion Ch 3 and Ch 16; Hbk 2.1)", "answerPage": 183, "block": "B"}, {"n": 30, "page": 17, "stem": "A newborn has an isolated cleft of the palate. What is the approximate probability that this is part of a recognised syndrome?", "options": ["10 per cent", "30 per cent", "70 per cent", "50 per cent", "90 per cent"], "key": "D", "type": "sba", "explanation": "Approximately 50 per cent of isolated cleft palates are syndromic, against approximately 30 per cent of cleft lip with or without cleft palate. (Companion Ch 16; Hbk 2.1)", "answerPage": 183, "block": "B"}, {"n": 31, "page": 17, "stem": "Which cell population forms practically all of the mesenchyme of the face?", "options": ["Mesodermal cells", "Endodermal cells", "Neural crest cells", "Trophoblastic cells", "Primordial germ cells"], "key": "C", "type": "sba", "explanation": "Neural crest cells form practically all of the facial mesenchyme, which is why disorders of neural crest migration produce craniofacial syndromes. (Proffit Ch 5; Hbk 2.1)", "answerPage": 183, "block": "B"}, {"n": 32, "page": 18, "stem": "What is the reported incidence of cleft lip with or without cleft palate?", "options": ["1 in 700", "1 in 250", "1 in 2000", "1 in 5000", "1 in 10000"], "key": "A", "type": "sba", "explanation": "Cleft lip with or without cleft palate occurs in approximately 1 in 700 births; isolated cleft palate in approximately 1 in 2000. (Companion Ch 16; Hbk 2.1 and 28.1)", "answerPage": 183, "block": "B"}, {"n": 33, "page": 18, "stem": "Which sex ratio applies to isolated cleft palate?", "options": ["Male 2 to 1", "Female 2 to 1", "Equal", "Male 4 to 1", "Female 4 to 1"], "key": "E", "type": "sba", "explanation": "Isolated cleft palate shows a female preponderance of approximately 4 to 1, the opposite of cleft lip with or without cleft palate, which is male 2 to 1. (Companion Ch 16; Hbk 2.1)", "answerPage": 183, "block": "B"}, {"n": 34, "page": 18, "stem": "By what mechanism does the cranial vault principally grow after birth?", "options": ["Endochondral ossification at synchondroses", "Displacement by the maxillary tuberosity", "Cartilaginous growth at the nasal septum", "Sutural apposition driven by the expanding brain, plus surface remodelling", "Interstitial growth within bone"], "key": "D", "type": "sba", "explanation": "The cranial vault grows by sutural apposition in response to the expanding brain, with surface remodelling. (Companion Ch 4; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 35, "page": 18, "stem": "The maxilla grows principally by which combination of mechanisms?", "options": ["Endochondral ossification only", "Displacement forwards and downwards by the surrounding sutures, plus surface remodelling", "Condylar growth plus surface remodelling", "Sutural growth only, with no remodelling", "Interstitial expansion"], "key": "B", "type": "sba", "explanation": "The maxilla is displaced downwards and forwards by growth at its sutures, with surface remodelling including resorption anteriorly and apposition at the tuberosity. (Companion Ch 4; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 36, "page": 18, "stem": "Which surface of the maxilla characteristically undergoes resorption during growth?", "options": ["The posterior surface of the tuberosity", "The orbital floor", "The palatal surface", "The zygomatic process", "The anterior surface"], "key": "E", "type": "sba", "explanation": "Resorption occurs on the anterior surface of the maxilla while apposition occurs posteriorly at the tuberosity, which is how arch length increases posteriorly. (Companion Ch 4; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 37, "page": 18, "stem": "Bjork’s implant studies demonstrated which single phenomenon?", "options": ["That the mandible does not grow after 14 years", "That the mandible rotates internally during growth, largely masked by surface remodelling", "That cephalometric growth prediction is accurate", "That the maxilla grows only by sutural apposition", "That the condyle is a primary growth centre"], "key": "B", "type": "sba", "explanation": "Bjork’s metallic implant studies revealed internal rotation of the jaws, largely masked by remodelling of the lower border. (Companion Ch 4; Hbk 2.3)", "answerPage": 184, "block": "B"}, {"n": 38, "page": 18, "stem": "Which equation correctly relates the three mandibular rotations?", "options": ["Total equals matrix minus intramatrix", "Intramatrix equals total plus matrix", "Matrix equals total plus intramatrix", "Total equals matrix plus intramatrix", "The three are independent"], "key": "D", "type": "sba", "explanation": "Total (true) rotation equals matrix (apparent) rotation plus intramatrix rotation, which is angular remodelling of the lower border. (Companion Ch 4; Hbk 2.3)", "answerPage": 184, "block": "B"}, {"n": 39, "page": 19, "stem": "A patient shows a forward-inclined condyle, a curved mandibular canal, a thick symphysis and a shallow antegonial notch. Which growth pattern do these signs suggest?", "options": ["Forward mandibular rotation", "Backward mandibular rotation", "No rotation", "Transverse maxillary deficiency", "Vertical maxillary excess"], "key": "A", "type": "sba", "explanation": "These are Bjork’s structural signs of forward (anterior) mandibular rotation, which is associated with a deep overbite and reduced lower face height. (Companion Ch 4; Hbk 2.3)", "answerPage": 184, "block": "B"}, {"n": 40, "page": 19, "stem": "Backward mandibular rotation is characteristically associated with which occlusal feature?", "options": ["Deep overbite", "Class III molar relationship", "Anterior open bite", "Bilateral crossbite", "Reduced overjet"], "key": "C", "type": "sba", "explanation": "Backward rotation increases anterior face height relative to posterior face height and is associated with anterior open bite. (Companion Ch 4; Hbk 2.3)", "answerPage": 184, "block": "B"}, {"n": 41, "page": 19, "stem": "Which single feature of a forward-rotating mandible explains late lower incisor crowding?", "options": ["Continued condylar growth", "Mesial drift of the first molars alone", "Increased intercanine width", "Progressive uprighting of the lower labial segment", "Loss of the leeway space"], "key": "D", "type": "sba", "explanation": "Forward mandibular rotation drives progressive uprighting of the lower labial segment, which is the principal factor in tertiary crowding. (Behrents; Solow; Hbk 2.3 and 19.4)", "answerPage": 184, "block": "B"}, {"n": 42, "page": 19, "stem": "Which is the principal site of postnatal mandibular growth?", "options": ["The symphysis", "The condyle, with extensive surface remodelling", "The coronoid process", "The alveolar process alone", "The mandibular canal"], "key": "B", "type": "sba", "explanation": "The condyle grows endochondrally, and the mandible additionally undergoes extensive surface remodelling with posterior remodelling of the ramus. (Companion Ch 4; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 43, "page": 19, "stem": "Which single anatomical structure carries the infraorbital nerve and forms part of the maxilla?", "options": ["The zygomatic arch", "The palatine shelf", "The pterygoid plates", "The nasal septum", "The roof of the maxillary sinus, which is the orbital floor"], "key": "E", "type": "sba", "explanation": "The roof of the maxillary sinus is the orbital floor, which carries the infraorbital nerve. (Standard anatomy; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 44, "page": 19, "stem": "Which statement about the cranial base angle is correct?", "options": ["An obtuse cranial base angle tends to position the glenoid fossa more posteriorly, contributing to an apparent Class II relationship", "It has no influence on the apparent jaw relationship", "It is fixed from birth", "It is measured between porion and orbitale", "It is unaffected by the spheno-occipital synchondrosis"], "key": "A", "type": "sba", "explanation": "An obtuse cranial base angle positions the glenoid fossa, and therefore the mandible, more posteriorly, contributing to a Class II relationship. (Companion Ch 4; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 45, "page": 19, "stem": "In cleft lip with or without cleft palate, what approximate proportion of cases are unilateral?", "options": ["20 per cent", "50 per cent", "80 per cent", "65 per cent", "95 per cent"], "key": "C", "type": "sba", "explanation": "Approximately 80 per cent are unilateral, and the left side is more commonly affected than the right. (Companion Ch 16; Hbk 2.1 and 28.1)", "answerPage": 184, "block": "B"}, {"n": 46, "page": 20, "stem": "Which single environmental exposure has the strongest evidence for reducing the risk of orofacial clefting?", "options": ["Vitamin D supplementation", "Folic acid supplementation", "Iron supplementation", "Avoidance of caffeine", "Zinc supplementation"], "key": "B", "type": "sba", "explanation": "Folic acid supplementation reduces the risk of orofacial clefting. Smoking, alcohol, anticonvulsants and retinoids increase it. (Companion Ch 16; Hbk 28.1)", "answerPage": 184, "block": "B"}, {"n": 47, "page": 20, "stem": "Which anticonvulsant drugs are associated with an increased risk of orofacial clefting?", "options": ["Carbamazepine and gabapentin", "Topiramate only", "Levetiracetam and lamotrigine alone", "Phenytoin and sodium valproate", "None are associated"], "key": "D", "type": "sba", "explanation": "Phenytoin and sodium valproate are the anticonvulsants classically associated with an increased risk of clefting. (Companion Ch 16; Hbk 28.1)", "answerPage": 184, "block": "B"}, {"n": 48, "page": 20, "stem": "Which statement about the palatine shelves is correct?", "options": ["They appear vertically either side of the tongue and later elevate", "They appear horizontally and then descend", "They form from the frontonasal process", "They fuse before the lip", "They fuse at week 4"], "key": "A", "type": "sba", "explanation": "The palatine shelves appear vertically either side of the tongue at week 6 and elevate above the tongue as the mandible grows forwards and the head extends. (Companion Ch 3; Hbk 2.1)", "answerPage": 184, "block": "B"}, {"n": 49, "page": 20, "stem": "Which of the following best describes the growth of the nasomaxillary complex relative to the anterior cranial base?", "options": ["Upwards and backwards", "Purely downwards", "Downwards and forwards", "Purely forwards", "It does not move relative to the cranial base"], "key": "C", "type": "sba", "explanation": "The nasomaxillary complex is displaced downwards and forwards relative to the anterior cranial base. (Companion Ch 4; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 50, "page": 20, "stem": "A soft tissue change commonly observed in adult life is which of the following?", "options": ["Increasing incisor show at rest", "Increasing upper lip vermilion display", "Thickening of the vermilion border", "Reduction in nasal projection", "Decreasing incisor show at rest, with lengthening of the nose and upper lip"], "key": "E", "type": "sba", "explanation": "With age the upper lip lengthens, the vermilion thins, the nose lengthens and incisor show at rest decreases. This is relevant to planning incisor display in adults. (Behrents; Hbk 2.4)", "answerPage": 184, "block": "B"}, {"n": 51, "page": 20, "stem": "Craniosynostosis presents early in life principally because of which fact?", "options": ["The cranial vault follows the neural growth curve and is approximately 90 per cent complete by age 5", "The mandible grows fastest in infancy", "The cranial base fuses at birth", "The sutures are the only sites of growth in the body", "Brain growth ceases at 2 years"], "key": "A", "type": "sba", "explanation": "Because cranial vault growth follows the neural curve and is largely complete by age 5, premature sutural fusion produces obvious deformity early. (Proffit Ch 2; Hbk 2.2)", "answerPage": 184, "block": "B"}, {"n": 52, "page": 20, "stem": "Which single statement about the nasal septum theory of Scott is correct?", "options": ["It proposed that sutures are the primary determinants of facial growth", "It proposed that soft tissue function determines bone growth", "It proposed that cartilage is the primary determinant and that sutures respond passively", "It proposed that growth is entirely genetically predetermined", "It proposed a cybernetic feedback model"], "key": "C", "type": "sba", "explanation": "Scott proposed cartilage, and particularly the nasal septum, as the primary determinant, with sutures responding passively to displacement. (Companion Ch 4; Hbk 1.4)", "answerPage": 184, "block": "B"}, {"n": 53, "page": 21, "stem": "The functional matrix theory would predict which of the following?", "options": ["That removing a functional matrix has no effect on the associated bone", "That sutures are growth centres", "That growth is entirely determined at conception", "That the condyle drives all mandibular growth", "That bone growth follows the growth of the soft tissue capsules and functional spaces it serves"], "key": "E", "type": "sba", "explanation": "Moss proposed that bone grows in response to its functional matrix. This underpins both functional appliance therapy and the airway hypothesis of facial form. (Companion Ch 4; Hbk 1.4)", "answerPage": 184, "block": "B"}, {"n": 54, "page": 21, "stem": "Which statement about the sex ratio and syndromic proportion of clefting is the best examination answer?", "options": ["The two cleft types share the same sex ratio because they are the same condition", "The opposite sex ratios indicate different developmental failures occurring at different times", "Sex ratio is not a useful discriminator", "Both types are equally likely to be syndromic", "Isolated cleft palate is more common than cleft lip with or without palate"], "key": "B", "type": "sba", "explanation": "The opposite sex ratios and different syndromic proportions are the clearest evidence that these are distinct developmental failures at different times. (Companion Ch 16; Hbk 2.1)", "answerPage": 185, "block": "B"}, {"n": 55, "page": 21, "stem": "A 3-year-old is noted to have severe midface hypoplasia, exophthalmos and syndactyly of the hands and feet. Which single diagnosis is most likely?", "options": ["Crouzon syndrome", "Pierre Robin sequence", "Treacher Collins syndrome", "Apert syndrome", "Cleidocranial dysplasia"], "key": "D", "type": "sba", "explanation": "Syndactyly distinguishes Apert from Crouzon; both involve FGFR2 mutations and craniosynostosis with midface hypoplasia. (Companion Ch 16; Hbk 28.4)", "answerPage": 185, "block": "B"}, {"n": 56, "page": 22, "stem": "What is the approximate incisor liability in the maxillary arch?", "options": ["3 mm", "5 mm", "7 mm", "10 mm", "12 mm"], "key": "C", "type": "sba", "explanation": "Incisor liability is approximately 7 mm in the maxilla and 5 mm in the mandible. Note that the larger liability is maxillary. (Companion Ch 5; Hbk 3.1)", "answerPage": 185, "block": "C"}, {"n": 57, "page": 22, "stem": "What is the approximate leeway space per quadrant in the mandibular arch?", "options": ["2.5 mm", "1.5 mm", "0.5 mm", "4.0 mm", "5.0 mm"], "key": "A", "type": "sba", "explanation": "Leeway space is approximately 2.5 mm per quadrant in the mandible and 1.5 mm in the maxilla. Note that the larger leeway is mandibular. (Companion Ch 5; Hbk 3.1)", "answerPage": 185, "block": "C"}, {"n": 58, "page": 22, "stem": "Which statement about primate spaces is correct?", "options": ["They lie distal to the maxillary canine and mesial to the mandibular canine", "They are pathological", "They are present only in the permanent dentition", "They develop at 6 years of age", "They lie mesial to the maxillary canine and distal to the mandibular canine"], "key": "E", "type": "sba", "explanation": "Primate spaces lie mesial to the maxillary canine and distal to the mandibular canine, and are present from eruption of the primary dentition. (Companion Ch 5; Hbk 3.1)", "answerPage": 185, "block": "C"}, {"n": 59, "page": 22, "stem": "A 4-year-old has no spacing anywhere in the primary dentition. What is the most appropriate interpretation?", "options": ["This is normal and reassuring", "This indicates macrodontia of the primary teeth", "This indicates hypodontia", "This predicts crowding in the permanent dentition", "This requires immediate intervention"], "key": "D", "type": "sba", "explanation": "Developmental spacing in the primary dentition is normal and necessary. Its absence predicts crowding of the permanent dentition. (Companion Ch 5; Hbk 3.1)", "answerPage": 185, "block": "C"}, {"n": 60, "page": 22, "stem": "A tooth typically erupts when what proportion of its root is formed?", "options": ["One quarter", "Two thirds to three quarters", "One half", "The root is fully formed", "The root has begun to resorb"], "key": "B", "type": "sba", "explanation": "Eruption occurs when approximately two thirds to three quarters of the root is formed, and continues until occlusal contact. (Companion Ch 5; Hbk 3.2)", "answerPage": 185, "block": "C"}, {"n": 61, "page": 22, "stem": "In the mandibular arch, which tooth is most commonly left crowded or displaced because of the eruption sequence?", "options": ["Canine", "First premolar", "Lateral incisor", "First molar", "Second premolar"], "key": "E", "type": "sba", "explanation": "In the mandible the sequence is canine, then first premolar, then second premolar, so the second premolar is the tooth left short of space. (Companion Ch 5; Hbk 3.2)", "answerPage": 185, "block": "C"}, {"n": 62, "page": 23, "stem": "In the maxillary arch, which tooth is most commonly left crowded or displaced because of the eruption sequence?", "options": ["Central incisor", "Canine", "Lateral incisor", "First premolar", "Second molar"], "key": "B", "type": "sba", "explanation": "In the maxilla the sequence is first premolar, second premolar, then canine, so the canine is the tooth left short of space. The last tooth to erupt in each arch is the one that ends up crowded. (Companion Ch 5; Hbk 3.2)", "answerPage": 185, "block": "C"}, {"n": 63, "page": 23, "stem": "A distal step terminal plane in the primary dentition most commonly develops into which molar relationship?", "options": ["Class I", "It self-corrects to Class I in most cases", "Class III", "Class II", "It cannot be predicted"], "key": "D", "type": "sba", "explanation": "A distal step becomes a Class II molar relationship and never self-corrects. A mesial step becomes Class I; a flush terminal plane may go either way. (Companion Ch 5; Hbk 3.2)", "answerPage": 185, "block": "C"}, {"n": 64, "page": 23, "stem": "Transient crowding of the lower permanent incisors shortly after their eruption is best managed by which single approach?", "options": ["Reassurance and review", "Extraction of the primary canines", "Immediate lower arch expansion", "Extraction of a lower incisor", "Fitting a lower lingual arch"], "key": "A", "type": "sba", "explanation": "Space for the mandibular incisors is negative for approximately two years after eruption. Transient early crowding is normal and self-correcting. (Proffit Ch 3; Hbk 3.1)", "answerPage": 185, "block": "C"}, {"n": 65, "page": 23, "stem": "What is the approximate prevalence of hypodontia, excluding third molars?", "options": ["1 per cent", "3 per cent", "6.4 per cent", "12 per cent", "20 per cent"], "key": "C", "type": "sba", "explanation": "Hypodontia excluding third molars affects approximately 6.4 per cent. Third molar agenesis occurs in up to 30 per cent. (Companion Ch 5 and Ch 12; Hbk 3.3)", "answerPage": 185, "block": "C"}, {"n": 66, "page": 23, "stem": "Which tooth is most commonly congenitally absent, excluding third molars?", "options": ["Maxillary lateral incisor", "Mandibular central incisor", "Maxillary second premolar", "Mandibular second premolar", "Maxillary canine"], "key": "D", "type": "sba", "explanation": "The mandibular second premolar is the most commonly absent, followed by the maxillary lateral incisor and the maxillary second premolar. (Companion Ch 5; Hbk 3.3)", "answerPage": 185, "block": "C"}, {"n": 67, "page": 23, "stem": "What is the approximate prevalence of supernumerary teeth in the permanent dentition?", "options": ["0.1 per cent", "2 per cent", "10 per cent", "15 per cent", "25 per cent"], "key": "B", "type": "sba", "explanation": "Supernumerary teeth affect approximately 2 per cent of the permanent dentition, with figures of up to 4 per cent quoted overall. About 90 per cent are maxillary. (Companion Ch 12; Hbk 3.3)", "answerPage": 185, "block": "C"}, {"n": 68, "page": 23, "stem": "Which type of supernumerary tooth most typically prevents eruption of a permanent incisor?", "options": ["Conical", "Mesiodens of conical form", "Supplemental", "Odontome", "Tuberculate"], "key": "E", "type": "sba", "explanation": "Tuberculate supernumeraries typically prevent eruption; conical supernumeraries more often cause displacement or a diastema. (Companion Ch 12; Hbk 3.3)", "answerPage": 185, "block": "C"}, {"n": 69, "page": 24, "stem": "An 8-year-old has an unerupted maxillary central incisor with a tuberculate supernumerary above it. What is the most appropriate first step after confirming the diagnosis?", "options": ["Remove the supernumerary and create or maintain space, then observe for eruption", "Extract the permanent incisor", "Expose and bond the incisor immediately", "Await spontaneous eruption for 3 years", "Fit a removable partial denture"], "key": "A", "type": "sba", "explanation": "Removal of the obstruction with space creation or maintenance, then observation for spontaneous eruption, is the standard sequence. Expose and bond if there is no eruption within about 12 months. (Companion Ch 12; Hbk 20.2)", "answerPage": 185, "block": "C"}, {"n": 70, "page": 24, "stem": "An ectopic maxillary first permanent molar is resorbing the distal aspect of the second primary molar in a 7-year-old. Which statement is most accurate?", "options": ["It will never resolve spontaneously", "The permanent molar must be extracted", "It may reverse spontaneously up to approximately 8 years of age", "The primary molar must be extracted immediately", "A CBCT is mandatory"], "key": "C", "type": "sba", "explanation": "Spontaneous disimpaction may occur up to approximately 8 years. Beyond that, a separator, brass wire or distalising spring is used. (Companion Ch 12; Hbk 3.3 and 20.2)", "answerPage": 185, "block": "C"}, {"n": 71, "page": 24, "stem": "What is the approximate prevalence of tooth transposition?", "options": ["0.03 per cent", "0.3 per cent", "3 per cent", "8 per cent", "15 per cent"], "key": "B", "type": "sba", "explanation": "Transposition affects approximately 0.3 per cent. True transposition involves crowns and roots; pseudo-transposition involves crowns only. (Proffit Ch 12; Hbk 3.3)", "answerPage": 185, "block": "C"}, {"n": 72, "page": 24, "stem": "Which transposition is the most common?", "options": ["Maxillary central and lateral incisor", "Maxillary canine and lateral incisor", "Mandibular canine and lateral incisor", "Maxillary canine and first premolar", "Mandibular first and second premolar"], "key": "D", "type": "sba", "explanation": "Maxillary canine to first premolar transposition is the most frequently reported. (Companion Ch 12; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 73, "page": 24, "stem": "Molar incisor hypomineralisation has an approximate prevalence of which value?", "options": ["15 per cent", "5 per cent", "1 per cent", "30 per cent", "50 per cent"], "key": "A", "type": "sba", "explanation": "MIH affects approximately 15 per cent of children and frequently changes the extraction calculus, since a compromised first permanent molar may become the planned extraction. (Companion Ch 12; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 74, "page": 24, "stem": "A first permanent molar of poor prognosis is to be extracted to allow the second permanent molar to erupt into its place. What is the ideal radiographic timing?", "options": ["Before the second molar crown is complete", "After the second molar has fully erupted", "When the bifurcation of the second permanent molar is just calcifying, at about 8 to 10 years of dental age", "At 6 years of age", "When the third molar has erupted"], "key": "C", "type": "sba", "explanation": "Calcification of the second permanent molar bifurcation, at approximately 8 to 10 years of dental age, is the classical timing. (Companion Ch 12; Hbk 3.4)", "answerPage": 186, "block": "C"}, {"n": 75, "page": 25, "stem": "Spontaneous space closure after first permanent molar extraction is generally better in which arch?", "options": ["The maxilla", "It depends only on age", "Both are equal", "Neither closes spontaneously", "The mandible"], "key": "E", "type": "sba", "explanation": "Spontaneous closure is better in the mandible in the sense that timing is critical there; the maxillary second molar drifts mesially readily at almost any age, whereas the mandibular one does not, which is why timing matters most in the lower arch. (Companion Ch 12; Hbk 3.4)", "answerPage": 186, "block": "C"}, {"n": 76, "page": 25, "stem": "Which extraction is most likely to be indicated to prevent over-eruption of an opposing tooth?", "options": ["A compensating extraction", "A balancing extraction", "A serial extraction", "A therapeutic extraction of a third molar", "An enforced extraction"], "key": "A", "type": "sba", "explanation": "A compensating extraction is the removal of the opposing tooth in the same quadrant, considered to preserve the buccal occlusion and prevent over-eruption. (Companion Ch 12; Hbk 13.5)", "answerPage": 186, "block": "C"}, {"n": 77, "page": 25, "stem": "A balancing extraction is principally performed to prevent which single problem?", "options": ["Over-eruption", "Root resorption", "Centre line shift", "Ankylosis", "Impaction of the second molar"], "key": "C", "type": "sba", "explanation": "A balancing extraction is the removal of the contralateral tooth in the same arch to prevent a centre line shift, and is most relevant for canines. (Companion Ch 12; Hbk 13.5)", "answerPage": 186, "block": "C"}, {"n": 78, "page": 25, "stem": "An infra-occluded primary molar with a permanent successor present and eruption obstructed should be managed how?", "options": ["Left indefinitely", "Ankylosed deliberately", "Restored with a stainless steel crown", "Built up with composite", "Extracted"], "key": "E", "type": "sba", "explanation": "Where the successor is present and eruption is obstructed, or infra-occlusion is severe, extraction is indicated. Otherwise monitor. (Companion Ch 12; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 79, "page": 25, "stem": "What is the approximate prevalence of infra-occlusion of primary molars?", "options": ["Under 1 per cent", "Up to 9 per cent", "20 per cent", "35 per cent", "50 per cent"], "key": "B", "type": "sba", "explanation": "Infra-occlusion affects up to approximately 9 per cent of primary molars. (Companion Ch 12; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 80, "page": 25, "stem": "Finding a peg-shaped maxillary lateral incisor should prompt which single action?", "options": ["Immediate restoration", "A CBCT of the whole dentition", "Extraction", "A search for other associated dental anomalies, including palatally displaced canines and hypodontia", "Referral for genetic testing"], "key": "D", "type": "sba", "explanation": "Dental anomalies co-occur far more often than chance, reflecting a shared genetic field effect. One anomaly is a reason to look for the others. (Companion Ch 5; Cobourne cases; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 81, "page": 25, "stem": "Which best describes gemination?", "options": ["Fusion of two separate tooth germs", "Union of two teeth by cementum only", "Incomplete division of a single tooth germ", "Excess cementum deposition", "An extra cusp on a molar"], "key": "C", "type": "sba", "explanation": "Gemination is incomplete division of a single tooth germ; fusion is union of two separate germs. Concrescence is union by cementum only. (Companion Ch 5; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 82, "page": 26, "stem": "What is the approximate prevalence of a double tooth in the permanent dentition?", "options": ["0.5 per cent", "0.05 per cent", "5 per cent", "10 per cent", "20 per cent"], "key": "A", "type": "sba", "explanation": "Double teeth affect approximately 0.5 per cent of the permanent dentition and rather more of the primary dentition. (Companion Ch 5; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 83, "page": 26, "stem": "Which of the following describes the increase in intercanine width that normally occurs during the mixed dentition?", "options": ["Increase occurs only in the maxilla", "Approximately 10 mm in each arch", "No increase occurs", "Approximately 1 mm in each arch", "Approximately 3 mm in the mandible and 4.5 mm in the maxilla"], "key": "E", "type": "sba", "explanation": "Intercanine width increases by approximately 3 mm in the mandible and 4.5 mm in the maxilla, which is one of the ways the incisor liability is met. (Companion Ch 5; Hbk 3.1)", "answerPage": 186, "block": "C"}, {"n": 84, "page": 26, "stem": "Which single statement about leeway space is correct?", "options": ["It is a deficit that must be met", "It is present only if the primary dentition is spaced", "It is larger in the maxilla", "It is an excess that can be used, and it is larger in the mandible", "It is created by extraction of the primary canines"], "key": "D", "type": "sba", "explanation": "Leeway space is the excess of the primary canine and molar widths over their successors. It is larger in the mandible at approximately 2.5 mm per quadrant. (Companion Ch 5; Hbk 3.1)", "answerPage": 186, "block": "C"}, {"n": 85, "page": 26, "stem": "Preservation of the leeway space to relieve mild lower arch crowding is best achieved with which appliance?", "options": ["A quadhelix", "A lower lingual arch", "A twin block", "A Nance button", "A transpalatal arch"], "key": "B", "type": "sba", "explanation": "A lower lingual arch preserves the leeway space by preventing mesial drift of the first permanent molars. It has good evidence as an interceptive measure. (Companion Ch 12; Hbk 20.2)", "answerPage": 186, "block": "C"}, {"n": 86, "page": 26, "stem": "Oligodontia is conventionally defined as the absence of how many teeth, excluding third molars?", "options": ["Two or more", "Four or more", "All permanent teeth", "Ten or more", "Six or more"], "key": "E", "type": "sba", "explanation": "Oligodontia is conventionally the absence of six or more teeth excluding third molars, and is frequently syndromic. (Companion Ch 5; Hbk 3.3)", "answerPage": 186, "block": "C"}, {"n": 87, "page": 26, "stem": "Ectodermal dysplasia characteristically produces which combination?", "options": ["Multiple supernumerary teeth and delayed eruption", "Hypodontia or anodontia with conical teeth, sparse hair and hypohidrosis", "Absent clavicles and delayed fontanelle closure", "Downward-sloping palpebral fissures and malar hypoplasia", "Macroglossia and midface hypoplasia"], "key": "B", "type": "sba", "explanation": "Ectodermal dysplasia produces hypodontia or anodontia, conical teeth, sparse hair and reduced sweating. (Companion Ch 16; Hbk 28.4)", "answerPage": 186, "block": "C"}, {"n": 88, "page": 26, "stem": "Cleidocranial dysplasia is caused by a mutation in which gene?", "options": ["FGFR2", "TCOF1", "PTH1R", "RUNX2", "MSX1"], "key": "D", "type": "sba", "explanation": "Cleidocranial dysplasia results from RUNX2 mutation, producing absent or hypoplastic clavicles, delayed fontanelle closure, multiple supernumeraries and failure of eruption. (Companion Ch 16; Hbk 28.4)", "answerPage": 186, "block": "C"}, {"n": 89, "page": 27, "stem": "Primary failure of eruption is associated with a loss-of-function mutation in which gene?", "options": ["PTH1R", "RUNX2", "FGFR2", "TCOF1", "PAX9"], "key": "A", "type": "sba", "explanation": "Primary failure of eruption is caused by a loss-of-function mutation in PTH1R. Affected teeth do not respond to orthodontic traction, and attempting it causes ankylosis. (Decker 2008; Hbk 4.8)", "answerPage": 186, "block": "C"}, {"n": 90, "page": 27, "stem": "Which statement about the dental follicle is correct?", "options": ["It is not required for eruption", "It becomes the periodontal ligament only", "It coordinates the osteoclastic resorption that forms the eruption pathway", "It is removed at the bell stage", "It determines crown morphology"], "key": "C", "type": "sba", "explanation": "The follicle is essential: removing it prevents eruption, whereas removing the tooth and leaving the follicle still allows a pathway to form. (Companion Ch 5; Hbk 4.8)", "answerPage": 186, "block": "C"}, {"n": 91, "page": 27, "stem": "At approximately what age do the first permanent molars erupt?", "options": ["4 years", "10 years", "8 years", "6 years", "12 years"], "key": "D", "type": "sba", "explanation": "The first permanent molars erupt at approximately 6 years, marking the start of the mixed dentition. (Companion Ch 5; Hbk 3.2)", "answerPage": 187, "block": "C"}, {"n": 92, "page": 27, "stem": "The primary dentition is normally complete by which age?", "options": ["18 months", "3 years", "2 years", "4 years", "5 years"], "key": "B", "type": "sba", "explanation": "The primary dentition erupts between about 6 months and 2.5 years and is complete by approximately 3 years. (Companion Ch 5; Hbk 3.2)", "answerPage": 187, "block": "C"}, {"n": 93, "page": 27, "stem": "What proportion of children show a flush terminal plane in the primary dentition?", "options": ["Under 20 per cent", "Approximately 30 per cent", "It is never seen", "Over 90 per cent", "Approximately 60 to 75 per cent"], "key": "E", "type": "sba", "explanation": "A flush terminal plane is seen in approximately 60 to 75 per cent of children and may correct to Class I using leeway space or remain end to end. (Companion Ch 5; Hbk 3.2)", "answerPage": 187, "block": "C"}, {"n": 94, "page": 27, "stem": "A megadont maxillary central incisor in an otherwise Class I dentition creates which principal problem?", "options": ["A tooth-size discrepancy detectable on Bolton analysis", "Anchorage loss", "Root resorption", "Ankylosis", "Delayed eruption of the canine"], "key": "A", "type": "sba", "explanation": "Megadontia produces a tooth-size discrepancy, which is quantified by the Bolton analysis and usually managed by interproximal reduction or restorative addition. (Companion Ch 5; Hbk 11.1)", "answerPage": 187, "block": "C"}, {"n": 95, "page": 27, "stem": "Which single number pair should be quoted for the Bolton analysis?", "options": ["Anterior 85 per cent and overall 95 per cent", "Anterior 91.3 per cent and overall 77.2 per cent", "Anterior 77.2 per cent and overall 91.3 per cent", "Anterior 70 per cent and overall 80 per cent", "Anterior 65 per cent and overall 88 per cent"], "key": "C", "type": "sba", "explanation": "The Bolton anterior ratio is 77.2 per cent and the overall ratio 91.3 per cent. A ratio above the norm indicates mandibular excess. (Companion Ch 7; Hbk 11.1)", "answerPage": 187, "block": "C"}, {"n": 96, "page": 29, "stem": "Which single observation is the cleanest evidence that orthodontic tooth movement is mediated by the periodontal ligament rather than by bone alone?", "options": ["Teeth move faster in younger patients", "Neither an ankylosed tooth nor an osseointegrated implant moves under orthodontic force", "Root resorption occurs during treatment", "Movement is faster in the maxilla", "Hyalinisation occurs at low force levels"], "key": "B", "type": "sba", "explanation": "An intact periodontal ligament is an absolute prerequisite. Ankylosed teeth and implants have no ligament and do not move, which localises the response to the ligament. (Companion Ch 6; Hbk 4.1)", "answerPage": 187, "block": "D"}, {"n": 97, "page": 29, "stem": "Which two workers independently founded the pressure-tension theory?", "options": ["Reitan and Storey", "Baumrind and Frantz", "Bjork and Skieller", "Sandstedt and Oppenheim", "Ericson and Kurol"], "key": "D", "type": "sba", "explanation": "Carl Sandstedt and Albin Oppenheim independently produced the light-microscopy studies that founded the pressure-tension theory at the turn of the twentieth century. (Companion Ch 6; Hbk 4.1)", "answerPage": 187, "block": "D"}, {"n": 98, "page": 29, "stem": "What is the approximate average width of the periodontal ligament?", "options": ["0.2 mm", "0.02 mm", "0.5 mm", "1.0 mm", "2.0 mm"], "key": "A", "type": "sba", "explanation": "The periodontal ligament is approximately 0.2 mm wide on average, and is thinnest around the middle third of the root. (Companion Ch 6; Hbk 4.2)", "answerPage": 187, "block": "D"}, {"n": 99, "page": 29, "stem": "Osteocytes constitute approximately what proportion of bone cells?", "options": ["10 to 15 per cent", "30 to 40 per cent", "85 to 90 per cent", "50 to 60 per cent", "Under 5 per cent"], "key": "C", "type": "sba", "explanation": "Osteocytes make up 85 to 90 per cent of bone cells and are the principal mechanosensors. (Companion Ch 6; Hbk 4.2)", "answerPage": 187, "block": "D"}, {"n": 100, "page": 29, "stem": "Which molecule secreted by osteocytes inhibits osteoblast differentiation and canonical Wnt signalling?", "options": ["RANKL", "Osteoprotegerin", "Interleukin 1 beta", "Cathepsin K", "Sclerostin"], "key": "E", "type": "sba", "explanation": "Sclerostin acts as a brake against excess bone formation. It is a refinement most candidates miss. (Companion Ch 6; Hbk 4.2)", "answerPage": 187, "block": "D"}, {"n": 101, "page": 30, "stem": "Which statement about RANKL and osteoprotegerin during orthodontic tooth movement is correct?", "options": ["RANKL is raised on the compression side and OPG on the tension side", "RANKL is raised on the tension side and OPG on the compression side", "Both are raised equally on both sides", "Neither is involved in orthodontic tooth movement", "OPG stimulates osteoclast differentiation directly"], "key": "A", "type": "sba", "explanation": "RANKL rises under compression and drives osteoclastic resorption; OPG, a soluble decoy receptor, rises under tension and opposes it. Reversing this is the single commonest slip in this topic. (Companion Ch 6; Hbk 4.4)", "answerPage": 187, "block": "D"}, {"n": 102, "page": 30, "stem": "At approximately what force level does hyalinisation occur?", "options": ["It occurs only above 500 g", "It occurs only above 150 g", "It occurs even at 30 g", "It never occurs with light forces", "It occurs only with bodily movement"], "key": "C", "type": "sba", "explanation": "Reitan showed in 1967 that hyalinisation occurs even at 30 g, and that it occurs more with tipping than with bodily movement. (Reitan 1967; Hbk 4.3)", "answerPage": 187, "block": "D"}, {"n": 103, "page": 30, "stem": "What is the approximate duration of the lag phase of orthodontic tooth movement?", "options": ["2 days", "7 days", "6 months", "3 months", "20 to 30 days"], "key": "E", "type": "sba", "explanation": "The lag phase lasts 20 to 30 days while hyalinised tissue is removed by undermining resorption. (Companion Ch 6; Hbk 4.3)", "answerPage": 187, "block": "D"}, {"n": 104, "page": 30, "stem": "Undermining resorption differs from frontal resorption in which respect?", "options": ["It proceeds directly from the periodontal ligament surface", "It proceeds from adjacent marrow spaces because osteoclasts cannot resorb beneath a hyalinised zone", "It occurs only on the tension side", "It occurs only in adults", "It is faster than frontal resorption"], "key": "B", "type": "sba", "explanation": "Osteoclasts cannot act beneath the cell-free hyalinised zone, so resorption proceeds from the adjacent marrow spaces. It is slower than frontal resorption. (Companion Ch 6; Hbk 4.3)", "answerPage": 187, "block": "D"}, {"n": 105, "page": 30, "stem": "What is the approximate normal rate of orthodontic tooth movement?", "options": ["0.1 mm per month", "1 mm per week", "3 mm per month", "1 mm per month", "5 mm per month"], "key": "D", "type": "sba", "explanation": "Approximately 1 mm per month, faster in the maxilla and in younger patients. (Companion Ch 6; Hbk 4.3)", "answerPage": 187, "block": "D"}, {"n": 106, "page": 30, "stem": "Which force range is currently considered optimal for bodily tooth movement?", "options": ["10 to 20 cN", "150 to 200 cN", "50 to 100 cN", "250 to 400 cN", "Over 500 cN"], "key": "C", "type": "sba", "explanation": "Theodorou and colleagues concluded that 50 to 100 cN is optimal for bodily movement, with similar rates achieved across 50 to 250 cN. (Theodorou 2019; Hbk 4.6)", "answerPage": 187, "block": "D"}, {"n": 107, "page": 30, "stem": "Which single statement best represents the examinable position on optimal force?", "options": ["No universal optimal force exists, because of large inter-individual variation and differing loaded root surface areas", "An optimal force of 150 g has been established for all movements", "Heavier forces always move teeth faster", "Force magnitude is irrelevant", "Optimal force is determined by bracket slot size"], "key": "A", "type": "sba", "explanation": "The examinable position is that no universal optimum exists. What matters more than absolute force is the differential stress generated. (Ren 2003, 2004; Hbk 4.6)", "answerPage": 187, "block": "D"}, {"n": 108, "page": 31, "stem": "Which force is appropriate for intrusion of a four-incisor segment?", "options": ["Approximately 500 g in total", "Approximately 150 g in total", "Approximately 250 g in total", "Approximately 400 g in total", "Approximately 60 g in total"], "key": "E", "type": "sba", "explanation": "Intrusion requires approximately 10 to 20 g per tooth, giving about 60 g total for four incisors, because force is dissipated through the small apical surface area. (Companion Ch 13; Nanda; Hbk 4.6)", "answerPage": 188, "block": "D"}, {"n": 109, "page": 31, "stem": "Storey and Smith in 1952 proposed which force range as optimal?", "options": ["30 to 60 g", "400 to 500 g", "250 to 300 g", "150 to 200 g", "Under 25 g"], "key": "D", "type": "sba", "explanation": "Storey and Smith’s historical range of 150 to 200 g is the figure to attribute to them. (Storey and Smith 1952; Hbk 4.6)", "answerPage": 188, "block": "D"}, {"n": 110, "page": 31, "stem": "Ren and colleagues modelled the fastest rate of canine retraction at approximately which force?", "options": ["72 cN", "272 cN", "150 cN", "500 cN", "1000 cN"], "key": "B", "type": "sba", "explanation": "Ren’s modelling gave a maximum at 272 cN, while also concluding that no universal ideal force can be defined. (Ren 2004; Hbk 4.6)", "answerPage": 188, "block": "D"}, {"n": 111, "page": 31, "stem": "What is the approximate threshold of force duration below which orthodontic tooth movement is not clinically useful?", "options": ["1 hour per day", "24 hours per day", "12 hours per day", "18 hours per day", "4 to 8 hours per day"], "key": "E", "type": "sba", "explanation": "Proffit gives a force duration threshold of approximately 4 to 8 hours per day, and notes that continuous force is more effective than intermittent force. (Proffit Ch 8; Hbk 4.6)", "answerPage": 188, "block": "D"}, {"n": 112, "page": 31, "stem": "RANKL expression during orthodontic tooth movement peaks at approximately which time?", "options": ["6 hours", "3 days", "14 days", "30 days", "60 days"], "key": "B", "type": "sba", "explanation": "RANKL peaks at 3 days and returns to baseline between days 6 and 58, implying that other pathways sustain the post-lag phase. (Danz 2021; Hbk 4.4)", "answerPage": 188, "block": "D"}, {"n": 113, "page": 31, "stem": "Which experimental finding most directly demonstrates that RANKL is essential for orthodontic tooth movement?", "options": ["Hyalinisation occurs at 30 g", "Movement is faster in the maxilla", "OPG rises on the tension side", "Deletion of RANKL in the periodontium of transgenic mice reduces osteoclasts and tooth movement", "Photobiomodulation accelerates discrete phases"], "key": "D", "type": "sba", "explanation": "Yang and colleagues showed in 2018 that RANKL deletion in transgenic mice reduces osteoclast numbers and tooth movement. (Yang 2018; Hbk 4.4)", "answerPage": 188, "block": "D"}, {"n": 114, "page": 31, "stem": "Osteoprotegerin gene transfer to the periodontium produces which effect?", "options": ["Reduced tooth movement", "Increased tooth movement", "No change in tooth movement", "Increased root resorption", "Accelerated eruption"], "key": "A", "type": "sba", "explanation": "Kanzaki and colleagues showed that OPG gene transfer reduces tooth movement, consistent with OPG acting as a decoy receptor for RANKL. (Kanzaki 2004; Hbk 4.4)", "answerPage": 188, "block": "D"}, {"n": 115, "page": 32, "stem": "Which is the correct sequence of Henneman’s four-step mechanotransduction model?", "options": ["Cell recruitment, matrix strain, tissue remodelling, fluid flow", "Tissue remodelling, cell differentiation, matrix strain, fluid flow", "Matrix strain and fluid flow, strain transferred to cells, cell recruitment and differentiation, tissue remodelling", "Fluid flow, tissue remodelling, matrix strain, cell recruitment", "Strain transferred to cells, matrix strain, tissue remodelling, fluid flow"], "key": "C", "type": "sba", "explanation": "Henneman’s model runs from extracellular matrix strain and fluid flow, through strain transfer to cells, to cell recruitment and differentiation, and finally tissue remodelling. (Henneman 2008; Hbk 4.5)", "answerPage": 188, "block": "D"}, {"n": 116, "page": 32, "stem": "What is the current status of the bone-bending hypothesis?", "options": ["It is the accepted mechanism of tooth movement", "It explains the lag phase", "It has been proved by implant studies", "There is little evidence that orthodontic forces bend bone to any clinically meaningful degree", "It replaced the pressure-tension theory"], "key": "D", "type": "sba", "explanation": "Baumrind proposed bone bending in 1969, but there is little evidence that orthodontic forces bend bone to a clinically meaningful degree. (Baumrind 1969; Hbk 4.5)", "answerPage": 188, "block": "D"}, {"n": 117, "page": 32, "stem": "Which statement about piezoelectricity in orthodontic tooth movement is correct?", "options": ["It is the principal mechanism of tooth movement", "The currents generated are too small and too short-lived to be clinically significant", "It explains hyalinisation", "It is the basis of photobiomodulation", "It has been demonstrated to double the rate of movement"], "key": "B", "type": "sba", "explanation": "Piezoelectric currents decay too rapidly and are too small to be clinically significant. Streaming potentials are of unclear significance. (Companion Ch 6; Hbk 4.5)", "answerPage": 188, "block": "D"}, {"n": 118, "page": 32, "stem": "What is the approximate radiographic incidence of orthodontically induced inflammatory root resorption?", "options": ["Under 10 per cent", "Approximately 30 per cent", "100 per cent", "Up to 95 per cent", "Up to 73 per cent"], "key": "E", "type": "sba", "explanation": "Radiographic incidence is quoted as up to 73 per cent and histological incidence as up to 90 per cent. (Companion Ch 6; Hbk 4.7)", "answerPage": 188, "block": "D"}, {"n": 119, "page": 32, "stem": "What proportion of teeth show severe root resorption, defined as loss of at least one third of root length?", "options": ["1 to 5 per cent", "Under 0.1 per cent", "10 to 15 per cent", "25 per cent", "Over 40 per cent"], "key": "A", "type": "sba", "explanation": "Severe resorption affects 1 to 5 per cent of treated teeth, and is greatest in the anterior maxilla. (Sameshima and Sinclair 2004; Hbk 4.7)", "answerPage": 188, "block": "D"}, {"n": 120, "page": 32, "stem": "Which single risk factor for orthodontically induced root resorption has substantive evidence?", "options": ["Treatment duration", "Class II elastics", "Heavy force", "Asthma", "Abnormal root morphology"], "key": "C", "type": "sba", "explanation": "Heavy force is the only factor with substantive supporting evidence. The others are suggested but not established. (Weltman 2010; Hbk 4.7)", "answerPage": 188, "block": "D"}, {"n": 121, "page": 33, "stem": "Significant root resorption is identified on a mid-treatment radiograph. What is the recommended management?", "options": ["Debond immediately", "Pause force application for 3 to 6 months", "Increase the force to complete treatment faster", "Root treat the affected teeth", "Continue unchanged and review at debond"], "key": "B", "type": "sba", "explanation": "Levander and colleagues recommended pausing force application for 3 to 6 months where significant resorption is identified. (Levander 1994; Hbk 4.7)", "answerPage": 188, "block": "D"}, {"n": 122, "page": 33, "stem": "Which teeth are most susceptible to orthodontically induced root resorption?", "options": ["Mandibular first molars", "Maxillary second molars", "Mandibular premolars", "Maxillary incisors", "Mandibular canines"], "key": "D", "type": "sba", "explanation": "The order of susceptibility is maxillary incisors, then canines, then mandibular incisors, then first permanent molars. (Companion Ch 6; Hbk 4.7)", "answerPage": 188, "block": "D"}, {"n": 123, "page": 33, "stem": "Which statement about the long-term significance of severe root resorption is correct?", "options": ["It does not necessarily cause greater mobility or discolouration in the long term", "It reliably causes increased mobility and tooth loss", "It always requires extraction of the affected tooth", "It reverses completely after debond", "It causes loss of vitality in most cases"], "key": "A", "type": "sba", "explanation": "Severe resorption does not necessarily cause greater mobility or discolouration long term, although it should still be minimised and consented for. (Cobourne cases; Hbk 4.7)", "answerPage": 188, "block": "D"}, {"n": 124, "page": 33, "stem": "At approximately what stage of root formation does a tooth normally erupt?", "options": ["One quarter formed", "One half formed", "Two thirds to three quarters formed", "Fully formed", "After apexification"], "key": "C", "type": "sba", "explanation": "Eruption occurs at approximately two thirds to three quarters root formation, and continues to occlusal contact and slowly thereafter. (Companion Ch 5; Hbk 4.8)", "answerPage": 188, "block": "D"}, {"n": 125, "page": 33, "stem": "Which structure is essential for formation of the eruption pathway?", "options": ["The reduced enamel epithelium alone", "Hertwig’s epithelial root sheath", "The periodontal ligament", "The alveolar crestal fibres", "The dental follicle"], "key": "E", "type": "sba", "explanation": "The dental follicle coordinates the osteoclastic resorption that forms the eruption pathway. Removing the follicle prevents eruption. (Companion Ch 5; Hbk 4.8)", "answerPage": 188, "block": "D"}, {"n": 126, "page": 33, "stem": "A 14-year-old has a lower second molar that has failed to erupt and does not respond to orthodontic traction, becoming ankylosed. Which diagnosis should be considered?", "options": ["Primary failure of eruption", "Mechanical obstruction by the third molar", "Ectopic eruption", "Ankylosis of the primary predecessor", "Dentine dysplasia"], "key": "A", "type": "sba", "explanation": "Primary failure of eruption, due to PTH1R mutation, does not respond to traction and attempts at traction cause ankylosis. Distinguish it from mechanical obstruction, which does respond. (Decker 2008; Hbk 4.8)", "answerPage": 188, "block": "D"}, {"n": 127, "page": 33, "stem": "Alveolar bone exists in a site only under which condition?", "options": ["Where the alveolar nerve runs", "Where a graft has been placed", "Where a tooth has erupted", "Where the periosteum is intact", "In the anterior maxilla only"], "key": "C", "type": "sba", "explanation": "Proffit’s argument is that alveolar bone exists only where a tooth erupted. Erupting and extruding teeth bring alveolar bone with them. (Proffit Ch 13; Hbk 4.8)", "answerPage": 188, "block": "D"}, {"n": 128, "page": 34, "stem": "Which single statement about corticotomy, micro-osteoperforation and piezocision is best supported?", "options": ["They reliably halve total treatment time", "They are contraindicated in adults", "They have no biological effect", "They act by increasing OPG expression", "They can increase the local rate through the regional acceleratory phenomenon, but the effect is short-lived and evidence for shorter overall treatment is sparse"], "key": "E", "type": "sba", "explanation": "The regional acceleratory phenomenon is real but transient, and evidence that these techniques shorten overall treatment is sparse. (Companion Ch 6; Hbk 4.9)", "answerPage": 189, "block": "D"}, {"n": 129, "page": 34, "stem": "What did El-Angbawi and colleagues conclude about photobiomodulation in 2023?", "options": ["It halves overall treatment time", "It may accelerate discrete phases but does not influence overall treatment time", "It increases root resorption", "It is more effective than corticotomy", "It works only in adults"], "key": "B", "type": "sba", "explanation": "Photobiomodulation may accelerate discrete phases of movement but does not influence overall treatment time. (El-Angbawi 2023; Hbk 4.9)", "answerPage": 189, "block": "D"}, {"n": 130, "page": 34, "stem": "On the tension side of a tooth undergoing orthodontic movement, which combination of changes occurs?", "options": ["RANKL up, OPG down, osteoclast recruitment", "Hyalinisation and undermining resorption", "Both RANKL and OPG down", "OPG up, RANKL down, osteoblast activity and bone deposition", "Cathepsin K release and Howship’s lacunae"], "key": "D", "type": "sba", "explanation": "On the tension side OPG rises and RANKL falls, with osteoblast activity, TGF-beta, VEGF and FGF2 supporting deposition and angiogenesis. (Companion Ch 6; Hbk 4.3)", "answerPage": 189, "block": "D"}, {"n": 131, "page": 34, "stem": "Osteoclasts resorb bone by which principal mechanism?", "options": ["Secretion of alkaline phosphatase", "Phagocytosis of intact hydroxyapatite crystals", "Release of cathepsins, matrix metalloproteinases and hydrogen ions, forming Howship’s lacunae", "Secretion of osteoprotegerin", "Deposition of osteoid"], "key": "C", "type": "sba", "explanation": "Osteoclasts acidify the resorption lacuna and release cathepsin K and MMPs, forming Howship’s lacunae. (Companion Ch 6; Hbk 4.2)", "answerPage": 189, "block": "D"}, {"n": 132, "page": 34, "stem": "The basic multicellular unit describes which concept?", "options": ["The coupled apposition and resorption unit of bone remodelling", "The smallest measurable unit of orthodontic force", "The unit of periodontal ligament width", "The bracket-wire interface", "A single osteocyte and its canaliculi"], "key": "A", "type": "sba", "explanation": "The BMU is the remodelling unit in which apposition and resorption are tightly coupled. (Companion Ch 6; Hbk 4.2)", "answerPage": 189, "block": "D"}, {"n": 133, "page": 34, "stem": "Which is the approximate composition of bone by proportion?", "options": ["Matrix 60 per cent, mineral 30 per cent, cells 10 per cent", "Matrix 20 per cent, mineral 70 per cent, cells 10 per cent", "Matrix 10 per cent, mineral 80 per cent, cells 10 per cent", "Matrix 45 per cent, mineral 45 per cent, cells 10 per cent", "Matrix 30 per cent, mineral 60 per cent, cells 10 per cent"], "key": "E", "type": "sba", "explanation": "Extracellular matrix is approximately 30 per cent, mineral approximately 60 per cent and cells approximately 10 per cent. (Companion Ch 6; Hbk 4.2)", "answerPage": 189, "block": "D"}, {"n": 134, "page": 34, "stem": "Which cells give rise to osteoclasts?", "options": ["Mesenchymal stem cells", "Epithelial rests of Malassez", "Periodontal ligament fibroblasts", "Haematopoietic stem cells, circulating as monocytes", "Cementoblasts"], "key": "D", "type": "sba", "explanation": "Osteoclasts are multinucleate cells derived from haematopoietic stem cells that circulate as monocytes. (Companion Ch 6; Hbk 4.2)", "answerPage": 189, "block": "D"}, {"n": 135, "page": 35, "stem": "Which of the following is a constituent of the periodontal ligament that is specific to it?", "options": ["Type I collagen", "Oxytalan fibres", "Fibroblasts", "Blood vessels", "Nerve endings"], "key": "B", "type": "sba", "explanation": "Elastic oxytalan fibres are a characteristic constituent of the periodontal ligament, along with epithelial rests of Malassez and pluripotent stem cells. (Companion Ch 6; Hbk 4.2)", "answerPage": 189, "block": "D"}, {"n": 136, "page": 35, "stem": "Which movement produces the greatest amount of hyalinisation for a given force?", "options": ["Bodily movement", "Root torque", "Extrusion", "Rotation", "Tipping"], "key": "E", "type": "sba", "explanation": "Tipping concentrates stress at the alveolar crest and apex, producing more hyalinisation than bodily movement for the same force. (Reitan 1967; Hbk 4.3)", "answerPage": 189, "block": "D"}, {"n": 137, "page": 35, "stem": "A patient asks how likely root resorption is. Which is the best answer to give at consent?", "options": ["It essentially never happens", "Some root shortening occurs in most people treated with fixed appliances, usually of no consequence, but in about 1 to 5 per cent of teeth it exceeds a third of the root", "It happens in about half of patients and always causes tooth loss", "It occurs only in adults", "It can be prevented entirely by light forces"], "key": "B", "type": "sba", "explanation": "This is the honest, quantified answer, with the risk-reduction measures of light forces, short treatment and a mid-treatment radiograph. (Companion Ch 2; Hbk 4.7)", "answerPage": 189, "block": "D"}, {"n": 138, "page": 35, "stem": "During the initial phase of tooth movement, what is principally happening?", "options": ["Frontal resorption", "Osteoblast recruitment", "Undermining resorption", "Displacement of the tooth within the periodontal ligament space, with fluid expressed", "Hyalinisation clearance"], "key": "D", "type": "sba", "explanation": "The initial phase lasts about 2 days and consists of displacement within the ligament space, before true bone remodelling begins. (Companion Ch 6; Hbk 4.3)", "answerPage": 189, "block": "D"}, {"n": 139, "page": 35, "stem": "Which is the correct force range for tipping a single tooth with a removable appliance?", "options": ["25 to 40 g", "10 to 20 g", "100 to 150 g", "200 to 250 g", "Over 300 g"], "key": "A", "type": "sba", "explanation": "Tipping a single tooth requires approximately 25 to 40 g, sometimes quoted as 35 to 60 g. Removable appliance springs are activated accordingly. (Companion Ch 9; Hbk 16.1)", "answerPage": 189, "block": "D"}, {"n": 140, "page": 35, "stem": "Substance P and calcitonin gene-related peptide are released early in tooth movement from which source?", "options": ["Osteoclasts", "Osteocytes", "Distorted nerve endings in the periodontal ligament", "Cementoblasts", "Epithelial rests of Malassez"], "key": "C", "type": "sba", "explanation": "Matrix strain and altered fluid flow distort nerve endings, releasing substance P and CGRP as part of the early neurogenic inflammatory response. (Companion Ch 6; Hbk 4.4)", "answerPage": 189, "block": "D"}, {"n": 141, "page": 36, "stem": "Which definition of malocclusion is the most defensible in an examination?", "options": ["Any deviation from ideal occlusion", "An occlusion requiring orthodontic treatment", "Any Class II or Class III relationship", "A variation from ideal occlusion of sufficient degree to be, or to have the potential to be, of aesthetic or functional significance to the individual", "An occlusion with crowding of more than 4 mm"], "key": "D", "type": "sba", "explanation": "Malocclusion is defined by significance to the individual, which is why demand and need are separate questions. (Companion Ch 2; Hbk 5.1)", "answerPage": 189, "block": "E"}, {"n": 142, "page": 36, "stem": "In Angle’s Class I molar relationship, the mesiobuccal cusp of the upper first permanent molar occludes with which structure?", "options": ["The mesial marginal ridge of the lower first molar", "The buccal groove of the lower first permanent molar", "The distal marginal ridge of the lower second premolar", "The central fossa of the lower first molar", "The buccal groove of the lower second molar"], "key": "B", "type": "sba", "explanation": "Angle’s Class I is defined by the mesiobuccal cusp of the upper first molar occluding in the buccal groove of the lower first molar. (Companion Ch 2; Hbk 5.2)", "answerPage": 189, "block": "E"}, {"n": 143, "page": 36, "stem": "Which is a principal limitation of Angle’s classification?", "options": ["It cannot be applied to adults", "It is not reproducible", "It requires a lateral cephalogram", "It cannot describe Class III cases", "It assumes the first permanent molar is in a stable, correct anteroposterior position, and ignores the vertical and transverse planes"], "key": "E", "type": "sba", "explanation": "Angle’s classification assumes a correctly positioned first molar and ignores the vertical and transverse dimensions, the skeletal pattern, and cases where the molar is missing or displaced. (Companion Ch 2; Hbk 5.2)", "answerPage": 189, "block": "E"}, {"n": 144, "page": 36, "stem": "The British Standards Institute classification of incisor relationship is based on which relationship?", "options": ["The relationship of the lower incisor edges to the cingulum plateau of the upper central incisors", "The molar relationship", "The relationship of the canines", "The overjet in millimetres", "The skeletal pattern"], "key": "A", "type": "sba", "explanation": "The BSI classification is incisor-based, defined by the position of the lower incisor edges relative to the cingulum plateau of the upper centrals. (Companion Ch 2; Hbk 5.2)", "answerPage": 189, "block": "E"}, {"n": 145, "page": 36, "stem": "In a Class II division 2 incisor relationship, which single feature is characteristic?", "options": ["The overjet is always increased", "The lower incisors are proclined", "The upper central incisors are retroclined", "The overbite is reduced", "The molars are always Class II"], "key": "C", "type": "sba", "explanation": "In Class II division 2 the upper central incisors are retroclined; the overjet is usually minimal but may be increased. (Companion Ch 2; Hbk 5.2)", "answerPage": 189, "block": "E"}, {"n": 146, "page": 37, "stem": "Andrews derived his six keys of occlusion from what sample?", "options": ["100 treated orthodontic cases", "120 non-orthodontic normal occlusions", "500 randomly selected patients", "A cadaveric collection", "A single family pedigree"], "key": "B", "type": "sba", "explanation": "Andrews studied 120 non-orthodontic normal occlusions to derive the six keys and, subsequently, the pre-adjusted prescription. (Andrews 1972; Hbk 5.2)", "answerPage": 189, "block": "E"}, {"n": 147, "page": 37, "stem": "Which is not one of Andrews’ six keys of occlusion?", "options": ["Correct molar relationship", "Correct crown angulation", "Correct crown inclination", "Canine-guided excursion", "Flat or minimal curve of Spee"], "key": "D", "type": "sba", "explanation": "The six keys are molar relationship, crown angulation, crown inclination, no rotations, tight contacts and a flat curve of Spee. Canine guidance is not among them. (Andrews 1972; Hbk 5.2)", "answerPage": 190, "block": "E"}, {"n": 148, "page": 37, "stem": "What proportion of the population develops an acceptable occlusion naturally?", "options": ["30 to 40 per cent", "Under 10 per cent", "60 per cent", "80 per cent", "Over 90 per cent"], "key": "A", "type": "sba", "explanation": "An acceptable occlusion develops naturally in only 30 to 40 per cent, which is one reason the specialty exists. (Cobourne cases; Hbk 5.4)", "answerPage": 190, "block": "E"}, {"n": 149, "page": 37, "stem": "What proportion of individuals have retruded contact position coincident with intercuspal position?", "options": ["Approximately 50 per cent", "Approximately 30 per cent", "Approximately 10 per cent", "Approximately 75 per cent", "Over 90 per cent"], "key": "C", "type": "sba", "explanation": "Posselt showed that only about 10 per cent have RCP coincident with ICP, and that a discrepancy of 0 to 2 mm is normal. (Posselt 1952; Hbk 5.1)", "answerPage": 190, "block": "E"}, {"n": 150, "page": 37, "stem": "What proportion of malocclusion has a specific, identifiable cause?", "options": ["Nearly all", "About 20 per cent", "About 50 per cent", "About 75 per cent", "Under 5 per cent"], "key": "E", "type": "sba", "explanation": "Only 5 per cent or fewer of malocclusions have a specific identifiable cause such as a syndrome, cleft, trauma or pathology. (Proffit Ch 5; Hbk 5.3)", "answerPage": 190, "block": "E"}, {"n": 151, "page": 37, "stem": "Equilibrium theory explains which observation?", "options": ["That teeth sit where resting soft tissue forces balance, so light sustained forces move teeth while heavy brief forces do not", "That heavy chewing forces determine tooth position", "That the mandible grows in response to function", "That expansion is stable", "That extraction narrows the airway"], "key": "A", "type": "sba", "explanation": "Equilibrium theory states that light sustained forces such as resting lip and tongue posture move teeth, whereas heavy brief forces such as chewing do not. (Proffit Ch 5; Hbk 5.3)", "answerPage": 190, "block": "E"}, {"n": 152, "page": 37, "stem": "A digit-sucking habit characteristically produces which combination?", "options": ["Retroclined uppers, proclined lowers and a deep overbite", "Bilateral scissors bite and increased overbite", "Proclined uppers, retroclined lowers, an asymmetric anterior open bite and a posterior crossbite", "Class III incisors with a reverse overjet", "A symmetrical anterior open bite with no transverse effect"], "key": "C", "type": "sba", "explanation": "The classic digit-sucking pattern is proclined uppers, retroclined lowers, an asymmetric anterior open bite and a posterior crossbite from a lowered tongue position and cheek pressure. (Companion Ch 12; Hbk 5.3)", "answerPage": 190, "block": "E"}, {"n": 153, "page": 38, "stem": "Which single statement about the airway and facial form is the most defensible?", "options": ["Chronic nasal obstruction causes long face syndrome", "Mouth breathing has been shown to be entirely harmless", "The airway has no relationship to facial form", "Adenoidectomy reliably normalises facial growth", "Chronic nasal obstruction is associated with, but not proved to cause, increased face height and a narrow maxilla"], "key": "E", "type": "sba", "explanation": "The association is real but weak, and causation is not established. Stating the association without asserting the cause is the examinable answer. (Companion Ch 7; Hbk 26.5)", "answerPage": 190, "block": "E"}, {"n": 154, "page": 38, "stem": "The prevalence of Class II malocclusion in United States adolescents is approximately which range?", "options": ["2 to 5 per cent", "15 to 22 per cent", "8 to 10 per cent", "30 to 40 per cent", "Over 50 per cent"], "key": "B", "type": "sba", "explanation": "Class II affects approximately 15 to 22 per cent of United States adolescents, and Class III approximately 5 to 6 per cent. (Mosby ch. on classification; Hbk 5.4)", "answerPage": 190, "block": "E"}, {"n": 155, "page": 38, "stem": "Worldwide Class III prevalence is approximately which value, with marked regional variation?", "options": ["1.2 per cent", "22 per cent", "15 per cent", "6.8 per cent", "30 per cent"], "key": "D", "type": "sba", "explanation": "Worldwide Class III prevalence is approximately 6.8 per cent, with much higher figures in East Asian populations. (Mosby ch. on classification; Hbk 5.4)", "answerPage": 190, "block": "E"}, {"n": 156, "page": 38, "stem": "Which is the normal range for overbite?", "options": ["0 to 1 mm", "5 to 7 mm", "2 to 4 mm, or one third to one half of the lower incisor crown", "Complete to the palatal mucosa", "There is no normal range"], "key": "C", "type": "sba", "explanation": "Normal overbite is 2 to 4 mm, or one third to one half of the lower incisor crown height. (Companion Ch 7; Hbk 5.4)", "answerPage": 190, "block": "E"}, {"n": 157, "page": 38, "stem": "Which single trait is the strongest evidence of a genetic contribution to malocclusion?", "options": ["Familial recurrence of a Class III skeletal pattern", "Crowding of the lower incisors", "Anterior open bite", "A midline diastema", "A unilateral crossbite"], "key": "A", "type": "sba", "explanation": "Skeletal pattern, particularly Class III, and tooth size and number show the highest heritability. Occlusal detail is more environmentally determined. (Proffit Ch 5; Hbk 5.3)", "answerPage": 190, "block": "E"}, {"n": 158, "page": 38, "stem": "The line of occlusion, as defined by Angle, passes through which structures?", "options": ["The buccal cusps of the upper teeth and the central fossae of the lower", "The interproximal contact points", "The incisal edges of both arches only", "The gingival margins of all teeth", "The central fossae and cingula of the upper arch, and the buccal cusps and incisal edges of the lower"], "key": "E", "type": "sba", "explanation": "Angle’s line of occlusion runs through the central fossae and cingula of the upper arch and the buccal cusps and incisal edges of the lower. (Companion Ch 2; Hbk 5.1)", "answerPage": 190, "block": "E"}, {"n": 159, "page": 39, "stem": "Centric relation is best defined as which position?", "options": ["Maximum intercuspation of the teeth", "The position adopted during swallowing", "The most retruded position of the mandible", "The condyle in its most superior and anterior position against the articular eminence, independent of tooth contact", "The rest position of the mandible"], "key": "D", "type": "sba", "explanation": "Centric relation is a condylar position independent of tooth contact. Intercuspal position is defined by the teeth. (Companion Ch 2; Hbk 5.1)", "answerPage": 190, "block": "E"}, {"n": 160, "page": 39, "stem": "Which is the ideal overjet range?", "options": ["0 to 1 mm", "2 to 4 mm", "5 to 6 mm", "Reverse by 1 mm", "It has no defined range"], "key": "B", "type": "sba", "explanation": "Ideal overjet is 2 to 4 mm, corresponding to the aim of Class I incisors in a stable soft tissue environment. (Cobourne cases; Hbk 5.4)", "answerPage": 190, "block": "E"}, {"n": 161, "page": 39, "stem": "A Class II division 1 malocclusion is perpetuated by a lower lip trap through which mechanism?", "options": ["The lip retroclines the upper incisors", "The lip causes a posterior crossbite", "The lip extrudes the lower molars", "The lip prevents mandibular growth", "The lip rests behind the upper incisors, proclining them and retroclining the lowers"], "key": "E", "type": "sba", "explanation": "A lower lip trap resting behind the upper incisors proclines them and retroclines the lowers, perpetuating the malocclusion. (Companion Ch 12; Hbk 22.1)", "answerPage": 190, "block": "E"}, {"n": 162, "page": 39, "stem": "What proportion of children with an overjet of 5 mm or more still have it as adults?", "options": ["13 per cent of children rises to 23 per cent of adults", "23 per cent of children falls to 13 per cent of adults", "Both figures are 23 per cent", "Both figures are 5 per cent", "Over half persist unchanged"], "key": "B", "type": "sba", "explanation": "Overjet of 5 mm or more falls from 23 per cent of children to 13 per cent of adults, because the mandible catches up. This is a key argument against early treatment. (Proffit Ch 13; Hbk 22.1)", "answerPage": 190, "block": "E"}, {"n": 163, "page": 39, "stem": "Which of the following is the correct definition of ideal occlusion?", "options": ["The occlusion most people have", "Any Class I occlusion", "An occlusion with no crowding", "A theoretical concept describing the anatomically perfect relationship of the dental arches, rarely found", "An occlusion after orthodontic treatment"], "key": "D", "type": "sba", "explanation": "Ideal occlusion is a theoretical construct. Normal occlusion is an occlusion within an accepted range of variation, functioning without pathology. (Companion Ch 2; Hbk 5.1)", "answerPage": 190, "block": "E"}, {"n": 164, "page": 39, "stem": "Which condition is most likely to produce a Class II malocclusion of acquired rather than developmental origin?", "options": ["A childhood condylar fracture with growth disturbance", "A digit habit", "A midline supernumerary", "Early loss of a primary molar", "Hypodontia of the lower second premolars"], "key": "A", "type": "sba", "explanation": "Condylar fracture in childhood is the commonest acquired cause of mandibular growth disturbance, and can produce a Class II relationship with asymmetry. (Companion Ch 15; Hbk 26.4)", "answerPage": 190, "block": "E"}, {"n": 165, "page": 39, "stem": "Which single statement about Class II division 2 incisors is correct?", "options": ["The lateral incisors are usually retroclined with the centrals", "The overbite is usually reduced", "The lateral incisors are frequently proclined and mesiolabially rotated", "The interincisal angle is usually decreased", "The lower face height is usually increased"], "key": "C", "type": "sba", "explanation": "In Class II division 2, the laterals are frequently proclined and mesiolabially rotated while the centrals are retroclined, and the interincisal angle is increased. (Companion Ch 2; Hbk 22.4)", "answerPage": 190, "block": "E"}, {"n": 166, "page": 40, "stem": "Which is the correct approximate prevalence of Class II division 2 in Caucasian populations?", "options": ["1 per cent", "30 per cent", "20 per cent", "5 to 10 per cent", "45 per cent"], "key": "D", "type": "sba", "explanation": "Class II division 2 affects approximately 5 to 10 per cent of Caucasian populations. (Companion Ch 2; Hbk 5.4)", "answerPage": 191, "block": "E"}, {"n": 167, "page": 40, "stem": "A patient has a 3 mm discrepancy between retruded contact position and intercuspal position with an anterior slide. Which single conclusion follows?", "options": ["This is entirely normal and requires no comment", "This exceeds the normal 0 to 2 mm range and should be recorded, since it may indicate a pseudo-Class III or a displacement", "It indicates temporomandibular joint disease", "It is an indication for occlusal adjustment", "It contraindicates orthodontic treatment"], "key": "B", "type": "sba", "explanation": "A discrepancy of 0 to 2 mm is normal. A larger anterior slide should be recorded, and raises the possibility of a pseudo-Class III or a functional displacement. (Posselt 1952; Hbk 5.1 and 23.1)", "answerPage": 191, "block": "E"}, {"n": 168, "page": 40, "stem": "Which of the following is described as a seventh key of occlusion, additional to Andrews’ original six?", "options": ["Canine guidance", "A Class I canine relationship", "Absence of a curve of Wilson", "Coincident centre lines", "Correct crown size, shape and tooth-size harmony"], "key": "E", "type": "sba", "explanation": "A seventh key covering crown size, shape and tooth-size harmony is often added to Andrews’ original six. (Andrews 1972; Hbk 5.2)", "answerPage": 191, "block": "E"}, {"n": 169, "page": 40, "stem": "Neural crest cells are relevant to the aetiology of malocclusion principally because of which fact?", "options": ["They form practically all the mesenchyme of the face", "They form the enamel organ", "They determine tooth eruption timing", "They form the periodontal ligament exclusively", "They control the growth spurt"], "key": "A", "type": "sba", "explanation": "Neural crest cells form practically all the facial mesenchyme, so disorders of their migration produce craniofacial anomalies. (Proffit Ch 5; Hbk 5.3)", "answerPage": 191, "block": "E"}, {"n": 170, "page": 40, "stem": "The equilibrium theory would predict that which of the following is unlikely to be stable?", "options": ["A tooth moved into the neutral zone", "Correction of a rotation with a bonded retainer", "Lower incisors proclined 4 mm beyond their original position", "Closure of a midline diastema with permanent retention", "Levelling of a curve of Spee in a growing child"], "key": "C", "type": "sba", "explanation": "Teeth moved outside the zone of soft tissue equilibrium return towards it. Lower incisor advance of more than about 2 mm very likely needs permanent retention. (Proffit Ch 17; Hbk 19.1)", "answerPage": 191, "block": "E"}, {"n": 171, "page": 41, "stem": "The Index of Orthodontic Treatment Need Dental Health Component is applied in which way?", "options": ["All qualifying traits are summed", "Only the single worst trait is recorded", "The mean of all traits is taken", "Traits are weighted and averaged", "Only overjet is considered"], "key": "B", "type": "sba", "explanation": "The DHC is hierarchical: only the single worst trait is recorded, following the MOCDO order. (Companion Ch 2; Hbk 6.1)", "answerPage": 191, "block": "F"}, {"n": 172, "page": 41, "stem": "What does the acronym MOCDO stand for?", "options": ["Molar, overjet, crossbite, displacement, overbite", "Missing teeth, occlusion, crowding, deviation, overbite", "Midline, occlusion, crowding, displacement, overjet", "Missing teeth, overjet, crossbite, displacement of contact points, overbite", "Molar, occlusion, canine, displacement, overjet"], "key": "D", "type": "sba", "explanation": "MOCDO is the hierarchy: Missing teeth, Overjet, Crossbite, Displacement of contact points, Overbite. Work down the list and record the first trait met. (Companion Ch 2; Hbk 6.1)", "answerPage": 191, "block": "F"}, {"n": 173, "page": 41, "stem": "An overjet of 7 mm falls into which IOTN Dental Health Component grade?", "options": ["4a", "3a", "5a", "2a", "4b"], "key": "A", "type": "sba", "explanation": "Overjet greater than 6 mm and up to 9 mm is grade 4a. Over 9 mm is 5a; over 3.5 mm up to 6 mm with incompetent lips is 3a. (Companion Ch 2; Hbk 6.1)", "answerPage": 191, "block": "F"}, {"n": 174, "page": 41, "stem": "A crossbite with a mandibular displacement of 3 mm falls into which grade?", "options": ["3c", "5c", "4c", "2c", "4d"], "key": "C", "type": "sba", "explanation": "A crossbite with a displacement of more than 2 mm is grade 4c. A displacement of 1 to 2 mm is 3c. (Companion Ch 2; Hbk 6.1)", "answerPage": 191, "block": "F"}, {"n": 175, "page": 41, "stem": "Impeded eruption of a tooth, other than by third molar crowding, falls into which grade?", "options": ["3i", "4i", "4t", "2i", "5i"], "key": "E", "type": "sba", "explanation": "Impeded eruption is grade 5i, in the very great need category. (Companion Ch 2; Hbk 6.1)", "answerPage": 191, "block": "F"}, {"n": 176, "page": 41, "stem": "The IOTN Aesthetic Component requires the clinician to select the photograph closest in which respect?", "options": ["Aesthetic impairment", "Morphological similarity to the patient", "Overjet magnitude", "Crowding severity", "Molar relationship"], "key": "A", "type": "sba", "explanation": "The AC is a rank order of attractiveness. The photograph selected should match the degree of aesthetic impairment, not the morphology. (Companion Ch 2; Hbk 6.1)", "answerPage": 191, "block": "F"}, {"n": 177, "page": 42, "stem": "Which Aesthetic Component grades correspond to a definite need for treatment?", "options": ["1 to 4", "5 to 7", "8 to 10", "Only 10", "Any grade above 3"], "key": "C", "type": "sba", "explanation": "Grades 1 to 4 indicate no need, 5 to 7 borderline need, and 8 to 10 need for treatment. (Companion Ch 2; Hbk 6.1)", "answerPage": 191, "block": "F"}, {"n": 178, "page": 42, "stem": "Which statement about the Peer Assessment Rating is correct?", "options": ["It measures need for treatment before treatment", "It replaced IOTN", "It is hierarchical and records only the worst trait", "It is scored from photographs", "It is an accumulative score with no maximum cut-off, used to assess the outcome of treatment"], "key": "E", "type": "sba", "explanation": "PAR is accumulative, scored from study casts before and after, and has no maximum. IOTN measures need; PAR measures outcome. (Companion Ch 2; Hbk 6.2)", "answerPage": 191, "block": "F"}, {"n": 179, "page": 42, "stem": "What PAR point reduction is required for a case to be classed as greatly improved?", "options": ["At least 10 points", "At least 22 points", "At least 30 points", "At least 50 points", "Any reduction"], "key": "B", "type": "sba", "explanation": "A reduction of at least 22 points, or greater than 70 per cent, is classed as greatly improved. (Companion Ch 2; Hbk 6.2)", "answerPage": 191, "block": "F"}, {"n": 180, "page": 42, "stem": "A PAR score reduction of 25 per cent indicates which outcome?", "options": ["Greatly improved", "Improved", "Cannot be interpreted", "Worse or no different", "Requires retreatment by definition"], "key": "D", "type": "sba", "explanation": "A reduction of less than 30 per cent is classed as worse or no different. Greater than 30 per cent is improved. (Companion Ch 2; Hbk 6.2)", "answerPage": 191, "block": "F"}, {"n": 181, "page": 42, "stem": "The PAR index is best used for which purpose?", "options": ["Judging an individual clinician on a single case", "Determining eligibility for treatment", "Auditing an operator or a service across many cases", "Predicting relapse", "Assessing facial aesthetics"], "key": "C", "type": "sba", "explanation": "PAR is a coarse instrument best used to audit an operator or service over many cases rather than to judge a single case. (Companion Ch 2; Hbk 6.2)", "answerPage": 191, "block": "F"}, {"n": 182, "page": 42, "stem": "Which index is used to assess the quality of orthodontic finishing across eight criteria?", "options": ["ABO Objective Grading System", "PAR", "ICON", "IOTN", "Little’s Irregularity Index"], "key": "A", "type": "sba", "explanation": "The ABO-OGS assesses alignment, marginal ridges, buccolingual inclination, occlusal relationship, occlusal contacts, overjet, interproximal contacts and root angulation. (Companion Ch 14; Hbk 6.3)", "answerPage": 191, "block": "F"}, {"n": 183, "page": 42, "stem": "Which index detected a significant difference in occlusal outcome between aligners and fixed appliances?", "options": ["PAR", "IOTN Dental Health Component", "Little’s Irregularity Index", "ICON", "ABO Objective Grading System"], "key": "E", "type": "sba", "explanation": "PAR shows no difference; ABO-OGS shows aligners significantly worse. PAR is the coarser measure and the two do not correlate. (Companion Ch 14; Hbk 6.3 and 17.5)", "answerPage": 191, "block": "F"}, {"n": 184, "page": 43, "stem": "Little’s Irregularity Index measures which quantity?", "options": ["The overjet", "The intercanine width", "The depth of the curve of Spee", "The sum of the linear displacements of the anatomical contact points of the mandibular incisors", "The Bolton discrepancy"], "key": "D", "type": "sba", "explanation": "Little’s Irregularity Index is the sum of contact point displacements of the mandibular incisors, used principally in relapse research. (Little 1975; Hbk 6.3)", "answerPage": 191, "block": "F"}, {"n": 185, "page": 43, "stem": "Which value of lower incisor irregularity has been proposed as an acceptable level of relapse?", "options": ["Under 1 mm", "Under 3.5 mm", "Under 6 mm", "Under 10 mm", "Any value is acceptable"], "key": "B", "type": "sba", "explanation": "Little proposed under 3.5 mm of lower incisor irregularity as an acceptable level of relapse. (Little 1975; Hbk 19.4)", "answerPage": 192, "block": "F"}, {"n": 186, "page": 43, "stem": "The ICON index combines which elements?", "options": ["Need and outcome only", "Overjet and overbite only", "Aesthetics and function", "Skeletal and dental factors", "Need, complexity and outcome"], "key": "E", "type": "sba", "explanation": "ICON, the Index of Complexity, Outcome and Need, combines all three in a single instrument. (Companion Ch 2; Hbk 6.3)", "answerPage": 192, "block": "F"}, {"n": 187, "page": 43, "stem": "Which IOTN grade corresponds to a reverse overjet greater than 3.5 mm with no reported masticatory or speech difficulty?", "options": ["3b", "4b", "5b", "2b", "5m"], "key": "B", "type": "sba", "explanation": "Reverse overjet greater than 3.5 mm without reported difficulty is 4b; with reported difficulties it becomes 5m. (Companion Ch 2; Hbk 6.1)", "answerPage": 192, "block": "F"}, {"n": 188, "page": 43, "stem": "A patient has 3 mm of contact point displacement in the lower labial segment and no other traits. Which DHC grade applies?", "options": ["2d", "5d", "4d", "3d", "1"], "key": "D", "type": "sba", "explanation": "Displacement of contact points greater than 2 mm and up to 4 mm is grade 3d. More than 4 mm is 4d. (Companion Ch 2; Hbk 6.1)", "answerPage": 192, "block": "F"}, {"n": 189, "page": 43, "stem": "Which single statement about the relationship between treatment need and treatment demand is correct?", "options": ["Demand is a separate question from need, and correlates only moderately with it", "They are the same thing", "Demand always exceeds need", "Need always exceeds demand", "Demand is measured by the Dental Health Component"], "key": "A", "type": "sba", "explanation": "Need and demand are distinct. Indices measure need; demand is driven principally by appearance and by social factors. (Proffit Ch 1; Hbk 6.1)", "answerPage": 192, "block": "F"}, {"n": 190, "page": 43, "stem": "Defects of cleft lip and palate fall into which IOTN grade?", "options": ["3p", "4p", "5p", "2p", "Not covered by IOTN"], "key": "C", "type": "sba", "explanation": "Cleft lip and palate defects are grade 5p, in the very great need category. (Companion Ch 2; Hbk 6.1)", "answerPage": 192, "block": "F"}, {"n": 191, "page": 44, "stem": "An increased and complete overbite causing gingival or palatal trauma falls into which grade?", "options": ["3f", "2f", "5f", "4f", "4a"], "key": "D", "type": "sba", "explanation": "An increased and complete overbite with gingival or palatal trauma is grade 4f. Complete to the gingiva without trauma is 3f. (Companion Ch 2; Hbk 6.1)", "answerPage": 192, "block": "F"}, {"n": 192, "page": 44, "stem": "Which is the correct use of the Aesthetic Component in relation to the Dental Health Component?", "options": ["The two are summed to give a total score", "They are recorded independently, and either may indicate need", "The AC overrides the DHC", "The DHC is used only if the AC is above 8", "The AC applies only to adults"], "key": "B", "type": "sba", "explanation": "The two components are recorded independently. Either may indicate need for treatment. (Companion Ch 2; Hbk 6.1)", "answerPage": 192, "block": "F"}, {"n": 193, "page": 44, "stem": "Which epidemiological figure best describes the prevalence of dental trauma by age 12?", "options": ["Under 2 per cent", "5 per cent", "Over 50 per cent", "35 per cent", "Up to 18 per cent"], "key": "E", "type": "sba", "explanation": "Up to approximately 18 per cent of children have experienced dental trauma by age 12, and increased overjet is a significant risk factor. (Companion Ch 2; Hbk 6.3 and 29.2)", "answerPage": 192, "block": "F"}, {"n": 194, "page": 44, "stem": "Traumatic loss of a maxillary central incisor affects approximately what proportion of children?", "options": ["3 per cent", "0.3 per cent", "8 per cent", "15 per cent", "25 per cent"], "key": "A", "type": "sba", "explanation": "Jarvinen reported that traumatic loss of a maxillary central affects approximately 3 per cent of children, typically boys with an increased overjet in the mixed dentition. (Jarvinen 1978; Hbk 20.6)", "answerPage": 192, "block": "F"}, {"n": 195, "page": 44, "stem": "Which single justification for the existence of indices of orthodontic treatment need is the most defensible?", "options": ["They determine which treatment technique to use", "They predict treatment outcome", "They allow the allocation of a scarce, largely publicly funded resource according to defined criteria", "They measure patient satisfaction", "They replace clinical judgement"], "key": "C", "type": "sba", "explanation": "Indices exist principally to allow rational, defensible allocation of a limited resource, which is the justice principle applied to orthodontics. (Companion Ch 2; Hbk 6.1 and 8.3)", "answerPage": 192, "block": "F"}, {"n": 196, "page": 45, "stem": "Evidence-based practice is best defined as the integration of which three elements?", "options": ["Randomised trials, meta-analyses and guidelines", "Best available evidence, clinical expertise and patient values", "Textbooks, expert opinion and audit", "Systematic reviews, cohort studies and consensus", "Research, teaching and practice"], "key": "B", "type": "sba", "explanation": "Evidence-based practice integrates the best available evidence with clinical expertise and the patient’s own values and preferences. (Companion Ch 1; Hbk 7.1)", "answerPage": 192, "block": "G"}, {"n": 197, "page": 45, "stem": "Which sits highest in the conventional hierarchy of evidence?", "options": ["A large randomised controlled trial", "A case series", "A prospective cohort study", "A systematic review with meta-analysis", "Expert opinion"], "key": "D", "type": "sba", "explanation": "Filtered secondary research sits above unfiltered primary research; clinical practice guidelines derived from high-quality meta-analysis sit at the top. (Companion Ch 1; Hbk 7.1)", "answerPage": 192, "block": "G"}, {"n": 198, "page": 45, "stem": "What does the acronym PICO denote?", "options": ["Population, intervention, comparison, outcome", "Patient, indication, cost, outcome", "Prevalence, incidence, comparison, odds", "Protocol, intervention, control, observation", "Population, incidence, cohort, odds"], "key": "A", "type": "sba", "explanation": "PICO structures an answerable clinical question: Population, Intervention, Comparison, Outcome. (Companion Ch 1; Hbk 7.2)", "answerPage": 192, "block": "G"}, {"n": 199, "page": 45, "stem": "Randomisation in a clinical trial principally achieves which single aim?", "options": ["It blinds the operator", "It increases the sample size", "It makes groups comparable in known and unknown confounders", "It removes the need for a control group", "It guarantees statistical significance"], "key": "C", "type": "sba", "explanation": "Randomisation balances both known and unknown confounders between groups, which is what no observational design can achieve. (Companion Ch 1; Hbk 7.2)", "answerPage": 192, "block": "G"}, {"n": 200, "page": 45, "stem": "Allocation concealment differs from blinding in which respect?", "options": ["Allocation concealment occurs after randomisation", "Allocation concealment applies only to crossover trials", "They are the same procedure", "Blinding applies only to statisticians", "Allocation concealment prevents the recruiter knowing the next allocation; blinding conceals group identity after allocation"], "key": "E", "type": "sba", "explanation": "Allocation concealment protects the randomisation sequence at the point of recruitment. Blinding conceals group membership thereafter. (Companion Ch 1; Hbk 7.2)", "answerPage": 192, "block": "G"}, {"n": 201, "page": 45, "stem": "In an orthodontic trial, blinding of which party is usually most feasible and most important?", "options": ["The outcome assessor", "The operator", "The patient", "The statistician alone", "The funder"], "key": "A", "type": "sba", "explanation": "Operator and patient blinding is rarely possible in orthodontics. Blinding the outcome assessor is both feasible and the most important protection against detection bias. (Companion Ch 1; Hbk 7.2)", "answerPage": 192, "block": "G"}, {"n": 202, "page": 46, "stem": "Intention-to-treat analysis means which of the following?", "options": ["Analysing only those who completed treatment", "Analysing per protocol", "Analysing participants in the group to which they were randomised, whatever they actually received", "Excluding dropouts", "Analysing only compliant participants"], "key": "C", "type": "sba", "explanation": "Intention-to-treat preserves the benefit of randomisation and gives the more conservative and realistic estimate of effect. (Companion Ch 1; Hbk 7.2)", "answerPage": 192, "block": "G"}, {"n": 203, "page": 46, "stem": "A type I error is best described as which of the following?", "options": ["Failing to detect a real effect", "Recruiting too few participants", "Using the wrong statistical test", "Measuring the wrong outcome", "Concluding there is an effect when there is none"], "key": "E", "type": "sba", "explanation": "A type I error is a false positive, conventionally controlled at an alpha of 0.05. A type II error is a false negative. (Companion Ch 1; Hbk 7.2)", "answerPage": 192, "block": "G"}, {"n": 204, "page": 46, "stem": "Statistical power is conventionally set at which level?", "options": ["50 per cent", "80 to 90 per cent", "65 per cent", "95 per cent", "99 per cent"], "key": "B", "type": "sba", "explanation": "Power is conventionally 80 to 90 per cent, and equals 1 minus beta, the probability of a type II error. (Companion Ch 1; Hbk 7.2)", "answerPage": 193, "block": "G"}, {"n": 205, "page": 46, "stem": "An I squared value of 78 per cent in a meta-analysis indicates which of the following?", "options": ["Low heterogeneity", "Moderate heterogeneity", "A statistically significant result", "High heterogeneity", "Publication bias"], "key": "D", "type": "sba", "explanation": "Conventional thresholds are 25 per cent low, 50 per cent moderate and 75 per cent high heterogeneity. (Companion Ch 1; Hbk 7.2)", "answerPage": 193, "block": "G"}, {"n": 206, "page": 46, "stem": "A relative risk of 0.58 for new incisor trauma after early overjet reduction corresponds to what reduction in risk?", "options": ["58 per cent", "29 per cent", "42 per cent", "142 per cent", "It cannot be expressed as a percentage"], "key": "C", "type": "sba", "explanation": "A relative risk of 0.58 corresponds to a 42 per cent relative reduction in risk, although the confidence intervals in these trials are wide. (Cobourne 2022; Hbk 7.3 and 22.2)", "answerPage": 193, "block": "G"}, {"n": 207, "page": 46, "stem": "A funnel plot is used to assess which problem?", "options": ["Publication bias", "Heterogeneity", "Confounding", "Regression to the mean", "Loss to follow-up"], "key": "A", "type": "sba", "explanation": "Asymmetry of a funnel plot suggests publication bias, in which positive results are preferentially published. (Companion Ch 1; Hbk 7.2)", "answerPage": 193, "block": "G"}, {"n": 208, "page": 46, "stem": "A 95 per cent confidence interval for a relative risk that runs from 0.32 to 1.14 should be interpreted how?", "options": ["The result is statistically significant", "Heterogeneity is high", "The intervention is harmful", "The sample size was adequate", "The result is compatible with no effect, because the interval crosses 1"], "key": "E", "type": "sba", "explanation": "An interval for a ratio measure that crosses 1 is compatible with no effect. For a difference measure the equivalent value is 0. (Companion Ch 1; Hbk 7.2)", "answerPage": 193, "block": "G"}, {"n": 209, "page": 47, "stem": "Which trial overturned the belief that early Class II treatment improves the final result?", "options": ["Mandall 2016", "Scott 2008", "Benson 2021", "O’Brien 2009", "Penning 2017"], "key": "D", "type": "sba", "explanation": "O’Brien’s Manchester twin block trial reported no long-term difference, with the latetreated group finishing slightly better and the early group having more attendances. (O’Brien 2009; Hbk 7.3)", "answerPage": 193, "block": "G"}, {"n": 210, "page": 47, "stem": "Which studies established that self-ligating brackets are not faster than conventional brackets?", "options": ["Tulloch and Keeling", "Scott and Fleming", "Ericson and Kurol", "Baumrind and Frantz", "Kerr and Kochel"], "key": "B", "type": "sba", "explanation": "Scott, Fleming and colleagues found no difference in rate of movement, treatment time, number of visits or occlusal outcome. (Scott 2008; Fleming 2010; Hbk 7.3 and 17.3)", "answerPage": 193, "block": "G"}, {"n": 211, "page": 47, "stem": "Which body of work established that orthodontic treatment does not cause temporomandibular disorder?", "options": ["The Cochrane reviews of 2021", "The Royal London space analysis studies", "The Florida trial", "The Manchester twin block trial", "The American Association of Orthodontists funded studies of 1992"], "key": "E", "type": "sba", "explanation": "Behrents and White reported the AAO-funded studies in 1992, showing no significant association and that TMD cannot be prevented by any intervention. (Behrents and White 1992; Hbk 7.3 and 26.2)", "answerPage": 193, "block": "G"}, {"n": 212, "page": 47, "stem": "The 2021 Cochrane review on interceptive extraction of the primary canine concluded what?", "options": ["Strong evidence that it prevents impaction", "Very weak evidence that it increases eruption, and no evidence that it reduces the need for surgery", "That double extraction is superior", "That it should be performed in all cases", "That it increases the need for surgery"], "key": "B", "type": "sba", "explanation": "Benson and colleagues found only very weak evidence for improved eruption and none for reducing surgical need, and no benefit from double extraction. (Benson 2021; Hbk 7.3 and 20.4)", "answerPage": 193, "block": "G"}, {"n": 213, "page": 47, "stem": "Penning and colleagues in 2017 studied customised appliances and found what?", "options": ["A significant reduction in treatment time", "Fewer appointments", "Superior occlusal outcomes", "Comparable outcomes with no reduction in treatment time, more breakages and more planning time", "Reduced root resorption"], "key": "D", "type": "sba", "explanation": "The randomised trial found comparable outcomes and no time saving, with more breakages, more complaints and more planning time. Treatment time was dictated by case difficulty and by the treating orthodontist. (Penning 2017; Hbk 7.3 and 17.3)", "answerPage": 193, "block": "G"}, {"n": 214, "page": 47, "stem": "Which conclusion about the effect of extraction on the airway is supported by the evidence?", "options": ["There is no evidence that extraction-based treatment reduces the oropharyngeal airway or increases sleep apnoea", "Extraction reliably narrows the oropharyngeal airway", "Extraction increases apnoea-hypopnoea index by 30 per cent", "Only premolar extraction affects the airway", "The evidence is strongly positive for harm"], "key": "A", "type": "sba", "explanation": "Larsen and Orabi found no evidence of harm, and the claim has been described in the literature as scaremongering and marketing. (Larsen 2015; Orabi 2021; Hbk 7.3 and 13.6)", "answerPage": 193, "block": "G"}, {"n": 215, "page": 48, "stem": "Baumrind’s 1984 work is cited in relation to which conclusion?", "options": ["Optimal force levels", "Anchorage loss during space closure", "The unreliability of cephalometric growth prediction", "Root resorption incidence", "Self-ligation"], "key": "C", "type": "sba", "explanation": "Cephalometric growth prediction was shown to be at best unreliable and no better than chance. (Baumrind 1984; Hbk 7.3 and 10.4)", "answerPage": 193, "block": "G"}, {"n": 216, "page": 48, "stem": "Number needed to treat is calculated as which of the following?", "options": ["1 divided by the relative risk", "The relative risk multiplied by 100", "The reciprocal of the odds ratio", "1 divided by the absolute risk reduction", "The absolute risk multiplied by the sample size"], "key": "D", "type": "sba", "explanation": "NNT is the reciprocal of the absolute risk reduction, and is the measure patients understand most readily. (Companion Ch 1; Hbk 7.2)", "answerPage": 193, "block": "G"}, {"n": 217, "page": 48, "stem": "Which single statement about the orthodontic evidence base is the most defensible in an oral examination?", "options": ["It is as robust as that of cardiology", "It is thin, with few large randomised trials, and several long-held beliefs have not survived it", "It is entirely absent", "It consists only of case reports", "It has been settled by consensus statements"], "key": "B", "type": "sba", "explanation": "Acknowledging the weakness of the evidence base, and naming the studies that overturned tradition, is the fastest way to demonstrate scholarship. (Companion Ch 1; Hbk 7.3)", "answerPage": 193, "block": "G"}, {"n": 218, "page": 48, "stem": "Richardson’s work of 2002 relates to which conclusion?", "options": ["Aligners are inferior on ABO-OGS", "Self-ligation is not faster", "Extraction does not damage the profile", "Growth prediction is unreliable", "Third molars are not a primary cause of late lower incisor crowding"], "key": "E", "type": "sba", "explanation": "Richardson’s work, supported by NICE guidance, established that third molars are not a primary cause of late lower incisor crowding. (Richardson 2002; NICE; Hbk 7.3 and 19.4)", "answerPage": 193, "block": "G"}, {"n": 219, "page": 48, "stem": "Luther’s 2007 conclusion concerned which belief?", "options": ["That an ideal functional occlusion improves stability and prevents TMD", "That extraction narrows the airway", "That early treatment shortens overall treatment", "That RME improves nasal breathing", "That headgear is more effective than a functional appliance"], "key": "A", "type": "sba", "explanation": "Luther found no evidence that an ideal functional occlusion improves stability or prevents temporomandibular disorder. (Luther 2007; Hbk 7.3)", "answerPage": 193, "block": "G"}, {"n": 220, "page": 48, "stem": "Bowman and Johnston in 2000 concluded what about extraction and the profile?", "options": ["Extraction reliably flattens the profile", "Extraction always improves the profile", "Lip retraction must be considerable before a profile is regarded as unattractive", "The profile is unaffected by incisor position", "Only non-extraction treatment preserves the profile"], "key": "C", "type": "sba", "explanation": "Bowman and Johnston found that lip retraction must be considerable before the profile is judged unattractive, and comparable cases treated either way show little facial difference. (Bowman and Johnston 2000; Hbk 13.6)", "answerPage": 193, "block": "G"}, {"n": 221, "page": 48, "stem": "Which study design is most susceptible to selection bias?", "options": ["Randomised controlled trial", "Retrospective case-control study", "Systematic review of randomised trials", "Meta-analysis", "Split-mouth randomised trial"], "key": "B", "type": "sba", "explanation": "Retrospective case-control designs are particularly susceptible to selection bias in the choice of cases and controls. (Companion Ch 1; Hbk 7.1)", "answerPage": 193, "block": "G"}, {"n": 222, "page": 49, "stem": "A split-mouth design is particularly appropriate for which type of orthodontic question?", "options": ["Comparing surgical with non-surgical Class III correction", "Comparing early with late Class II treatment", "Comparing two extraction patterns", "Comparing two bonding adhesives", "Comparing retention regimens"], "key": "D", "type": "sba", "explanation": "A split-mouth design suits localised interventions with no carry-across effect, such as adhesive or bracket comparisons. It is inappropriate where the intervention affects the whole patient. (Companion Ch 1; Hbk 7.2)", "answerPage": 193, "block": "G"}, {"n": 223, "page": 49, "stem": "The GRADE approach is used to assess which of the following?", "options": ["The certainty of the evidence for an outcome", "The size of a treatment effect", "The cost of an intervention", "The prevalence of a condition", "The statistical power of a study"], "key": "A", "type": "sba", "explanation": "GRADE rates the certainty of evidence, downgrading for risk of bias, inconsistency, indirectness, imprecision and publication bias. (Companion Ch 1; Hbk 7.2)", "answerPage": 194, "block": "G"}, {"n": 224, "page": 49, "stem": "Which single factor most commonly downgrades the certainty of evidence in orthodontic Cochrane reviews?", "options": ["Publication bias", "Indirectness of population", "Risk of bias and imprecision arising from small, unblinded trials", "Excessive sample sizes", "Absence of a comparator"], "key": "C", "type": "sba", "explanation": "Orthodontic trials are typically small, with operator blinding impossible, so risk of bias and imprecision are the commonest reasons for downgrading. (Companion Ch 1; Hbk 7.2)", "answerPage": 194, "block": "G"}, {"n": 225, "page": 49, "stem": "An orthodontic claim is supported only by a series of 15 consecutively treated cases with no control group. Where does this sit in the hierarchy of evidence?", "options": ["Above a cohort study", "It has no place in the hierarchy", "At the level of a randomised trial", "At the level of a systematic review", "Below a cohort study and above expert opinion"], "key": "E", "type": "sba", "explanation": "A case series sits below cross-sectional and cohort designs and above expert opinion. It cannot establish causation. (Companion Ch 1; Hbk 7.1)", "answerPage": 194, "block": "G"}, {"n": 226, "page": 50, "stem": "Which three elements are required for consent to be valid?", "options": ["Capacity, sufficient information and voluntariness", "A signed form, a witness and a chaperone", "Capacity, cost disclosure and a cooling-off period", "Written information, a second opinion and a signature", "Age over 16, a parent present and a written estimate"], "key": "A", "type": "sba", "explanation": "Valid consent requires capacity, sufficient information and voluntariness, and it is a process rather than a single event. (GDC Standards; Hbk 8.1)", "answerPage": 194, "block": "H"}, {"n": 227, "page": 50, "stem": "The Montgomery standard requires disclosure of which risks?", "options": ["Only risks occurring in more than 1 per cent of cases", "Only risks the clinician considers material", "Risks to which a reasonable patient in the patient’s position would attach significance", "Only risks specified by the regulator", "All conceivable risks without exception"], "key": "C", "type": "sba", "explanation": "Montgomery replaced the professional standard with a patient-centred one: the material risks are those a reasonable patient in that position would attach significance to. (GDC Standards; Hbk 8.1)", "answerPage": 194, "block": "H"}, {"n": 228, "page": 50, "stem": "Which alternative must always be discussed as part of orthodontic consent?", "options": ["Treatment by a specialist only", "Surgical treatment in every case", "Treatment abroad", "Treatment with aligners specifically", "The alternative of no treatment, and what will happen if nothing is done"], "key": "E", "type": "sba", "explanation": "All reasonable alternatives must be discussed, including the option of no treatment and its consequences. (GDC Standards; Hbk 8.1)", "answerPage": 194, "block": "H"}, {"n": 229, "page": 50, "stem": "Which single statement about a signed consent form is correct?", "options": ["It constitutes consent", "It is evidence that a consent process took place, but is not itself consent", "It removes liability for complications", "It is required only for surgical procedures", "It is valid indefinitely"], "key": "B", "type": "sba", "explanation": "A signed form is evidence of consent, not consent itself. What matters is the discussion, and the record of it. (GDC Standards; Hbk 8.1 and 30.3)", "answerPage": 194, "block": "H"}, {"n": 230, "page": 50, "stem": "Gillick competence describes which situation?", "options": ["Emergency treatment without consent", "A parent’s right to override a child’s refusal", "An adult lacking capacity", "A child under 16 with sufficient understanding to consent to treatment", "Consent by a sibling"], "key": "D", "type": "sba", "explanation": "Gillick competence describes a child under 16 with sufficient understanding and intelligence to understand fully what is proposed. (GDC Standards; Hbk 8.2)", "answerPage": 194, "block": "H"}, {"n": 231, "page": 50, "stem": "Capacity is best described as which of the following?", "options": ["A fixed attribute of an individual", "Determined solely by age", "Decision-specific and time-specific, assessed by a four-part functional test", "Determined by the treating clinician’s judgement of the patient’s intelligence", "Present only in adults"], "key": "C", "type": "sba", "explanation": "Capacity is decision- and time-specific and is assessed by whether the person can understand, retain, weigh and communicate the decision. (Mental capacity legislation; Hbk 8.2)", "answerPage": 194, "block": "H"}, {"n": 232, "page": 51, "stem": "What is the approximate prevalence of body dysmorphic disorder among orthodontic patients?", "options": ["5 to 13 per cent", "1 to 3 per cent", "Under 1 per cent", "20 to 25 per cent", "Over 30 per cent"], "key": "A", "type": "sba", "explanation": "Body dysmorphic disorder affects 5 to 13 per cent of orthodontic patients, against 0.7 to 2.5 per cent of the general population and up to 17 per cent of those seeking orthognathic surgery. (Dons 2022; Hbk 8.3)", "answerPage": 194, "block": "H"}, {"n": 233, "page": 51, "stem": "Which single feature is the strongest red flag for body dysmorphic disorder in an orthodontic consultation?", "options": ["A request for aligners rather than fixed appliances", "A history of two previous courses of successful treatment", "A request for a second opinion", "Anxiety about the cost", "Preoccupation with a defect that is trivial or invisible to the clinician, with serial dissatisfaction with previous treatment"], "key": "E", "type": "sba", "explanation": "Preoccupation with an imperceptible defect, serial dissatisfaction and refusal to accept reassurance are the classic features. (Dons 2022; Hbk 8.3)", "answerPage": 194, "block": "H"}, {"n": 234, "page": 51, "stem": "Which statement about motivation and cooperation is best supported?", "options": ["Cooperation can be reliably predicted at the first visit", "Cooperation correlates with IOTN grade", "Girls cooperate better than boys", "Internally motivated patients cooperate better than those brought by a parent or dentist", "Cooperation is unrelated to attendance history"], "key": "D", "type": "sba", "explanation": "No reliable predictor of cooperation exists. Internal motivation is the best available proxy, along with attendance history and hygiene at assessment. (Mosby ch. on motivation; Hbk 8.3)", "answerPage": 194, "block": "H"}, {"n": 235, "page": 51, "stem": "Which appliance type is associated with the highest discontinuation rates in children and adolescents?", "options": ["Fixed labial appliances", "Removable appliances", "Bonded retainers", "Transpalatal arches", "Lingual appliances"], "key": "B", "type": "sba", "explanation": "Klaus and colleagues reported high discontinuation rates in children and adolescents, especially with removable appliances. (Klaus 2017; Hbk 8.3)", "answerPage": 194, "block": "H"}, {"n": 236, "page": 51, "stem": "Which benefit of orthodontic treatment has the best supporting evidence?", "options": ["Improved periodontal health", "Reduced caries incidence", "Improved speech", "Improved masticatory efficiency", "Psychosocial benefit and improved dental aesthetics"], "key": "E", "type": "sba", "explanation": "Psychosocial benefit and dental aesthetics are the best-supported benefits. The functional claims all require qualifiers. (Proffit Ch 1; Hbk 29.1)", "answerPage": 194, "block": "H"}, {"n": 237, "page": 51, "stem": "Seehra and colleagues in 2011 reported which finding?", "options": ["Orthodontic treatment improves long-term psychological health", "Increased overjet makes a child more susceptible to teasing and bullying", "Aligners are preferred by adolescents", "Extraction improves self-esteem", "Retention compliance is high"], "key": "B", "type": "sba", "explanation": "Seehra found that increased overjet increases susceptibility to teasing and bullying, which is a legitimate treatment indication. (Seehra 2011; Hbk 8.3)", "answerPage": 194, "block": "H"}, {"n": 238, "page": 51, "stem": "Kenealy and colleagues in 2007 concluded what about the long-term psychological effects of orthodontic treatment?", "options": ["There is strong evidence of lasting benefit", "Benefit is confined to females", "Treatment worsens psychological health", "There is little objective evidence that treatment improves long-term psychological health", "Benefit is proportional to PAR reduction"], "key": "D", "type": "sba", "explanation": "Kenealy found little objective evidence of long-term psychological benefit. Do not overclaim this at consent. (Kenealy 2007; Hbk 8.3)", "answerPage": 194, "block": "H"}, {"n": 239, "page": 52, "stem": "Javidi and colleagues in 2017 found that orthodontic treatment improves which domains of oral health related quality of life?", "options": ["The emotional and social well-being domains", "The functional limitation and physical pain domains", "The psychological disability domain only", "All domains equally", "No domains"], "key": "A", "type": "sba", "explanation": "Javidi reported improvement in the emotional and social well-being domains of OHRQoL. (Javidi 2017; Hbk 8.3)", "answerPage": 194, "block": "H"}, {"n": 240, "page": 52, "stem": "A 13-year-old wants fixed appliances but her plaque control is poor and there is generalised marginal gingivitis. What is the most appropriate action?", "options": ["Place the appliance and reinforce hygiene at each visit", "Place the appliance but use glass ionomer for all bonds", "Defer active treatment, institute a documented oral hygiene programme with review, and re-assess", "Refer for periodontal surgery", "Offer aligners instead as they are removable"], "key": "C", "type": "sba", "explanation": "Demineralisation in elective treatment that the clinician chose to start is indefensible. Defer, document, review and re-assess. (Companion Ch 2; Hbk 8.3 and 29.2)", "answerPage": 194, "block": "H"}, {"n": 241, "page": 52, "stem": "Which of the four principles of biomedical ethics is most directly engaged by the existence of indices of orthodontic treatment need?", "options": ["Autonomy", "Beneficence", "Non-maleficence", "Justice", "Veracity"], "key": "D", "type": "sba", "explanation": "Indices exist to allocate a scarce, largely publicly funded resource, which is the principle of justice applied to orthodontics. (Companion Ch 2; Hbk 8.3)", "answerPage": 195, "block": "H"}, {"n": 242, "page": 52, "stem": "Which single item must be discussed at consent and is most frequently omitted by candidates?", "options": ["The cost of treatment", "That retention is lifelong if the result is to be held, and that this is agreed before treatment begins", "The name of the bracket system", "The number of archwires that will be used", "The manufacturer of the adhesive"], "key": "B", "type": "sba", "explanation": "Retention is agreed before active treatment begins, not mentioned at debond. It is one of the twelve traps that cost most marks. (Companion Ch 13; Hbk 8.1 and 19.3)", "answerPage": 195, "block": "H"}, {"n": 243, "page": 52, "stem": "A child assents to treatment but the parent refuses. What is the correct position?", "options": ["Proceed on the child’s assent alone", "Proceed if the IOTN grade is 4 or above", "Refer to a court immediately", "Proceed if the child is over 12", "Treatment should not proceed without consent from a person with parental responsibility"], "key": "E", "type": "sba", "explanation": "Consent must be obtained from a person with parental responsibility for a child who is not Gillick competent. Elective treatment should not proceed without it. (GDC Standards; Hbk 8.2)", "answerPage": 195, "block": "H"}, {"n": 244, "page": 52, "stem": "Which single statement about a child’s assent is correct?", "options": ["It is clinically decisive, because a technically ideal plan the child will not wear is not a plan", "It is legally sufficient for elective treatment in all cases", "It is irrelevant if the parent consents", "It is required only for surgical procedures", "It replaces the need for parental consent after age 14"], "key": "A", "type": "sba", "explanation": "Even where parental consent is legally sufficient, the child’s assent determines whether the appliance is worn and therefore whether the plan will work. (Nanda; Hbk 8.2)", "answerPage": 195, "block": "H"}, {"n": 245, "page": 53, "stem": "Which is the correct way to check understanding at the end of a consent discussion?", "options": ["Ask whether the patient has any questions", "Provide a leaflet and ask them to sign", "Ask the patient to tell you back, in their own words, what has been agreed", "Repeat the information a second time", "Ask the parent whether the child understood"], "key": "C", "type": "sba", "explanation": "Asking the patient to restate what has been agreed is the recognised method of checking understanding, and should be recorded. (GDC Standards; Hbk 8.1)", "answerPage": 195, "block": "H"}, {"n": 246, "page": 53, "stem": "Which single figure should be quoted at consent about demineralisation?", "options": ["It affects fewer than 1 in 100 patients", "It affects up to half of fixed appliance patients and can be visible within 6 months", "It affects only patients with poor diet", "It affects around 5 per cent", "It affects only the lower incisors"], "key": "B", "type": "sba", "explanation": "White spot lesions affect up to half of fixed appliance patients and are visible within 6 months, commonest on first molars, upper laterals and lower canines. (Gorelick 1982; Hbk 8.1 and 29.2)", "answerPage": 195, "block": "H"}, {"n": 247, "page": 53, "stem": "An adult self-refers requesting aligner treatment, having been dissatisfied with two previous courses of orthodontics elsewhere and presenting extensive photographic documentation of a discrepancy you cannot see. What is the most appropriate response?", "options": ["Begin aligner treatment as requested", "Offer surgery", "Refer directly to an orthodontist for immediate treatment", "Explore the patient’s expectations carefully, consider body dysmorphic disorder, and do not commit to treatment at this visit", "Discharge the patient without explanation"], "key": "D", "type": "sba", "explanation": "Serial dissatisfaction with a defect invisible to the clinician is a red flag. Careful exploration of expectations, and declining to commit at that visit, is the safe response. (Dons 2022; Hbk 8.3)", "answerPage": 195, "block": "H"}, {"n": 248, "page": 53, "stem": "Which item of information about cost should be given at the outset?", "options": ["The total fee and the cost of replacing lost or broken retainers", "Only the total treatment fee", "Only the deposit", "Nothing, until treatment is complete", "Only the cost of records"], "key": "A", "type": "sba", "explanation": "Cost is part of valid consent, and the cost of replacement retainers is the item most often omitted and most often disputed later. (GDC Standards; Hbk 8.1 and 19.3)", "answerPage": 195, "block": "H"}, {"n": 249, "page": 53, "stem": "Which single statement about consent as a process is correct?", "options": ["Consent obtained at the assessment visit covers all subsequent changes of plan", "Consent may be delegated to a nurse", "A material change of plan during treatment requires the consent discussion to be revisited and recorded", "Consent is required only before the first appliance is fitted", "Consent expires after 12 months"], "key": "C", "type": "sba", "explanation": "A material change of plan, such as a decision to extract or to proceed to surgery, requires the consent discussion to be repeated and recorded. (GDC Standards; Hbk 8.1 and 30.3)", "answerPage": 195, "block": "H"}, {"n": 250, "page": 53, "stem": "Which of the following best describes the role of the patient’s own concern in treatment planning?", "options": ["It is subordinate to the occlusal analysis", "It determines the appliance but not the aims", "It is relevant only in adults", "It should be recorded but not acted upon", "It is the outcome measure against which treatment will ultimately be judged"], "key": "E", "type": "sba", "explanation": "The patient’s own concern sets the outcome against which the treatment will be judged, which is why it is recorded first and ranked highly in the problem list. (Proffit Ch 6; Hbk 8.3 and 12.4)", "answerPage": 195, "block": "H"}, {"n": 251, "page": 54, "stem": "Which is the most appropriate response to a parent who has read online that orthodontic extractions cause facial collapse?", "options": ["Explain that comparable cases treated with and without extraction show little or no facial difference, and that lip retraction must be considerable before a profile is judged unattractive", "Agree and plan non-extraction treatment regardless", "Decline to discuss the point", "Refer the family elsewhere", "Provide a leaflet without discussion"], "key": "A", "type": "sba", "explanation": "The comparative evidence should be explained plainly. Rushing, Paquette, Iared and Bowman and Johnston are the relevant sources. (Bowman and Johnston 2000; Hbk 13.6)", "answerPage": 195, "block": "H"}, {"n": 252, "page": 54, "stem": "A patient asks whether orthodontic treatment will cure their jaw clicking. What is the most appropriate reply?", "options": ["It usually does", "It will cure it if the occlusion is perfected", "There is no evidence that orthodontic treatment reduces temporomandibular disorder signs and symptoms, and none that it causes them", "It will worsen it", "Orthodontics should be avoided in anyone with a click"], "key": "C", "type": "sba", "explanation": "The examinable position is that orthodontics is TMJ-neutral. Do not promise a cure, and do not let a click drive irreversible occlusal change. (Macfarlane 2009; Luther 2010; Hbk 26.2)", "answerPage": 195, "block": "H"}, {"n": 253, "page": 54, "stem": "A 16-year-old asks that her parents not be told the details of her orthodontic treatment. What is the most appropriate approach?", "options": ["Refuse and inform the parents in full", "Continue treatment without records", "Discharge her from care", "Inform the parents only in writing", "Explore her reasons, respect confidentiality where she has capacity, and encourage but not compel parental involvement"], "key": "E", "type": "sba", "explanation": "A 16-year-old is presumed to have capacity. Confidentiality should be respected while encouraging, not compelling, parental involvement. (GDC Standards; Hbk 8.2)", "answerPage": 195, "block": "H"}, {"n": 254, "page": 54, "stem": "Which single statement about eating disorders and orthodontic treatment is correct?", "options": ["They are an absolute contraindication for life", "Elective treatment should be deferred while the disorder is active, with liaison and preventive care in the interim", "They have no relevance to orthodontics", "They contraindicate only removable appliances", "They require antibiotic cover"], "key": "B", "type": "sba", "explanation": "Active eating disorders are a reason to defer elective treatment, with liaison, prevention and management of erosion in the interim. (Companion Ch 7; Hbk 29.3)", "answerPage": 195, "block": "H"}, {"n": 255, "page": 54, "stem": "Which statement about the elective nature of orthodontic treatment is correct?", "options": ["It lowers the standard of consent required", "It removes the need to discuss alternatives", "It has no bearing on consent", "It raises the standard, because the patient is healthy and the treatment is chosen rather than needed", "It applies only to adult patients"], "key": "D", "type": "sba", "explanation": "Elective treatment on a healthy dentition raises rather than lowers the consent standard, and makes foreseeable complications such as demineralisation harder to defend. (GDC Standards; Hbk 8.1)", "answerPage": 195, "block": "H"}, {"n": 256, "page": 55, "stem": "In which position should a patient be seated for extra-oral examination?", "options": ["Supine with the head supported", "Reclined at 45 degrees", "Upright, Frankfort plane horizontal, in natural head position, teeth in centric occlusion and lips at rest", "Standing with the head tilted forward", "Upright with the mouth open"], "key": "C", "type": "sba", "explanation": "Natural head position with the Frankfort plane horizontal, teeth in occlusion and lips at rest is the reproducible standard. (Companion Ch 7; Hbk 9.2)", "answerPage": 195, "block": "I"}, {"n": 257, "page": 55, "stem": "Which single finding most changes the urgency of treating a crossbite?", "options": ["The presence of a mandibular displacement on closing", "The number of teeth involved", "The patient’s age", "The IOTN aesthetic component grade", "The overjet"], "key": "A", "type": "sba", "explanation": "A crossbite with a displacement is treated on diagnosis; one without a displacement is treated when convenient. (Companion Ch 12; Hbk 24.1)", "answerPage": 195, "block": "I"}, {"n": 258, "page": 55, "stem": "Competent lips are best defined as which of the following?", "options": ["Lips that meet with muscular effort", "Lips that cover the upper incisors completely", "Lips that meet only on swallowing", "Lips with an interlabial gap under 6 mm", "Lips that meet at rest with no muscular effort"], "key": "E", "type": "sba", "explanation": "Competent lips meet at rest without muscular effort. Potentially competent lips would meet but for proclined incisors; incompetent lips do not meet at rest. (Companion Ch 7; Hbk 9.2)", "answerPage": 196, "block": "I"}, {"n": 259, "page": 55, "stem": "What interlabial gap is regarded as the key soft tissue sign of vertical excess?", "options": ["Over 1 mm", "Over 12 mm", "Over 8 mm", "Over 3 to 4 mm", "Any measurable gap"], "key": "D", "type": "sba", "explanation": "An interlabial gap greater than 3 to 4 mm is the key soft tissue sign of vertical excess and of a skeletal open bite tendency. (Nanda; Hbk 9.2 and 25.2)", "answerPage": 196, "block": "I"}, {"n": 260, "page": 55, "stem": "What is the approximate normal maxillary-mandibular plane angle?", "options": ["17 degrees", "27 degrees", "22 degrees", "34 degrees", "40 degrees"], "key": "B", "type": "sba", "explanation": "The maxillary-mandibular plane angle is approximately 27 degrees plus or minus 4, as is the Frankfort-mandibular plane angle. (Companion Ch 7; Hbk 10.2)", "answerPage": 196, "block": "I"}, {"n": 261, "page": 55, "stem": "Lower anterior face height normally represents approximately what proportion of total anterior face height?", "options": ["45 per cent", "50 per cent", "75 per cent", "65 per cent", "55 per cent"], "key": "E", "type": "sba", "explanation": "Lower anterior face height is approximately 55 per cent plus or minus 2 of total anterior face height. (Companion Ch 7; Hbk 10.2)", "answerPage": 196, "block": "I"}, {"n": 262, "page": 56, "stem": "What proportion of the upper incisor crown is revealed by an average smile?", "options": ["25 to 50 per cent", "75 to 100 per cent", "50 to 75 per cent", "100 per cent plus 4 mm of gingiva", "Under 25 per cent"], "key": "B", "type": "sba", "explanation": "An average smile reveals 75 to 100 per cent of the upper incisor crown plus up to 2 mm of gingiva. (Nanda; Hbk 9.2 and 18.4)", "answerPage": 196, "block": "I"}, {"n": 263, "page": 56, "stem": "The smile curve is parallel to the lower lip in approximately what proportion of people?", "options": ["40 per cent", "55 per cent", "70 per cent", "85 per cent", "Over 95 per cent"], "key": "D", "type": "sba", "explanation": "Approximately 85 per cent have a smile curve parallel to the lower lip, and approximately 90 per cent show a premolar as the terminal tooth in the smile. (Nanda; Hbk 18.4)", "answerPage": 196, "block": "I"}, {"n": 264, "page": 56, "stem": "A nasolabial angle of 75 degrees in a patient with a bimaxillary protrusion suggests which of the following?", "options": ["Incisor retraction is likely to improve the profile", "Incisor retraction will worsen the profile", "Incisor proclination is indicated", "The nasolabial angle is irrelevant to planning", "Surgery is mandatory"], "key": "A", "type": "sba", "explanation": "An acute nasolabial angle means retraction is likely to help. An obtuse angle means retraction will harm the profile. (Mosby ch. on space analysis; Hbk 9.2 and 21.2)", "answerPage": 196, "block": "I"}, {"n": 265, "page": 56, "stem": "From what age should the maxillary canine be palpated in the buccal sulcus at every examination?", "options": ["6 years", "12 years", "9 to 10 years", "14 years", "Only if the primary canine is mobile"], "key": "C", "type": "sba", "explanation": "Palpation of the buccal sulcus from 9 to 10 years is the single most important screening manoeuvre for the palatally displaced canine. (Ericson and Kurol; Hbk 9.3 and 20.4)", "answerPage": 196, "block": "I"}, {"n": 266, "page": 56, "stem": "What is the normal range of maximum mouth opening in an adult?", "options": ["20 to 25 mm", "25 to 35 mm", "At least 60 mm", "At least 40 mm", "There is no normal range"], "key": "D", "type": "sba", "explanation": "Maximum opening of at least 40 mm is regarded as normal. Deviation or deflection on opening should be recorded. (Companion Ch 2; Hbk 26.3)", "answerPage": 196, "block": "I"}, {"n": 267, "page": 56, "stem": "Which single record is most useful for permitting formal space analysis?", "options": ["Extra-oral photographs", "Study casts or an intra-oral scan", "A lateral cephalogram", "A panoramic radiograph", "A periapical of the incisors"], "key": "B", "type": "sba", "explanation": "Study casts or a scan permit measurement, space analysis and a medico-legal record of the starting point. (Companion Ch 7; Hbk 9.4)", "answerPage": 196, "block": "I"}, {"n": 268, "page": 56, "stem": "Which is the correct indication for a lateral cephalogram?", "options": ["Every orthodontic patient", "To predict growth", "Only in adults", "Only in Class III cases", "Where incisors will be moved significantly, growth will be modified, or surgery is planned"], "key": "E", "type": "sba", "explanation": "A lateral cephalogram is not justified routinely, and specifically not for minor tooth movement, nor on the basis of growth prediction alone. (Companion Ch 7; Hbk 9.4 and 10.4)", "answerPage": 196, "block": "I"}, {"n": 269, "page": 57, "stem": "Which parallax rule identifies the position of an unerupted tooth?", "options": ["The object that moves with the tube is lingual or palatal", "The object that moves with the tube is buccal", "The object that moves against the tube is palatal", "Movement direction is unrelated to position", "Parallax cannot be used for canines"], "key": "A", "type": "sba", "explanation": "The SLOB rule states that the object which moves in the Same direction as the tube shift is Lingual, and the one moving in the Opposite direction is Buccal. (Companion Ch 7; Hbk 9.4)", "answerPage": 196, "block": "I"}, {"n": 270, "page": 57, "stem": "Which imaging modality is required to assess the temporomandibular disc?", "options": ["Panoramic radiograph", "Cone beam computed tomography", "Magnetic resonance imaging", "Lateral cephalogram", "Submentovertex view"], "key": "C", "type": "sba", "explanation": "MRI is required for the disc and soft tissues. CBCT images bone but cannot image the disc or muscle. (Companion Ch 2; Hbk 10.5 and 26.3)", "answerPage": 196, "block": "I"}, {"n": 271, "page": 57, "stem": "Which single principle governs the taking of any orthodontic radiograph?", "options": ["As many views as possible for completeness", "Justification for the individual patient, optimisation and limitation", "Routine annual radiography", "Radiography only when requested by the patient", "Radiography at every visit"], "key": "B", "type": "sba", "explanation": "Justification, optimisation and limitation govern all exposures. There is no threshold dose, so every exposure must be individually justified. (Companion Ch 7; Hbk 9.4 and 30.2)", "answerPage": 196, "block": "I"}, {"n": 272, "page": 57, "stem": "Which examination finding would most strongly suggest a pseudo-Class III?", "options": ["A reverse overjet of 5 mm with no displacement", "Proclined lower incisors", "A Class III molar relationship a full unit bilaterally", "An anterior displacement from retruded contact position to intercuspal position, with an edge-to-edge incisor relationship in centric relation", "An increased lower face height"], "key": "D", "type": "sba", "explanation": "A pseudo-Class III manipulates back to an edge-to-edge relationship in centric relation. The prognosis is completely different from a true skeletal Class III. (Mosby ch. on Class III; Hbk 23.1)", "answerPage": 196, "block": "I"}, {"n": 273, "page": 57, "stem": "The rule of thirds divides the face using which landmarks?", "options": ["Glabella, subnasale and menton, with trichion", "Nasion, gonion and menton", "Porion, orbitale and menton", "Sella, nasion and A point", "Trichion, nasion and pogonion"], "key": "A", "type": "sba", "explanation": "The rule of thirds uses trichion, glabella, subnasale and menton. The lower third divides into one third upper lip and two thirds lower lip and chin. (Companion Ch 7; Hbk 9.2)", "answerPage": 196, "block": "I"}, {"n": 274, "page": 57, "stem": "Which single element of the history sets the outcome against which treatment will be judged?", "options": ["The medical history", "The family history", "The presenting complaint and what the patient expects treatment to achieve", "The dental attendance history", "The social history"], "key": "C", "type": "sba", "explanation": "The patient’s own concern is recorded first because it becomes the outcome measure. It also ranks highly in the problem list. (Proffit Ch 6; Hbk 9.1 and 12.4)", "answerPage": 196, "block": "I"}, {"n": 275, "page": 57, "stem": "Which finding on examination of a Class III patient most influences prognosis for camouflage?", "options": ["The molar relationship", "The presence of third molars", "The overbite", "The centre line", "The degree of existing dental compensation, particularly lower incisor inclination"], "key": "E", "type": "sba", "explanation": "A heavily compensated case has less room left for camouflage. Lower incisor inclination is the key measure. (Companion Ch 13; Hbk 23.1)", "answerPage": 196, "block": "I"}, {"n": 276, "page": 58, "stem": "Which is the appropriate set of extra-oral photographs for an orthodontic record?", "options": ["Frontal at rest, frontal smiling, profile and three-quarter", "Frontal only", "Profile only", "Frontal smiling and occlusal", "Three-quarter only"], "key": "A", "type": "sba", "explanation": "Four extra-oral views are standard: frontal at rest, frontal smiling, profile and threequarter, together with five intra-oral views. (Companion Ch 7; Hbk 9.4 and Part 4)", "answerPage": 196, "block": "I"}, {"n": 277, "page": 58, "stem": "Which single statement about vitality testing before orthodontic treatment is correct?", "options": ["It is required for every patient", "It is required only in adults", "It is required for any traumatised or discoloured tooth before force is applied, and the baseline recorded", "It is required only if the tooth is mobile", "It should be performed after appliance placement"], "key": "C", "type": "sba", "explanation": "Any traumatised or discoloured tooth requires vitality testing and a periapical radiograph before force is applied, with the baseline recorded. (Companion Ch 8; Hbk 9.4 and 20.7)", "answerPage": 196, "block": "I"}, {"n": 278, "page": 58, "stem": "What is the normal incisor show at rest in a young adult?", "options": ["0 to 1 mm", "The upper incisors should not show at rest", "6 to 8 mm", "10 mm", "2 to 4 mm"], "key": "E", "type": "sba", "explanation": "Incisor show at rest is approximately 2 to 4 mm in a young adult, decreasing with age as the upper lip lengthens. (Nanda; Hbk 9.2)", "answerPage": 197, "block": "I"}, {"n": 279, "page": 58, "stem": "Which is the appropriate order of examination?", "options": ["Intra-oral, then extra-oral, then history", "History, then extra-oral, then intra-oral", "Radiographs, then history, then examination", "Extra-oral, then history, then radiographs", "Any order, provided all elements are covered"], "key": "B", "type": "sba", "explanation": "A fixed order is required for reproducibility: complaint and history, then extra-oral, then intra-oral, then a provisional problem list, then a decision about records. (Companion Ch 7; Hbk 9.1)", "answerPage": 197, "block": "I"}, {"n": 280, "page": 58, "stem": "Which single feature should be recorded when describing an overbite?", "options": ["Its depth in millimetres only", "Its relationship to the curve of Spee", "Whether it is Class I or Class II", "Whether it is increased, average or reduced; complete or incomplete; and traumatic or not", "Its IOTN grade only"], "key": "D", "type": "sba", "explanation": "A complete description records the degree, whether it is complete to tooth or tissue or incomplete, and whether there is trauma. (Companion Ch 7; Hbk 9.3)", "answerPage": 197, "block": "I"}, {"n": 281, "page": 58, "stem": "A CBCT is being considered for an impacted canine. Which single justification is adequate?", "options": ["The patient has requested one", "It provides a more attractive image for the record", "Conventional imaging has not established the relationship of the canine to the lateral incisor root, and the answer will change management", "It is included in the practice fee", "It is routine for all impactions"], "key": "C", "type": "sba", "explanation": "Justification requires a specific question the scan will answer and evidence that the answer will change management, with conventional imaging having failed to answer it. (Companion Ch 7; Hbk 10.5)", "answerPage": 197, "block": "I"}, {"n": 282, "page": 58, "stem": "Which single statement about buccal corridors is correct?", "options": ["They are one component of smile aesthetics, and extraction does not reliably widen them", "They should always be eliminated", "They are widened by every extraction", "They determine the extraction decision", "They are measured on a lateral cephalogram"], "key": "A", "type": "sba", "explanation": "Meyer, Christou and Cheng found that extraction does not produce larger buccal corridors or a less attractive smile. (Meyer 2014; Hbk 9.2 and 13.6)", "answerPage": 197, "block": "I"}, {"n": 283, "page": 59, "stem": "Which single feature of the lower lip most influences a Class II division 1 malocclusion?", "options": ["Its vermilion thickness", "Its relationship to the E-line only", "Its colour", "Its length relative to the upper lip", "Whether it rests behind the upper incisors, forming a lip trap"], "key": "E", "type": "sba", "explanation": "A lower lip trap resting behind the upper incisors proclines them and retroclines the lowers, perpetuating the malocclusion. (Companion Ch 12; Hbk 9.2 and 22.1)", "answerPage": 197, "block": "I"}, {"n": 284, "page": 59, "stem": "Which of the following should be recorded before any orthodontic appliance is placed in an adult?", "options": ["The patient’s occupation", "The patient’s preferred appointment times", "The brand of toothpaste used", "Pre-existing gingival recession, with probing of every tooth", "The number of previous dental visits"], "key": "D", "type": "sba", "explanation": "Probing every adult and recording pre-existing recession is essential, both clinically and medico-legally. (Nanda; Hbk 27.1)", "answerPage": 197, "block": "I"}, {"n": 285, "page": 59, "stem": "Which single statement about the path of closure is correct?", "options": ["It is relevant only in Class III cases", "A deviation from retruded contact position to intercuspal position is one of the most important findings that can be made, and must be recorded", "It cannot be assessed clinically", "It is assessed only on mounted casts", "It is relevant only in adults"], "key": "B", "type": "sba", "explanation": "The path of closure changes urgency, prognosis and sometimes the diagnosis itself, as in pseudo-Class III and functional crossbite. (Companion Ch 7; Hbk 9.3)", "answerPage": 197, "block": "I"}, {"n": 286, "page": 60, "stem": "Standardisation of a lateral cephalogram is achieved by which device?", "options": ["A bite jig", "A rectangular collimator", "A phantom head", "A grid", "A cephalostat"], "key": "E", "type": "sba", "explanation": "The cephalostat holds the mid-sagittal plane at a fixed distance from source and film, keeping magnification constant and making films comparable. (Companion Ch 7; Hbk 10.1)", "answerPage": 197, "block": "J"}, {"n": 287, "page": 60, "stem": "For a lateral cephalogram, the teeth should be in which position?", "options": ["Maximum intercuspation", "Retruded contact position", "The rest position", "Edge to edge", "Wide open"], "key": "B", "type": "sba", "explanation": "The teeth are placed in retruded contact position with the lips at rest, in natural head position or with the Frankfort plane horizontal. (Companion Ch 7; Hbk 10.1)", "answerPage": 197, "block": "J"}, {"n": 288, "page": 60, "stem": "Which landmark is defined as the deepest concavity on the anterior maxilla between the anterior nasal spine and the alveolar crest?", "options": ["Nasion", "Pogonion", "B point", "A point", "Prosthion"], "key": "D", "type": "sba", "explanation": "A point is the deepest concavity on the anterior maxilla. It represents the anterior limit of the apical base, but no specific anatomical structure exists there. (Companion Ch 7; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 289, "page": 60, "stem": "What is the normal value for SNA?", "options": ["81 degrees plus or minus 3", "78 degrees plus or minus 3", "75 degrees plus or minus 3", "85 degrees plus or minus 3", "90 degrees plus or minus 3"], "key": "A", "type": "sba", "explanation": "SNA is 81 degrees plus or minus 3, SNB is 78 degrees plus or minus 3, and ANB is 3 degrees plus or minus 2. (Companion Ch 7; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 290, "page": 60, "stem": "An ANB of 6 degrees indicates which skeletal pattern?", "options": ["Class I", "Class III", "Class II", "It cannot be determined from ANB", "Bimaxillary retrusion"], "key": "C", "type": "sba", "explanation": "ANB of 2 to 4 degrees is Class I, greater than 4 degrees is Class II and less than 2 degrees is Class III, subject to the Eastman correction. (Companion Ch 7; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 291, "page": 60, "stem": "The Wits appraisal is measured between which structures?", "options": ["Sella and nasion", "Gonion and menton", "Porion and orbitale", "Perpendiculars from A and B points to the functional occlusal plane", "Nasion and pogonion"], "key": "D", "type": "sba", "explanation": "The Wits appraisal drops perpendiculars from A and B points to the functional occlusal plane, sidestepping cranial base error altogether. (Companion Ch 7; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 292, "page": 61, "stem": "Which normal value applies to the Wits appraisal in males?", "options": ["Plus 1 mm", "Minus 1 mm", "Minus 4 mm", "Plus 4 mm", "Zero in both sexes"], "key": "B", "type": "sba", "explanation": "The Wits appraisal is approximately minus 1 mm in males and 0 mm in females, both plus or minus 2 mm. (Companion Ch 7; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 293, "page": 61, "stem": "The Eastman correction adjusts ANB for which factor?", "options": ["The vertical dimension", "The position of porion", "Magnification error", "The occlusal plane cant", "The anteroposterior position of nasion and the inclination of the sella-nasion plane"], "key": "E", "type": "sba", "explanation": "The Eastman correction adjusts ANB by 0.5 degrees for every degree that the sellanasion to maxillary plane angle differs from 8 degrees, and for SNA differing from 81 degrees. (Cobourne cases; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 294, "page": 61, "stem": "Which is the normal value for upper incisor inclination to the maxillary plane?", "options": ["109 degrees plus or minus 6", "102 degrees plus or minus 6", "95 degrees plus or minus 6", "118 degrees plus or minus 6", "125 degrees plus or minus 6"], "key": "A", "type": "sba", "explanation": "Upper incisor to maxillary plane is 109 degrees plus or minus 6; lower incisor to mandibular plane is 93 degrees plus or minus 6. (Companion Ch 7; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 295, "page": 61, "stem": "Which is the normal value for the interincisal angle?", "options": ["110 degrees plus or minus 10", "120 degrees plus or minus 10", "135 degrees plus or minus 10", "150 degrees plus or minus 10", "160 degrees plus or minus 10"], "key": "C", "type": "sba", "explanation": "The interincisal angle is 135 degrees plus or minus 10, and its correction is essential to overbite stability. (Companion Ch 7; Hbk 10.2)", "answerPage": 197, "block": "J"}, {"n": 296, "page": 61, "stem": "Houston’s 1983 statement about cephalometrics was which of the following?", "options": ["Cephalometrics is the most accurate diagnostic tool available", "Cephalometrics is definitely not an exact science", "Cephalometrics should replace clinical examination", "Cephalometrics predicts growth reliably", "Cephalometrics is unnecessary in orthodontics"], "key": "B", "type": "sba", "explanation": "Houston’s aphorism is the one to quote when discussing the limitations of cephalometric analysis. (Houston 1983; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 297, "page": 61, "stem": "Baumrind and Frantz in 1971 demonstrated which finding about landmark identification?", "options": ["All landmarks have equal reliability", "Error is random and cancels out", "Error is eliminated by digitisation", "Each landmark has a characteristic non-circular envelope of error in x and y", "Only soft tissue landmarks are unreliable"], "key": "D", "type": "sba", "explanation": "Each landmark has its own non-circular envelope of error, and the error is cumulative because the same landmarks are reused across an analysis. (Baumrind and Frantz 1971; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 298, "page": 61, "stem": "Why are A and B points criticised as cephalometric landmarks?", "options": ["They are convenient rather than anatomical, and both remodel as the incisors move", "They are difficult to see on a radiograph", "They are bilateral structures", "They lie outside the mid-sagittal plane", "They are affected by head position only"], "key": "A", "type": "sba", "explanation": "A and B points represent the anterior limit of the apical bases but correspond to no specific anatomical structure, and they remodel as the incisors move. (Companion Ch 7; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 299, "page": 62, "stem": "Which single problem affects the Frankfort horizontal plane as a reference?", "options": ["It is easy to locate but variable between individuals", "It cannot be identified on a lateral cephalogram", "Porion and orbitale are both difficult to locate, are bilateral and must be averaged, and the plane does not lie in the mid-sagittal plane", "It changes with tooth movement", "It requires a CBCT to identify"], "key": "C", "type": "sba", "explanation": "Frankfort horizontal is sensitive to head positioning and to landmark error in porion and orbitale, both of which are bilateral and hard to locate. (Companion Ch 7; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 300, "page": 62, "stem": "Why must the enlargement factor of a cephalostat be known?", "options": ["To calculate radiation dose", "To choose the exposure time", "To identify landmarks", "To superimpose serial films", "To permit comparison of linear values between machines"], "key": "E", "type": "sba", "explanation": "Every machine has its own enlargement factor, which must be known before linear measurements are compared between machines. (Companion Ch 7; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 301, "page": 62, "stem": "Which of the following statements about cephalometric superimposition is correct?", "options": ["No method has been proved to deliver completely accurate results, and all carry appreciable error", "One method has been proved completely accurate", "Superimposition should be performed on outlines", "Superimposition is required for all patients", "Superimposition eliminates landmark error"], "key": "A", "type": "sba", "explanation": "Graf and colleagues concluded that no method has been proved completely accurate, and Baumrind and Ghafari found that all carry appreciable error with none clearly superior. (Graf 2022; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 302, "page": 62, "stem": "Superimposition on the mandible should use which structures?", "options": ["The lower border and the gonial angle", "The mandibular plane and menton", "The internal cortical outline of the symphysis, the mandibular canal and the tooth germ crypts", "The condylar outline", "The incisal edges"], "key": "C", "type": "sba", "explanation": "Bjork’s stable mandibular structures are the internal cortical outline of the symphysis, the mandibular canal and the tooth germ crypts. (Companion Ch 7; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 303, "page": 62, "stem": "In what order should the three superimpositions be performed?", "options": ["Mandible, maxilla, cranial base", "The order is immaterial", "Maxilla, mandible, cranial base", "Cranial base, mandible, maxilla", "Cranial base, maxilla, mandible"], "key": "E", "type": "sba", "explanation": "Cranial base first, showing total change of both jaws, then maxilla, then mandible. Always superimpose on structures, never on outlines. (Proffit Ch 6; Hbk 10.3)", "answerPage": 198, "block": "J"}, {"n": 304, "page": 62, "stem": "Cephalometric growth prediction should be regarded in which way?", "options": ["As reliable in Class II cases", "As at best unreliable, and never a justification for a radiograph on its own", "As accurate to within 1 mm", "As mandatory before functional appliance therapy", "As superior to serial films"], "key": "B", "type": "sba", "explanation": "Ricketts’ visualised treatment objective and Bjork’s implant studies underpinned growth prediction, which has since been shown to be at best unreliable. (Baumrind 1984; Hbk 10.4)", "answerPage": 198, "block": "J"}, {"n": 305, "page": 62, "stem": "What is the constructive alternative to cephalometric growth prediction?", "options": ["A single CBCT", "A three-dimensional facial scan alone", "Hand-wrist radiography alone", "Serial films approximately one year apart", "Genetic testing"], "key": "D", "type": "sba", "explanation": "Serial films about a year apart give a more accurate assessment of the direction of change, and are particularly valuable in Class III where decisions are deliberately deferred. (Companion Ch 7; Hbk 10.4)", "answerPage": 198, "block": "J"}, {"n": 306, "page": 63, "stem": "Which single limitation of CBCT is most relevant to temporomandibular assessment?", "options": ["It has a low radiation dose", "It cannot image cortical bone", "It cannot image the disc or the muscles", "It requires a cephalostat", "It is unavailable in most centres"], "key": "C", "type": "sba", "explanation": "CBCT images bone well but cannot image the disc, the retrodiscal tissues or muscle. That requires MRI. (Mosby ch. on imaging; Hbk 10.5 and 26.3)", "answerPage": 198, "block": "J"}, {"n": 307, "page": 63, "stem": "What proportion of CBCT scans are reported to contain incidental findings?", "options": ["From about a quarter to nearly all", "Approximately 10 per cent", "Under 5 per cent", "Approximately 15 per cent", "None"], "key": "A", "type": "sba", "explanation": "Reported rates of incidental findings on CBCT range from about a quarter to nearly all scans, depending on the definition and field of view. (Mosby ch. on imaging; Hbk 10.5)", "answerPage": 198, "block": "J"}, {"n": 308, "page": 63, "stem": "Which is a valid justification for a CBCT in orthodontics?", "options": ["To obtain a more attractive record", "To assess oral hygiene", "To predict growth", "To measure the overjet", "To assess an impacted tooth where conventional imaging is inadequate and where the result will change management"], "key": "E", "type": "sba", "explanation": "Impacted teeth where conventional imaging is inadequate, suspected resorption of adjacent incisor roots, clefts, complex asymmetry and orthognathic planning are the accepted indications. (Companion Ch 7; Hbk 10.5)", "answerPage": 198, "block": "J"}, {"n": 309, "page": 63, "stem": "Which statement about applying two-dimensional cephalometric norms to three-dimensional measurements is correct?", "options": ["They may be applied directly", "They apply only in adults", "They apply only to skeletal measurements", "They cannot be applied directly, because landmark definitions differ and no agreed normative database exists", "They apply only to angular measurements"], "key": "D", "type": "sba", "explanation": "Three-dimensional cephalometry removes projection error in principle, but landmark definitions differ from two-dimensional ones and there is no agreed normative database. (Mosby ch. on imaging; Hbk 10.5)", "answerPage": 198, "block": "J"}, {"n": 310, "page": 63, "stem": "Three-dimensional facial surface imaging by stereophotogrammetry has which principal advantage?", "options": ["It shows bone in detail", "It involves no ionising radiation and permits serial soft tissue superimposition", "It replaces the lateral cephalogram", "It images the temporomandibular disc", "It measures tooth movement directly"], "key": "B", "type": "sba", "explanation": "Stereophotogrammetry uses no ionising radiation and is useful for soft tissue outcome assessment and serial monitoring of asymmetry. (Haner 2021; Hbk 10.5)", "answerPage": 198, "block": "J"}, {"n": 311, "page": 63, "stem": "Which regions give good reproducibility for serial three-dimensional facial superimposition?", "options": ["The cheeks and the chin", "The ears", "The lips and the nasolabial folds", "The lower border of the mandible", "The forehead, mid-nose and infraorbital regions"], "key": "E", "type": "sba", "explanation": "Haner and colleagues reported good reproducibility using the forehead, mid-nose and infraorbital regions. (Haner 2021; Hbk 10.5 and 24.4)", "answerPage": 198, "block": "J"}, {"n": 312, "page": 63, "stem": "Which is the correct positioning for a posteroanterior cephalogram?", "options": ["Mid-sagittal plane perpendicular to the beam and parallel to the film", "Mid-sagittal plane parallel to the beam and perpendicular to the film", "Frankfort plane vertical", "The head rotated 45 degrees", "The patient supine"], "key": "B", "type": "sba", "explanation": "For a posteroanterior view the mid-sagittal plane is parallel to the beam and perpendicular to the film; the lateral view is the reverse. (Companion Ch 7; Hbk 10.1)", "answerPage": 198, "block": "J"}, {"n": 313, "page": 64, "stem": "Which is the principal difficulty in assessing asymmetry on a posteroanterior cephalogram?", "options": ["Radiation dose", "Patient cooperation", "Magnification", "Identifying the midsagittal plane", "Film size"], "key": "D", "type": "sba", "explanation": "Identifying a reliable midsagittal reference is the hard part of posteroanterior analysis of asymmetry. (Mosby ch. on asymmetry; Hbk 24.4)", "answerPage": 198, "block": "J"}, {"n": 314, "page": 64, "stem": "Which of the following is the normal range for the Holdaway angle?", "options": ["7 to 15 degrees", "0 to 5 degrees", "20 to 25 degrees", "30 to 40 degrees", "45 degrees plus"], "key": "A", "type": "sba", "explanation": "The Holdaway angle, describing the soft tissue profile, is normally 7 to 15 degrees. A value of 3.5 degrees or less favours surgery in Class III. (Companion Ch 13; Hbk 10.2 and 23.4)", "answerPage": 198, "block": "J"}, {"n": 315, "page": 64, "stem": "What is the normal position of the lower incisor relative to the A-pogonion line?", "options": ["Minus 4 mm", "Plus 4 mm", "0 mm plus or minus 2", "Plus 8 mm", "It is not a recognised measurement"], "key": "C", "type": "sba", "explanation": "Lower incisor to A-pogonion of 0 mm plus or minus 2 is the classical stability reference. (Companion Ch 7; Hbk 10.2)", "answerPage": 199, "block": "J"}, {"n": 316, "page": 64, "stem": "A radiograph is described as unjustified if which condition applies?", "options": ["The dose exceeds 1 mSv", "A previous radiograph exists", "The patient is under 16", "There is no specific clinical question that the radiograph will answer and that will change management", "It is taken in general practice"], "key": "D", "type": "sba", "explanation": "Justification requires a specific question and a change in management. Curiosity is not a justification, and there is no threshold dose. (Companion Ch 7; Hbk 9.4 and 30.2)", "answerPage": 199, "block": "J"}, {"n": 317, "page": 64, "stem": "Which is the appropriate first-line radiograph for a survey of the developing dentition?", "options": ["Lateral cephalogram", "Panoramic radiograph", "CBCT", "Full-mouth periapicals", "Occlusal view alone"], "key": "B", "type": "sba", "explanation": "The panoramic radiograph is the default survey film in orthodontics. It is not suitable for fine detail, for which periapicals are used. (Companion Ch 7; Hbk 9.4)", "answerPage": 199, "block": "J"}, {"n": 318, "page": 64, "stem": "Which single cephalometric threshold most strongly favours surgery in a Class III patient?", "options": ["ANB of minus 1 degree", "SNA of 79 degrees", "MMPA of 30 degrees", "Overjet of 0 mm", "Wits appraisal of minus 11 mm or worse"], "key": "E", "type": "sba", "explanation": "A Wits appraisal of minus 11 mm or worse is among the most important discriminators, with ANB of minus 4 degrees or worse and a reverse overjet of minus 5 mm or worse. (Kerr 1992; Hbk 23.4)", "answerPage": 199, "block": "J"}, {"n": 319, "page": 64, "stem": "Which cephalometric threshold favours surgery rather than camouflage in a Class II patient?", "options": ["Pogonion to nasion perpendicular of 18 mm or more", "Overjet greater than 6 mm", "MMPA less than 20 degrees", "ANB of 5 degrees", "SNB of 76 degrees"], "key": "A", "type": "sba", "explanation": "Proffit’s thresholds are overjet over 10 mm, pogonion to nasion perpendicular of 18 mm or more, mandibular body under 70 mm, or anterior face height over 125 mm. (Proffit 1992; Hbk 12.2)", "answerPage": 199, "block": "J"}, {"n": 320, "page": 65, "stem": "Which of the following best describes the correct role of cephalometric analysis?", "options": ["It replaces clinical examination", "It is the primary diagnostic tool", "It supplements a thorough clinical examination and does not attempt to replace it", "It determines the appliance to be used", "It is required for all patients"], "key": "C", "type": "sba", "explanation": "Cephalometric analysis supplements clinical examination. This is the correct closing stance in any answer on the subject. (Companion Ch 7; Hbk 10.3)", "answerPage": 199, "block": "J"}, {"n": 321, "page": 65, "stem": "Which measure would be most affected by an error in locating porion?", "options": ["SNA", "Frankfort-mandibular plane angle", "SNB", "Wits appraisal", "Interincisal angle"], "key": "B", "type": "sba", "explanation": "Frankfort horizontal depends on porion and orbitale, so an error in porion directly affects the Frankfort-mandibular plane angle. (Companion Ch 7; Hbk 10.3)", "answerPage": 199, "block": "J"}, {"n": 322, "page": 65, "stem": "Which single measure is least affected by cranial base morphology?", "options": ["SNA", "SNB", "ANB", "Wits appraisal", "Sella-nasion to mandibular plane"], "key": "D", "type": "sba", "explanation": "The Wits appraisal is measured to the functional occlusal plane and does not use the cranial base, which is why it is used when cranial base morphology is atypical. (Companion Ch 7; Hbk 10.2)", "answerPage": 199, "block": "J"}, {"n": 323, "page": 65, "stem": "Which statement about artificial intelligence assisted cephalometric landmarking is correct?", "options": ["It reduces error, and the main practical advantage of software is versatility rather than accuracy", "It has eliminated measurement error", "It is less reliable than manual tracing in all studies", "It removes the need for justification of the radiograph", "It is not yet available"], "key": "A", "type": "sba", "explanation": "Software reduces but does not eliminate error. Its main advantage is versatility: multiple analyses, superimposition and orthognathic prediction planning. (Companion Ch 7; Hbk 10.3)", "answerPage": 199, "block": "J"}, {"n": 324, "page": 65, "stem": "Which single step best reduces measurement error in a cephalometric research study?", "options": ["Increasing the exposure", "Using a larger sample", "Hand-tracing then digitising, repeating measurements, calibrating examiners and knowing the magnification", "Using only angular measurements", "Using digital rather than film-based images"], "key": "C", "type": "sba", "explanation": "Error reduction requires good films, correct positioning, optimal viewing conditions, repeated measurement, examiner calibration and knowledge of magnification. (Companion Ch 7; Hbk 10.3)", "answerPage": 199, "block": "J"}, {"n": 325, "page": 65, "stem": "What is the approximate exposure time of a modern solid-state cephalostat using horizontal scanning?", "options": ["0.1 seconds", "1 second", "60 seconds", "30 seconds", "10 seconds"], "key": "E", "type": "sba", "explanation": "Modern solid-state cephalostats scan horizontally over an approximately 10-second exposure. (Companion Ch 7; Hbk 10.1)", "answerPage": 199, "block": "J"}, {"n": 326, "page": 66, "stem": "Space analysis assesses how many areas of space requirement?", "options": ["Six", "Four", "Five", "Three", "Eight"], "key": "A", "type": "sba", "explanation": "The six areas are crowding or spacing, levelling the curve of Spee, arch width change, incisor anteroposterior change, angulation and inclination. (Companion Ch 8; Hbk 11.2)", "answerPage": 199, "block": "K"}, {"n": 327, "page": 66, "stem": "Approximately how much arch length is consumed by levelling a curve of Spee?", "options": ["0.5 mm per 1 mm of depth", "3 mm per 1 mm of depth", "Approximately 1 mm of arch length per 1 mm of curve depth", "Levelling does not consume arch length", "It depends only on the wire used"], "key": "C", "type": "sba", "explanation": "As a working rule, levelling consumes approximately 1 mm of arch length per 1 mm of curve depth. (Companion Ch 8; Hbk 11.2)", "answerPage": 199, "block": "K"}, {"n": 328, "page": 66, "stem": "How much usable space does arch expansion yield relative to the amount of expansion?", "options": ["The full amount", "Expansion yields no usable space", "Twice the amount", "One quarter", "Approximately half the amount of expansion"], "key": "E", "type": "sba", "explanation": "Expansion creates space equal to only about half the amount of expansion, which is why expansion is a poor substitute for extraction in significant crowding. (O’Higgins and Lee 2000; Hbk 11.2)", "answerPage": 199, "block": "K"}, {"n": 329, "page": 66, "stem": "How much space is required for each millimetre of incisor retraction?", "options": ["1 mm", "2 mm", "3 mm", "4 mm", "0.5 mm"], "key": "B", "type": "sba", "explanation": "Each millimetre of incisor retraction requires 2 mm of space, since the movement occurs on both sides of the arch. (Companion Ch 8; Hbk 11.2)", "answerPage": 199, "block": "K"}, {"n": 330, "page": 66, "stem": "Approximately how much space is consumed by 10 degrees of palatal root torque of the upper labial segment?", "options": ["0.25 mm", "5 mm", "3 mm", "1 mm", "None"], "key": "D", "type": "sba", "explanation": "Approximately 1 mm of space is consumed per 10 degrees of torque, which is why torque requirements must be included in the space analysis. (Cobourne cases; Hbk 11.2)", "answerPage": 199, "block": "K"}, {"n": 331, "page": 66, "stem": "What is the maximum interproximal reduction generally regarded as acceptable per contact in the buccal segments?", "options": ["0.1 mm", "0.25 mm", "Up to 1 mm", "2 mm", "3 mm"], "key": "C", "type": "sba", "explanation": "Up to approximately 1 mm per contact is acceptable in the buccal segments and approximately 0.5 mm anteriorly. (Companion Ch 8; Hbk 11.2)", "answerPage": 199, "block": "K"}, {"n": 332, "page": 67, "stem": "The relationship between the space requirements of the two arches should reflect which of the following?", "options": ["The molar relationship to which the case will be finished", "The patient’s age", "The anchorage available", "The appliance chosen", "The overbite"], "key": "A", "type": "sba", "explanation": "An equal requirement finishes Class I molars; a greater maxillary requirement finishes Class II molars. Getting this backwards makes the extraction pattern wrong before treatment starts. (Companion Ch 8; Hbk 11.2)", "answerPage": 200, "block": "K"}, {"n": 333, "page": 67, "stem": "Which named method of space analysis should be cited in an examination?", "options": ["The Bolton analysis", "The Little analysis", "The Moyers analysis", "The Tanaka-Johnston analysis", "The Royal London Hospital space analysis"], "key": "E", "type": "sba", "explanation": "Kirschen, O’Higgins and Lee described the Royal London Hospital space analysis, which assigns a millimetre value to every item. (Kirschen 2000; Hbk 11.2)", "answerPage": 200, "block": "K"}, {"n": 334, "page": 67, "stem": "What benefit of formal space analysis was reported by Al-Abdallah and colleagues?", "options": ["Shorter treatment times", "Fewer appointments", "Reduced root resorption", "A more disciplined and less varied approach, with more realistic aims and greater anticipation of anchorage requirements", "Better patient satisfaction scores"], "key": "D", "type": "sba", "explanation": "Formal analysis produces a more disciplined and less varied approach, particularly valuable for trainees. (Al-Abdallah 2008; Hbk 11.2)", "answerPage": 200, "block": "K"}, {"n": 335, "page": 67, "stem": "The Tanaka-Johnston prediction for the mandibular arch adds what value to half the sum of the mandibular incisor widths?", "options": ["9.5 mm", "10.5 mm", "11.0 mm", "12.0 mm", "13.5 mm"], "key": "B", "type": "sba", "explanation": "Tanaka-Johnston adds 10.5 mm per quadrant for the mandibular arch and 11.0 mm for the maxillary arch. (Proffit Ch 6; Hbk 11.3)", "answerPage": 200, "block": "K"}, {"n": 336, "page": 67, "stem": "Moyers probability tables predict the combined width of which teeth?", "options": ["The permanent incisors", "The third molars", "The permanent molars", "The primary molars", "The unerupted canine and premolars"], "key": "E", "type": "sba", "explanation": "Moyers tables predict the combined mesiodistal width of the unerupted canine and premolars from the measured mandibular incisors, usually at the 75 per cent probability level. (Proffit Ch 6; Hbk 11.3)", "answerPage": 200, "block": "K"}, {"n": 337, "page": 67, "stem": "When performing a mixed dentition space analysis, which item must be added to the space available?", "options": ["The Bolton discrepancy", "The leeway space", "The curve of Spee depth", "The overjet", "The intercanine width"], "key": "B", "type": "sba", "explanation": "The leeway space must be added to the space available, since it becomes available as the primary molars and canines are shed. (Companion Ch 5; Hbk 11.3)", "answerPage": 200, "block": "K"}, {"n": 338, "page": 68, "stem": "Which single statement about the digital set-up is correct?", "options": ["It predicts the biological response to treatment", "It shows root position without additional imaging", "It replaces the space analysis", "It is a geometric prediction only, containing no biology, no anchorage and no soft tissue response", "It guarantees the predicted outcome"], "key": "D", "type": "sba", "explanation": "A digital set-up shows what the teeth would look like if they went where you asked, not whether they will. It contains no biology and no anchorage. (Mosby ch. on digital planning; Hbk 11.4)", "answerPage": 200, "block": "K"}, {"n": 339, "page": 68, "stem": "In a case with 9 mm of crowding and a thin mandibular symphysis, a digital set-up showing full alignment without extraction fails to account for which factor?", "options": ["The alveolar envelope and the biological limit of lower incisor advance", "Bracket prescription", "The archwire sequence", "The bonding adhesive", "The retention regimen"], "key": "A", "type": "sba", "explanation": "A set-up cannot tell you that the lower incisors will be outside the alveolar envelope. The space analysis and the biological limit decide, not the software. (Mosby ch. on digital planning; Hbk 11.4)", "answerPage": 200, "block": "K"}, {"n": 340, "page": 68, "stem": "Which single phrase best captures the principal limitation of computer-aided planning?", "options": ["More is better", "Measure twice, cut once", "Garbage in, garbage out", "Form follows function", "Less is more"], "key": "C", "type": "sba", "explanation": "Errors enter at the scan, and in surgical planning at the bite registration. The output is only as good as the input. (Mosby ch. on digital planning; Hbk 11.4)", "answerPage": 200, "block": "K"}, {"n": 341, "page": 68, "stem": "Which measurement is used to quantify a tooth-size discrepancy?", "options": ["Little’s Irregularity Index", "The ICON index", "The PAR index", "The Bolton analysis", "The Wits appraisal"], "key": "D", "type": "sba", "explanation": "Bolton’s anterior ratio of 77.2 per cent and overall ratio of 91.3 per cent quantify toothsize discrepancy. (Companion Ch 7; Hbk 11.1)", "answerPage": 200, "block": "K"}, {"n": 342, "page": 68, "stem": "A Bolton overall ratio of 95 per cent indicates which of the following?", "options": ["Maxillary tooth-size excess", "Mandibular tooth-size excess", "No discrepancy", "A measurement error", "A Class III skeletal pattern"], "key": "B", "type": "sba", "explanation": "A ratio above the norm of 91.3 per cent indicates relative mandibular excess; below it indicates relative maxillary excess. (Companion Ch 7; Hbk 11.1)", "answerPage": 200, "block": "K"}, {"n": 343, "page": 68, "stem": "Which impression material is dimensionally unstable and must be cast promptly?", "options": ["Addition silicone", "Impression compound", "Polyether", "Condensation silicone", "Alginate"], "key": "E", "type": "sba", "explanation": "Alginate is dimensionally unstable and should be cast within about 10 minutes or stored in 100 per cent humidity. (Companion Ch 10; Hbk 15.4)", "answerPage": 200, "block": "K"}, {"n": 344, "page": 68, "stem": "Which impression material offers the greatest dimensional stability for appliance construction?", "options": ["Addition silicone", "Alginate", "Impression plaster", "Zinc oxide eugenol", "Agar"], "key": "A", "type": "sba", "explanation": "Addition silicone is dimensionally stable and accurate, and is used where accuracy matters, such as for bonded retainers and appliances. (Companion Ch 10; Hbk 15.4)", "answerPage": 200, "block": "K"}, {"n": 345, "page": 69, "stem": "Which is the correct method of measuring the depth of the curve of Spee on a study cast?", "options": ["From the incisal edge to the gingival margin", "From the mesial to the distal of the first molar", "From the deepest cusp tip to a plane joining the incisal edges and the distal cusp of the last molar", "From the occlusal plane to the mandibular plane", "It cannot be measured on a cast"], "key": "C", "type": "sba", "explanation": "The curve of Spee is measured from the deepest cusp tip to a plane joining the incisal edges and the distal cusp of the most posterior tooth. (Companion Ch 7; Hbk 11.1)", "answerPage": 200, "block": "K"}, {"n": 346, "page": 69, "stem": "Which of the following is not a source of space in a space analysis?", "options": ["Extraction", "Space opening for a prosthesis", "Molar distal movement", "Interproximal reduction", "Differential growth"], "key": "B", "type": "sba", "explanation": "Space opening for a prosthesis adds to the requirement, not the supply. The seven sources are tooth reduction or enlargement, extraction, prosthetic space opening as a requirement, molar distal movement, molar mesial movement, differential growth and residue. (Companion Ch 8; Hbk 11.2)", "answerPage": 200, "block": "K"}, {"n": 347, "page": 69, "stem": "Uprighting a distally angulated canine has which effect on the space analysis?", "options": ["It creates space", "It creates space only in the mandible", "It has no effect", "It consumes space", "It creates space only in extraction cases"], "key": "D", "type": "sba", "explanation": "Correction of angulation, or tip, consumes space, and is one of the six areas of space requirement. (Companion Ch 8; Hbk 11.2)", "answerPage": 200, "block": "K"}, {"n": 348, "page": 69, "stem": "Intra-oral scanning compared with conventional impressions offers which principal advantage?", "options": ["Better patient tolerance, immediate transmissibility and digital storage, with comparable full-arch accuracy", "Superior accuracy for subgingival margins", "Lower equipment cost", "The ability to record the airway", "Elimination of the need for a laboratory"], "key": "A", "type": "sba", "explanation": "Scanning is better tolerated, immediately transmissible and permits digital set-up and storage. Deep undercuts and subgingival margins remain harder than with an impression. (Mosby ch. on digital planning; Hbk 15.4)", "answerPage": 200, "block": "K"}, {"n": 349, "page": 69, "stem": "Which single use of the digital set-up is most defensible in patient communication?", "options": ["Guaranteeing the final result", "Predicting treatment duration", "Demonstrating the space requirement and the consequence of extracting versus expanding", "Predicting relapse", "Predicting root resorption"], "key": "C", "type": "sba", "explanation": "A set-up is useful for demonstrating geometry and the consequences of a choice, not for guaranteeing outcomes. (Mosby ch. on digital planning; Hbk 11.4)", "answerPage": 200, "block": "K"}, {"n": 350, "page": 69, "stem": "Crowding of 6 mm in an arch is classified as which severity?", "options": ["Mild", "Not classifiable", "Severe", "Very severe", "Moderate"], "key": "E", "type": "sba", "explanation": "Mild crowding is 1 to 4 mm, moderate 5 to 8 mm and severe 9 mm or more. (Companion Ch 8; Hbk 13.1)", "answerPage": 201, "block": "K"}, {"n": 351, "page": 70, "stem": "Which is the correct first stage of the treatment planning sequence?", "options": ["Diagnosis, comprising examination, records and the patient’s own concerns", "Space analysis", "Anchorage planning", "Appliance selection", "Extraction decision"], "key": "A", "type": "sba", "explanation": "The nine-step sequence begins with diagnosis and ends with retention, and each stage constrains the next. (Companion Ch 8; Hbk 12.1)", "answerPage": 201, "block": "L"}, {"n": 352, "page": 70, "stem": "Where does orthodontic treatment planning begin, according to the modern position?", "options": ["With the mandibular incisor position", "With the molar relationship", "With the position of the dentition, particularly the maxillary incisors, within the face", "With the space analysis", "With the skeletal pattern on the cephalogram"], "key": "C", "type": "sba", "explanation": "This is a deliberate shift from the classical approach of planning around mandibular incisor position and isolated static occlusal goals. (Companion Ch 8; Hbk 12.1)", "answerPage": 201, "block": "L"}, {"n": 353, "page": 70, "stem": "Which structures define the limits of orthodontic treatment in each individual?", "options": ["The alveolar bone alone", "The periodontal ligament", "The cranial base", "The temporomandibular joints", "The soft tissues"], "key": "E", "type": "sba", "explanation": "Ackerman and Proffit, and Holdaway, established that the soft tissues define the limits of orthodontic treatment. (Ackerman and Proffit 1997; Hbk 12.1)", "answerPage": 201, "block": "L"}, {"n": 354, "page": 70, "stem": "The problem list should be ranked in which order?", "options": ["Alphabetically", "By order of importance to the patient", "By order in which they will be treated", "By anatomical region", "By IOTN grade"], "key": "B", "type": "sba", "explanation": "Proffit’s discipline is to rank the problem list in order of importance to the patient. The chief complaint always ranks high. (Proffit Ch 6; Hbk 12.4)", "answerPage": 201, "block": "L"}, {"n": 355, "page": 70, "stem": "Which single feature makes a treatment objective measurable?", "options": ["That it is written down", "That it has a time limit", "That it is agreed with the patient", "That a colleague could assess whether it had been achieved", "That it refers to the occlusion"], "key": "D", "type": "sba", "explanation": "Rubber-stamp objectives such as achieve a good functional occlusion are not objectives, because no colleague could measure you against them. (Mosby ch. on treatment planning; Hbk 12.4)", "answerPage": 201, "block": "L"}, {"n": 356, "page": 70, "stem": "Growth modification is much more effective for which malocclusion?", "options": ["Class I", "Class III", "Class II", "Anterior open bite", "Bimaxillary protrusion"], "key": "C", "type": "sba", "explanation": "Growth modification relies on compliance and favourable growth and is much more effective for Class II than for Class III. (Companion Ch 8; Hbk 12.2)", "answerPage": 201, "block": "L"}, {"n": 357, "page": 71, "stem": "Which single factor determines whether growth modification is available as an option?", "options": ["Whether the patient is still growing", "The patient’s motivation", "The severity of crowding", "The IOTN grade", "The appliance chosen"], "key": "A", "type": "sba", "explanation": "Growth status is the first discriminator. Its absence converts growth modification into camouflage or a surgical problem. (Companion Ch 8; Hbk 12.2)", "answerPage": 201, "block": "L"}, {"n": 358, "page": 71, "stem": "For every 1 mm of maxillary incisor retraction, the lips retract approximately how far?", "options": ["0.3 mm", "2.0 mm", "1.0 mm", "1.5 mm", "0.7 mm"], "key": "E", "type": "sba", "explanation": "Konstantonis reported 0.7 mm of lip retraction per 1 mm of incisor retraction, with a 1.6 degree increase in nasolabial angle. (Konstantonis 2018; Hbk 12.2)", "answerPage": 201, "block": "L"}, {"n": 359, "page": 71, "stem": "For every 1 mm of maxillary incisor retraction, the nasolabial angle increases by approximately how much?", "options": ["0.5 degrees", "5 degrees", "3 degrees", "1.6 degrees", "It decreases"], "key": "D", "type": "sba", "explanation": "The nasolabial angle increases by approximately 1.6 degrees per millimetre of incisor retraction. (Konstantonis 2018; Hbk 12.2)", "answerPage": 201, "block": "L"}, {"n": 360, "page": 71, "stem": "The envelope of discrepancy describes which concept?", "options": ["The range of cephalometric normality", "The range of movement achievable by orthodontics alone, with growth modification, and by surgery, in each direction", "The limits of the alveolar bone", "The variation in landmark identification", "The range of acceptable overjet"], "key": "B", "type": "sba", "explanation": "The envelope of discrepancy is asymmetric, extended modestly by growth modification in growers, and its soft tissue limits are frequently tighter than its hard tissue limits. (Proffit Ch 7; Hbk 12.3)", "answerPage": 201, "block": "L"}, {"n": 361, "page": 71, "stem": "Which single statement about the envelope of discrepancy is correct?", "options": ["It is symmetrical in all directions", "It applies only to Class II cases", "Growth modification extends it equally in all patients", "Soft tissue limits are always wider than hard tissue limits", "Maxillary incisors can be retracted further than they can be advanced"], "key": "E", "type": "sba", "explanation": "The envelope is asymmetric: more movement is possible in some directions than others, and retraction of maxillary incisors exceeds advancement. (Proffit Ch 7; Hbk 12.3)", "answerPage": 201, "block": "L"}, {"n": 362, "page": 71, "stem": "A compromised tooth sits in a less convenient position than a healthy one. Which should be extracted?", "options": ["The healthy tooth, for symmetry", "The compromised tooth, even though its position is less convenient", "Neither; treat non-extraction", "Both", "The decision depends on the IOTN grade"], "key": "B", "type": "sba", "explanation": "Prognosis beats symmetry. A compromised tooth should always be removed in preference to a healthy one. (Companion Ch 8; Hbk 12.4 and 13.2)", "answerPage": 201, "block": "L"}, {"n": 363, "page": 71, "stem": "Which stage of the planning sequence follows directly from the space analysis?", "options": ["Appliance selection", "Phasing", "Retention", "Anchorage planning", "Diagnosis"], "key": "D", "type": "sba", "explanation": "Anchorage arises directly from the space analysis and the extraction pattern, and cannot be decided before them. (Companion Ch 8; Hbk 12.1)", "answerPage": 201, "block": "L"}, {"n": 364, "page": 72, "stem": "Which is the correct phasing of a fixed appliance treatment?", "options": ["Alignment and levelling, overjet and overbite correction, space closure, detailing and finishing", "Space closure, alignment, levelling, detailing", "Detailing, alignment, space closure, levelling", "Overbite correction, detailing, alignment, space closure", "Levelling, detailing, alignment, space closure"], "key": "A", "type": "sba", "explanation": "The conventional phasing is alignment and levelling, then overjet and overbite correction, then space closure, then detailing and finishing. (Companion Ch 8; Hbk 12.1 and 18)", "answerPage": 201, "block": "L"}, {"n": 365, "page": 72, "stem": "At which point in the plan should retention be decided?", "options": ["At debond", "At the mid-treatment review", "Before active treatment begins, and agreed with the patient", "When the retainer is fitted", "When relapse occurs"], "key": "C", "type": "sba", "explanation": "Retention should be discussed prior to the commencement of active treatment, and the patient must agree to it. (Companion Ch 13; Hbk 12.1 and 19.3)", "answerPage": 201, "block": "L"}, {"n": 366, "page": 72, "stem": "A non-growing patient has a moderate skeletal Class II discrepancy and asks for a nonsurgical solution. Which route is being described?", "options": ["Growth modification", "Interceptive treatment", "Orthognathic surgery", "Camouflage", "Adjunctive treatment"], "key": "D", "type": "sba", "explanation": "Camouflage accepts the skeletal pattern and positions the teeth to disguise it. Its limits are the alveolar envelope, the soft tissue response and the existing dental compensation. (Companion Ch 8; Hbk 12.2)", "answerPage": 201, "block": "L"}, {"n": 367, "page": 72, "stem": "Which of the following is not one of Proffit’s cephalometric thresholds favouring surgery in Class II?", "options": ["Overjet greater than 10 mm", "MMPA greater than 40 degrees", "Mandibular body length less than 70 mm", "Anterior face height greater than 125 mm", "Pogonion to nasion perpendicular of 18 mm or more"], "key": "B", "type": "sba", "explanation": "The four thresholds are overjet over 10 mm, pogonion to nasion perpendicular of 18 mm or more, mandibular body under 70 mm and anterior face height over 125 mm. (Proffit 1992; Hbk 12.2)", "answerPage": 201, "block": "L"}, {"n": 368, "page": 72, "stem": "Which single element of the plan is most frequently omitted by candidates in a treatment planning question?", "options": ["The extraction pattern", "The phasing", "The anchorage plan", "The appliance", "The facial aims"], "key": "E", "type": "sba", "explanation": "Facial aims are routinely forgotten. A Class I incisor and canine relationship must not be achieved at the expense of the soft tissue profile. (Companion Ch 8; Hbk 12.1)", "answerPage": 202, "block": "L"}, {"n": 369, "page": 72, "stem": "Which single statement about compliance in treatment planning is correct?", "options": ["It is a planning factor, because a technically ideal plan the patient will not wear is not a plan", "It should be assessed at the mid-treatment review", "It is irrelevant with fixed appliances", "It can be reliably predicted from the IOTN grade", "It applies only to functional appliances"], "key": "A", "type": "sba", "explanation": "Compliance is a planning factor, not an afterthought, and it influences the choice of appliance from the outset. (Companion Ch 8; Hbk 12.1)", "answerPage": 202, "block": "L"}, {"n": 370, "page": 72, "stem": "Which single element must be included when presenting treatment options?", "options": ["Only the option you recommend", "Only the cheapest option", "All reasonable options, including no treatment and its consequences", "Only options available in your own practice", "Only surgical options if the discrepancy is severe"], "key": "C", "type": "sba", "explanation": "All reasonable alternatives must be presented, including no treatment. In a diagnostic case, offering three options and saying why two were rejected scores higher than asserting a single plan. (GDC Standards; Hbk 12.4 and Part 3)", "answerPage": 202, "block": "L"}, {"n": 371, "page": 73, "stem": "Which single sentence best summarises a case for an examiner?", "options": ["A statement of the extraction pattern", "A statement giving age, growth status, the three planes of space, incisor and molar class, the key numbers and the soft tissue driver", "A statement of the IOTN grade", "A statement of the patient’s chief complaint alone", "A statement of the appliance to be used"], "key": "B", "type": "sba", "explanation": "The one-sentence summary contains everything the examiner needs to place the case, and taking control of the frame makes everything afterwards easier. (Hbk Part 3)", "answerPage": 202, "block": "L"}, {"n": 372, "page": 73, "stem": "Which is the correct interpretation of a heavily dentally compensated Class III case?", "options": ["It will be easier to camouflage", "Compensation always indicates a growing patient", "Compensation is irrelevant to planning", "There is less room left for camouflage, so surgery becomes more likely", "Compensation improves stability"], "key": "D", "type": "sba", "explanation": "Existing compensation consumes the movement available for camouflage. It is often the deciding factor between camouflage and surgery. (Companion Ch 13; Hbk 12.2 and 23.4)", "answerPage": 202, "block": "L"}, {"n": 373, "page": 73, "stem": "Which patient factor most often changes the plan between a 12-year-old and a 32-year-old with the same malocclusion?", "options": ["The absence of growth, which removes growth modification and changes overbite mechanics", "The appliance available", "The IOTN grade", "The extraction pattern alone", "The retention regimen alone"], "key": "A", "type": "sba", "explanation": "Growth status changes the availability of growth modification and reverses the consequences of buccal segment extrusion for overbite reduction. (Companion Ch 13; Hbk 12.2 and 25.1)", "answerPage": 202, "block": "L"}, {"n": 374, "page": 73, "stem": "The Class III thresholds for surgery include which value for lower incisor inclination?", "options": ["100 degrees or more", "93 degrees", "80 degrees or less", "110 degrees", "Lower incisor inclination is not used"], "key": "C", "type": "sba", "explanation": "A lower incisor inclination of 80 degrees or less indicates that decompensation has already occurred and camouflage has little room left. (Kerr 1992; Hbk 23.4)", "answerPage": 202, "block": "L"}, {"n": 375, "page": 73, "stem": "Discriminant analysis of the Class III surgical thresholds predicts the need for surgery with approximately what accuracy?", "options": ["50 per cent", "65 per cent", "75 per cent", "100 per cent", "Over 90 per cent"], "key": "E", "type": "sba", "explanation": "Discriminant analysis on these cephalometric variables predicts the need for surgery with over 90 per cent accuracy. (Kochel 2011; Hbk 23.4)", "answerPage": 202, "block": "L"}, {"n": 376, "page": 73, "stem": "Which statement about the interaction between space analysis and anchorage is correct?", "options": ["The space analysis is completed first, and the anchorage requirement follows from it", "Anchorage is decided first and constrains the space analysis", "The two are unrelated", "Anchorage depends only on the appliance", "Anchorage is decided at the working wire stage"], "key": "A", "type": "sba", "explanation": "Anchorage requirement follows from the plan, not the other way round. This ordering is a frequent examination point. (Cobourne cases; Hbk 11.2 and 12.1)", "answerPage": 202, "block": "L"}, {"n": 377, "page": 74, "stem": "A patient presents with an unfavourable Class III pattern in the mixed dentition. What is often the correct answer?", "options": ["Immediate facemask therapy in all cases", "Immediate camouflage with fixed appliances", "Monitor into the late teens, avoiding mandibular extractions if surgery is likely", "Immediate surgical referral", "Extraction of the lower first premolars"], "key": "C", "type": "sba", "explanation": "In an unfavourable Class III, monitoring is often correct because Class III worsens with growth, and mandibular extractions consume the decompensation space the surgeon will need. (Companion Ch 8; Hbk 23.2)", "answerPage": 202, "block": "L"}, {"n": 378, "page": 74, "stem": "Which single question should be answered before choosing an extraction pattern?", "options": ["Which brackets will be used", "What the IOTN aesthetic component grade is", "What the patient’s occupation is", "Which retainer will be fitted", "What the space requirement is in each arch, and what molar relationship the case will finish to"], "key": "E", "type": "sba", "explanation": "The extraction pattern follows from the differential space requirement between the arches and the intended finishing molar relationship. (Companion Ch 8; Hbk 11.2 and 13.3)", "answerPage": 202, "block": "L"}, {"n": 379, "page": 74, "stem": "Which single term describes limited tooth movement undertaken to serve a larger periodontal or restorative goal?", "options": ["Comprehensive treatment", "Adjunctive treatment", "Interceptive treatment", "Camouflage", "Growth modification"], "key": "B", "type": "sba", "explanation": "Adjunctive treatment serves a larger goal, such as uprighting a molar before a bridge, and is often appropriate in general practice. (Proffit Ch 18; Hbk 27.1)", "answerPage": 202, "block": "L"}, {"n": 380, "page": 74, "stem": "Which statement best describes the relationship between facial and occlusal aims?", "options": ["Occlusal aims always take precedence", "They are independent", "Facial aims are relevant only in surgical cases", "They must be reconciled against the skeletal pattern, and a Class I occlusion must not be bought at the cost of the profile", "Facial aims apply only to adults"], "key": "D", "type": "sba", "explanation": "Reconciling facial and occlusal aims against the skeletal pattern is the third stage of the planning sequence and the one most often omitted. (Companion Ch 8; Hbk 12.1)", "answerPage": 202, "block": "L"}, {"n": 381, "page": 74, "stem": "Which single statement about treatment planning in the presence of a tooth of poor prognosis is correct?", "options": ["The tooth should be retained and the plan built around it", "The tooth should be root treated and retained", "The tooth should be removed in preference to a healthy tooth, even in a less convenient position", "The tooth should be extracted only after appliance removal", "The tooth should be extracted only if it is symptomatic"], "key": "C", "type": "sba", "explanation": "A compromised tooth should always be removed in preference to a healthy one. This is one of the four factors governing extraction choice. (Companion Ch 8; Hbk 13.2)", "answerPage": 202, "block": "L"}, {"n": 382, "page": 74, "stem": "The database, problem list, ranked problem list, possible solutions and plan sequence is attributed to which author?", "options": ["Proffit", "Andrews", "Angle", "Begg", "Tweed"], "key": "A", "type": "sba", "explanation": "Proffit’s problem-oriented approach runs from database through a ranked problem list and possible solutions to a single reconciled plan. (Proffit Ch 6; Hbk 12.4)", "answerPage": 202, "block": "L"}, {"n": 383, "page": 75, "stem": "Which is the correct approach when facial aims and occlusal aims conflict in a non-growing patient with a severe skeletal discrepancy?", "options": ["Prioritise the occlusion and accept the profile", "Extract four premolars and reassess", "Begin camouflage and reassess at 12 months", "Refer only if the patient complains about the profile", "Recognise that the case is likely to require surgery, and make that decision before treatment begins"], "key": "E", "type": "sba", "explanation": "The camouflage-or-surgery decision must be made before treatment begins, because pre-surgical orthodontics decompensates in the opposite direction from camouflage. (Proffit Ch 19; Hbk 12.2 and 27.2)", "answerPage": 202, "block": "L"}, {"n": 384, "page": 75, "stem": "A 14-year-old has 4 mm of lower crowding, 7 mm of upper crowding and a half-unit Class II molar relationship. Which extraction pattern best reflects the space requirement?", "options": ["Four first premolars", "Lower first premolars only", "Upper second premolars and lower first premolars", "Upper first premolars and lower second premolars", "Four second premolars"], "key": "D", "type": "sba", "explanation": "The greater maxillary requirement finishes to a Class II molar relationship, which is achieved by extracting further back in the mandible. (Companion Ch 8; Hbk 13.3)", "answerPage": 202, "block": "L"}, {"n": 385, "page": 75, "stem": "Which factor should be assessed before any decision about arch expansion in the lower arch?", "options": ["The patient’s age", "That the mandibular arch is the template and lower intercanine expansion relapses", "The bracket prescription", "The overbite", "The IOTN grade"], "key": "B", "type": "sba", "explanation": "The mandibular arch is the template. Lower intercanine width is among the least amenable dimensions to change, and expansion relapses. (Companion Ch 8; Hbk 12.1 and 19.1)", "answerPage": 202, "block": "L"}, {"n": 386, "page": 75, "stem": "Which is the correct definition of camouflage in orthodontics?", "options": ["Treatment that disguises a poor result", "Treatment that avoids retention", "Treatment using aesthetic appliances", "Treatment without extraction", "Acceptance of the skeletal pattern with positioning of the teeth to disguise it"], "key": "E", "type": "sba", "explanation": "Camouflage accepts the skeletal discrepancy and positions the teeth to disguise it, within the limits of the alveolar envelope and the soft tissues. (Companion Ch 8; Hbk 12.2)", "answerPage": 202, "block": "L"}, {"n": 387, "page": 75, "stem": "Which single element should close a treatment planning answer in an oral examination?", "options": ["The bracket prescription", "What would change your mind, and where you would refer", "The cost", "The appointment interval", "The archwire sequence"], "key": "B", "type": "sba", "explanation": "Saying what would change your mind and where you would refer demonstrates judgement and knowledge of your own limits. (Hbk Part 3 and Part 5)", "answerPage": 202, "block": "L"}, {"n": 388, "page": 75, "stem": "Which is the correct order of the last three stages of the planning sequence?", "options": ["Retention, phasing, appliance", "Retention, appliance, phasing", "Phasing, retention, appliance", "Appliance, phasing, retention", "Appliance, retention, phasing"], "key": "D", "type": "sba", "explanation": "The sequence ends appliance, phasing, retention, having begun with diagnosis, problem list and aims. (Companion Ch 8; Hbk 12.1)", "answerPage": 203, "block": "L"}, {"n": 389, "page": 75, "stem": "In a diagnostic case, which single failure is most commonly seen?", "options": ["An unranked list of findings with no argument", "Excessive detail on the cephalometric analysis", "Failure to name the appliance", "Failure to quote the IOTN grade", "Excessive discussion of retention"], "key": "A", "type": "sba", "explanation": "The commonest failure is an unranked list of ten findings with no argument. Rank them, and say which two you would treat if you could treat only two. (Hbk Part 3)", "answerPage": 203, "block": "L"}, {"n": 390, "page": 76, "stem": "A space analysis shows an upper requirement of 12 mm and a lower requirement of 5 mm. What does this imply for the finish?", "options": ["Class I molars", "Class III molars", "Class II molars", "The analysis is in error", "The molar relationship is unaffected"], "key": "C", "type": "sba", "explanation": "A greater maxillary space requirement means the maxillary buccal segments will move further forward relative to the mandibular ones, finishing to Class II molars. (Companion Ch 8; Hbk 11.2)", "answerPage": 203, "block": "L"}, {"n": 391, "page": 77, "stem": "Which method of creating space is the most predictable?", "options": ["Expansion", "Distalisation", "Interproximal reduction", "Extraction", "Proclination"], "key": "D", "type": "sba", "explanation": "Extraction yields the full mesiodistal width of the tooth and is the most predictable source of space, at the cost of an anchorage demand. (Companion Ch 8; Hbk 13.1)", "answerPage": 203, "block": "M"}, {"n": 392, "page": 77, "stem": "Crowding of 3 mm in an arch is classified as which severity?", "options": ["Moderate", "Mild", "Severe", "Very severe", "Not classifiable"], "key": "B", "type": "sba", "explanation": "Mild crowding is 1 to 4 mm, moderate 5 to 8 mm and severe 9 mm or more. (Companion Ch 8; Hbk 13.1)", "answerPage": 203, "block": "M"}, {"n": 393, "page": 77, "stem": "Proffit’s threshold above which extraction is almost always required is which value?", "options": ["4 mm", "6 mm", "20 mm", "15 mm", "10 mm"], "key": "E", "type": "sba", "explanation": "Proffit gives fewer than 4 mm as rarely requiring extraction, 5 to 9 mm as a judgement, and 10 mm or more as almost always requiring extraction. (Proffit Ch 7; Hbk 13.6)", "answerPage": 203, "block": "M"}, {"n": 394, "page": 77, "stem": "In a Class II malocclusion, where should the mandibular extraction be sited relative to the maxillary one?", "options": ["Further back", "Further forward", "In the same position", "In the lower arch only", "Extraction should be avoided"], "key": "A", "type": "sba", "explanation": "Class II requires extraction further back in the mandible, typically maxillary first premolars with mandibular second premolars, so that the greater maxillary space allows retraction of the upper labial segment. (Companion Ch 8; Hbk 13.3)", "answerPage": 203, "block": "M"}, {"n": 395, "page": 77, "stem": "In a Class III malocclusion, where should the mandibular extraction be sited relative to the maxillary one?", "options": ["Further back", "In the same position", "Further forward", "In the upper arch only", "Extraction should be avoided"], "key": "C", "type": "sba", "explanation": "Class III requires extraction further forward in the mandible, typically mandibular first premolars with maxillary second premolars. (Companion Ch 8; Hbk 13.3)", "answerPage": 203, "block": "M"}, {"n": 396, "page": 77, "stem": "Which single principle governs the choice of extraction site?", "options": ["Symmetry above all", "Put the space where the movement is needed", "Always extract first premolars", "Always extract in all four quadrants", "Extract the tooth with the longest root"], "key": "B", "type": "sba", "explanation": "Space is most useful where the movement is needed, which is the rationale behind the differential extraction patterns by class. (Companion Ch 8; Hbk 13.3)", "answerPage": 203, "block": "M"}, {"n": 397, "page": 78, "stem": "Which extraction gives the best spontaneous improvement, particularly in the mixed dentition?", "options": ["First permanent molar", "Lower incisor", "Second premolar", "First premolar", "Second permanent molar"], "key": "D", "type": "sba", "explanation": "First premolar extraction relieves anterior crowding most efficiently and gives the best spontaneous improvement, especially in the mixed dentition. (Companion Ch 8; Hbk 13.4)", "answerPage": 203, "block": "M"}, {"n": 398, "page": 78, "stem": "Second premolar extraction is preferred over first premolar extraction in which circumstance?", "options": ["Mild to moderate crowding sited posteriorly, or where anchorage should favour the anterior segment", "Severe anterior crowding", "A large overjet", "Maximum anchorage cases", "Severe proclination"], "key": "A", "type": "sba", "explanation": "Second premolar extraction suits posteriorly sited crowding and cases where the anchorage balance should favour the anterior segment. It also eases Class II mechanics in the lower arch. (Companion Ch 8; Hbk 13.4)", "answerPage": 203, "block": "M"}, {"n": 399, "page": 78, "stem": "Extraction of a second permanent molar requires which condition to be met?", "options": ["The third molar must be absent", "The first molar must be restored", "A third molar must be present, of good size, correctly angulated and at the right stage of development", "The patient must be over 18", "The overbite must be reduced"], "key": "C", "type": "sba", "explanation": "Second molar extraction requires a third molar present, of good size, angulated at 30 degrees or less to the second molar long axis, and at an appropriate developmental stage. (Companion Ch 8; Hbk 13.4)", "answerPage": 203, "block": "M"}, {"n": 400, "page": 78, "stem": "Lower incisor extraction is most appropriate in which situation?", "options": ["Severe upper arch crowding", "Bimaxillary protrusion", "Class II division 1 with a large overjet", "Anterior open bite", "Severe lower labial segment crowding, a lower incisor of poor prognosis, or mild Class III camouflage in a non-grower"], "key": "E", "type": "sba", "explanation": "Lower incisor extraction is rarely indicated, and its costs are tooth-size discrepancy, residual spacing and a deepened overbite. (Companion Ch 8; Hbk 13.4)", "answerPage": 203, "block": "M"}, {"n": 401, "page": 78, "stem": "NICE guidance on prophylactic removal of third molars to prevent late lower incisor crowding states what?", "options": ["It is not recommended", "It is recommended in all cases", "It is recommended only in females", "It is recommended after age 25", "It is recommended if the third molars are impacted"], "key": "A", "type": "sba", "explanation": "NICE advises against prophylactic removal of developing third molars to prevent late lower incisor crowding, and third molars are not a primary cause. (NICE; Richardson 2002; Hbk 13.4 and 19.4)", "answerPage": 203, "block": "M"}, {"n": 402, "page": 78, "stem": "A balancing extraction is most relevant for which tooth type?", "options": ["Molars", "Second premolars", "Canines", "Second permanent molars", "Third molars"], "key": "C", "type": "sba", "explanation": "Balancing extraction to prevent a centre line shift is most relevant for canines, and to a lesser extent incisors. It is rarely needed for molars. (Companion Ch 12; Hbk 13.5)", "answerPage": 203, "block": "M"}, {"n": 403, "page": 79, "stem": "A compensating extraction is performed for which purpose?", "options": ["To prevent a centre line shift", "To allow eruption of the third molar", "To relieve crowding", "To create anchorage", "To preserve the buccal occlusion and prevent over-eruption of the opposing tooth"], "key": "E", "type": "sba", "explanation": "Compensating extraction removes the opposing tooth in the same quadrant, and is considered principally for first permanent molars. (Companion Ch 12; Hbk 13.5)", "answerPage": 203, "block": "M"}, {"n": 404, "page": 79, "stem": "The evidence on soft tissue differences between extraction and non-extraction treatment shows what?", "options": ["Extraction reliably flattens the profile", "Differences are minimal, and both groups are perceived to benefit", "Non-extraction reliably worsens the profile", "The evidence is entirely absent", "Only extraction of first premolars affects the profile"], "key": "B", "type": "sba", "explanation": "Rushing, Paquette and Iared found minimal soft tissue differences, with both groups perceived to benefit. (Rushing 1995; Iared 2017; Hbk 13.6)", "answerPage": 203, "block": "M"}, {"n": 405, "page": 79, "stem": "Meyer, Christou and Cheng examined which claim about extraction?", "options": ["That extraction narrows the airway", "That extraction causes root resorption", "That extraction causes TMD", "That extraction produces larger buccal corridors and a less attractive smile", "That extraction shortens treatment"], "key": "D", "type": "sba", "explanation": "These studies found that extraction does not produce larger buccal corridors or a less attractive smile. (Meyer 2014; Christou 2019; Hbk 13.6)", "answerPage": 204, "block": "M"}, {"n": 406, "page": 79, "stem": "Pont’s index of arch width is best regarded in which way?", "options": ["As an accurate predictor of ideal arch width", "As applicable only to Class I cases", "As not an acceptable predictor of arch width", "As the standard for expansion planning", "As superior to the space analysis"], "key": "C", "type": "sba", "explanation": "Proffit concluded that arch width indices such as Pont’s are not acceptable predictors of arch width. (Proffit Ch 7; Hbk 13.6)", "answerPage": 204, "block": "M"}, {"n": 407, "page": 79, "stem": "A canine requiring less than half a unit of distal movement is best managed how?", "options": ["Distalisation", "Extraction of the first premolar", "Extraction of the second premolar", "Interproximal reduction alone", "Expansion"], "key": "A", "type": "sba", "explanation": "The conventional rule is: less than half a unit distalise, more than half a unit extract, more than one unit both. (Companion Ch 8; Hbk 13.1)", "answerPage": 204, "block": "M"}, {"n": 408, "page": 79, "stem": "Which single factor most often determines that a first permanent molar rather than a premolar should be extracted?", "options": ["Its position in the arch", "The presence of third molars", "The patient’s age", "The overbite", "Its poor long-term prognosis, for example from caries or molar incisor hypomineralisation"], "key": "E", "type": "sba", "explanation": "A first permanent molar is extracted only when its prognosis is poor. Prognosis beats symmetry and beats convenience of position. (Companion Ch 12; Hbk 13.4)", "answerPage": 204, "block": "M"}, {"n": 409, "page": 79, "stem": "Which four factors govern the choice of extraction?", "options": ["Age, sex, arch form and overbite", "IOTN grade, PAR score, overjet and overbite", "Anchorage, appliance, arch form and retention", "Condition of the teeth, site and degree of crowding, type of malocclusion, and age", "Cost, compliance, aesthetics and function"], "key": "D", "type": "sba", "explanation": "These four factors are the standard structure for an extraction question, and prognosis is the first of them. (Cobourne cases; Hbk 13.2)", "answerPage": 204, "block": "M"}, {"n": 410, "page": 80, "stem": "Single-arch extraction commits the clinician to which outcome?", "options": ["A Class I molar relationship", "Accepting a Class II or Class III molar relationship", "An anterior open bite", "A deepened overbite in all cases", "A crossbite"], "key": "B", "type": "sba", "explanation": "Extracting in one arch only means accepting a non-Class I molar relationship, which must be a deliberate decision made in advance. (Cobourne cases; Hbk 13.3)", "answerPage": 204, "block": "M"}, {"n": 411, "page": 80, "stem": "Which single statement about the timing of extraction in the mixed dentition is correct?", "options": ["Timing is irrelevant", "Extraction should follow eruption of the third molars", "Extraction should always be deferred to the permanent dentition", "Extraction in the mixed dentition always requires a space maintainer", "Well-timed extraction permits spontaneous alignment, whereas in the permanent dentition appliances become obligatory"], "key": "E", "type": "sba", "explanation": "Well-timed extraction in the mixed dentition permits spontaneous improvement. In the permanent dentition, appliances are required. (Companion Ch 8; Hbk 13.2)", "answerPage": 204, "block": "M"}, {"n": 412, "page": 80, "stem": "Which of the following is the least appropriate reason to extract a healthy premolar?", "options": ["Severe crowding requiring space", "A patient request to shorten treatment time", "A large overjet requiring retraction", "Anchorage planning in a maximum anchorage case", "Correction of a centre line discrepancy"], "key": "B", "type": "sba", "explanation": "Extraction is not justified by a wish to shorten treatment. The four factors are prognosis, site and degree of crowding, malocclusion type and age. (Companion Ch 8; Hbk 13.2)", "answerPage": 204, "block": "M"}, {"n": 413, "page": 80, "stem": "What total interproximal reduction is realistically available across a full arch?", "options": ["Around 2 mm", "Unlimited", "Around 15 mm", "A modest amount, in the order of 4 to 8 mm across all contacts", "None"], "key": "D", "type": "sba", "explanation": "Interproximal reduction offers a modest total, in the order of 0.5 mm per anterior contact and up to 1 mm per buccal contact. Enamel is finite. (Companion Ch 8; Hbk 13.1)", "answerPage": 204, "block": "M"}, {"n": 414, "page": 80, "stem": "Serial extraction is contraindicated in which circumstance?", "options": ["A Class II or Class III skeletal pattern, deep overbite, open bite or hypodontia", "Severe crowding with a Class I skeletal pattern", "A well-motivated patient", "Adequate space for the canines", "The presence of all permanent teeth"], "key": "A", "type": "sba", "explanation": "Serial extraction requires severe crowding with a Class I pattern and no vertical problem. It is contraindicated in Class II or III, deep or open bite, hypodontia and mild crowding. (Proffit Ch 12; Hbk 20.3)", "answerPage": 204, "block": "M"}, {"n": 415, "page": 80, "stem": "What is the classical sequence of serial extraction?", "options": ["First premolars, then primary canines, then first primary molars", "First permanent molars, then premolars, then canines", "Primary canines, then first primary molars, then first premolars as they erupt", "Primary molars, then permanent molars, then premolars", "Primary canines, then first premolars, then primary molars"], "key": "C", "type": "sba", "explanation": "The sequence is primary canines at about 8 to 9 years, first primary molars at about 9 to 10 years, then the first premolars as they erupt. (Proffit Ch 12; Hbk 20.3)", "answerPage": 204, "block": "M"}, {"n": 416, "page": 80, "stem": "Which is a recognised disadvantage of serial extraction?", "options": ["It always requires surgery", "It increases the risk of root resorption", "It cannot be performed before age 14", "A long period of unattractive spacing, a deepening overbite, retroclination of the lower incisors, and a fixed appliance usually still required", "It requires a lateral cephalogram at each visit"], "key": "D", "type": "sba", "explanation": "The disadvantages are prolonged spacing, a deepening overbite, lower incisor retroclination, the usual need for a fixed appliance anyway, and irreversible commitment at a young age. (Proffit Ch 12; Hbk 20.3)", "answerPage": 204, "block": "M"}, {"n": 417, "page": 81, "stem": "Which single statement about extraction and temporomandibular disorder is correct?", "options": ["Premolar extraction causes TMD", "There is no evidence that extraction causes temporomandibular disorder", "Extraction cures TMD", "Extraction should be avoided in any patient with a click", "Only four-premolar extraction is implicated"], "key": "B", "type": "sba", "explanation": "The AAO-funded studies found no causal association, despite the 1987 Brimm versus Malloy award of 850000 dollars following premolar extraction treatment. (Behrents and White 1992; Hbk 13.6 and 26.1)", "answerPage": 204, "block": "M"}, {"n": 418, "page": 81, "stem": "Which single statement about the airway and extraction is supported by the evidence?", "options": ["Extraction reduces the oropharyngeal airway", "The evidence is equivocal", "Extraction increases the risk of apnoea by 20 per cent", "Only maxillary extraction affects the airway", "There is no evidence that extraction-based treatment reduces the oropharyngeal airway or increases sleep apnoea"], "key": "E", "type": "sba", "explanation": "Larsen and Orabi found no evidence for the claim, which has been described in the literature as scaremongering and marketing. (Larsen 2015; Orabi 2021; Hbk 13.6)", "answerPage": 204, "block": "M"}, {"n": 419, "page": 81, "stem": "Extraction of a first permanent molar in the mandible requires more careful timing than in the maxilla because of which fact?", "options": ["The maxillary second molar drifts mesially readily at almost any age, whereas the mandibular one does not", "The mandibular third molar erupts earlier", "The mandibular first molar has a longer root", "Anchorage is greater in the maxilla", "The mandibular arch is the template"], "key": "A", "type": "sba", "explanation": "Timing is critical in the mandible because the mandibular second molar does not drift mesially as readily as the maxillary one. (Companion Ch 12; Hbk 3.4 and 13.4)", "answerPage": 204, "block": "M"}, {"n": 420, "page": 81, "stem": "A patient has a heavily restored, hypomineralised lower first permanent molar and 5 mm of lower crowding. Which extraction is most appropriate?", "options": ["Lower first premolar", "Lower second premolar", "Lower first permanent molar", "Lower incisor", "Lower second permanent molar"], "key": "C", "type": "sba", "explanation": "Prognosis beats convenience. The compromised molar should be removed in preference to a healthy premolar, with timing chosen against second molar development. (Companion Ch 12; Hbk 13.2 and 13.4)", "answerPage": 204, "block": "M"}, {"n": 421, "page": 81, "stem": "Which single consideration should be confirmed radiographically before extracting a first permanent molar?", "options": ["The overbite", "The presence, position and development of all permanent teeth including third molars", "The bone density", "The width of the periodontal ligament", "The condylar morphology"], "key": "B", "type": "sba", "explanation": "The presence and position of all permanent teeth, including third molars, must be confirmed before committing to first molar extraction. (Companion Ch 12; Hbk 3.4)", "answerPage": 204, "block": "M"}, {"n": 422, "page": 81, "stem": "Which of the following is the correct effect of proclining the lower incisors by 1 mm?", "options": ["It gains 1 mm of arch space", "It loses 2 mm", "It gains 4 mm", "It gains 2 mm of arch space", "It has no effect on space"], "key": "D", "type": "sba", "explanation": "Each millimetre of incisor advance yields 2 mm of arch space, but stability is lost beyond about 2 mm of advance. (Bennett and McLaughlin; Hbk 11.2 and 19.1)", "answerPage": 204, "block": "M"}, {"n": 423, "page": 81, "stem": "Which single statement about extraction in the presence of a missing lateral incisor is correct?", "options": ["The decision is set by the existing occlusion, which determines whether the space is opened or closed", "The canine should always be extracted", "Extraction of premolars is always required", "The space must always be opened", "Implants should be placed immediately"], "key": "A", "type": "sba", "explanation": "In hypodontia of the lateral incisors the existing molar relationship decides: Class II favours closure and canine substitution; Class I with ideal intercuspation favours opening. (Mosby ch. on hypodontia; Hbk 20.6 and Part 3 Drill 5)", "answerPage": 204, "block": "M"}, {"n": 424, "page": 82, "stem": "A Class I case has 8 mm of crowding in both arches and an acute nasolabial angle. Which extraction pattern is most appropriate?", "options": ["Four second premolars", "Upper first premolars only", "Four first premolars", "Lower first premolars only", "No extraction, with expansion"], "key": "C", "type": "sba", "explanation": "Corresponding premolar extraction in both arches maintains the Class I buccal segment, and first premolars give maximum anterior space. An acute nasolabial angle means retraction will help. (Companion Ch 8; Hbk 13.3 and 21.2)", "answerPage": 205, "block": "M"}, {"n": 425, "page": 82, "stem": "A Class I case has 4 mm of crowding in both arches, an obtuse nasolabial angle and a flat profile. Which approach is most appropriate?", "options": ["Four first premolar extraction", "Upper first premolar extraction only", "Four second premolar extraction", "Lower incisor extraction", "A non-extraction approach with interproximal reduction and minor arch development"], "key": "E", "type": "sba", "explanation": "An obtuse nasolabial angle and a flat profile mean retraction will harm the face. Mild crowding is better managed without extraction. (Mosby ch. on space analysis; Hbk 13.2 and 21.2)", "answerPage": 205, "block": "M"}, {"n": 426, "page": 82, "stem": "Which single statement about anchorage loss and extraction site is supported by the evidence?", "options": ["Anchorage loss is the same for first and second premolar extraction", "Anchorage loss is greater with first premolar extraction", "Anchorage loss is greater with second premolar extraction", "Anchorage loss occurs only in the maxilla", "Anchorage loss does not occur if a lingual arch is fitted"], "key": "A", "type": "sba", "explanation": "Haque and colleagues found that anchorage loss is the same for first and second premolar extraction, and that two-thirds of the space is lost without support. (Haque 2017; Hbk 14.4)", "answerPage": 205, "block": "M"}, {"n": 427, "page": 82, "stem": "Which is the correct approach to a canine requiring more than one unit of distal movement?", "options": ["Distalise alone", "Extract alone", "Both distalise and extract", "Accept the position", "Expand the arch"], "key": "C", "type": "sba", "explanation": "More than one unit of distal movement requires both extraction and distalisation. Less than half a unit is distalised; more than half a unit is extracted. (Companion Ch 8; Hbk 13.1)", "answerPage": 205, "block": "M"}, {"n": 428, "page": 82, "stem": "Which extraction pattern would you expect in a Class I case with 6 mm of upper crowding, 6 mm of lower crowding and Class I molars?", "options": ["Upper first and lower second premolars", "Lower first premolars only", "Upper second and lower first premolars", "Upper first premolars only", "Corresponding premolars in both arches"], "key": "E", "type": "sba", "explanation": "Equal space requirement in both arches maintains the Class I buccal segment relationship, so corresponding premolars are extracted. (Companion Ch 8; Hbk 13.3)", "answerPage": 205, "block": "M"}, {"n": 429, "page": 82, "stem": "Which single statement about extraction in the adult patient is correct?", "options": ["Extraction spaces close spontaneously as in children", "Spontaneous closure does not occur, so appliances are obligatory and anchorage must be planned from the outset", "Extraction is contraindicated in adults", "Only second premolars may be extracted in adults", "Adult extraction sites do not require root parallelism"], "key": "B", "type": "sba", "explanation": "In the permanent dentition, and particularly in adults, spontaneous improvement does not occur and appliance treatment with planned anchorage is obligatory. (Companion Ch 8; Hbk 13.2 and 27.1)", "answerPage": 205, "block": "M"}, {"n": 430, "page": 83, "stem": "Which single number should be quoted when explaining the cost of unsupported anchorage?", "options": ["One quarter of the space is lost", "One third of the space is lost", "Nine-tenths of the space is lost", "Around two-thirds of the space is lost", "No space is lost"], "key": "D", "type": "sba", "explanation": "Around two-thirds of the space created is lost unless anchorage is supported, which is the sharpest single fact on this topic. (Haque 2017; Hbk 14.4)", "answerPage": 205, "block": "M"}, {"n": 431, "page": 84, "stem": "The centre of resistance of a single-rooted tooth lies approximately where?", "options": ["At the apex", "At the incisal edge", "One third to one half down the root from the alveolar crest", "At the cementoenamel junction", "At the bracket"], "key": "C", "type": "sba", "explanation": "For a single-rooted tooth the centre of resistance lies one third to one half down the root; for a multirooted tooth it lies 1 to 2 mm apical to the furcation. (Companion Ch 6; Hbk 14.1)", "answerPage": 205, "block": "N"}, {"n": 432, "page": 84, "stem": "Which statement about the centre of rotation is correct?", "options": ["It moves with the force system applied", "It is fixed by anatomy", "It always coincides with the centre of resistance", "It lies at the apex in all movements", "It is determined by bracket slot size"], "key": "A", "type": "sba", "explanation": "The centre of resistance is fixed by the anatomy; the centre of rotation moves according to the moment-to-force ratio applied. (Companion Ch 6; Hbk 14.1)", "answerPage": 205, "block": "N"}, {"n": 433, "page": 84, "stem": "A couple is best defined as which of the following?", "options": ["A single force applied at the bracket", "The product of force and distance", "Two forces in the same direction", "A force applied through the centre of resistance", "Two equal, opposite, parallel, non-collinear forces producing rotation with no net force"], "key": "E", "type": "sba", "explanation": "A couple produces pure rotation about the centre of resistance wherever it is applied, and has no net translational force. (Companion Ch 6; Hbk 14.1)", "answerPage": 205, "block": "N"}, {"n": 434, "page": 84, "stem": "Which moment-to-force ratio produces bodily movement of a tooth?", "options": ["0 to 1", "Approximately 7 to 1", "Approximately 2 to 1", "Approximately 10 to 1", "Approximately 20 to 1"], "key": "D", "type": "sba", "explanation": "A ratio of approximately 10 to 1 places the centre of rotation at infinity, giving translation. Zero gives uncontrolled tipping; 7 to 1 gives controlled tipping; 12 to 1 and above gives root torque. (Companion Ch 6; Hbk 14.2)", "answerPage": 205, "block": "N"}, {"n": 435, "page": 84, "stem": "A moment-to-force ratio of approximately 7 to 1 produces which movement?", "options": ["Uncontrolled tipping", "Controlled tipping", "Translation", "Root torque", "Pure rotation"], "key": "B", "type": "sba", "explanation": "Controlled tipping places the centre of rotation near the apex, so the crown moves while the root is held. (Companion Ch 6; Hbk 14.2)", "answerPage": 205, "block": "N"}, {"n": 436, "page": 84, "stem": "A single force applied at the bracket with no counterbalancing moment produces which movement?", "options": ["Bodily movement", "Pure rotation", "Root torque", "Pure intrusion", "Uncontrolled tipping, with crown and root moving in opposite directions"], "key": "E", "type": "sba", "explanation": "A moment-to-force ratio of zero gives uncontrolled tipping about a centre of rotation near the centre of resistance. This is what a removable appliance does. (Companion Ch 6; Hbk 14.2)", "answerPage": 205, "block": "N"}, {"n": 437, "page": 85, "stem": "Periodontal attachment loss has which effect on the mechanics of tooth movement?", "options": ["The centre of resistance moves coronally, reducing tipping", "The centre of resistance moves apically, so the same force produces a larger moment and more tipping", "The centre of resistance is unchanged", "The centre of rotation becomes fixed", "Force levels must be increased"], "key": "B", "type": "sba", "explanation": "Bone loss moves the centre of resistance apically, increasing the moment arm from the bracket. Lighter forces and higher moment-to-force ratios are required. (Companion Ch 6; Hbk 14.2)", "answerPage": 205, "block": "N"}, {"n": 438, "page": 85, "stem": "A one-couple system is best described as which of the following?", "options": ["Statically indeterminate", "Applicable only to removable appliances", "Impossible to construct clinically", "Statically determinate, with a calculable and measurable force system", "Always producing pure translation"], "key": "D", "type": "sba", "explanation": "A cantilever or utility arch engaged in one bracket and tied as a point contact elsewhere is statically determinate. A continuous archwire engaged in several brackets is indeterminate. (Nanda; Hbk 14.3)", "answerPage": 205, "block": "N"}, {"n": 439, "page": 85, "stem": "Most clinical orthodontics is statically indeterminate. What does this mean?", "options": ["The force system cannot be calculated, only estimated", "The forces are zero", "The appliance is unstable", "The forces are always excessive", "Equilibrium does not apply"], "key": "A", "type": "sba", "explanation": "Two-couple systems cannot be calculated, only estimated, which is why clinical experience matters so much in continuous archwire mechanics. (Nanda; Hbk 14.3)", "answerPage": 205, "block": "N"}, {"n": 440, "page": 85, "stem": "Which law of physics underlies the concept of orthodontic anchorage?", "options": ["Hooke’s law", "Wolff’s law", "Newton’s third law", "Pascal’s law", "Boyle’s law"], "key": "C", "type": "sba", "explanation": "Every applied force produces an equal and opposite reaction. Anchorage cannot be avoided, only planned. (Companion Ch 6; Hbk 14.4)", "answerPage": 205, "block": "N"}, {"n": 441, "page": 85, "stem": "Maximum anchorage is best defined as which of the following?", "options": ["The anchorage unit may move mesially freely", "Both units move similar amounts", "Equal and opposite movement of two units", "No, or almost no, mesial movement of the anchorage unit", "Anchorage derived from the opposing arch"], "key": "D", "type": "sba", "explanation": "Maximum anchorage means the space is used entirely for anterior retraction. Minimum anchorage allows the posterior unit to use up to two-thirds of the space. (Companion Ch 6; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 442, "page": 85, "stem": "Reciprocal anchorage describes which situation?", "options": ["Anchorage from a miniscrew", "Equal and opposite movement of two units, which is acceptable and intended", "Anchorage from the opposing arch", "Anchorage from a headgear", "Anchorage in the vertical plane only"], "key": "B", "type": "sba", "explanation": "Reciprocal anchorage is used deliberately in midline diastema closure, expansion and crossbite correction with a fixed appliance. (Companion Ch 6; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 443, "page": 85, "stem": "Which single factor most determines the anchorage value of a group of teeth?", "options": ["The number of teeth", "The patient’s age", "The bracket prescription", "The archwire material", "The summed root surface area"], "key": "E", "type": "sba", "explanation": "Jepsen’s measurements of root surface area are the basis of relative anchorage values. Root area matters more than tooth number. (Jepsen 1963; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 444, "page": 86, "stem": "Stationary anchorage is more efficient than simple anchorage because of which fact?", "options": ["The anchor unit is being moved bodily while the active unit tips, using the same absolute anchorage more efficiently", "The anchor unit is bonded to bone", "Fewer teeth are involved", "The wire is stiffer", "Elastics are avoided"], "key": "A", "type": "sba", "explanation": "In stationary anchorage the anchor unit resists bodily movement while the active unit tips, which is a more efficient use of the same anchorage. (Companion Ch 6; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 445, "page": 86, "stem": "Unless anchorage is supported, approximately what proportion of the space created is lost?", "options": ["One quarter", "One third", "Two-thirds", "Nine-tenths", "None"], "key": "C", "type": "sba", "explanation": "Haque and colleagues found that around two-thirds of the space created is lost without anchorage support. (Haque 2017; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 446, "page": 86, "stem": "What did Diar-Bakirly and colleagues conclude about the transpalatal arch?", "options": ["It provides substantial sagittal anchorage", "It provides very little additional anchorage in the sagittal plane", "It reliably distalises molars", "It expands the maxilla by 4 mm", "It prevents root resorption"], "key": "B", "type": "sba", "explanation": "A transpalatal arch provides very little additional anchorage in the sagittal plane, although it is useful for molar derotation and transverse control. (Diar-Bakirly 2017; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 447, "page": 86, "stem": "Rebellato and colleagues reported which finding about the lower lingual arch?", "options": ["It provides substantial anchorage", "It is contraindicated in the mixed dentition", "It reliably preserves leeway space and provides maximum anchorage", "It provides little anchorage support and can procline the lower incisors", "It prevents late lower incisor crowding"], "key": "D", "type": "sba", "explanation": "A lingual arch gives little anchorage support and can procline the lower incisors, although it is effective for preserving leeway space. (Rebellato 1997; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 448, "page": 86, "stem": "Melsen and Verna advised which precaution in maximum anchorage cases?", "options": ["Anchor teeth should not be subject to initial aligning forces", "Use the heaviest wire available from the start", "Bond second molars last", "Avoid transpalatal arches", "Use Class II elastics from the outset"], "key": "A", "type": "sba", "explanation": "In maximum anchorage cases, anchor teeth should be excluded from the initial aligning wire so that anchorage is not spent during levelling. (Melsen and Verna 1999; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 449, "page": 86, "stem": "Proffit’s ratio of anterior retraction to posterior protraction for reciprocal space closure without reinforcement is approximately which value?", "options": ["3 to 1", "2 to 1", "1 to 1", "4 to 1", "10 to 1"], "key": "C", "type": "sba", "explanation": "Reciprocal closure without reinforcement is approximately 1 to 1, determined by periodontal ligament area rather than tooth number. A stabilising arch shifts it to about 2 to 1; headgear with elastics reaches 3 or 4 to 1. (Proffit Ch 15; Hbk 14.4)", "answerPage": 206, "block": "N"}, {"n": 450, "page": 86, "stem": "Which direction of headgear pull is indicated in a patient with increased vertical proportions?", "options": ["Cervical or low pull", "Straight or combination pull", "Headgear is contraindicated", "Any direction", "High pull or occipital"], "key": "E", "type": "sba", "explanation": "High-pull or occipital headgear is intrusive on the molar and is indicated in high-angle patients. Cervical pull is extrusive and suits reduced vertical proportions. (Companion Ch 6; Hbk 14.5)", "answerPage": 206, "block": "N"}, {"n": 451, "page": 87, "stem": "Which force and duration are appropriate for headgear used for anchorage support?", "options": ["250 to 350 g per side for 10 to 12 hours per day", "150 g for 8 hours per day", "450 to 500 g per side for 14 hours per day", "600 g per side for 24 hours per day", "100 g per side for 6 hours per day"], "key": "A", "type": "sba", "explanation": "Anchorage support requires 250 to 350 g per side for 10 to 12 hours per day. Distalisation or an orthopaedic effect requires 450 to 500 g per side for 14 hours per day. (Companion Ch 6; Hbk 14.5)", "answerPage": 206, "block": "N"}, {"n": 452, "page": 87, "stem": "How many independent safety mechanisms are mandatory on a headgear?", "options": ["None", "One", "Two", "Three", "Four"], "key": "C", "type": "sba", "explanation": "Two independent safety mechanisms are mandatory: a self-releasing snap-away neck strap and a locking facebow. (Companion Ch 6; Hbk 14.5)", "answerPage": 206, "block": "N"}, {"n": 453, "page": 87, "stem": "Samuels described which two mechanisms of headgear injury?", "options": ["Direct trauma and thermal injury", "Traction and torsion", "Chemical burn and allergic reaction", "Compression and shearing", "Catapult injury and nocturnal disengagement"], "key": "E", "type": "sba", "explanation": "The catapult injury occurs when the bow disengages under tension and recoils into the face. Nocturnal disengagement occurs during sleep. (Samuels 1996; Hbk 14.5)", "answerPage": 206, "block": "N"}, {"n": 454, "page": 87, "stem": "A patient reports that the headgear facebow came out during the night. What is the correct instruction?", "options": ["Continue wearing it and report at the next visit", "Stop wearing it immediately and attend for review", "Reduce the wear time by half", "Wear it only during the day", "Replace the neck strap and continue"], "key": "B", "type": "sba", "explanation": "The patient should stop wearing it and attend. Consequences of headgear injury include penetrating eye injury with loss of vision and intra-orbital infection. (Samuels 1996; Hbk 14.5)", "answerPage": 206, "block": "N"}, {"n": 455, "page": 87, "stem": "A temporary anchorage device changes which element of the mechanical system?", "options": ["The force system", "The moment-to-force ratio", "Newton’s third law", "The biological response to the force system, by placing the reaction in bone", "The centre of resistance"], "key": "D", "type": "sba", "explanation": "A TAD does not change the force system. It changes the biological response, by placing the reaction where nothing can move. (Mosby ch. on TADs; Hbk 14.6)", "answerPage": 206, "block": "N"}, {"n": 456, "page": 87, "stem": "In direct skeletal anchorage, which requirement applies?", "options": ["The screw must be ligated to the anchor teeth", "A rectangular steel wire must be used", "The line of force must pass through the screw", "The screw must be loaded immediately", "The screw must be in the mandible"], "key": "C", "type": "sba", "explanation": "In direct anchorage the active force acts on or through the screw, so the line of force must pass through it. (Mosby ch. on TADs; Hbk 14.6)", "answerPage": 206, "block": "N"}, {"n": 457, "page": 87, "stem": "In indirect skeletal anchorage, the anchor teeth should be ligated to the screw using which wire?", "options": ["A large rectangular stainless steel wire", "A light elastomeric chain", "A superelastic nickel titanium wire", "A 0.012 inch round wire", "Floss ligature"], "key": "A", "type": "sba", "explanation": "Indirect anchorage requires a rigid connection, so a large rectangular stainless steel wire is used, stiff enough not to flex. (Mosby ch. on TADs; Hbk 14.6)", "answerPage": 206, "block": "N"}, {"n": 458, "page": 88, "stem": "What is the recommended insertion torque range for an orthodontic miniscrew?", "options": ["1 to 3 Ncm", "Over 40 Ncm", "15 to 20 Ncm", "25 to 30 Ncm", "5 to 10 Ncm"], "key": "E", "type": "sba", "explanation": "Below 5 Ncm gives poor primary stability; above 10 Ncm risks microfracture and poor secondary stability. (Companion Ch 11; Hbk 14.6)", "answerPage": 206, "block": "N"}, {"n": 459, "page": 88, "stem": "Miniscrew failure rates rise appreciably below which dimensions?", "options": ["6 mm length and 1.0 mm diameter", "12 mm length and 2.0 mm diameter", "10 mm length and 1.6 mm diameter", "8 mm length and 1.2 mm diameter", "Dimensions do not affect failure"], "key": "D", "type": "sba", "explanation": "Failure rates increase below 8 mm in length and 1.2 mm in diameter. (Companion Ch 11; Hbk 14.6)", "answerPage": 206, "block": "N"}, {"n": 460, "page": 88, "stem": "Which is the single commonest cause of miniscrew failure?", "options": ["Excessive force", "Root contact", "Patient age", "Screw material", "Immediate loading"], "key": "B", "type": "sba", "explanation": "Root contact is the commonest cause of failure, followed by thin cortical bone, mobile mucosa and inflammation. (Companion Ch 11; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 461, "page": 88, "stem": "Which miniscrew site has the lowest reported failure rate?", "options": ["Mandibular buccal shelf", "Maxillary buccal interradicular", "Zygomatic buttress", "Maxillary between the first and second molars", "Median palate"], "key": "E", "type": "sba", "explanation": "The median palate has a failure rate of approximately 1.3 per cent, because placement there is not restricted by the dentition. (Companion Ch 11; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 462, "page": 88, "stem": "Which miniscrew site has the highest reported failure rate?", "options": ["Median palate", "Mandibular buccal shelf", "Maxillary buccal interradicular", "Zygomatic buttress", "Paramedian palate"], "key": "B", "type": "sba", "explanation": "The mandibular buccal shelf has a reported failure rate of approximately 65 per cent, against approximately 1.3 per cent in the median palate. (Companion Ch 11; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 463, "page": 88, "stem": "What is the approximate pooled failure rate for orthodontic miniscrews across all sites?", "options": ["2 per cent", "6 per cent", "25 per cent", "12 per cent", "40 per cent"], "key": "D", "type": "sba", "explanation": "The pooled failure rate is approximately 12.3 per cent, corresponding to an overall survival of 80 to 90 per cent. (Companion Ch 11; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 464, "page": 88, "stem": "A palatal implant requires a minimum bone thickness of which value?", "options": ["4 mm", "2 mm", "1 mm", "8 mm", "10 mm"], "key": "A", "type": "sba", "explanation": "Nanda gives a minimum of 4 mm of bone thickness for a palatal implant, noting that the hard palate generally does not exceed 3 mm outside the paramedian region. (Nanda; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 465, "page": 89, "stem": "After what interval should an orthodontic miniplate be loaded?", "options": ["Immediately", "At 3 months", "At about 3 weeks", "At 6 months", "After 12 months"], "key": "C", "type": "sba", "explanation": "Nanda recommends loading a miniplate at approximately three weeks, not immediately, and notes a requirement for 2 to 3 mm of cortical bone depth. (Nanda; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 466, "page": 89, "stem": "A miniscrew is mobile at four weeks. What is the correct management?", "options": ["Tighten it and continue", "Splint it to the adjacent tooth", "Reduce the force and continue", "Remove it, identify the cause, and either re-site it or change the anchorage plan", "Prescribe antibiotics and continue"], "key": "D", "type": "sba", "explanation": "A mobile screw will not become stable and perpetuates inflammation. Remove it, check for root contact, and re-site or change the plan. (Companion Ch 11; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 467, "page": 89, "stem": "Which single factor most governs the success of a temporary anchorage device?", "options": ["The material of the screw", "Cortical bone thickness at the site", "The patient’s age", "The archwire in use", "The bracket prescription"], "key": "B", "type": "sba", "explanation": "Success is governed principally by cortical bone thickness, together with the avoidance of root contact and of mobile mucosa. (Proffit Ch 10; Hbk 14.6)", "answerPage": 207, "block": "N"}, {"n": 468, "page": 89, "stem": "Which force is appropriate for space closure using sliding mechanics?", "options": ["50 g", "Over 600 g", "300 g", "500 g", "150 g"], "key": "E", "type": "sba", "explanation": "Space closure is performed at approximately 150 g. Attempts to transfer traditional edgewise forces of 500 to 600 g produced the roller coaster effect, and 200 g is no better than 150 g. (McLaughlin, Bennett and Trevisi; Hbk 14.4 and 18.2)", "answerPage": 207, "block": "N"}, {"n": 469, "page": 89, "stem": "Which effect does bonding the second molars have on anchorage and levelling?", "options": ["It brings the second molars into the system, aiding bite opening and increasing the anchorage unit", "It reduces anchorage", "It has no effect", "It increases root resorption", "It prevents sliding mechanics"], "key": "A", "type": "sba", "explanation": "Second molars should be bonded as early as possible: they are needed in the system for bite opening and they add to the anchorage unit. (Bennett and McLaughlin; Hbk 18.1)", "answerPage": 207, "block": "N"}, {"n": 470, "page": 89, "stem": "A laceback is best described as which of the following?", "options": ["An elastomeric chain from molar to canine", "A bend placed distal to the molar tube", "A passive 0.010 inch wire ligature from the molar to the canine", "A stainless steel wire tied to a miniscrew", "A stop placed mesial to the molar"], "key": "C", "type": "sba", "explanation": "A laceback is a passive wire ligature that distalises the canine without tipping it, and prevents incisor advance during levelling. (Bennett and McLaughlin; Hbk 18.1)", "answerPage": 207, "block": "N"}, {"n": 471, "page": 89, "stem": "Without lacebacks, the lower incisor advances by approximately how much during levelling?", "options": ["0.2 mm", "1.4 mm", "3 mm", "5 mm", "It does not advance"], "key": "B", "type": "sba", "explanation": "Without lacebacks the lower incisor advances by approximately 1.4 mm; with them it retracts by approximately 1.0 mm. (McLaughlin, Bennett and Trevisi; Hbk 14.4 and 18.1)", "answerPage": 207, "block": "N"}, {"n": 472, "page": 90, "stem": "A bendback serves which purpose?", "options": ["To increase anchorage in the vertical plane", "To open the bite", "To derotate the molar", "To minimise labial tipping of the incisors as the wire straightens", "To retain the arch form"], "key": "D", "type": "sba", "explanation": "A bendback is placed in the wire distal to the molar tube to minimise labial tipping of the incisors during alignment. (Bennett and McLaughlin; Hbk 18.1)", "answerPage": 207, "block": "N"}, {"n": 473, "page": 90, "stem": "Class II elastics produce which combination of side effects?", "options": ["Lower incisor proclination, upper incisor extrusion and an increased occlusal plane cant", "Lower incisor retroclination and upper incisor intrusion", "Molar intrusion in both arches", "Reduction in lower face height", "Maxillary expansion"], "key": "A", "type": "sba", "explanation": "Class II elastics correct the molar relationship at the cost of lower incisor proclination, upper incisor extrusion and an increased occlusal plane cant. They are barred if the lower incisors are already forward. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 207, "block": "N"}, {"n": 474, "page": 90, "stem": "Class III elastics are particularly hazardous in which patient?", "options": ["A low-angle patient", "A patient with a deep overbite", "A high-angle patient with an increased lower face height", "A growing patient", "A patient with a Class III skeletal base"], "key": "C", "type": "sba", "explanation": "Class III elastics extrude the lower molars and rotate the mandible down and back, which is dangerous in a high-angle patient. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 207, "block": "N"}, {"n": 475, "page": 90, "stem": "Which single statement about anchorage in the maxillary arch is supported by the evidence?", "options": ["The maxillary arch resists anchorage loss better than the mandibular arch", "Anchorage is unnecessary in the maxilla", "Anchorage loss occurs only in the mandible", "Anchorage loss is independent of arch", "The maxillary arch is particularly susceptible to anchorage loss"], "key": "E", "type": "sba", "explanation": "Giannopoulou and colleagues found the maxillary arch particularly susceptible to anchorage loss. (Giannopoulou 2016; Hbk 14.4)", "answerPage": 207, "block": "N"}, {"n": 476, "page": 90, "stem": "The equilibrium equations governing an orthodontic force system state which of the following?", "options": ["The sum of forces equals zero and the sum of moments equals zero", "The sum of forces equals the sum of moments", "Forces must exceed moments", "Moments must exceed forces", "Neither forces nor moments need balance"], "key": "A", "type": "sba", "explanation": "Equilibrium requires that the sum of forces and the sum of moments both equal zero. Every applied force produces a reaction somewhere. (Nanda; Hbk 14.3)", "answerPage": 207, "block": "N"}, {"n": 477, "page": 90, "stem": "Which anchorage classification allows the anchorage unit to move mesially freely?", "options": ["Maximum, or Group A", "Moderate, or Group B", "Minimum, or Group C", "Reciprocal", "Absolute"], "key": "C", "type": "sba", "explanation": "Minimum anchorage, Group C, allows the posterior segment to use up to two-thirds of the space. (Companion Ch 6; Hbk 14.4)", "answerPage": 207, "block": "N"}, {"n": 478, "page": 90, "stem": "Cortical anchorage refers to which concept?", "options": ["Anchorage from the cortical plate of the palate", "Anchorage in the vertical plane", "Anchorage from a miniplate", "Anchorage from the opposing arch", "Increased resistance to movement when roots lie against cortical bone"], "key": "E", "type": "sba", "explanation": "Roots driven against cortical bone resist movement more, which increases anchorage but also increases the risk of root resorption. (Companion Ch 6; Hbk 14.4)", "answerPage": 207, "block": "N"}, {"n": 479, "page": 91, "stem": "Which single statement about a Nance button is correct?", "options": ["It provides absolute anchorage", "It provides palatal anchorage but carries a risk of ulceration beneath the acrylic button", "It is used only in the mandible", "It expands the maxilla", "It cannot be combined with a fixed appliance"], "key": "B", "type": "sba", "explanation": "The Nance button provides palatal anchorage, with a recognised risk of ulceration and tissue overgrowth beneath the acrylic. (Companion Ch 6; Hbk 15.5)", "answerPage": 207, "block": "N"}, {"n": 480, "page": 91, "stem": "Which is the correct force for intrusion of a single tooth?", "options": ["150 g", "35 to 60 g", "100 g", "10 to 20 g", "250 g"], "key": "D", "type": "sba", "explanation": "Intrusion requires 10 to 20 g per tooth because force is concentrated at the small apical surface area. It is the lightest movement in orthodontics. (Proffit Ch 14; Hbk 14.4 and 25.1)", "answerPage": 208, "block": "N"}, {"n": 481, "page": 91, "stem": "Which single statement about placing a miniscrew as a general dentist with an interest in orthodontics is most defensible?", "options": ["All sites are equally appropriate", "Miniscrews should never be placed outside a specialist practice", "Placement in the maxillary buccal interradicular region with adequate space and imaging is within scope with appropriate training, whereas the mandibular buccal shelf is not", "Miniscrews may be placed without imaging", "Miniscrews are contraindicated in general practice"], "key": "C", "type": "sba", "explanation": "Recognising which sites are reliable and which are not, and referring the whole case rather than the screw when the case depends on a difficult site, demonstrates the judgement examiners look for. (Companion Ch 11; Hbk 14.6)", "answerPage": 208, "block": "N"}, {"n": 482, "page": 92, "stem": "Which property is defined as the gradient of the elastic portion of the stress-strain curve?", "options": ["Stiffness", "Strength", "Range", "Formability", "Resilience"], "key": "A", "type": "sba", "explanation": "Stiffness is Young’s modulus, the gradient of the elastic portion. Low stiffness is desirable in an aligning wire. (Companion Ch 10; Hbk 15.1)", "answerPage": 208, "block": "O"}, {"n": 483, "page": 92, "stem": "Springback is calculated as which ratio?", "options": ["Stiffness divided by range", "Resilience divided by strength", "Modulus of elasticity divided by yield strength", "Range multiplied by stiffness", "Yield strength divided by modulus of elasticity"], "key": "E", "type": "sba", "explanation": "Springback equals yield strength divided by modulus of elasticity, and is effectively the working range of the wire. (Companion Ch 10; Hbk 15.1)", "answerPage": 208, "block": "O"}, {"n": 484, "page": 92, "stem": "Which identity relates the three principal wire properties?", "options": ["Strength equals stiffness plus range", "Stiffness equals strength multiplied by range", "Range equals strength multiplied by stiffness", "Strength equals stiffness multiplied by range", "The three are independent"], "key": "D", "type": "sba", "explanation": "Proffit’s identity is strength equals stiffness multiplied by range. You cannot raise one without paying elsewhere. (Proffit Ch 9; Hbk 15.1)", "answerPage": 208, "block": "O"}, {"n": 485, "page": 92, "stem": "Which combination describes the ideal orthodontic archwire?", "options": ["High strength, high stiffness, low range, low formability", "High strength, low stiffness, high range, high formability", "Low strength, low stiffness, high range, low formability", "High strength, high stiffness, high range, low formability", "Low strength, high stiffness, low range, high formability"], "key": "B", "type": "sba", "explanation": "The ideal wire has high strength, low stiffness, high range and high formability, plus biocompatibility, weldability, low friction and low cost. No single wire meets all of these. (Proffit Ch 9; Hbk 15.1)", "answerPage": 208, "block": "O"}, {"n": 486, "page": 92, "stem": "Which is the composition of austenitic stainless steel used in orthodontics?", "options": ["Iron 50 per cent, chromium 30 per cent, nickel 20 per cent", "Titanium and molybdenum", "Iron 90 per cent, chromium 5 per cent, nickel 5 per cent", "Titanium 55 per cent, nickel 45 per cent", "Iron 70 per cent, chromium 17 to 20 per cent, nickel 8 to 12 per cent"], "key": "E", "type": "sba", "explanation": "The 18-8 austenitic composition is iron approximately 70 per cent, chromium 17 to 20 per cent, nickel 8 to 12 per cent and carbon up to 0.08 per cent. (Companion Ch 10; Hbk 15.2)", "answerPage": 208, "block": "O"}, {"n": 487, "page": 92, "stem": "The modulus of elasticity of nickel titanium relative to stainless steel is approximately which value?", "options": ["0.05", "0.26", "0.5", "1.0", "2.0"], "key": "B", "type": "sba", "explanation": "Nickel titanium has a modulus approximately 0.26 that of stainless steel, giving it much lower stiffness and a much larger working range. (Mosby ch. on materials; Hbk 15.2)", "answerPage": 208, "block": "O"}, {"n": 488, "page": 93, "stem": "The stiffness of beta titanium relative to stainless steel is approximately which value?", "options": ["One tenth", "Equal", "One half", "One third", "Twice"], "key": "D", "type": "sba", "explanation": "Beta titanium, or TMA, has a stiffness of approximately one third that of stainless steel, with good formability and weldability but higher friction. (Companion Ch 10; Hbk 15.2)", "answerPage": 208, "block": "O"}, {"n": 489, "page": 93, "stem": "Which property of nickel titanium prevents it from being used for a bonded retainer or a finishing wire with bends?", "options": ["Its inability to be bent, welded or soldered", "Its high stiffness", "Its low range", "Its high cost", "Its high friction"], "key": "A", "type": "sba", "explanation": "Nickel titanium cannot be permanently bent, welded or soldered, which limits it to alignment. (Companion Ch 10; Hbk 15.2)", "answerPage": 208, "block": "O"}, {"n": 490, "page": 93, "stem": "Superelasticity in a nickel titanium archwire refers to which phenomenon?", "options": ["A high modulus of elasticity", "Shape memory on heating", "A load-deflection plateau with hysteresis, arising from a stress-induced phase transformation", "A low yield strength", "High formability"], "key": "C", "type": "sba", "explanation": "Superelasticity is a real, measurable phenomenon arising from a stress-induced austenite to martensite transformation, producing a plateau in the unloading curve. (Proffit Ch 9; Hbk 15.2)", "answerPage": 208, "block": "O"}, {"n": 491, "page": 93, "stem": "Which archwire comparison was supported by Cochrane evidence?", "options": ["Copper nickel titanium is superior to conventional nickel titanium", "Beta titanium aligns faster than nickel titanium", "Stainless steel aligns faster than nickel titanium", "Coaxial superelastic nickel titanium produces greater movement over 12 weeks than singlestrand nickel titanium", "No archwire has ever been compared"], "key": "D", "type": "sba", "explanation": "Wang and colleagues found greater movement with coaxial superelastic nickel titanium over 12 weeks; otherwise there is insufficient evidence that any archwire is superior. (Wang 2018; Hbk 15.2)", "answerPage": 208, "block": "O"}, {"n": 492, "page": 93, "stem": "Papageorgiou and colleagues in 2014 reported which finding about copper nickel titanium?", "options": ["It is significantly faster than conventional nickel titanium", "It is slightly slower to reach a working wire and more painful", "It causes less root resorption", "It is stiffer than stainless steel", "It cannot be used in the mandible"], "key": "B", "type": "sba", "explanation": "Austenitic-active wires were slightly better than martensitic-stabilised ones, and copper nickel titanium sequences were slightly slower to a working wire and more painful. (Papageorgiou 2014; Hbk 15.2)", "answerPage": 208, "block": "O"}, {"n": 493, "page": 93, "stem": "Which is the standard etchant concentration and time for enamel bonding?", "options": ["10 per cent phosphoric acid for 60 seconds", "Hydrofluoric acid for 20 seconds", "50 per cent phosphoric acid for 5 seconds", "17 per cent EDTA for 2 minutes", "37 per cent phosphoric acid for 15 to 30 seconds"], "key": "E", "type": "sba", "explanation": "Enamel is etched with 37 per cent phosphoric acid for 15 to 30 seconds, then rinsed and dried to a frosted appearance. (Mosby ch. on bonding; Hbk 15.3)", "answerPage": 208, "block": "O"}, {"n": 494, "page": 94, "stem": "Self-etching primers compared with conventional etch and bond show which characteristic?", "options": ["A shallower etch pattern, faster application, and comparable clinical bond failure rates", "Significantly higher bond failure rates", "Superior bond strength in all studies", "Incompatibility with light curing", "A requirement for a separate etchant"], "key": "A", "type": "sba", "explanation": "Self-etching primers combine etch and prime, produce a shallower etch pattern, and give comparable clinical bond failure rates. (Companion Ch 10; Hbk 15.3)", "answerPage": 208, "block": "O"}, {"n": 495, "page": 94, "stem": "Ceramic brackets bond to composite by which principal mechanism?", "options": ["Mechanical retention alone", "Ionic exchange", "Silane coupling, providing a chemical bond", "Micromechanical retention in the enamel only", "Adhesion by van der Waals forces"], "key": "C", "type": "sba", "explanation": "Silane coupling gives a chemical bond. The consequence is that ceramic brackets bond too well, and the enamel may pay at debond. (Mosby ch. on bonding; Hbk 15.3)", "answerPage": 208, "block": "O"}, {"n": 496, "page": 94, "stem": "Which is a recognised disadvantage of ceramic brackets?", "options": ["Poor aesthetics", "Brittleness, higher friction, abrasion of opposing enamel, and risk of enamel fracture at debond", "Inability to accept a rectangular wire", "Incompatibility with elastomeric modules", "Excessive flexibility"], "key": "B", "type": "sba", "explanation": "Ceramic brackets are more brittle, have higher friction, abrade opposing enamel, and carry a risk of enamel fracture at debond. (Companion Ch 10; Hbk 15.3)", "answerPage": 208, "block": "O"}, {"n": 497, "page": 94, "stem": "Which cement is preferred for orthodontic bands because of its fluoride release?", "options": ["Zinc phosphate", "Zinc polycarboxylate", "Composite resin", "Glass ionomer", "Calcium hydroxide"], "key": "D", "type": "sba", "explanation": "Glass ionomer cement releases fluoride and is preferred for band cementation, particularly in patients at risk of demineralisation. (Companion Ch 10; Hbk 15.3)", "answerPage": 209, "block": "O"}, {"n": 498, "page": 94, "stem": "White spot lesions become visible within approximately what period of appliance placement?", "options": ["6 months", "2 weeks", "18 months", "3 years", "Only after debond"], "key": "A", "type": "sba", "explanation": "White spot lesions can be visible within 6 months and affect up to half of fixed appliance patients. (Gorelick 1982; Hbk 15.3 and 29.2)", "answerPage": 209, "block": "O"}, {"n": 499, "page": 94, "stem": "Which teeth are the commonest sites for white spot lesions during fixed appliance treatment?", "options": ["Lower incisors and lower premolars", "Upper central incisors and upper canines", "First molars, upper lateral incisors and lower canines", "Second molars only", "Lower molars only"], "key": "C", "type": "sba", "explanation": "The commonest sites are first molars, upper lateral incisors and lower canines, and lesions are more prevalent in males. (Gorelick 1982; Hbk 15.3)", "answerPage": 209, "block": "O"}, {"n": 500, "page": 94, "stem": "Benson and colleagues in 2019 recommended which preventive regimen?", "options": ["Fluoride varnish annually", "No specific regimen", "Chlorhexidine mouthwash twice daily indefinitely", "Silver diamine fluoride at debond", "Daily high-fluoride toothpaste plus professional high-concentration fluoride every 6 to 8 weeks"], "key": "E", "type": "sba", "explanation": "Daily high-fluoride toothpaste, at 2800 or 5000 parts per million, plus professional highconcentration fluoride foam or varnish every 6 to 8 weeks, is the recommended regimen. (Benson 2019; Hbk 15.3)", "answerPage": 209, "block": "O"}, {"n": 501, "page": 95, "stem": "Which ligation method is preferred in a patient with poor plaque control?", "options": ["Stainless steel ligatures", "Elastomeric modules", "Elastomeric chain", "Self-ligating clips only", "Any method is equivalent"], "key": "A", "type": "sba", "explanation": "Steel ligatures rather than elastomeric modules reduce plaque retention, and are described as the cheapest intervention available in a poor brusher. (Mosby ch. on complications; Hbk 15.3)", "answerPage": 209, "block": "O"}, {"n": 502, "page": 95, "stem": "Which instrument and technique is recommended for adhesive clean-up at debond?", "options": ["A diamond bur at high speed", "An ultrasonic scaler", "A tungsten carbide bur at low speed, followed by polishing", "A steel scaler alone", "Air abrasion"], "key": "C", "type": "sba", "explanation": "A tungsten carbide bur at low speed followed by polishing minimises enamel loss and iatrogenic damage. (Companion Ch 10; Hbk 15.3)", "answerPage": 209, "block": "O"}, {"n": 503, "page": 95, "stem": "Which is the typical archwire used for initial alignment?", "options": ["0.019 by 0.025 inch stainless steel", "0.016 by 0.022 inch cobalt chromium", "0.021 by 0.025 inch beta titanium", "0.036 inch stainless steel", "0.012 to 0.018 inch round nickel titanium or multistrand"], "key": "E", "type": "sba", "explanation": "Alignment uses light, flexible, large-range wires: 0.012 to 0.018 inch round nickel titanium or multistrand. (Companion Ch 10; Hbk 15.2 and 18.1)", "answerPage": 209, "block": "O"}, {"n": 504, "page": 95, "stem": "Which is the standard MBT working wire in a 0.022 inch slot?", "options": ["0.016 inch stainless steel", "0.019 by 0.025 inch stainless steel", "0.017 by 0.025 inch beta titanium", "0.021 by 0.025 inch stainless steel", "0.018 inch nickel titanium"], "key": "B", "type": "sba", "explanation": "The 0.019 by 0.025 inch stainless steel wire in a 0.022 slot gives overbite control while remaining loose enough to slide. (McLaughlin, Bennett and Trevisi; Hbk 15.2 and 18.2)", "answerPage": 209, "block": "O"}, {"n": 505, "page": 95, "stem": "A 0.016 by 0.022 inch wire deflects approximately how much more than a 0.019 by 0.025 inch wire in the same slot?", "options": ["10 per cent", "25 per cent", "80 per cent", "47 per cent", "They deflect equally"], "key": "D", "type": "sba", "explanation": "The MBT literature gives 47 per cent more deflection with 0.016 by 0.022 than with 0.019 by 0.025. (McLaughlin, Bennett and Trevisi; Hbk 15.2)", "answerPage": 209, "block": "O"}, {"n": 506, "page": 95, "stem": "Popular superelastic nickel titanium archwires may expand the lower intercanine width by up to which amount?", "options": ["1 mm", "2.4 mm", "5.9 mm", "9 mm", "They do not expand it"], "key": "C", "type": "sba", "explanation": "Preformed superelastic nickel titanium archwires may expand the lower intercanine width by up to 5.9 mm if allowed to express fully, which is why arch form must be a deliberate decision. (McLaughlin, Bennett and Trevisi; Hbk 15.2 and 18.5)", "answerPage": 209, "block": "O"}, {"n": 507, "page": 95, "stem": "Cobalt chromium wire such as Elgiloy has which distinctive property?", "options": ["It is supplied soft and formable, then heat-treated to raise its stiffness", "It cannot be bent", "It is superelastic", "It cannot be soldered", "It has a lower modulus than nickel titanium"], "key": "A", "type": "sba", "explanation": "Cobalt chromium is supplied in a soft, formable state and is heat-treated after bending to raise its stiffness. (Companion Ch 10; Hbk 15.2)", "answerPage": 209, "block": "O"}, {"n": 508, "page": 96, "stem": "Which single statement about aesthetic coated archwires is correct?", "options": ["They match the mechanical properties of uncoated wires", "They eliminate friction", "They are stiffer than stainless steel", "They cannot be used with ceramic brackets", "Their mechanical properties are inferior and the coating degrades in service"], "key": "E", "type": "sba", "explanation": "Coated and composite aesthetic wires have poorer mechanical properties and the coating degrades, so their role remains limited. (Companion Ch 10; Hbk 15.2)", "answerPage": 209, "block": "O"}, {"n": 509, "page": 96, "stem": "Nickel allergy affects approximately what proportion of females?", "options": ["1 to 3 per cent", "60 per cent", "40 to 50 per cent", "10 to 30 per cent", "Under 1 per cent"], "key": "D", "type": "sba", "explanation": "Nickel allergy affects approximately 10 to 30 per cent of females and 1 to 3 per cent of males. (Chakravarthi 2012; Hbk 15.6)", "answerPage": 209, "block": "O"}, {"n": 510, "page": 96, "stem": "A patient with a documented nickel allergy requires fixed appliance treatment. What is the correct approach?", "options": ["Orthodontic treatment is contraindicated", "Avoid nickel titanium and use stainless steel, beta titanium or alternatives, and avoid extraoral nickel components", "Use nickel titanium but prescribe antihistamines", "Use only ceramic brackets", "Treat with aligners only"], "key": "B", "type": "sba", "explanation": "Stainless steel is safe because the nickel is bound within the austenitic lattice. Avoid nickel titanium and extra-oral nickel-containing components. (Companion Ch 7; Hbk 15.6)", "answerPage": 209, "block": "O"}, {"n": 511, "page": 96, "stem": "The prevalence of latex allergy in healthcare workers is approximately which value?", "options": ["1.2 per cent", "4.3 per cent", "35 per cent", "20 per cent", "9.7 per cent"], "key": "E", "type": "sba", "explanation": "Latex allergy affects approximately 4.3 per cent of the general population and 9.7 per cent of healthcare workers. (Wu 2016; Hbk 15.6)", "answerPage": 209, "block": "O"}, {"n": 512, "page": 96, "stem": "Which is the correct activation regimen for a removable expansion plate?", "options": ["1 mm daily", "0.25 mm twice weekly", "0.25 mm daily", "2 mm weekly", "0.5 mm monthly"], "key": "B", "type": "sba", "explanation": "A removable expansion plate is activated 0.25 mm twice weekly, giving slow, largely dental expansion. (Companion Ch 12; Hbk 15.5 and 24.2)", "answerPage": 209, "block": "O"}, {"n": 513, "page": 96, "stem": "Which is the correct activation regimen for a rapid maxillary expander?", "options": ["0.25 mm twice weekly", "2 mm per day for 1 week", "1 turn per week for 3 months", "1 to 4 turns per day, giving 0.25 to 1 mm per day, over 2 to 4 weeks", "0.1 mm per day for 6 months"], "key": "D", "type": "sba", "explanation": "Rapid maxillary expansion uses 1 to 4 turns per day over 2 to 4 weeks, generating forces up to 10 kg. (Companion Ch 9; Hbk 15.5 and 24.2)", "answerPage": 209, "block": "O"}, {"n": 514, "page": 96, "stem": "What force may be generated by a rapid maxillary expander?", "options": ["Up to 10 kg", "Up to 2 kg", "Up to 500 g", "Up to 50 kg", "Under 100 g"], "key": "A", "type": "sba", "explanation": "Rapid maxillary expansion generates forces of up to approximately 10 kg, which is why it opens the midpalatal suture. (Companion Ch 9; Hbk 15.5 and 24.2)", "answerPage": 209, "block": "O"}, {"n": 515, "page": 97, "stem": "Which appliance was found by Cochrane review to be approximately 3 months faster than an expansion plate?", "options": ["The transpalatal arch", "The Nance button", "The quadhelix", "The lingual arch", "The rapid maxillary expander"], "key": "C", "type": "sba", "explanation": "Ugolini and colleagues found that a quadhelix beats an expansion plate and is approximately 3 months faster, with high-certainty evidence at ages 7 to 11. (Ugolini 2021; Hbk 15.5 and 24.2)", "answerPage": 209, "block": "O"}, {"n": 516, "page": 97, "stem": "The diode laser used in orthodontics operates at which wavelength range?", "options": ["400 to 500 nm", "2940 nm", "1064 nm only", "810 to 980 nm", "10600 nm"], "key": "D", "type": "sba", "explanation": "The orthodontic diode laser operates at 810 to 980 nm, absorbed by melanin and haemoglobin, cutting soft tissue while sparing enamel and metal. (Mosby ch. on lasers; Hbk 15.5)", "answerPage": 210, "block": "O"}, {"n": 517, "page": 97, "stem": "Which is an appropriate orthodontic use of a diode laser?", "options": ["Cutting enamel to create space", "Exposure of a partially erupted tooth, gingival recontouring, frenectomy or operculectomy", "Removing composite adhesive", "Cutting an archwire", "Debonding ceramic brackets"], "key": "B", "type": "sba", "explanation": "The diode laser is a soft tissue finishing instrument. The cause of any gingival disproportion should be diagnosed before it is used. (Mosby ch. on lasers; Hbk 15.5)", "answerPage": 210, "block": "O"}, {"n": 518, "page": 97, "stem": "Alginate impressions must be cast within approximately what period?", "options": ["Timing is unimportant", "Within 24 hours", "Within 3 days", "Within a week", "Immediately or within about 10 minutes, or stored in 100 per cent humidity"], "key": "E", "type": "sba", "explanation": "Alginate is dimensionally unstable and should be cast promptly or stored in 100 per cent humidity. (Companion Ch 10; Hbk 15.4)", "answerPage": 210, "block": "O"}, {"n": 519, "page": 97, "stem": "Which is the principal advantage of glass ionomer over composite for band cementation?", "options": ["Fluoride release", "Higher bond strength", "Better aesthetics", "Faster setting", "Lower cost only"], "key": "A", "type": "sba", "explanation": "Fluoride release is the principal advantage, and is relevant because bands are placed on teeth at risk of demineralisation. (Companion Ch 10; Hbk 15.3)", "answerPage": 210, "block": "O"}, {"n": 520, "page": 97, "stem": "Which orthodontic instrument should be used to prevent a cut archwire end from being inhaled or swallowed?", "options": ["A ligature cutter", "A Weingart plier", "A distal end cutter that retains the fragment", "A How plier", "A bird beak plier"], "key": "C", "type": "sba", "explanation": "A distal end cutter retains the fragment. Wire ends are sharps, and every wire end must be accounted for. (Companion Ch 10; Hbk 30.1)", "answerPage": 210, "block": "O"}, {"n": 521, "page": 97, "stem": "Which is the correct storage and maintenance procedure for orthodontic pliers after sterilisation?", "options": ["Store wet in disinfectant", "Dry thoroughly and oil the hinges after sterilisation", "Store in the autoclave", "Wrap in gauze while damp", "No maintenance is required"], "key": "B", "type": "sba", "explanation": "Orthodontic pliers are heat-tolerant but corrode. They must be dried thoroughly and the hinges oiled after sterilisation. (Local decontamination guidance; Hbk 30.1)", "answerPage": 210, "block": "O"}, {"n": 522, "page": 98, "stem": "Resilience is best defined as which quantity?", "options": ["The gradient of the elastic portion", "The permanent deformation tolerated", "The maximum load before fracture", "The area under the elastic portion of the stress-strain curve", "The distance the wire can be deflected"], "key": "D", "type": "sba", "explanation": "Resilience is the energy stored, represented by the area under the elastic portion of the curve. (Companion Ch 10; Hbk 15.1)", "answerPage": 210, "block": "O"}, {"n": 523, "page": 98, "stem": "Formability is best defined as which quantity?", "options": ["The amount of permanent deformation the wire tolerates before fracture", "The stiffness of the wire", "The energy stored elastically", "The yield strength", "The modulus of elasticity"], "key": "A", "type": "sba", "explanation": "Formability describes how far a wire can be bent permanently without fracturing, and is why stainless steel remains indispensable for finishing. (Companion Ch 10; Hbk 15.1)", "answerPage": 210, "block": "O"}, {"n": 524, "page": 98, "stem": "Which properties are not represented on the stress-strain curve but matter clinically?", "options": ["Stiffness and range", "Yield strength and resilience", "Biocompatibility, environmental stability, joinability, friction and cost", "Strength and springback", "Modulus and formability"], "key": "C", "type": "sba", "explanation": "Biocompatibility, environmental stability, joinability, friction, ductility and cost are all clinically important and are not on the curve. (Companion Ch 10; Hbk 15.1)", "answerPage": 210, "block": "O"}, {"n": 525, "page": 98, "stem": "Which single statement about intra-oral scanning accuracy is correct?", "options": ["It is inferior to alginate for full arches", "It cannot produce a digital set-up", "It is unaffected by moisture", "It is more accurate for edentulous spans than for dentate arches", "It is comparable to addition silicone for full arches, with deep undercuts and subgingival margins remaining harder"], "key": "E", "type": "sba", "explanation": "Full-arch accuracy is comparable to addition silicone in most studies. Deep undercuts, subgingival margins and edentulous spans remain more difficult. (Mosby ch. on digital planning; Hbk 15.4)", "answerPage": 210, "block": "O"}, {"n": 526, "page": 99, "stem": "Removable appliance design should be considered under which four headings?", "options": ["Active components, retention, anchorage, baseplate", "Aims, retention, anchorage, baseplate", "Alignment, retraction, anchorage, bite plane", "Anchorage, reciprocation, adjustment, baseplate", "Aesthetics, retention, adjustment, bonding"], "key": "A", "type": "sba", "explanation": "The ARAB mnemonic covers Active components, Retention, Anchorage and Baseplate. (Companion Ch 9; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 527, "page": 99, "stem": "Which movement can a removable appliance deliver?", "options": ["Bodily movement", "Root torque", "Uncontrolled tipping", "Rotation of a canine", "Intrusion of a molar"], "key": "C", "type": "sba", "explanation": "A removable appliance achieves only two-point contact on a tooth and therefore delivers uncontrolled tipping. Bodily movement, rotation and torque are beyond it. (Companion Ch 9; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 528, "page": 99, "stem": "What wire gauge is conventionally used for an Adams clasp on a first permanent molar?", "options": ["0.5 mm", "0.6 mm", "1.2 mm", "0.9 mm", "0.7 mm"], "key": "E", "type": "sba", "explanation": "An Adams clasp on a molar uses 0.7 mm wire; on a premolar 0.6 mm is used. (Companion Ch 9; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 529, "page": 99, "stem": "Which wire gauge is used for a palatal finger spring?", "options": ["0.7 mm", "0.5 mm", "0.9 mm", "1.0 mm", "0.3 mm"], "key": "B", "type": "sba", "explanation": "A palatal finger spring uses 0.5 mm wire, often with a guard. A buccal canine retractor uses 0.7 mm. (Companion Ch 9; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 530, "page": 99, "stem": "By approximately how much should a palatal finger spring be activated?", "options": ["One quarter of the wire diameter", "5 mm", "Twice the wire diameter", "Approximately half the diameter of the spring wire", "Activation is not required"], "key": "D", "type": "sba", "explanation": "A palatal finger spring is activated by approximately half the diameter of the wire, delivering approximately 25 to 40 g. (Companion Ch 9; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 531, "page": 99, "stem": "What force is appropriate for tipping a single tooth with a removable appliance?", "options": ["10 g", "100 g", "25 to 40 g", "200 g", "400 g"], "key": "C", "type": "sba", "explanation": "Tipping a single tooth requires approximately 25 to 40 g. Excess force causes discomfort, appliance displacement and anchorage loss. (Companion Ch 9; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 532, "page": 100, "stem": "The two fatal limitations of removable appliances are which of the following?", "options": ["Compliance and two-point contact", "Cost and aesthetics", "Anchorage and retention", "Speech and hygiene", "Breakage and adjustment time"], "key": "A", "type": "sba", "explanation": "Proffit identifies compliance and two-point contact as the two fatal limitations of removable appliances. (Proffit Ch 10; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 533, "page": 100, "stem": "A flat anterior bite plane in a removable appliance serves which purpose?", "options": ["Crossbite correction", "Retention of expansion", "Rotation of incisors", "Anchorage reinforcement only", "Overbite reduction"], "key": "E", "type": "sba", "explanation": "A flat anterior bite plane disoccludes the posterior teeth and allows them to erupt, reducing the overbite by relative intrusion in a growing patient. (Companion Ch 9; Hbk 16.1 and 25.1)", "answerPage": 210, "block": "P"}, {"n": 534, "page": 100, "stem": "Posterior bite planes in a removable appliance are used principally for which purpose?", "options": ["Overbite reduction", "Retention", "Anchorage", "Disocclusion during anterior or posterior crossbite correction", "Molar distalisation"], "key": "D", "type": "sba", "explanation": "Posterior bite planes disocclude the teeth to allow a crossbite to be corrected, particularly an anterior crossbite being corrected by proclination. (Companion Ch 9; Hbk 16.1)", "answerPage": 210, "block": "P"}, {"n": 535, "page": 100, "stem": "Functional appliances produce which predominant effect?", "options": ["Skeletal change of 8 to 10 mm", "Dentoalveolar change, with a small and largely transient skeletal effect", "Pure condylar growth with no dental change", "Maxillary expansion only", "Vertical change only"], "key": "B", "type": "sba", "explanation": "The dominant effect is dentoalveolar: upper incisors retrocline, lower incisors procline, and buccal segment eruption is guided. The skeletal effect is a few millimetres at best and essentially transient. (Companion Ch 9; Hbk 16.2)", "answerPage": 211, "block": "P"}, {"n": 536, "page": 100, "stem": "Which is the most sophisticated explanation of how functional appliances work?", "options": ["They stimulate condylar cartilage directly", "They reposition the glenoid fossa", "They restrain maxillary growth only", "They alter muscle fibre type permanently", "They unlock the occlusion and permit normal mandibular growth to express itself, alongside dentoalveolar change"], "key": "E", "type": "sba", "explanation": "The occlusion is locked by intercuspation; the appliance unlocks it. This reads far better than saying the appliance grows the mandible. (Companion Ch 9; Hbk 16.2)", "answerPage": 211, "block": "P"}, {"n": 537, "page": 100, "stem": "At what angle to the occlusal plane are twin block bite blocks conventionally constructed?", "options": ["30 degrees", "70 degrees", "45 degrees", "90 degrees", "110 degrees"], "key": "B", "type": "sba", "explanation": "Clark’s twin block uses bite blocks inclined at approximately 70 degrees to the occlusal plane. (Companion Ch 9; Hbk 16.3)", "answerPage": 211, "block": "P"}, {"n": 538, "page": 100, "stem": "Which is the principal advantage of the twin block over a one-piece activator?", "options": ["It produces greater skeletal change", "It is fixed to the teeth", "It requires no compliance", "Its two-piece design allows full-time wear and eating with the appliance in place", "It corrects the transverse dimension"], "key": "D", "type": "sba", "explanation": "The two-piece design permits full-time wear and eating, which is why the twin block became the most widely used functional appliance. (Companion Ch 9; Hbk 16.3)", "answerPage": 211, "block": "P"}, {"n": 539, "page": 101, "stem": "Posterior open bites developing during twin block treatment should be managed how?", "options": ["Trim the bite blocks progressively to allow posterior eruption", "Abandon the appliance", "Add posterior acrylic", "Fit a fixed appliance immediately", "Increase the wear time"], "key": "A", "type": "sba", "explanation": "Posterior open bites are expected and are managed by progressive trimming of the blocks to allow the posterior teeth to erupt. (Companion Ch 9; Hbk 16.3 and 22.3)", "answerPage": 211, "block": "P"}, {"n": 540, "page": 101, "stem": "Which functional appliance does not depend on patient compliance?", "options": ["Twin block", "Andresen activator", "Herbst", "Bionator", "Frankel"], "key": "C", "type": "sba", "explanation": "The Herbst is a fixed functional appliance using bilateral telescopic rods and tubes, so it does not depend on wear-time compliance. (Companion Ch 9; Hbk 16.3)", "answerPage": 211, "block": "P"}, {"n": 541, "page": 101, "stem": "Over what period does a Herbst appliance typically reduce the overjet?", "options": ["2 to 3 weeks", "3 years", "18 to 24 months", "6 to 8 months", "It does not reduce the overjet"], "key": "D", "type": "sba", "explanation": "Pancherz reported overjet reduction in 6 to 8 months with the Herbst appliance. (Pancherz 1982; Hbk 16.4)", "answerPage": 211, "block": "P"}, {"n": 542, "page": 101, "stem": "The Pacha randomised trial reported which failure rates for twin block and Herbst?", "options": ["Twin block 17 per cent, Herbst 37 per cent", "Twin block 37 per cent, Herbst 17 per cent", "Both 25 per cent", "Twin block 5 per cent, Herbst 50 per cent", "Neither appliance failed"], "key": "B", "type": "sba", "explanation": "Pacha reported 37 per cent failure with the twin block against 17 per cent with the Herbst, although the Herbst required more visits and produced more emergencies. (Pacha 2023; Hbk 16.4)", "answerPage": 211, "block": "P"}, {"n": 543, "page": 101, "stem": "The Pacha trial reported which mean overjet reductions for twin block and Herbst?", "options": ["3 mm and 4 mm respectively", "7.1 mm and 5.8 mm respectively", "Both 6 mm", "Both 9 mm", "5.8 mm and 7.1 mm respectively"], "key": "E", "type": "sba", "explanation": "The twin block achieved a smaller mean overjet reduction of 5.8 mm against 7.1 mm for the Herbst, and took 1.5 months longer. (Pacha 2023; Hbk 16.4)", "answerPage": 211, "block": "P"}, {"n": 544, "page": 101, "stem": "Pancherz reported what proportion of overjet correction remained stable at 32 years?", "options": ["86 per cent", "64 per cent", "46 per cent", "95 per cent", "100 per cent"], "key": "A", "type": "sba", "explanation": "At 32 years, 64 per cent of molar correction and 86 per cent of overjet correction remained stable, with a recommendation of at least 2 years of activator retention. (Pancherz 2014; Hbk 16.4)", "answerPage": 211, "block": "P"}, {"n": 545, "page": 101, "stem": "Which retention regimen did Pancherz recommend after Herbst treatment?", "options": ["None", "6 weeks of vacuum-formed retention", "At least 2 years with an activator", "A bonded retainer only", "Night-time headgear"], "key": "C", "type": "sba", "explanation": "Pancherz recommended at least 2 years of activator retention after Herbst treatment. (Pancherz 2014; Hbk 16.4)", "answerPage": 211, "block": "P"}, {"n": 546, "page": 102, "stem": "Which is the optimal timing for functional appliance therapy?", "options": ["CS1", "CS3, the circumpubertal period", "CS2", "CS5", "Timing is immaterial"], "key": "B", "type": "sba", "explanation": "The greatest response occurs in the circumpubertal period, corresponding to cervical vertebral maturation stage CS3. (Mosby ch. on growth modification; Hbk 16.2 and 22.3)", "answerPage": 211, "block": "P"}, {"n": 547, "page": 102, "stem": "The Frankel appliance differs from the twin block in which respect?", "options": ["It is fixed", "It produces no dentoalveolar change", "It cannot be worn at night", "It is tissue-borne, using buccal shields and lip pads to hold the soft tissues away from the dentition", "It is made of metal only"], "key": "D", "type": "sba", "explanation": "The Frankel is tissue-borne, using buccal shields and lip pads to allow transverse and sagittal dentoalveolar development. It is fragile. (Companion Ch 9; Hbk 16.3)", "answerPage": 211, "block": "P"}, {"n": 548, "page": 102, "stem": "Voudouris and colleagues in 2003 reported which finding using implanted electrodes?", "options": ["A reduction in lateral pterygoid activity on protrusion", "Increased lateral pterygoid activity on protrusion", "No measurable muscle activity", "Increased masseter activity only", "Increased temporalis activity only"], "key": "A", "type": "sba", "explanation": "Implanted electrodes showed a reduction in lateral pterygoid activity on protrusion, contradicting earlier surface electromyography. (Voudouris 2003; Hbk 16.2)", "answerPage": 211, "block": "P"}, {"n": 549, "page": 102, "stem": "Koretsi and colleagues in 2015 reported which effect of functional appliance therapy?", "options": ["A large skeletal effect persisting into adulthood", "No effect on the profile", "A positive effect on the soft tissue profile in Class II subjects", "Increased root resorption", "Improved periodontal health"], "key": "C", "type": "sba", "explanation": "Functional appliance therapy has a positive effect on the soft tissue profile in Class II subjects. (Koretsi 2015; Hbk 16.2)", "answerPage": 211, "block": "P"}, {"n": 550, "page": 102, "stem": "Santana and colleagues in 2020 compared maximal with incremental mandibular advancement and found what?", "options": ["Incremental advancement was significantly superior", "Neither approach was effective", "Maximal advancement caused condylar resorption", "Incremental advancement doubled the skeletal effect", "Little clinical difference between the two"], "key": "E", "type": "sba", "explanation": "There is little clinical difference between maximal and incremental advancement. (Santana 2020; Hbk 16.4)", "answerPage": 211, "block": "P"}, {"n": 551, "page": 102, "stem": "Before functional appliance therapy in a patient with a retroclined upper labial segment, which step is required?", "options": ["Procline the upper labial segment to convert it to a division 1 pattern", "Extract upper first premolars", "Fit a transpalatal arch", "Reduce the overbite with a bite plane only", "Begin with Class II elastics"], "key": "A", "type": "sba", "explanation": "Decompensation of a retroclined upper labial segment is required so that the mandible can be postured forwards. (Cobourne cases; Hbk 22.3)", "answerPage": 211, "block": "P"}, {"n": 552, "page": 102, "stem": "Which appliance combination is used for vertical control in a high-angle Class II patient?", "options": ["Cervical pull headgear with a twin block", "A quadhelix with Class II elastics", "High-pull headgear combined with a functional appliance", "A lower lingual arch alone", "A Nance button with Class III elastics"], "key": "C", "type": "sba", "explanation": "High-pull headgear combined with a functional appliance provides vertical control in the hyperdivergent Class II patient. (Companion Ch 9; Hbk 16.3 and 22.4)", "answerPage": 211, "block": "P"}, {"n": 553, "page": 103, "stem": "Which is the correct force and duration for facemask protraction therapy?", "options": ["150 g per side for 8 hours per day", "50 g per side at night only", "100 g per side for 24 hours per day", "800 g per side for 6 hours per day", "Approximately 400 g per side for 12 to 14 hours per day"], "key": "E", "type": "sba", "explanation": "Facemask therapy uses approximately 400 g per side for 12 to 14 hours per day, ideally before age 10. (Companion Ch 9; Hbk 23.3)", "answerPage": 211, "block": "P"}, {"n": 554, "page": 103, "stem": "Approximately what proportion of the overjet correction achieved by facemask therapy is dental rather than skeletal?", "options": ["10 per cent", "About half", "90 per cent", "None", "100 per cent"], "key": "B", "type": "sba", "explanation": "About half the overjet correction achieved with a facemask is dental. Overcorrection to a positive overjet of 3 to 4 mm is recommended. (Mosby ch. on Class III; Hbk 23.3)", "answerPage": 211, "block": "P"}, {"n": 555, "page": 103, "stem": "Mandall and colleagues in 2016 reported what proportion of facemask-treated patients avoided surgery?", "options": ["36 per cent", "100 per cent", "85 per cent", "Over 60 per cent", "None"], "key": "D", "type": "sba", "explanation": "Over 60 per cent avoided surgery against 36 per cent without early treatment, although most of the initial skeletal effect is lost with growth. (Mandall 2016; Hbk 23.3)", "answerPage": 212, "block": "P"}, {"n": 556, "page": 103, "stem": "Proffit reports what recurrence rate of anterior crossbite 8 years after facemask therapy?", "options": ["Under 5 per cent", "10 per cent", "25 to 33 per cent", "60 per cent", "90 per cent"], "key": "C", "type": "sba", "explanation": "Proffit reports 25 to 33 per cent recurrence of the anterior crossbite at 8 years, mostly requiring surgery. (Proffit Ch 13; Hbk 23.3)", "answerPage": 212, "block": "P"}, {"n": 557, "page": 103, "stem": "The chin cup is best described in which way?", "options": ["A device whose short-term gain is not maintained after growth, with no agreement that it inhibits mandibular growth", "An effective inhibitor of mandibular growth", "The treatment of choice for Class III in all children", "A fixed functional appliance", "An anchorage device"], "key": "A", "type": "sba", "explanation": "The chin cup largely redirects the mandible downwards and backwards, and its shortterm gain is not maintained after growth. (Nanda; Hbk 23.3)", "answerPage": 212, "block": "P"}, {"n": 558, "page": 103, "stem": "Which single statement about myofunctional therapy is best supported?", "options": ["Muscle exercises reliably correct malocclusion", "Myofunctional appliances have strong randomised evidence", "Tongue exercises close a skeletal open bite", "Lip exercises correct a Class II skeletal pattern", "Interrupting a digit habit before the permanent incisors are established allows spontaneous correction of an anterior open bite"], "key": "E", "type": "sba", "explanation": "There is reasonable evidence that habit interruption before the permanent incisors are established permits spontaneous correction. There is no good evidence that exercises alone correct a malocclusion. (Companion Ch 12; Hbk 16.5)", "answerPage": 212, "block": "P"}, {"n": 559, "page": 103, "stem": "Which is the correct first-line approach to a digit-sucking habit in a motivated 8-year-old?", "options": ["A palatal crib immediately", "A twin block", "Extraction of the upper incisors", "Positive reinforcement and reminder therapy", "No intervention at any age"], "key": "D", "type": "sba", "explanation": "Positive reinforcement and reminder therapy come first. A habit-breaking appliance such as a palatal crib is used if that fails, and only in a motivated child. (Companion Ch 12; Hbk 16.5)", "answerPage": 212, "block": "P"}, {"n": 560, "page": 104, "stem": "A habit-breaking appliance should be explained to a child in which way?", "options": ["As a punishment for the habit", "As a reminder rather than a punishment", "As a temporary brace to straighten the teeth", "As a retainer", "As a device that will be fitted permanently"], "key": "B", "type": "sba", "explanation": "The appliance is a reminder, not a punishment, and this framing improves acceptance and outcome. (Companion Ch 12; Hbk 16.5)", "answerPage": 212, "block": "P"}, {"n": 561, "page": 104, "stem": "Which of the following removable appliance components provides retention on an incisor?", "options": ["Adams clasp", "T-spring", "Roberts retractor", "Z-spring", "Southend clasp"], "key": "E", "type": "sba", "explanation": "The Southend clasp provides retention on incisors. Adams clasps are used on molars and premolars. (Companion Ch 9; Hbk 16.1)", "answerPage": 212, "block": "P"}, {"n": 562, "page": 104, "stem": "A Roberts retractor is constructed in which gauge of wire?", "options": ["0.7 mm without tubing", "0.5 mm in tubing", "0.9 mm in tubing", "1.0 mm without tubing", "0.3 mm in tubing"], "key": "B", "type": "sba", "explanation": "A Roberts retractor uses 0.5 mm wire supported in tubing, and retracts the upper labial segment by tipping. (Companion Ch 9; Hbk 16.1)", "answerPage": 212, "block": "P"}, {"n": 563, "page": 104, "stem": "A midline expansion screw in a removable appliance delivers approximately what expansion per quarter turn?", "options": ["0.1 mm", "1.0 mm", "0.5 mm", "0.25 mm", "2.0 mm"], "key": "D", "type": "sba", "explanation": "A midline screw delivers approximately 0.25 mm per quarter turn, activated twice weekly for slow expansion. (Companion Ch 9; Hbk 16.1)", "answerPage": 212, "block": "P"}, {"n": 564, "page": 104, "stem": "Which single statement about the Andresen activator is correct?", "options": ["It is a tooth-borne, passive, one-piece appliance worn principally at night", "It is a fixed appliance", "It is tissue-borne", "It permits eating in situ", "It corrects transverse discrepancies reliably"], "key": "A", "type": "sba", "explanation": "The Andresen activator is the original tooth-borne, passive, one-piece functional appliance, bulky and worn at night, and wholly compliance-dependent. (Companion Ch 9; Hbk 16.3)", "answerPage": 212, "block": "P"}, {"n": 565, "page": 104, "stem": "Which appliance is attached to a fixed appliance and used mid-treatment for Class II correction?", "options": ["Twin block", "Frankel", "Forsus or similar semi-rigid fixed functional", "Andresen activator", "Bionator"], "key": "C", "type": "sba", "explanation": "Forsus and similar semi-rigid fixed functionals attach to a fixed appliance and are used mid-treatment. (Companion Ch 9; Hbk 16.3)", "answerPage": 212, "block": "P"}, {"n": 566, "page": 104, "stem": "Which single statement about proprietary prefabricated myofunctional appliance systems is correct?", "options": ["They have strong randomised evidence of skeletal effect", "They correct skeletal open bite reliably", "They are superior to the twin block", "There is no evidence for the stronger claims made for them", "They eliminate the need for fixed appliances"], "key": "D", "type": "sba", "explanation": "There is no good evidence for the stronger claims made by proprietary myofunctional appliance systems. (Companion Ch 12; Hbk 16.5)", "answerPage": 212, "block": "P"}, {"n": 567, "page": 106, "stem": "First order movement refers to which of the following?", "options": ["Tip", "In and out", "Torque", "Rotation", "Intrusion"], "key": "B", "type": "sba", "explanation": "First order is in and out, built into the slot-to-base distance. Second order is tip, or angulation; third order is torque, or inclination. (Companion Ch 10; Hbk 17.1)", "answerPage": 212, "block": "Q"}, {"n": 568, "page": 106, "stem": "Third order movement is built into which feature of a pre-adjusted bracket?", "options": ["The slot-to-base distance", "The mesiodistal slot angulation", "The bracket base curvature", "The tie wings", "The buccolingual slot inclination"], "key": "E", "type": "sba", "explanation": "Torque is expressed through the buccolingual inclination of the slot, and controls incisor root position and buccal root torque of molars. (Companion Ch 10; Hbk 17.1)", "answerPage": 212, "block": "Q"}, {"n": 569, "page": 106, "stem": "Angle’s edgewise appliance of 1928 differed from the ribbon arch in which respect?", "options": ["The slot was turned horizontal, giving greater control of tooth movement", "The slot was made vertical", "The wire was made round", "Brackets were bonded rather than banded", "Ligation was elastomeric"], "key": "A", "type": "sba", "explanation": "Turning the slot horizontal gave greater control of tooth movement, but required all three orders to be bent into the wire tooth by tooth. (Angle 1928; Hbk 17.2)", "answerPage": 212, "block": "Q"}, {"n": 570, "page": 106, "stem": "Standard edgewise treatment traditionally left results undertreated by approximately what proportion?", "options": ["Under 5 per cent", "30 to 40 per cent", "10 to 20 per cent", "50 per cent", "It did not undertreat"], "key": "C", "type": "sba", "explanation": "Bennett and McLaughlin record that standard edgewise results were traditionally left 10 to 20 per cent undertreated because of the wire bending required. (Bennett and McLaughlin; Hbk 17.2)", "answerPage": 212, "block": "Q"}, {"n": 571, "page": 106, "stem": "The pre-adjusted edgewise appliance moved the source of error from where to where?", "options": ["From the bracket to the wire", "From the wire to the bracket position", "From the patient to the operator", "From the archwire to the ligature", "From the slot to the base"], "key": "B", "type": "sba", "explanation": "Pre-adjustment built the three orders into the bracket, which moved the error from wire bending to bracket positioning. Bracket position is now where cases are lost. (Andrews 1979; Hbk 17.2)", "answerPage": 212, "block": "Q"}, {"n": 572, "page": 106, "stem": "Which is the correct chronological order of Angle’s appliances?", "options": ["Edgewise, ribbon arch, pin and tube, E-arch", "Pin and tube, edgewise, E-arch, ribbon arch", "Ribbon arch, E-arch, edgewise, pin and tube", "E-arch, pin and tube, ribbon arch, edgewise", "E-arch, ribbon arch, edgewise, pin and tube"], "key": "D", "type": "sba", "explanation": "Angle worked through the E-arch, pin and tube, ribbon arch and finally the edgewise appliance of 1928. (Proffit Ch 10; Hbk 17.2)", "answerPage": 212, "block": "Q"}, {"n": 573, "page": 107, "stem": "The Begg appliance is best characterised as which of the following?", "options": ["An anchorage philosophy based on differential force, with deliberate tipping then uprighting", "A torque-driven appliance", "A lingual appliance", "An aligner system", "A functional appliance"], "key": "A", "type": "sba", "explanation": "Begg inverted the ribbon arch slot and used differential force with three stages, deliberately tipping teeth and then uprighting them with auxiliary springs. (Begg 1956; Hbk 17.2)", "answerPage": 213, "block": "Q"}, {"n": 574, "page": 107, "stem": "The Tip-Edge appliance operates by which principle?", "options": ["Full three-dimensional control from the outset", "Continuous heavy force", "Limited tipping, with full prescription expressed in rectangular wire at finishing", "Tissue-borne mechanics", "Self-ligation"], "key": "C", "type": "sba", "explanation": "Kesling’s Tip-Edge allows limited tipping and then expresses the full prescription in a rectangular finishing wire. (Kesling 1988; Hbk 17.2)", "answerPage": 213, "block": "Q"}, {"n": 575, "page": 107, "stem": "The MBT prescription differs from the Andrews prescription principally in which respects?", "options": ["Increased anterior tip and less incisor torque", "Absence of second order values", "Larger slot size", "Vertical slot orientation", "Reduced anterior tip, more palatal root torque on upper incisors, and three canine torque options"], "key": "E", "type": "sba", "explanation": "MBT reduced anterior tip and increased palatal root torque on the upper incisors, with three canine torque options, because proven mechanics determined the bracket design. (McLaughlin, Bennett and Trevisi; Hbk 17.2)", "answerPage": 213, "block": "Q"}, {"n": 576, "page": 107, "stem": "Which statement about 0.018 inch and 0.022 inch slot sizes is correct?", "options": ["There is no evidence that either is superior", "The 0.022 slot is proven superior", "The 0.018 slot is proven superior", "The 0.022 slot cannot accept a rectangular wire", "The 0.018 slot cannot express torque"], "key": "A", "type": "sba", "explanation": "There is no evidence that either slot size is superior. The 0.018 slot expresses torque earlier in a smaller wire; the 0.022 slot allows more robust sliding mechanics. (Mosby ch. on appliances; Hbk 17.2)", "answerPage": 213, "block": "Q"}, {"n": 577, "page": 107, "stem": "What is the appropriate finishing wire in an 0.018 inch slot?", "options": ["0.016 inch round steel", "0.019 by 0.025 inch", "0.017 by 0.025 inch", "0.021 by 0.025 inch", "0.014 inch nickel titanium"], "key": "C", "type": "sba", "explanation": "Finishing wires fill or nearly fill the slot: 0.017 by 0.025 inch in an 0.018 slot and 0.021 by 0.025 inch in an 0.022 slot. (Proffit Ch 16; Hbk 17.2 and 18.3)", "answerPage": 213, "block": "Q"}, {"n": 578, "page": 107, "stem": "The MBT principle for varying wire stiffness at the finishing stage is which of the following?", "options": ["Change the dimension, not the material", "Use only beta titanium", "Use the same wire throughout", "Use only nickel titanium", "Change the material, not the dimension"], "key": "E", "type": "sba", "explanation": "Stiffness should be varied by changing material rather than dimension, so that the slot remains filled. (Proffit Ch 16; Hbk 17.2)", "answerPage": 213, "block": "Q"}, {"n": 579, "page": 107, "stem": "Scott, Fleming and colleagues studied self-ligating brackets and found what?", "options": ["Faster tooth movement and shorter treatment", "No difference in rate of movement, treatment time, number of visits or occlusal outcome", "Superior occlusal outcomes", "Significant expansion of the arches", "Reduced root resorption"], "key": "B", "type": "sba", "explanation": "Multiple randomised trials found no difference in rate, treatment time, visits or occlusal outcome, with only a marginal pain benefit and unsupported expansion claims. (Scott 2008; Fleming 2010; Hbk 17.3)", "answerPage": 213, "block": "Q"}, {"n": 580, "page": 108, "stem": "The distinction between active and passive self-ligating brackets is which of the following?", "options": ["Active brackets are bonded and passive brackets are banded", "Passive brackets have a larger slot", "Active brackets are ceramic", "Active clips store energy against the wire; passive slides do not", "Active brackets require elastomeric ligation"], "key": "D", "type": "sba", "explanation": "The distinction is a design difference, not a demonstrated clinical advantage. (Mosby ch. on appliances; Hbk 17.3)", "answerPage": 213, "block": "Q"}, {"n": 581, "page": 108, "stem": "Penning and colleagues studied customised appliances and reported which finding on treatment time?", "options": ["A reduction of 4 months", "A reduction of 8 months", "No reduction in treatment time", "A doubling of treatment time", "Treatment time was not measured"], "key": "C", "type": "sba", "explanation": "Outcomes were comparable with no time saving, and there were more breakages, more complaints and more planning time. Treatment time was dictated by case difficulty and by the treating orthodontist. (Penning 2017; Hbk 17.3)", "answerPage": 213, "block": "Q"}, {"n": 582, "page": 108, "stem": "Which is the principal biomechanical difference between lingual and labial fixed appliances?", "options": ["The lingual bracket lies palatal to the centre of resistance and closer to it vertically, altering intrusive and torquing effects", "The lingual bracket is further from the centre of resistance", "Lingual appliances cannot deliver torque", "Lingual appliances have a larger interbracket span anteriorly", "Lingual appliances use only round wires"], "key": "A", "type": "sba", "explanation": "The changed bracket position alters the moment systems, and the shorter anterior interbracket span raises effective stiffness. (Companion Ch 10; Hbk 17.4)", "answerPage": 213, "block": "Q"}, {"n": 583, "page": 108, "stem": "The principal obstacle to a stock lingual appliance is which of the following?", "options": ["The cost of the brackets", "Bond strength", "Patient acceptance", "Archwire availability", "The very variable lingual anatomy of the teeth"], "key": "E", "type": "sba", "explanation": "Lingual anatomy varies greatly between teeth and patients, which is why customised CAD-CAM lingual brackets and robotically-bent wires were developed. (Companion Ch 10; Hbk 17.4)", "answerPage": 213, "block": "Q"}, {"n": 584, "page": 108, "stem": "Speech disturbance following placement of a lingual appliance typically lasts how long?", "options": ["Permanently", "12 months", "6 months", "1 to 3 weeks", "It does not occur"], "key": "D", "type": "sba", "explanation": "Speech disturbance is usual but transient, typically resolving within 1 to 3 weeks. (Companion Ch 10; Hbk 17.4)", "answerPage": 213, "block": "Q"}, {"n": 585, "page": 108, "stem": "Which single statement about the evidence for lingual appliances is correct?", "options": ["They produce superior outcomes to labial appliances", "Comparative trials are few and small, so superiority of outcome should not be claimed", "They are proven faster", "They cause less root resorption", "They eliminate the need for retention"], "key": "B", "type": "sba", "explanation": "The comparative evidence is limited. The indication is an adult whose sole objection is visibility and who accepts the trade-offs. (Companion Ch 10; Hbk 17.4)", "answerPage": 213, "block": "Q"}, {"n": 586, "page": 109, "stem": "Clear aligners work by which mechanical principle?", "options": ["A constant force from a rigid shell", "A shape-memory alloy effect", "A magnetic force", "Continuous heavy force", "A viscoelastic plastic shell acting as a spring that relaxes, with force decaying through the wear period"], "key": "E", "type": "sba", "explanation": "The plastic is viscoelastic: force decays through the wear period and decays faster when warm and moist. Plastic persuades; wire overpowers. (Companion Ch 14; Hbk 17.5)", "answerPage": 213, "block": "Q"}, {"n": 587, "page": 109, "stem": "Which tooth movement do clear aligners perform least predictably?", "options": ["Anterior intrusion", "Root torque, extrusion and rotation of round-sectioned teeth", "Tipping", "Arch expansion by tipping", "Mild crowding relief"], "key": "B", "type": "sba", "explanation": "Root torque, extrusion and rotation of round teeth such as canines and premolars are the least predictable aligner movements. (Companion Ch 14; Hbk 17.5)", "answerPage": 213, "block": "Q"}, {"n": 588, "page": 109, "stem": "Bonded attachments in aligner therapy serve which purpose?", "options": ["To improve aesthetics", "To reduce friction", "To increase retention of the aligner only", "To give the plastic a feature to push against, which is essential for extrusion and rotation", "To provide anchorage in bone"], "key": "D", "type": "sba", "explanation": "Attachments are essential for movements that the smooth plastic shell cannot otherwise deliver, particularly extrusion and rotation. (Companion Ch 14; Hbk 17.5)", "answerPage": 213, "block": "Q"}, {"n": 589, "page": 109, "stem": "Invisalign achieves the predicted outcome with approximately what accuracy?", "options": ["Around 41 per cent", "Around 65 per cent", "Around 85 per cent", "Around 95 per cent", "100 per cent"], "key": "A", "type": "sba", "explanation": "Kravitz reported approximately 41 per cent accuracy against the predicted outcome, with rotation the least accurate movement. (Kravitz 2009; Hbk 17.5)", "answerPage": 213, "block": "Q"}, {"n": 590, "page": 109, "stem": "What proportion of aligner cases complete treatment without a refinement?", "options": ["41 per cent", "17 per cent", "6 per cent", "65 per cent", "90 per cent"], "key": "C", "type": "sba", "explanation": "Only about 6 per cent complete without a refinement, and over 17 per cent convert to fixed appliances to finish. (Companion Ch 14; Hbk 17.5)", "answerPage": 213, "block": "Q"}, {"n": 591, "page": 109, "stem": "What proportion of aligner cases convert to fixed appliances to finish?", "options": ["Under 2 per cent", "50 per cent", "35 per cent", "Over 17 per cent", "None"], "key": "D", "type": "sba", "explanation": "Over 17 per cent convert to fixed appliances. These are the two numbers to quote at consent. (Companion Ch 14; Hbk 17.5)", "answerPage": 213, "block": "Q"}, {"n": 592, "page": 109, "stem": "Which index shows aligners to be significantly worse than fixed appliances?", "options": ["PAR", "ABO Objective Grading System", "IOTN Dental Health Component", "ICON", "Little’s Irregularity Index"], "key": "B", "type": "sba", "explanation": "PAR shows no difference; the ABO Objective Grading System shows aligners significantly worse, particularly for buccolingual inclination, occlusal contacts, overjet and root angulation. (Companion Ch 14; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 593, "page": 110, "stem": "Which outcomes favour aligners over fixed appliances?", "options": ["Occlusal outcome and root angulation", "Reduced relapse", "Severe crowding correction", "Torque expression", "Less pain in the first few days, better periodontal index scores, less eating disturbance and far less visibility"], "key": "E", "type": "sba", "explanation": "Aligners perform better on pain in the first days, periodontal indices, eating disturbance and visibility. Fixed appliances are better on every occlusal measure. (Companion Ch 14; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 594, "page": 110, "stem": "What daily wear time is required for aligner therapy?", "options": ["20 to 22 hours", "14 to 16 hours", "8 to 10 hours", "24 hours", "Wear time is immaterial"], "key": "A", "type": "sba", "explanation": "Aligners require 20 to 22 hours per day. Compliance is the weakest element in the system. (Companion Ch 14; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 595, "page": 110, "stem": "Which is the unsolved biomechanical problem in aligner therapy?", "options": ["Bond failure", "Wire selection", "The influence of adjacent teeth, since the aligner acts on every tooth simultaneously and reaction forces are accepted rather than designed", "Ligation", "Bracket positioning"], "key": "C", "type": "sba", "explanation": "The aligner is a single appliance acting on all teeth at once, so reaction forces are accepted rather than designed. This is the central unsolved problem. (Mosby ch. on aligners; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 596, "page": 110, "stem": "Cobourne’s assessment of aligner performance at three years after treatment reported what?", "options": ["Less post-treatment change than fixed appliances", "Greater post-treatment change than fixed appliances", "No difference", "Complete stability", "Improvement over time"], "key": "B", "type": "sba", "explanation": "Cobourne’s cases report greater post-treatment change at three years with aligners, alongside worse ABO grading. (Cobourne cases; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 597, "page": 110, "stem": "Which patient is the most appropriate candidate for aligner therapy in general practice?", "options": ["An adolescent with 10 mm of crowding and a skeletal Class II pattern", "A patient requiring molar uprighting", "A patient requiring extraction space closure", "An adult with mild to moderate crowding, a Class I skeletal pattern and good motivation", "A patient requiring significant torque correction"], "key": "D", "type": "sba", "explanation": "The appropriate candidate has mild to moderate crowding, a Class I skeletal pattern and good motivation, with the refinement and conversion rates explained at consent. (Companion Ch 14; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 598, "page": 110, "stem": "Which single statement should be made at consent for aligner treatment?", "options": ["That fewer than one in ten cases finishes without a refinement and around one in six converts to fixed appliances", "That the predicted outcome is guaranteed", "That treatment will be faster than with fixed appliances", "That no attachments will be needed", "That retention will not be required"], "key": "A", "type": "sba", "explanation": "These are the two numbers that make the consent honest and defensible. (Companion Ch 14; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 599, "page": 110, "stem": "Which single element of the pre-adjusted appliance cannot compensate for a bracket placed incorrectly?", "options": ["The archwire sequence", "The ligation method", "The prescription", "The slot size", "The elastic wear"], "key": "C", "type": "sba", "explanation": "The prescription cannot fix a misplaced bracket. Bracket position, not prescription, decides the result. (Mosby ch. on appliances; Hbk 17.1 and 18.3)", "answerPage": 214, "block": "Q"}, {"n": 600, "page": 111, "stem": "Which single statement about Roth’s contribution to prescription design is correct?", "options": ["He introduced the vertical slot", "He introduced lingual brackets", "He invented the edgewise appliance", "He introduced self-ligation", "He sought one appliance rather than an inventory, with over-corrected values built in"], "key": "E", "type": "sba", "explanation": "Roth’s aim was a single prescription rather than an inventory of brackets, with overcorrected values built in. (McLaughlin, Bennett and Trevisi; Hbk 17.2)", "answerPage": 214, "block": "Q"}, {"n": 601, "page": 111, "stem": "Andrews derived the pre-adjusted prescription in which year?", "options": ["1979", "1956", "1972", "1928", "1988"], "key": "A", "type": "sba", "explanation": "Andrews described the six keys in 1972 and the pre-adjusted prescription built into each bracket in 1979. (Andrews 1979; Hbk 17.2)", "answerPage": 214, "block": "Q"}, {"n": 602, "page": 111, "stem": "Which single feature distinguishes true customised lingual appliances from stock lingual systems?", "options": ["Slot size", "Bonding technique", "CAD-CAM brackets and robotically-bent wires that compensate for individual lingual anatomy", "Wire material", "Ligation method"], "key": "C", "type": "sba", "explanation": "Customised systems use CAD-CAM brackets and robotically-bent archwires to compensate for the variable lingual anatomy. (Companion Ch 10; Hbk 17.4)", "answerPage": 214, "block": "Q"}, {"n": 603, "page": 111, "stem": "Which is a recognised drawback of lingual appliances?", "options": ["Poor aesthetics", "Incompatibility with elastics", "Inability to correct rotations", "Excessive visibility", "Difficult access and hygiene, longer chairside time, tongue discomfort and a steep learning curve"], "key": "E", "type": "sba", "explanation": "The drawbacks are speech disturbance, tongue discomfort and ulceration, access and hygiene difficulty, chairside time, cost and the learning curve. (Companion Ch 10; Hbk 17.4)", "answerPage": 214, "block": "Q"}, {"n": 604, "page": 111, "stem": "Which single statement about clear aligners and severe crowding is correct?", "options": ["Aligners perform as well as fixed appliances", "Fixed appliances are better for severe crowding and complex cases", "Aligners are superior for severe crowding", "Severity is irrelevant to appliance choice", "Aligners should be used for all extraction cases"], "key": "B", "type": "sba", "explanation": "Fixed appliances outperform aligners in severe crowding and complex cases, and in every occlusal outcome measure. (Companion Ch 14; Hbk 17.5)", "answerPage": 214, "block": "Q"}, {"n": 605, "page": 111, "stem": "The claim that self-ligating brackets produce arch expansion is best described how?", "options": ["Well supported by randomised evidence", "Supported only in adults", "Supported only in the mandible", "Unsupported", "Proven by Cochrane review"], "key": "D", "type": "sba", "explanation": "Expansion claims for self-ligating brackets are unsupported by the randomised evidence. (Scott 2008; Fleming 2010; Hbk 17.3)", "answerPage": 214, "block": "Q"}, {"n": 606, "page": 112, "stem": "Which statement about ligation method and rate of tooth movement is correct?", "options": ["Elastomeric ligation is significantly faster", "Self-ligation is significantly faster", "No difference in rate of movement has been demonstrated", "Steel ligatures are significantly faster", "Rate depends only on the ligation method"], "key": "C", "type": "sba", "explanation": "No difference in rate of movement has been demonstrated between ligation methods, once the trials are considered together. (Scott 2008; Fleming 2010; Hbk 17.3)", "answerPage": 214, "block": "Q"}, {"n": 607, "page": 113, "stem": "At what stage of treatment is anchorage principally spent or saved?", "options": ["During levelling and aligning, before any active mechanics begin", "During space closure", "During finishing", "During retention", "At debond"], "key": "A", "type": "sba", "explanation": "Anchorage is spent or saved during levelling and aligning. Lacebacks, bendbacks and the exclusion of anchor teeth from the initial wire all act at this stage. (McLaughlin, Bennett and Trevisi; Hbk 18.1)", "answerPage": 214, "block": "R"}, {"n": 608, "page": 113, "stem": "When should second molars be bonded?", "options": ["At the finishing stage", "Never", "Only in extraction cases", "Only in adults", "As early as possible, because they are needed for bite opening and anchorage"], "key": "E", "type": "sba", "explanation": "Second molars should be included as early as possible: the anchorage mechanics are the bite-opening mechanics. (Bennett and McLaughlin; Hbk 18.1)", "answerPage": 214, "block": "R"}, {"n": 609, "page": 113, "stem": "How long should a rectangular working wire remain passive before active force is applied?", "options": ["Immediately active", "Six months", "Three months", "Approximately one month", "Passive periods are unnecessary"], "key": "D", "type": "sba", "explanation": "Approximately one month of passive rectangular wire allows the slots to line up. Level slot line-up is what makes sliding mechanics possible. (McLaughlin, Bennett and Trevisi; Hbk 18.2)", "answerPage": 214, "block": "R"}, {"n": 610, "page": 113, "stem": "At what interval should tiebacks be reactivated during space closure?", "options": ["Weekly", "Every 4 to 6 weeks", "Every 3 months", "Every 6 months", "Once only"], "key": "B", "type": "sba", "explanation": "Tiebacks are reactivated at 4 to 6 weeks, using a 0.010 inch wire ligature with a module stretched to about twice its resting length. (McLaughlin, Bennett and Trevisi; Hbk 18.2)", "answerPage": 215, "block": "R"}, {"n": 611, "page": 113, "stem": "Which is the principal advantage of loop mechanics over sliding mechanics?", "options": ["Simplicity", "Better patient comfort", "Lower cost", "Shorter chairside time", "Absence of friction"], "key": "E", "type": "sba", "explanation": "Loop mechanics avoid friction but require wire bending and produce a force system that is harder to control. (Proffit Ch 15; Hbk 18.2)", "answerPage": 215, "block": "R"}, {"n": 612, "page": 113, "stem": "Coil springs compared with elastomeric modules for space closure show which characteristic?", "options": ["Slower and less consistent movement", "More consistent and slightly faster translation", "Identical performance", "Greater anchorage loss", "Greater root resorption"], "key": "B", "type": "sba", "explanation": "Comparative work shows coil springs give more consistent and slightly faster translation than modules. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 215, "block": "R"}, {"n": 613, "page": 114, "stem": "Every 1 mm of lower incisor advance yields how much space?", "options": ["0.5 mm", "1 mm", "4 mm", "2 mm", "None"], "key": "D", "type": "sba", "explanation": "Each millimetre of lower incisor advance yields 2 mm of space, but stability is lost beyond about 2 mm of advance. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 215, "block": "R"}, {"n": 614, "page": 114, "stem": "The conventional limit for lower incisor proclination is which value?", "options": ["100 degrees to the mandibular plane", "93 degrees to the mandibular plane", "85 degrees to the mandibular plane", "115 degrees to the mandibular plane", "There is no limit"], "key": "A", "type": "sba", "explanation": "The MBT literature quotes 100 degrees to the mandibular plane as the conventional limit for lower incisor proclination. (McLaughlin, Bennett and Trevisi; Hbk 18.2)", "answerPage": 215, "block": "R"}, {"n": 615, "page": 114, "stem": "Which single question should be asked before planning overjet reduction?", "options": ["Which bracket prescription is in use", "What the patient’s age is", "Whether lower arch anchorage is available", "Which retainer will be used", "What the IOTN grade is"], "key": "C", "type": "sba", "explanation": "Bennett’s question is whether lower arch anchorage is available. If the lower incisors are already forward, Class II elastics are barred. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 215, "block": "R"}, {"n": 616, "page": 114, "stem": "The commonest single reason a case does not finish well is which of the following?", "options": ["Poor archwire selection", "Excessive force", "Inadequate elastic wear", "Bracket positioning", "Poor bonding technique"], "key": "D", "type": "sba", "explanation": "Bracket positioning is the commonest reason a case does not finish. Every bracket should be reassessed at the working wire stage and repositioned before finishing wires. (Proffit Ch 16; Hbk 18.3)", "answerPage": 215, "block": "R"}, {"n": 617, "page": 114, "stem": "At which stage should brackets be reassessed and repositioned?", "options": ["At bond-up", "At the working wire stage, before finishing wires", "At debond", "At the first review after debond", "They should never be repositioned"], "key": "B", "type": "sba", "explanation": "Reassess every bracket against marginal ridge levels and gingival contour at the working wire stage, and reposition before finishing wires. (Proffit Ch 16; Hbk 18.3)", "answerPage": 215, "block": "R"}, {"n": 618, "page": 114, "stem": "Root parallelism at extraction sites should be confirmed by which means?", "options": ["Clinical inspection", "Intra-oral photographs", "A lateral cephalogram", "Study casts", "A panoramic radiograph at the finishing stage"], "key": "E", "type": "sba", "explanation": "A panoramic radiograph at the finishing stage confirms root parallelism, particularly at extraction sites. (Proffit Ch 16; Hbk 18.3)", "answerPage": 215, "block": "R"}, {"n": 619, "page": 114, "stem": "For how long should a case be settled in light round wires with vertical elastics before retention?", "options": ["Approximately 6 weeks", "1 week", "3 months", "6 months", "Settling is unnecessary"], "key": "A", "type": "sba", "explanation": "Never go straight from rectangular wires to retainers. Settle in light round wires for approximately six weeks, keeping every space closed. (McLaughlin, Bennett and Trevisi; Hbk 18.3)", "answerPage": 215, "block": "R"}, {"n": 620, "page": 115, "stem": "Which arch form should be retained at the end of treatment?", "options": ["The treated arch form", "A standard ovoid form", "The patient’s original arch form", "A standard tapered form", "Whichever is most aesthetic"], "key": "C", "type": "sba", "explanation": "The original arch form should be retained, not the treated one. Changing arch form results in relapse in up to 70 per cent of cases. (McLaughlin, Bennett and Trevisi; Hbk 18.5)", "answerPage": 215, "block": "R"}, {"n": 621, "page": 115, "stem": "The distribution of arch forms in a Caucasian orthodontic practice is approximately which of the following?", "options": ["Ovoid 50 per cent, tapered 42 per cent, square 8 per cent", "Tapered 50 per cent, ovoid 42 per cent, square 8 per cent", "Square 50 per cent, ovoid 30 per cent, tapered 20 per cent", "Equal thirds", "Tapered 80 per cent, ovoid 15 per cent, square 5 per cent"], "key": "B", "type": "sba", "explanation": "Tapered 50 per cent, ovoid 42 per cent and square 8 per cent, with a recommended stock ratio of 45, 45 and 10. Japanese samples are almost the reverse. (McLaughlin, Bennett and Trevisi; Hbk 18.5)", "answerPage": 215, "block": "R"}, {"n": 622, "page": 115, "stem": "Buccal uprighting of the posterior segments relapses in approximately what proportion of cases?", "options": ["10 per cent", "30 per cent", "95 per cent", "70 per cent", "It does not relapse"], "key": "D", "type": "sba", "explanation": "Buccal uprighting relapses in approximately 70 per cent of cases, which also means 30 per cent is stable, so the manoeuvre is unpredictable rather than worthless. (McLaughlin, Bennett and Trevisi; Hbk 18.5)", "answerPage": 215, "block": "R"}, {"n": 623, "page": 115, "stem": "The connector area rule for anterior aesthetics is which of the following?", "options": ["50, 40, 30 from the midline distally", "30, 40, 50 from the midline distally", "Equal connectors throughout", "60, 40, 20", "20, 40, 60"], "key": "A", "type": "sba", "explanation": "Connector areas descend in size from central to central, then central to lateral, then lateral to canine, following the 50, 40, 30 rule. (Nanda; Hbk 18.4)", "answerPage": 215, "block": "R"}, {"n": 624, "page": 115, "stem": "Incisal embrasures should show which pattern?", "options": ["Equal size throughout", "Decreasing size from the midline distally", "Increasing size from the midline distally", "Absence of embrasures", "Largest between the centrals"], "key": "C", "type": "sba", "explanation": "Incisal embrasures increase in size from the midline distally, and this is a checkable finishing criterion. (Nanda; Hbk 18.4)", "answerPage": 215, "block": "R"}, {"n": 625, "page": 115, "stem": "The gingival zenith of the lateral incisor should sit where relative to the centrals and canines?", "options": ["On the same line", "Position is immaterial", "2 mm above the line", "3 mm below the line", "0.5 to 1 mm below the line joining the central and canine zeniths"], "key": "E", "type": "sba", "explanation": "The upper central and canine zeniths sit on a level line, with the lateral incisor zenith 0.5 to 1 mm below it. (Nanda; Hbk 18.4)", "answerPage": 215, "block": "R"}, {"n": 626, "page": 115, "stem": "In which five planes should the occlusion be checked at finishing?", "options": ["Horizontal, vertical, transverse, dynamic and cephalometric or aesthetic", "Sagittal, vertical, transverse, rotational and axial", "Anterior, posterior, left, right and midline", "Static, dynamic, functional, aesthetic and periodontal", "Occlusal, incisal, buccal, lingual and apical"], "key": "A", "type": "sba", "explanation": "The MBT finishing check covers horizontal, vertical, transverse, dynamic and cephalometric or aesthetic planes, finishing to ABO requirements deliberately rather than by luck. (McLaughlin, Bennett and Trevisi; Hbk 18.3)", "answerPage": 215, "block": "R"}, {"n": 627, "page": 116, "stem": "Which is the correct first-line management of an anterior crossbite in Stage I, where there is space and a positive overbite will result?", "options": ["Extraction of the lower incisor", "Class III elastics", "Proclination of the upper incisor with an opening coil or a removable appliance with a Z-spring and posterior bite planes", "Rapid maxillary expansion", "Referral for surgery"], "key": "C", "type": "sba", "explanation": "Proclination is the appropriate correction where there is room and a positive overbite will result. Posterior crossbites should be corrected before anterior ones. (Companion Ch 12; Hbk 18.1)", "answerPage": 215, "block": "R"}, {"n": 628, "page": 116, "stem": "What force should be used for traction on an exposed impacted canine?", "options": ["10 g", "400 g", "100 g", "200 g", "30 to 50 g"], "key": "E", "type": "sba", "explanation": "Light traction of approximately 30 to 50 g along a controlled path, against adequate anchorage, is appropriate. Space must be created first. (Companion Ch 13; Hbk 18.1)", "answerPage": 215, "block": "R"}, {"n": 629, "page": 116, "stem": "Which single element must precede exposure of an impacted tooth?", "options": ["Retention planning", "Creation of space", "Debonding of the opposing arch", "A CBCT in all cases", "Extraction of the contralateral tooth"], "key": "B", "type": "sba", "explanation": "Space must be created first, then exposure, then light traction against adequate anchorage. (Companion Ch 13; Hbk 18.1 and 20.4)", "answerPage": 216, "block": "R"}, {"n": 630, "page": 116, "stem": "Which single check should be made before every space closure activation?", "options": ["The patient’s oral hygiene score alone", "The bracket prescription", "The archwire material", "Whether the anchorage is holding, measured objectively", "The elastic size"], "key": "D", "type": "sba", "explanation": "Anchorage should be measured on the casts or with a superimposed photograph rather than by impression, and checked before every activation. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 216, "block": "R"}, {"n": 631, "page": 116, "stem": "Class II elastics are contraindicated in which circumstance?", "options": ["A deep overbite", "A Class II molar relationship", "Lower incisors already proclined beyond the alveolar envelope", "A growing patient", "Mild crowding"], "key": "C", "type": "sba", "explanation": "Class II elastics procline the lower incisors, so they are barred if the lower incisors are already forward. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 216, "block": "R"}, {"n": 632, "page": 116, "stem": "Which is the correct sequence of the three treatment stages?", "options": ["Alignment and levelling, buccal segment correction and space closure, finishing and detailing", "Space closure, alignment, finishing", "Finishing, alignment, space closure", "Levelling, finishing, space closure", "Space closure, finishing, alignment"], "key": "A", "type": "sba", "explanation": "Stage I is alignment and levelling, Stage II is buccal segment correction and space closure, Stage III is finishing and detailing. (Companion Ch 10; Hbk 18)", "answerPage": 216, "block": "R"}, {"n": 633, "page": 116, "stem": "Which single feature is most often left imperfect at the end of treatment and should be checked deliberately?", "options": ["Molar relationship", "Overbite", "Overjet", "Centre line", "Vertical position and torque of the canines"], "key": "E", "type": "sba", "explanation": "Canines are frequently left slightly extruded or under-torqued. Check the gingival margin level against the central incisor and the cusp tip in the smile. (McLaughlin, Bennett and Trevisi; Hbk 18.3)", "answerPage": 216, "block": "R"}, {"n": 634, "page": 117, "stem": "Interproximal reduction at the finishing stage is used for which purposes?", "options": ["Anchorage control", "Molar distalisation", "Overbite reduction", "Tooth-size discrepancy, black triangles and marginal ridge discrepancies", "Root parallelism"], "key": "D", "type": "sba", "explanation": "Finishing interproximal reduction addresses tooth-size discrepancy, black triangles and marginal ridge discrepancies. (Proffit Ch 16; Hbk 18.3)", "answerPage": 216, "block": "R"}, {"n": 635, "page": 117, "stem": "Which single statement about detailing bends is correct?", "options": ["They should be avoided entirely in a pre-adjusted appliance", "They comprise first order in and out, second order tip, third order torque and artistic positioning bends", "They are placed only in nickel titanium", "They replace bracket repositioning", "They are placed before space closure"], "key": "B", "type": "sba", "explanation": "Detailing bends cover all three orders plus artistic positioning, and are placed in a wire that fills or nearly fills the slot. (Proffit Ch 16; Hbk 18.3)", "answerPage": 216, "block": "R"}, {"n": 636, "page": 117, "stem": "Which is the correct approach to a residual space at an extraction site during settling?", "options": ["Leave it to close spontaneously", "Debond and refer", "Open it to allow settling", "Place a temporary pontic", "Keep every space closed through settling"], "key": "E", "type": "sba", "explanation": "Every space must be kept closed through the settling period, or it will reopen. (McLaughlin, Bennett and Trevisi; Hbk 18.3)", "answerPage": 216, "block": "R"}, {"n": 637, "page": 117, "stem": "Which single statement about the lower arch during Stage I is correct?", "options": ["The lower arch should be expanded to relieve crowding", "The lower arch is the template, and its original form should be preserved", "The lower arch should be aligned last", "Lower incisor inclination is freely modifiable", "The lower arch requires no anchorage planning"], "key": "B", "type": "sba", "explanation": "The mandibular arch is the template, and intercanine width and lower incisor inclination are the least amenable to change. (Companion Ch 8; Hbk 18.5)", "answerPage": 216, "block": "R"}, {"n": 638, "page": 117, "stem": "Which auxiliary is used to level a deep curve of Spee by true intrusion in a non-growing patient?", "options": ["A reverse curve archwire", "Class II elastics", "A quadhelix", "A utility or bypass intrusion arch, or segmental mechanics", "A transpalatal arch"], "key": "D", "type": "sba", "explanation": "True intrusion in a non-growing patient requires a one-couple intrusion arch or segmental mechanics, at approximately 60 g total. (Burstone 1977; Hbk 18.1 and 25.1)", "answerPage": 216, "block": "R"}, {"n": 639, "page": 117, "stem": "Which single statement about anchorage measurement is correct?", "options": ["Anchorage loss should be measured objectively, on casts or by superimposed photographs", "Anchorage loss can be judged by clinical impression", "Anchorage loss cannot be measured", "Anchorage loss is measured only on a cephalogram", "Anchorage loss is irrelevant once the working wire is placed"], "key": "A", "type": "sba", "explanation": "Measurement rather than impression is required, because anchorage loss is progressive and difficult to judge by eye. (Bennett and McLaughlin; Hbk 18.2)", "answerPage": 216, "block": "R"}, {"n": 640, "page": 117, "stem": "What proportion of cases did the MBT authors treat without extraction?", "options": ["20 to 30 per cent", "40 to 50 per cent", "70 to 80 per cent", "Over 95 per cent", "None"], "key": "C", "type": "sba", "explanation": "The MBT authors report 70 to 80 per cent of cases treated non-extraction, with extraction reserved for defined vertical and protrusion patterns. (McLaughlin, Bennett and Trevisi; Hbk 18.2)", "answerPage": 216, "block": "R"}, {"n": 641, "page": 118, "stem": "Which is the correct role of a laceback in a maximum anchorage case?", "options": ["To advance the incisors", "To expand the arch", "To open the bite", "To distalise the canine without tipping it, preventing incisor advance during levelling", "To derotate the molar"], "key": "D", "type": "sba", "explanation": "Lacebacks distalise the canine without tipping and are the single most effective way of preventing incisor advance during levelling. (Bennett and McLaughlin; Hbk 18.1)", "answerPage": 216, "block": "R"}, {"n": 642, "page": 119, "stem": "The elastic recoil of gingival and supracrestal fibres continues for approximately how long after tooth movement?", "options": ["1 week", "6 to 12 months", "3 years", "10 years", "Indefinitely"], "key": "B", "type": "sba", "explanation": "Periodontal ligament reorganisation takes about 3 to 4 months, but supracrestal collagen and elastic fibres take up to 6 to 12 months. (Proffit Ch 17; Hbk 19.1)", "answerPage": 216, "block": "S"}, {"n": 643, "page": 119, "stem": "Which movement relapses most readily because of gingival fibre recoil?", "options": ["Extrusion", "Tipping", "Intrusion", "Bodily movement", "Rotation"], "key": "E", "type": "sba", "explanation": "Rotations relapse most readily, which is the rationale for circumferential supracrestal fiberotomy and for bonded retention. (Proffit Ch 17; Hbk 19.1)", "answerPage": 216, "block": "S"}, {"n": 644, "page": 119, "stem": "Which are Proffit’s three causes of relapse?", "options": ["Elastic recoil of gingival fibres, soft tissue pressures and continued growth", "Poor bracket position, inadequate torque and early debond", "Anchorage loss, root resorption and demineralisation", "Extraction, expansion and proclination", "Poor compliance, breakage and missed appointments"], "key": "A", "type": "sba", "explanation": "The three causes act on three different timescales: fibre recoil over months, soft tissue pressures continuously, and growth over a lifetime. (Proffit Ch 17; Hbk 19.1)", "answerPage": 216, "block": "S"}, {"n": 645, "page": 119, "stem": "Beyond approximately what degree of lower incisor advance is permanent retention very likely to be required?", "options": ["0.5 mm", "5 mm", "2 mm", "8 mm", "Advance never requires permanent retention"], "key": "C", "type": "sba", "explanation": "If the lower incisors were advanced by more than about 2 mm, permanent retention is very likely to be needed. (Proffit Ch 17; Hbk 19.1)", "answerPage": 216, "block": "S"}, {"n": 646, "page": 119, "stem": "Houston’s rule for overbite stability requires which condition?", "options": ["A Class I molar relationship", "Correction of the interincisal angle and establishment of an occlusal stop", "A bonded retainer", "Extraction of premolars", "Levelling by intrusion only"], "key": "B", "type": "sba", "explanation": "Overbite reduction relapses unless the interincisal angle is corrected and an occlusal stop established. (Houston 1989; Millett 2012; Hbk 19.1)", "answerPage": 216, "block": "S"}, {"n": 647, "page": 119, "stem": "Which retainer was found more effective than a Hawley in the lower labial segment?", "options": ["A bonded retainer", "A Begg wrap-around retainer", "A positioner", "A vacuum-formed retainer", "A spring retainer"], "key": "D", "type": "sba", "explanation": "Rowland and colleagues found vacuum-formed retainers more effective than Hawley retainers in the lower labial segment. (Rowland 2007; Hbk 19.2)", "answerPage": 216, "block": "S"}, {"n": 648, "page": 120, "stem": "Forde and Martin reported which comparison between fixed and removable retainers?", "options": ["Fixed retainers are marginally more effective in the lower arch for the first 12 months, especially for rotations, and equivalent thereafter", "Fixed retainers are superior indefinitely", "Removable retainers are superior throughout", "There is no difference at any time point", "Fixed retainers cause more relapse"], "key": "A", "type": "sba", "explanation": "Fixed retainers are marginally better for the first 12 months, particularly for rotations, and equivalent thereafter. (Forde 2017; Martin 2023; Hbk 19.2)", "answerPage": 217, "block": "S"}, {"n": 649, "page": 120, "stem": "By 4 to 5 years after treatment, what proportion of patients are still wearing their retainers?", "options": ["Nearly all", "A majority", "A minority", "Approximately half", "All patients"], "key": "C", "type": "sba", "explanation": "Al-Moghrabi and Kramer found that by 4 to 5 years post-treatment the majority of patients have stopped wearing their retainers. (Al-Moghrabi 2018; Hbk 19.3)", "answerPage": 217, "block": "S"}, {"n": 650, "page": 120, "stem": "Which single complication is associated with long-term bonded retainers?", "options": ["Root resorption", "Condylar resorption", "Loss of vitality", "Ankylosis", "Bond failure, wire fracture, unwanted torque or wire syndrome, calculus and caries"], "key": "E", "type": "sba", "explanation": "Bonded retainers require lifelong monitoring for bond failure, wire fracture, unwanted torque, calculus and caries. (Companion Ch 13; Hbk 19.2)", "answerPage": 217, "block": "S"}, {"n": 651, "page": 120, "stem": "Which is the most honest sentence to give a patient about the duration of retention?", "options": ["If you want the teeth to stay where they are, you wear a retainer for as long as you want that; there is no endpoint", "Retention is required for two years", "Retention is required until growth ceases", "Retention is optional after debond", "Retention is required only for the lower arch"], "key": "A", "type": "sba", "explanation": "There is no endpoint. This is the honest statement, and it must be made before active treatment begins, not at debond. (Companion Ch 13; Hbk 19.3)", "answerPage": 217, "block": "S"}, {"n": 652, "page": 120, "stem": "When should the retention plan be agreed?", "options": ["At debond", "At the mid-treatment review", "Before active treatment begins", "When relapse occurs", "At the first review after debond"], "key": "C", "type": "sba", "explanation": "Retention should be discussed prior to the commencement of active treatment, and the patient must agree the plan. (Companion Ch 13; Hbk 19.3)", "answerPage": 217, "block": "S"}, {"n": 653, "page": 120, "stem": "Which type of crowding is described as tertiary?", "options": ["Tooth size versus jaw size", "Crowding due to tongue, lip and cheek pressures", "Crowding due to supernumeraries", "Crowding due to early loss of primary teeth", "Crowding developing from adolescence onwards"], "key": "E", "type": "sba", "explanation": "Primary crowding is tooth size versus jaw size, secondary is environmental, and tertiary is the late crowding developing from adolescence onwards. (Companion Ch 5; Hbk 19.4)", "answerPage": 217, "block": "S"}, {"n": 654, "page": 120, "stem": "Which is the major factor driving late lower incisor crowding?", "options": ["Third molars", "Mandibular growth rotation uprighting the lower labial segment", "The anterior component of occlusal force", "Reduced interproximal wear", "Periodontal attachment loss"], "key": "B", "type": "sba", "explanation": "Continued mandibular growth rotation, uprighting the lower labial segment, is the major factor. Growth continues throughout adult life in the original pattern. (Behrents 1985; Solow 1980; Hbk 19.4)", "answerPage": 217, "block": "S"}, {"n": 655, "page": 121, "stem": "The anterior component of occlusal force as a cause of late lower crowding is best described how?", "options": ["Proven", "Relevant only in males", "The principal cause", "Doubted, because the forces are too brief", "Relevant only after extraction"], "key": "D", "type": "sba", "explanation": "Southard proposed it, but the short duration of these forces makes it an unlikely cause. (Southard 1990; Hbk 19.4)", "answerPage": 217, "block": "S"}, {"n": 656, "page": 121, "stem": "Sinclair and Little reported which finding in untreated subjects?", "options": ["Arch dimensions increase with age", "Crowding resolves spontaneously", "Mandibular arch width and length decrease with age, with increasing anterior crowding", "Third molars prevent crowding", "No change occurs after 18 years"], "key": "C", "type": "sba", "explanation": "Untreated subjects show decreasing mandibular arch width and length with increasing anterior crowding, which establishes late crowding as ageing rather than relapse. (Sinclair and Little 1983; Hbk 19.4)", "answerPage": 217, "block": "S"}, {"n": 657, "page": 121, "stem": "A 27-year-old presents with 2 mm of lower incisor irregularity 10 years after orthodontic treatment. What is the correct interpretation?", "options": ["Normal age-related change rather than relapse, occurring in treated and untreated people alike", "Treatment failure requiring retreatment at no charge", "Evidence of an unstable extraction pattern", "Evidence of inadequate torque expression", "Evidence of third molar pressure"], "key": "A", "type": "sba", "explanation": "Late lower incisor crowding is age-related change, not relapse, and no extraction pattern or archwire sequence prevents it. The answer is long-term bonded retention. (Thilander 2009; Hbk 19.4)", "answerPage": 217, "block": "S"}, {"n": 658, "page": 121, "stem": "Circumferential supracrestal fiberotomy is performed at which point?", "options": ["After debond", "Only in adults", "Six months after debond", "At the time of bonding", "Before appliance removal"], "key": "E", "type": "sba", "explanation": "Both circumferential supracrestal fiberotomy and frenectomy are performed before appliance removal. The evidence for fiberotomy is weak but it is not harmful. (Cobourne cases; Hbk 19.1 and 21.1)", "answerPage": 217, "block": "S"}, {"n": 659, "page": 121, "stem": "Which is the correct sequence when closing a midline diastema associated with a prominent fraenum?", "options": ["Frenectomy first, then close the space", "Neither is required", "Frenectomy alone will close the space", "Close the space first, then perform a frenectomy if needed", "Extract the fraenum-bearing tooth"], "key": "D", "type": "sba", "explanation": "A frenectomy performed before closure leaves scar tissue that resists closure. Close first, then operate if needed, and always retain permanently. (Cobourne cases; Hbk 21.1)", "answerPage": 217, "block": "S"}, {"n": 660, "page": 121, "stem": "Which retainer permits posterior settling of the occlusion?", "options": ["A vacuum-formed retainer", "A Hawley or Begg wrap-around retainer", "A bonded retainer alone", "A positioner", "None permit settling"], "key": "B", "type": "sba", "explanation": "A Hawley or Begg wrap-around retainer permits posterior settling, whereas a full-coverage vacuum-formed retainer holds the posterior teeth apart. (Companion Ch 13; Hbk 19.2)", "answerPage": 217, "block": "S"}, {"n": 661, "page": 121, "stem": "Which retention appliance simultaneously settles the occlusion and retains?", "options": ["A Hawley retainer", "A vacuum-formed retainer", "A bonded retainer", "A spring retainer", "A positioner"], "key": "E", "type": "sba", "explanation": "A positioner settles the occlusion and retains simultaneously, but is bulky and poorly tolerated. (Proffit Ch 17; Hbk 19.2)", "answerPage": 217, "block": "S"}, {"n": 662, "page": 122, "stem": "Which single appliance is used to correct minor relapse of lower incisor alignment?", "options": ["A quadhelix", "A spring retainer or an aligner used as an active retainer", "A twin block", "A transpalatal arch", "A facemask"], "key": "B", "type": "sba", "explanation": "Active retainers, such as a spring retainer, a Barrer retainer or an aligner, can correct minor relapse of lower incisor alignment. (Companion Ch 13; Hbk 19.2)", "answerPage": 217, "block": "S"}, {"n": 663, "page": 122, "stem": "An anterior crossbite corrected with a positive overbite typically requires which retention?", "options": ["Permanent bonded retention", "A functional appliance", "Six months of full-time wear", "Usually no retention, because the correction is self-retaining", "A fixed retainer for 12 months"], "key": "D", "type": "sba", "explanation": "Wiedel and Bondemark found that an anterior crossbite corrected with a positive overbite is usually stable and requires no retention. (Wiedel and Bondemark 2015; Hbk 19.1 and 24.3)", "answerPage": 217, "block": "S"}, {"n": 664, "page": 122, "stem": "Which is the correct retention strategy after lower intercanine expansion?", "options": ["Permanent retention, since lower intercanine expansion reliably relapses", "No retention is required", "Six weeks of retention", "Retention only until growth ceases", "A Hawley retainer for 3 months"], "key": "A", "type": "sba", "explanation": "Lower intercanine width should not be expanded, and where it has been, permanent retention is required. (Proffit Ch 17; Hbk 19.1)", "answerPage": 217, "block": "S"}, {"n": 665, "page": 122, "stem": "Which is the standard vacuum-formed retainer material thickness?", "options": ["0.25 mm", "2 mm", "0.75 to 1 mm", "3 mm", "4 mm"], "key": "C", "type": "sba", "explanation": "Vacuum-formed retainers are made from 0.75 to 1 mm thermoplastic sheet. They wear out and must be replaced. (Companion Ch 13; Hbk 19.2)", "answerPage": 217, "block": "S"}, {"n": 666, "page": 122, "stem": "A common retention regimen after fixed appliance treatment is which of the following?", "options": ["Full-time for 5 years, then stop", "Full-time indefinitely", "Nights for 6 weeks, then stop", "Full-time for approximately 3 months, then nights indefinitely", "Alternate nights for 12 months, then stop"], "key": "D", "type": "sba", "explanation": "There is no universally accepted regimen. A common protocol is full-time for the first 3 months, or straight to nights with a vacuum-formed retainer, then nights indefinitely. (Companion Ch 13; Hbk 19.3)", "answerPage": 217, "block": "S"}, {"n": 667, "page": 122, "stem": "Retention cannot be abandoned until which condition is met?", "options": ["The patient reaches 18 years", "Growth is essentially completed", "The retainer is lost", "Two years have elapsed", "The occlusion has settled"], "key": "B", "type": "sba", "explanation": "Retention cannot be abandoned until growth is essentially complete, and even then late crowding continues as an age-related change. (Proffit Ch 17; Hbk 19.1)", "answerPage": 218, "block": "S"}, {"n": 668, "page": 122, "stem": "Which single item related to retention is most often omitted from the consent discussion and most often disputed later?", "options": ["The type of retainer", "The impression material", "The colour of the retainer", "The laboratory used", "The cost of replacing lost or broken retainers"], "key": "E", "type": "sba", "explanation": "The cost of replacement retainers should be stated at the outset, together with the consequences of loss. (GDC Standards; Hbk 19.3)", "answerPage": 218, "block": "S"}, {"n": 669, "page": 123, "stem": "Which of the following is the correct place for a bonded retainer in the lower arch?", "options": ["From 6 to 6", "From 3 to 3, or 2 to 2", "On the incisors only, spot-bonded to two teeth", "On the canines only", "Bonded to the molars"], "key": "A", "type": "sba", "explanation": "A multistrand wire bonded 3 to 3, or 2 to 2, is the usual configuration in the lower arch. (Companion Ch 13; Hbk 19.2)", "answerPage": 218, "block": "S"}, {"n": 670, "page": 123, "stem": "Which single statement about teeth moved outside the zone of soft tissue equilibrium is correct?", "options": ["They are stable once the periodontal ligament reorganises", "They stabilise after 12 months", "They return towards the neutral zone and need permanent retention", "They require no retention if the occlusion is ideal", "They relapse only in adults"], "key": "C", "type": "sba", "explanation": "Any tooth moved outside the neutral zone, such as by lower incisor proclination or lower arch expansion, needs permanent retention. (Proffit Ch 17; Hbk 19.1)", "answerPage": 218, "block": "S"}, {"n": 671, "page": 123, "stem": "Which statement about growth and retention is correct?", "options": ["Growth ceases at 18 and retention can then stop", "Very slow growth continues throughout adult life in the original pattern, so retention cannot be abandoned on the basis of age alone", "Growth affects only the maxilla after 18", "Growth-related change is confined to Class III patients", "Growth has no relevance to retention"], "key": "B", "type": "sba", "explanation": "Behrents demonstrated continued rotational growth throughout adult life, which is one of the three causes of relapse. (Behrents 1985; Hbk 19.1)", "answerPage": 218, "block": "S"}, {"n": 672, "page": 123, "stem": "Wire syndrome associated with a bonded retainer refers to which problem?", "options": ["Fracture of the wire", "Gingival recession", "Caries beneath the composite", "Unwanted torque or positional change developing in one or more bonded teeth from an unnoticed partial bond failure or wire distortion", "Loss of vitality"], "key": "D", "type": "sba", "explanation": "Wire syndrome describes progressive unwanted tooth movement caused by an unnoticed change in a bonded retainer, and is the reason lifelong monitoring is required. (Companion Ch 13; Hbk 19.2)", "answerPage": 218, "block": "S"}, {"n": 673, "page": 123, "stem": "Which is the correct advice about retainer wear in a patient who reports the retainer feels tight after a week without wear?", "options": ["Attend for review rather than forcing it, since tightness indicates movement has occurred", "Force it into place and continue", "Discard the retainer", "Wear it full time for a month without review", "Reduce wear to alternate nights"], "key": "A", "type": "sba", "explanation": "Tightness indicates that movement has occurred. Forcing a retainer can fracture it or move teeth unpredictably. Review is required. (Companion Ch 13; Hbk 19.3)", "answerPage": 218, "block": "S"}, {"n": 674, "page": 123, "stem": "Which is the correct sequence of the three timescales of relapse?", "options": ["Growth over months, fibres over years, soft tissues over decades", "Soft tissues over weeks, growth over months, fibres over years", "Fibres over months, soft tissues continuously, growth over a lifetime", "All three act over the same period", "Only fibre recoil is time-limited"], "key": "C", "type": "sba", "explanation": "Fibre recoil acts over months, soft tissue pressures act continuously, and growth acts over a lifetime. (Proffit Ch 17; Hbk 19.1)", "answerPage": 218, "block": "S"}, {"n": 675, "page": 123, "stem": "Which single measure best prevents relapse of a closed midline diastema?", "options": ["A vacuum-formed retainer worn at night", "Interproximal reduction", "A Hawley retainer for 6 months", "A frenectomy alone", "A permanent bonded retainer"], "key": "E", "type": "sba", "explanation": "A closed diastema relapses reliably, so a bonded retainer is not optional. (Cobourne cases; Hbk 19.1 and 21.1)", "answerPage": 218, "block": "S"}, {"n": 676, "page": 124, "stem": "Which is the correct interpretation of retention as it appears in a treatment plan?", "options": ["A planned and agreed element of the plan, decided before treatment begins", "A single sentence in the conclusion", "A decision made at debond", "A decision for the patient alone", "An optional extra"], "key": "A", "type": "sba", "explanation": "Retention should occupy a paragraph in the plan rather than a sentence in the conclusion, and must be agreed before treatment begins. (Companion Ch 8; Hbk 12.1 and 19.3)", "answerPage": 218, "block": "S"}, {"n": 677, "page": 125, "stem": "Which interceptive intervention has the strongest supporting evidence?", "options": ["Arch expansion for crowding", "Two-phase Class II treatment", "Correction of a posterior crossbite with a displacement at ages 7 to 11", "Interceptive extraction of the primary canine", "Serial extraction"], "key": "C", "type": "sba", "explanation": "Ugolini’s Cochrane review provides high-certainty evidence that a quadhelix or expansion plate beats observation at ages 7 to 11 for crossbite with displacement. (Ugolini 2021; Hbk 20.2)", "answerPage": 218, "block": "T"}, {"n": 678, "page": 125, "stem": "Localised space loss of what magnitude can generally be regained?", "options": ["Up to 1 mm", "Any amount", "Up to 6 mm", "Up to 10 mm", "3 mm or less"], "key": "E", "type": "sba", "explanation": "Localised space loss of 3 mm or less is the space-regaining case. More than 4 mm generally means extraction. (Proffit Ch 12; Hbk 20.1)", "answerPage": 218, "block": "T"}, {"n": 679, "page": 125, "stem": "Which single question should be asked at every interceptive decision?", "options": ["Which appliance is available", "Does waiting cost growth I cannot get back", "What the patient prefers", "What the IOTN grade is", "Whether the parents can afford treatment"], "key": "B", "type": "sba", "explanation": "The interceptive question is always whether waiting costs growth that cannot be recovered. If not, waiting is usually correct. (Companion Ch 12; Hbk 20.1)", "answerPage": 218, "block": "T"}, {"n": 680, "page": 125, "stem": "A review interval for an interceptive decision should be specified how?", "options": ["As keep an eye on it", "As at the discretion of the general dentist", "As whenever the patient returns", "As a defined date, with a defined endpoint", "No review is required"], "key": "D", "type": "sba", "explanation": "Every observation period must have a defined endpoint. Indefinite observation is not a plan. (Proffit Ch 12; Hbk 20.1)", "answerPage": 218, "block": "T"}, {"n": 681, "page": 125, "stem": "The prevalence of maxillary canine impaction is approximately which value?", "options": ["Under 1 per cent", "8 per cent", "2 to 3 per cent", "15 per cent", "25 per cent"], "key": "C", "type": "sba", "explanation": "The maxillary canine fails to erupt in approximately 2 to 3 per cent of Caucasian children, with up to 85 per cent of these palatal. (Ferguson 1990; Hbk 20.4)", "answerPage": 218, "block": "T"}, {"n": 682, "page": 125, "stem": "What proportion of impacted maxillary canines are palatally positioned?", "options": ["Up to 85 per cent", "45 per cent", "20 per cent", "95 per cent", "All of them"], "key": "A", "type": "sba", "explanation": "Up to 85 per cent of impacted maxillary canines are palatal, which is why palpation of the buccal sulcus is the key screening manoeuvre. (Ferguson 1990; Hbk 20.4)", "answerPage": 218, "block": "T"}, {"n": 683, "page": 126, "stem": "Bilateral occurrence of maxillary canine impaction is reported in what proportion of affected patients?", "options": ["Under 5 per cent", "Always bilateral", "60 per cent", "80 per cent", "17 to 45 per cent"], "key": "E", "type": "sba", "explanation": "Peck reported bilateral occurrence in 17 to 45 per cent, with impaction up to three times more common in females and five times more common in Europeans than Asians. (Peck 1994; Hbk 20.4)", "answerPage": 218, "block": "T"}, {"n": 684, "page": 126, "stem": "The eruptive path of the maxillary canine is approximately how long?", "options": ["5 mm", "10 mm", "40 mm", "Over 20 mm", "It has no defined length"], "key": "D", "type": "sba", "explanation": "The maxillary canine has the longest eruptive path in the dentition, over 20 mm, which is one reason it is so often displaced. (Companion Ch 12; Hbk 20.4)", "answerPage": 218, "block": "T"}, {"n": 685, "page": 126, "stem": "The real threat posed by a palatally displaced canine is which of the following?", "options": ["Loss of the primary canine", "Resorption of the lateral and central incisor roots", "Ankylosis of the first molar", "Loss of arch length only", "Development of a dentigerous cyst in all cases"], "key": "B", "type": "sba", "explanation": "The principal threat is resorption of the adjacent incisor roots, which is why localisation matters and why CBCT is sometimes justified. (Companion Ch 12; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 686, "page": 126, "stem": "The RCS guidance interval for interceptive extraction of the primary canine is which age range?", "options": ["6 to 8 years", "After 16 years", "14 to 16 years", "Any age", "10 to 13 years"], "key": "E", "type": "sba", "explanation": "Interception is conventionally at 10 to 11 years, with RCS guidance giving 10 to 13 years, provided there is space and the canine position is favourable. (Ericson and Kurol; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 687, "page": 126, "stem": "Which angulation of the canine to the midsagittal plane is regarded as favourable for interception?", "options": ["Under 10 degrees", "20 to 30 degrees", "40 to 50 degrees", "Over 55 degrees", "Angulation is irrelevant"], "key": "B", "type": "sba", "explanation": "An angulation of 20 to 30 degrees to the midsagittal plane, with the crown distal to the lateral incisor root midline, is favourable. Prognosis worsens beyond 55 degrees. (Ericson and Kurol; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 688, "page": 126, "stem": "Ericson and Kurol found what proportion of canines normalise when the overlap of the lateral incisor root is less than half?", "options": ["54 per cent", "64 per cent", "78 per cent", "91 per cent", "100 per cent"], "key": "D", "type": "sba", "explanation": "Overlap of less than half the lateral incisor root gives 91 per cent normalisation; overlap of more than half gives 64 per cent after primary canine extraction. (Ericson and Kurol 1988; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 689, "page": 126, "stem": "Naoumova’s randomised work identified which two most influential predictors of successful eruption?", "options": ["Alpha angle and sector position", "Age and sex", "Overjet and overbite", "Arch length and intercanine width", "Skeletal pattern and vertical proportion"], "key": "A", "type": "sba", "explanation": "Alpha angle and sector position are the most influential predictors of eruption after primary canine extraction. (Naoumova 2015, 2018; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 690, "page": 127, "stem": "The 2017 Cochrane review by Parkin compared open and closed exposure and found what?", "options": ["Closed exposure was significantly superior", "Open exposure was significantly superior", "No difference in success or other outcomes, on low to very low quality evidence", "Open exposure caused more ankylosis", "Closed exposure was faster"], "key": "C", "type": "sba", "explanation": "Parkin found no difference in success or other outcomes. Cassina later reported that open exposure was associated with just over 2 months less time to alignment and lower odds of ankylosis. (Parkin 2017; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 691, "page": 127, "stem": "Which surgical technique is indicated for a buccally displaced canine lying below the mucogingival junction?", "options": ["Closed exposure with a gold chain", "Extraction", "Open exposure with a dressing", "An apically repositioned flap", "Autotransplantation"], "key": "D", "type": "sba", "explanation": "Kokich described the apically repositioned flap for buccal canines below the mucogingival junction, so that the tooth erupts through attached tissue. (Kokich 2004; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 692, "page": 127, "stem": "The reported success rate of canine autotransplantation is approximately which value?", "options": ["55 per cent", "88 per cent", "70 per cent", "97 per cent", "100 per cent"], "key": "B", "type": "sba", "explanation": "Patel reported success of approximately 88 per cent, with semi-rigid splinting for no more than 3 weeks followed by root treatment. (Patel 2009; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 693, "page": 127, "stem": "Which prognostic feature most worsens the outlook for aligning an impacted canine?", "options": ["A crown position below the apical third of the incisor roots", "Presence of the primary canine", "A palatal position", "An age of 12 years", "A crown position above the apical third of the incisor roots"], "key": "E", "type": "sba", "explanation": "Prognosis worsens with height above the apical third of the incisor roots, with a horizontal position at or across the lateral incisor midline, and with angulation above about 55 degrees. (Companion Ch 13; Hbk 20.4)", "answerPage": 219, "block": "T"}, {"n": 694, "page": 127, "stem": "The prevalence of mandibular second molar impaction is approximately which value?", "options": ["Just over 2 per cent", "0.2 per cent", "8 per cent", "15 per cent", "25 per cent"], "key": "A", "type": "sba", "explanation": "Mandibular second molar impaction affects just over 2 per cent, with evidence of a genetic basis at least in the mandible. (Shapira 2011; Hbk 20.5)", "answerPage": 219, "block": "T"}, {"n": 695, "page": 127, "stem": "Which radiographic sign warns of impending mandibular second molar impaction?", "options": ["A short root on the first molar", "A widened periodontal ligament space", "A third molar follicle sitting above the occlusal table of the developing second molar", "An enlarged mandibular canal", "A deep antegonial notch"], "key": "C", "type": "sba", "explanation": "A third molar follicle above the occlusal table of the developing second molar is the warning sign on the panoramic radiograph. (Companion Ch 12; Hbk 20.5)", "answerPage": 219, "block": "T"}, {"n": 696, "page": 127, "stem": "Which is the correct escalating ladder for an impacted mandibular second molar?", "options": ["Extract the second molar, then observe", "Observe, disimpact, remove the third molar, surgically upright, then extract the second molar", "Surgically upright first, then observe", "Extract the third molar, then extract the second molar", "Apply orthodontic traction immediately"], "key": "B", "type": "sba", "explanation": "The ladder escalates from observation for 6 to 12 months, through disimpaction and third molar removal, to surgical uprighting, with second molar extraction as the least successful last resort. (Companion Ch 12; Hbk 20.5)", "answerPage": 219, "block": "T"}, {"n": 697, "page": 128, "stem": "Extraction of the impacted mandibular second molar is described in which way?", "options": ["The treatment of choice", "Contraindicated in all cases", "The fastest option with the best results", "The least successful outcome, because it commits the patient to unpredictable third molar eruption", "The first-line intervention"], "key": "D", "type": "sba", "explanation": "Magnusson and Kjellberg found that extraction of the second molar itself gives the least successful outcome. (Magnusson and Kjellberg 2009; Hbk 20.5)", "answerPage": 219, "block": "T"}, {"n": 698, "page": 128, "stem": "Where should a separator or open coil be placed to disimpact a mesially tilted mandibular second molar?", "options": ["Below the contact point", "Above the contact point", "At the gingival margin of the first molar", "On the distal of the third molar", "On the occlusal surface"], "key": "A", "type": "sba", "explanation": "A separator, brass wire or open coil is placed below the contact point in order to disimpact the tooth. (Companion Ch 12; Hbk 20.5)", "answerPage": 219, "block": "T"}, {"n": 699, "page": 128, "stem": "After avulsion of a maxillary central incisor in a 9-year-old, what is the correct immediate approach?", "options": ["Leave the socket to heal and plan a prosthesis", "Extract the contralateral incisor for symmetry", "Always attempt re-implantation, even with a poor long-term prognosis", "Close the space orthodontically at once", "Place an immediate implant"], "key": "C", "type": "sba", "explanation": "Re-implantation maintains the space and the alveolar bone and buys years, even when the long-term prognosis is poor. (Companion Ch 12; Hbk 20.6)", "answerPage": 219, "block": "T"}, {"n": 700, "page": 128, "stem": "Implant placement to replace a missing maxillary central incisor in an adolescent should be deferred until when?", "options": ["Age 16 in girls and 18 in boys as a rule", "Age 14 in both sexes", "Immediately after space creation", "Immediately after debond", "Growth is complete, confirmed by serial records"], "key": "E", "type": "sba", "explanation": "Continued vertical alveolar growth leaves an implant crown in infra-occlusion, so implants must await confirmed completion of growth. (Companion Ch 12; Hbk 20.6)", "answerPage": 219, "block": "T"}, {"n": 701, "page": 128, "stem": "Which single argument favours letting a maxillary central incisor space close and reopening it later?", "options": ["It preserves alveolar bone", "It shortens treatment", "It avoids the need for orthodontics", "It avoids retention", "It is cheaper"], "key": "A", "type": "sba", "explanation": "Space closure preserves alveolar bone height, at the cost of committing the patient to further orthodontics later. Space maintenance risks alveolar resorption. (Companion Ch 12; Hbk 20.6)", "answerPage": 219, "block": "T"}, {"n": 702, "page": 128, "stem": "After an uncomplicated crown fracture, how long should orthodontic force be delayed?", "options": ["No delay", "6 months", "3 months", "12 months", "24 months"], "key": "C", "type": "sba", "explanation": "Uncomplicated crown fracture, subluxation and minor lateral luxation each require a 3-month rest period before orthodontic force. (Companion Ch 8; Hbk 20.7)", "answerPage": 219, "block": "T"}, {"n": 703, "page": 129, "stem": "After re-implantation following avulsion, how long should orthodontic force be delayed?", "options": ["3 months", "6 months", "No delay is needed", "24 months", "12 months"], "key": "E", "type": "sba", "explanation": "Re-implantation, intrusion, extrusion and moderate or severe lateral luxation all require a 12-month rest period. (Companion Ch 8; Hbk 20.7)", "answerPage": 220, "block": "T"}, {"n": 704, "page": 129, "stem": "After a complicated crown fracture, orthodontic force should be delayed until which point?", "options": ["3 months have elapsed", "A hard tissue barrier is seen", "The tooth is root treated", "6 weeks have elapsed", "The tooth is asymptomatic"], "key": "B", "type": "sba", "explanation": "A complicated crown fracture requires a delay until a hard tissue barrier is demonstrable. (Companion Ch 8; Hbk 20.7)", "answerPage": 220, "block": "T"}, {"n": 705, "page": 129, "stem": "A root-fractured tooth healing by connective tissue rather than by dentine and cementum should be treated in which way?", "options": ["As a normal tooth", "With heavy forces to overcome the fracture", "With no orthodontic force ever", "As a short-rooted tooth, with light forces", "By extraction"], "key": "D", "type": "sba", "explanation": "Connective tissue healing means the coronal fragment behaves as a short-rooted tooth, so light forces are used. (Companion Ch 8; Hbk 20.7)", "answerPage": 220, "block": "T"}, {"n": 706, "page": 129, "stem": "During orthodontic movement of a previously traumatised tooth, radiographs should be repeated at what interval after starting movement?", "options": ["2 weeks", "18 months", "6 to 9 months", "At debond only", "Radiographs are unnecessary"], "key": "C", "type": "sba", "explanation": "Radiographs should be repeated 6 to 9 months after starting movement, with threemonthly vitality testing. (Companion Ch 8; Hbk 20.7)", "answerPage": 220, "block": "T"}, {"n": 707, "page": 129, "stem": "Which are the three complications of moving a previously traumatised tooth?", "options": ["Loss of vitality, pulpal calcification and root resorption where resorption has already occurred", "Ankylosis, caries and periodontal disease", "Fracture, discolouration and mobility", "Impaction, transposition and ectopia", "Gingival recession, hyperplasia and abscess"], "key": "A", "type": "sba", "explanation": "These three complications should be named specifically at consent for a case involving a previously traumatised tooth. (Companion Ch 8; Hbk 20.7)", "answerPage": 220, "block": "T"}, {"n": 708, "page": 129, "stem": "If root resorption appears on a mid-treatment radiograph in a previously traumatised tooth, force should be paused for how long?", "options": ["1 month", "Force need not be paused", "9 months", "12 months", "3 months"], "key": "E", "type": "sba", "explanation": "Pause for 3 months in a previously traumatised tooth, against 3 to 6 months for orthodontically induced resorption generally. (Companion Ch 8; Hbk 20.7)", "answerPage": 220, "block": "T"}, {"n": 709, "page": 129, "stem": "Serial extraction is indicated in which circumstance?", "options": ["Class II division 2 with a deep overbite", "Hypodontia of the lower second premolars", "Anterior open bite with a digit habit", "Severe crowding with a Class I skeletal pattern and no vertical problem", "Mild crowding of 3 mm"], "key": "D", "type": "sba", "explanation": "Serial extraction requires severe crowding with a Class I skeletal pattern and no vertical discrepancy. It is contraindicated in Class II or III, deep or open bite and hypodontia. (Proffit Ch 12; Hbk 20.3)", "answerPage": 220, "block": "T"}, {"n": 710, "page": 130, "stem": "Which appliance is used to preserve the leeway space to relieve mild lower arch crowding?", "options": ["A quadhelix", "A lower lingual arch", "A twin block", "A transpalatal arch", "A Nance button"], "key": "B", "type": "sba", "explanation": "A lower lingual arch preserves the leeway space by preventing mesial drift of the first permanent molars, and has good evidence as an interceptive measure. (Companion Ch 12; Hbk 20.2)", "answerPage": 220, "block": "T"}, {"n": 711, "page": 130, "stem": "An anterior crossbite with a displacement in an 8-year-old, with space available and a positive overbite anticipated, should be treated in which way?", "options": ["Observation until the permanent dentition", "Extraction of the lower incisor", "Rapid maxillary expansion", "Facemask therapy", "Proclination of the upper incisor, for example with a removable appliance and posterior bite planes"], "key": "E", "type": "sba", "explanation": "An anterior crossbite with a displacement is treated on diagnosis, and correction is selfretaining if a positive overbite results. An incline plane corrects it in 3 to 4 weeks. (Companion Ch 12; Hbk 20.2 and 24.3)", "answerPage": 220, "block": "T"}, {"n": 712, "page": 130, "stem": "Which single sign indicates that a posterior crossbite requires treatment on diagnosis?", "options": ["Involvement of three or more teeth", "A mandibular displacement on closing", "Bilateral involvement", "Presence in the primary dentition", "Association with a digit habit"], "key": "B", "type": "sba", "explanation": "A displacement makes the case urgent because it causes attrition, is associated with asymmetric growth and with recession, and the case will not settle until corrected. (Ugolini 2021; Hbk 20.2 and 24.1)", "answerPage": 220, "block": "T"}, {"n": 713, "page": 130, "stem": "An anterior open bite caused by a digit habit that ceases before the permanent incisors are established will usually do what?", "options": ["Persist unchanged", "Require a twin block", "Require surgery", "Close spontaneously", "Worsen with growth"], "key": "D", "type": "sba", "explanation": "A habit-related open bite usually closes spontaneously if the habit stops before the permanent incisors are in occlusion. A skeletal open bite will not. (Companion Ch 12; Hbk 20.2 and 25.2)", "answerPage": 220, "block": "T"}, {"n": 714, "page": 130, "stem": "A skeletal anterior open bite, if treated early at all, should be treated at approximately which age?", "options": ["7 to 9 years", "4 to 5 years", "11 to 12 years", "14 to 16 years", "Only after growth is complete"], "key": "A", "type": "sba", "explanation": "Where early treatment of a skeletal open bite is undertaken, it is done at 7 to 9 years, although the evidence is weak. (Mosby ch. on interceptive treatment; Hbk 20.2)", "answerPage": 220, "block": "T"}, {"n": 715, "page": 130, "stem": "Which is the correct management of a tuberculate supernumerary preventing eruption of a maxillary central incisor?", "options": ["Extract the permanent incisor", "Expose and bond the incisor at the same visit in all cases", "Remove the supernumerary, create or maintain space, and observe for eruption for about 12 months", "Observe for 3 years", "Extract the primary incisor only"], "key": "C", "type": "sba", "explanation": "Remove the obstruction, create and maintain space, then observe. Expose and bond if there is no eruption within about 12 months. (Companion Ch 12; Hbk 20.2)", "answerPage": 220, "block": "T"}, {"n": 716, "page": 131, "stem": "An ectopic maxillary first permanent molar in a 7-year-old resorbing the second primary molar may be managed initially by which approach?", "options": ["Immediate extraction of the second primary molar", "Rapid maxillary expansion", "Immediate extraction of the first permanent molar", "Observation, since spontaneous disimpaction may occur up to about 8 years", "Headgear"], "key": "D", "type": "sba", "explanation": "Spontaneous disimpaction may occur up to approximately 8 years. Beyond that a separator, brass wire or distalising spring is used. (Companion Ch 12; Hbk 20.2)", "answerPage": 220, "block": "T"}, {"n": 717, "page": 131, "stem": "Which interceptive intervention has weak evidence and should be presented cautiously?", "options": ["Correction of a crossbite with a displacement", "Arch expansion undertaken purely to relieve crowding", "Leeway space maintenance", "Removal of a supernumerary preventing eruption", "Habit interception before the permanent incisors erupt"], "key": "B", "type": "sba", "explanation": "Expansion yields only about half its width as usable space and lower arch expansion relapses, so expansion purely to relieve crowding has weak evidence. (Cobourne cases; Hbk 20.2)", "answerPage": 220, "block": "T"}, {"n": 718, "page": 131, "stem": "Two-phase Class II treatment is best described in which way?", "options": ["Superior to single-phase treatment", "Contraindicated in all cases", "Superior in all high-angle cases", "Mandatory when the overjet exceeds 6 mm", "Not superior to a single phase started in the late mixed dentition, except for trauma risk or significant teasing"], "key": "E", "type": "sba", "explanation": "The randomised trials found no long-term advantage. The exceptions are high trauma risk and significant teasing. (O’Brien 2009; Hbk 20.2 and 22.2)", "answerPage": 220, "block": "T"}, {"n": 719, "page": 131, "stem": "Which is the correct approach to transient crowding of the lower permanent incisors in an 8-year-old?", "options": ["Reassure and review", "Extract the primary canines", "Fit a lower lingual arch immediately", "Begin lower arch expansion", "Extract a lower incisor"], "key": "A", "type": "sba", "explanation": "Space for the mandibular incisors is negative for about two years after eruption. Transient early crowding is normal and self-correcting. (Proffit Ch 3; Hbk 20.1)", "answerPage": 220, "block": "T"}, {"n": 720, "page": 131, "stem": "A firm, unresorbed primary maxillary canine in a 14-year-old should be regarded in which way?", "options": ["As normal and reassuring", "As an indication for immediate extraction without imaging", "As a red flag for an ectopic permanent canine", "As an indication for a CBCT in all cases", "As a contraindication to orthodontic treatment"], "key": "C", "type": "sba", "explanation": "A firm primary canine beyond 14 years is a red flag. Palpation from 9 to 10 years and radiographic localisation are indicated. (Companion Ch 12; Hbk 20.4)", "answerPage": 220, "block": "T"}, {"n": 721, "page": 131, "stem": "Which is the correct first step in the five-step interceptive triage?", "options": ["Choose the appliance", "Ask whether there is a problem at all, or whether this is normal development", "Take a lateral cephalogram", "Refer to a specialist", "Extract the primary canines"], "key": "B", "type": "sba", "explanation": "The triage begins by asking whether this is a problem at all, since transient lower incisor crowding, a midline diastema and the ugly duckling stage are all normal. (Proffit Ch 12; Hbk 20.1)", "answerPage": 220, "block": "T"}, {"n": 722, "page": 132, "stem": "In a Class I malocclusion, which statement is correct?", "options": ["The skeletal base is the principal problem", "Surgery is frequently required", "Growth modification is always indicated", "The skeletal base is not the problem, so the problem is space, transverse or vertical", "Extraction is always required"], "key": "D", "type": "sba", "explanation": "In Class I the base is not the problem, so the diagnosis must specify whether the problem is space, transverse or vertical. (Cobourne cases; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 723, "page": 132, "stem": "A midline diastema in a 9-year-old with unerupted canines is best managed how?", "options": ["Reassurance and review, since it usually closes as the canines erupt", "Immediate closure with a fixed appliance", "Frenectomy", "Extraction of the primary canines", "Bonded retainer placement"], "key": "A", "type": "sba", "explanation": "A midline diastema is normal in the mixed dentition, the so-called ugly duckling stage, and usually closes as the canines erupt. (Companion Ch 12; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 724, "page": 132, "stem": "Which investigation should precede attributing a persistent midline diastema to a prominent fraenum?", "options": ["A lateral cephalogram", "A CBCT", "An occlusal or periapical radiograph to exclude a midline supernumerary", "A study cast analysis", "A blanching test alone"], "key": "C", "type": "sba", "explanation": "A midline supernumerary must be excluded radiographically before the diastema is attributed to the fraenum. (Companion Ch 12; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 725, "page": 132, "stem": "Which single feature most reliably indicates that retraction will improve the profile in bimaxillary protrusion?", "options": ["An obtuse nasolabial angle", "An increased lower face height", "A Class II molar relationship", "A deep overbite", "An acute nasolabial angle with lip procumbency and strain on closure"], "key": "E", "type": "sba", "explanation": "An acute nasolabial angle with lip procumbency and strain on closure means retraction is likely to help. An obtuse angle means it will harm. (Mosby ch. on space analysis; Hbk 21.2)", "answerPage": 221, "block": "U"}, {"n": 726, "page": 132, "stem": "Bimaxillary protrusion is significantly more common in which populations?", "options": ["African and East Asian", "Northern European", "South American only", "Middle Eastern only", "It shows no population variation"], "key": "A", "type": "sba", "explanation": "Bimaxillary protrusion is much commoner in patients of African and East Asian descent, and Caucasian cephalometric norms should not be applied uncritically. (Companion Ch 13; Hbk 21.2)", "answerPage": 221, "block": "U"}, {"n": 727, "page": 132, "stem": "Which is the usual treatment plan for a significant bimaxillary protrusion?", "options": ["Non-extraction alignment", "Four second premolar extractions with minimum anchorage", "Four first premolar extractions with maximum anchorage and bodily retraction of the labial segments", "Expansion", "Distalisation with headgear alone"], "key": "C", "type": "sba", "explanation": "Four first premolar extractions with maximum anchorage, using TADs, headgear or a stabilising arch, with bodily retraction, is the usual plan. (Companion Ch 13; Hbk 21.2)", "answerPage": 221, "block": "U"}, {"n": 728, "page": 133, "stem": "The evidence associates gingival recession most strongly with which movement?", "options": ["Proclination in a low-angle patient", "Expansion of the maxilla", "Intrusion of the lower incisors", "Extrusion of the molars", "Retroclination in a high-angle Class III patient with a narrow symphysis and a thin biotype"], "key": "E", "type": "sba", "explanation": "Joss-Vassalli, Aziz and Tepedino associate recession more with retroclination in highangle cases with a narrow symphysis and thin biotype than with proclination. (Joss-Vassalli 2010; Hbk 21.2 and 29.2)", "answerPage": 221, "block": "U"}, {"n": 729, "page": 133, "stem": "Which assessment should precede planning significant incisor retraction in a bimaxillary protrusion?", "options": ["Bracket prescription selection", "Assessment of gingival biotype and symphyseal width, considering CBCT of the symphysis", "Selection of the archwire sequence", "Selection of the retention regimen", "Assessment of the third molars"], "key": "B", "type": "sba", "explanation": "Biotype and symphyseal width must be assessed before planning, since they determine whether the retraction can be delivered safely. (Nanda; Hbk 21.2)", "answerPage": 221, "block": "U"}, {"n": 730, "page": 133, "stem": "Which surgical option is available for a severe skeletal bimaxillary protrusion?", "options": ["Le Fort I advancement", "Genioplasty alone", "Bilateral sagittal split advancement", "Anterior segmental osteotomies, or a two-jaw procedure with setback", "Surgically assisted rapid palatal expansion"], "key": "D", "type": "sba", "explanation": "Anterior segmental osteotomies, described by Wunderer and Kole, or a two-jaw procedure with setback, are the surgical options. (Proffit Ch 19; Hbk 21.2 and 27.3)", "answerPage": 221, "block": "U"}, {"n": 731, "page": 133, "stem": "Which single element should drive the decision in a bimaxillary protrusion?", "options": ["The incisor angle in isolation", "The molar relationship", "The lips at rest and on smiling, the nasolabial angle, and the periodontal support", "The overbite", "The arch form"], "key": "C", "type": "sba", "explanation": "The decision is driven by the soft tissue and the periodontium, not by the cephalometric angle alone. (Nanda; Hbk 21.2)", "answerPage": 221, "block": "U"}, {"n": 732, "page": 133, "stem": "Generalised spacing in a Class I adult with small teeth is best managed how?", "options": ["Closure and permanent retention, or redistribution and restorative build-up", "Extraction of premolars", "Expansion", "Distalisation", "No treatment in any case"], "key": "A", "type": "sba", "explanation": "Generalised spacing from tooth-size discrepancy is managed by closure with permanent retention, or by redistribution and restoration, depending on the Bolton discrepancy. (Cobourne cases; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 733, "page": 133, "stem": "Which single feature makes a Class I crowded case suitable for non-extraction management?", "options": ["Crowding of 9 mm", "A thin mandibular symphysis", "A deep overbite", "A Class II molar relationship", "Crowding of 3 to 4 mm with an obtuse nasolabial angle and a flat profile"], "key": "E", "type": "sba", "explanation": "Mild crowding with an obtuse nasolabial angle and a flat profile is better managed without extraction, since retraction would harm the face. (Mosby ch. on space analysis; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 734, "page": 133, "stem": "In a Class I case with 8 mm of crowding in both arches, which extraction pattern maintains the buccal segment relationship?", "options": ["Upper first and lower second premolars", "Upper first premolars only", "Upper second and lower first premolars", "Corresponding premolars in both arches", "Second permanent molars"], "key": "D", "type": "sba", "explanation": "Corresponding premolar extraction in both arches maintains the Class I buccal segment relationship. (Companion Ch 8; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 735, "page": 134, "stem": "Which single statement about the periodontal management of a bimaxillary protrusion case is correct?", "options": ["Periodontal referral should follow debond", "A periodontist should be involved early, with light forces, bodily movement and consideration of grafting", "Periodontal assessment is unnecessary in young patients", "Recession cannot be prevented", "Retraction should always be avoided"], "key": "B", "type": "sba", "explanation": "Early periodontal involvement, light bodily forces, avoidance of over-retraction and consideration of soft tissue grafting are the recognised strategies. (Nanda; Hbk 21.2)", "answerPage": 221, "block": "U"}, {"n": 736, "page": 134, "stem": "Which movement should be used to retract the labial segments in a bimaxillary protrusion?", "options": ["Uncontrolled tipping", "Intrusion alone", "Extrusion", "Pure rotation", "Bodily movement, with a high moment-to-force ratio"], "key": "E", "type": "sba", "explanation": "Bodily movement is required, both for the aesthetic result and to protect the periodontium. Tipping concentrates stress at the crest and apex. (Nanda; Hbk 14.2 and 21.2)", "answerPage": 221, "block": "U"}, {"n": 737, "page": 134, "stem": "Which is the correct sequence when a persistent midline diastema requires both closure and a frenectomy?", "options": ["Frenectomy, then closure", "Closure, then frenectomy before appliance removal", "Frenectomy after debond", "Both simultaneously at bond-up", "Neither is required"], "key": "B", "type": "sba", "explanation": "A frenectomy performed before closure leaves scar tissue that resists closure. Perform it before appliance removal, and retain permanently. (Cobourne cases; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 738, "page": 134, "stem": "Which single feature would make canine substitution for a missing lateral incisor inadvisable?", "options": ["A Class II molar relationship", "A well-aligned lower arch", "A spaced upper arch", "A high smile line with a dark, large and prominent canine", "A young patient"], "key": "D", "type": "sba", "explanation": "Canine substitution is inadvisable where the canine is dark, large or prominent and the smile line is high. It is favoured in Class II molar cases where the lower arch needs no space. (Mosby ch. on hypodontia; Hbk 21.1 and Part 3 Drill 5)", "answerPage": 221, "block": "U"}, {"n": 739, "page": 134, "stem": "Canine substitution for a missing lateral incisor requires the case to finish in which molar relationship?", "options": ["Class II", "Class I", "Class III", "Any relationship", "A cusp-to-cusp relationship"], "key": "A", "type": "sba", "explanation": "Closing the lateral incisor space by protracting the buccal segments finishes the case to a Class II molar relationship, which must be a deliberate choice. (Mosby ch. on hypodontia; Hbk 21.1)", "answerPage": 221, "block": "U"}, {"n": 740, "page": 134, "stem": "Which additional procedures are usually required when substituting a canine for a lateral incisor?", "options": ["None", "Root canal treatment of the canine", "Recontouring and often composite build-up, gingival recontouring of the canine zenith, and palatal root torque on the canine", "Extraction of the first premolar", "Surgical repositioning"], "key": "C", "type": "sba", "explanation": "Recontouring, build-up, gingival recontouring and palatal root torque are all required so that the canine presents a flatter surface in a lateral incisor position. (Mosby ch. on hypodontia; Hbk 21.1)", "answerPage": 222, "block": "U"}, {"n": 741, "page": 135, "stem": "Which retention regimen applies while awaiting a definitive restoration in a space-opening case?", "options": ["Night-time wear only", "Bonded retention alone", "No retention", "Full-time retention until the definitive restoration is placed", "Six weeks of retention"], "key": "D", "type": "sba", "explanation": "Retention is full-time until the definitive restoration is placed, and a bonded retainer thereafter. (Mosby ch. on hypodontia; Hbk 21.1)", "answerPage": 222, "block": "U"}, {"n": 742, "page": 135, "stem": "The soft tissue response of 0.7 mm of lip retraction per 1 mm of incisor retraction is most relevant in which case type?", "options": ["Class III camouflage", "Bimaxillary protrusion", "Anterior open bite", "Deep overbite", "Transverse discrepancy"], "key": "B", "type": "sba", "explanation": "The Konstantonis figures are most directly applied in bimaxillary protrusion, where the whole plan is driven by the intended lip change. (Konstantonis 2018; Hbk 21.2)", "answerPage": 222, "block": "U"}, {"n": 743, "page": 135, "stem": "Which single statement about Class I malocclusion and the lower labial segment is correct?", "options": ["The lower labial segment can be freely repositioned", "The lower labial segment should always be retroclined", "The lower labial segment should always be proclined", "The lower labial segment position is irrelevant in Class I", "The lower labial segment is the fixed point around which the plan is built"], "key": "E", "type": "sba", "explanation": "The lower labial segment position is the fixed point the plan is built around, because it is the least amenable to stable change. (Cobourne cases; Hbk 21.1)", "answerPage": 222, "block": "U"}, {"n": 744, "page": 135, "stem": "A Class I case presents with a displaced upper lateral incisor in crossbite with a displacement on closing. What is the priority?", "options": ["Correct the crossbite, since a displacement causes attrition and recession", "Align the arches first and correct the crossbite last", "Refer for surgical assessment", "Extract the lateral incisor", "Observe until growth is complete"], "key": "A", "type": "sba", "explanation": "A crossbite with a displacement is treated on diagnosis, and correction is self-retaining if a positive overbite results. (Companion Ch 12; Hbk 24.3)", "answerPage": 222, "block": "U"}, {"n": 745, "page": 135, "stem": "Which anchorage arrangement is required in a maximum anchorage bimaxillary protrusion case?", "options": ["Reciprocal anchorage", "Minimum anchorage", "Skeletal anchorage, headgear or a stabilising arch, with lacebacks during levelling", "A lower lingual arch alone", "A transpalatal arch alone"], "key": "C", "type": "sba", "explanation": "Maximum anchorage requires reinforcement, and where the case needs 100 per cent of the space for the anterior teeth, only bone will do. (Nanda; Hbk 14.4 and 21.2)", "answerPage": 222, "block": "U"}, {"n": 746, "page": 135, "stem": "Which single statement about treating bimaxillary protrusion in an adult with a thin symphysis is correct?", "options": ["Retraction should proceed as planned regardless", "The symphyseal morphology may limit the retraction achievable safely, and this changes the plan before treatment begins", "A CBCT is never justified", "Recession is unavoidable", "Surgery is always required"], "key": "B", "type": "sba", "explanation": "If the symphysis and biotype will not tolerate the retraction required, that changes the plan before a single bracket is chosen. (Nanda; Hbk 21.2)", "answerPage": 222, "block": "U"}, {"n": 747, "page": 136, "stem": "Class II malocclusion most commonly arises from which skeletal component?", "options": ["Maxillary excess", "Transverse maxillary deficiency", "Vertical maxillary excess", "Mandibular retrognathia", "Cranial base shortening"], "key": "D", "type": "sba", "explanation": "Class II is most often due to mandibular retrognathia, although the responsible jaw must be established in each case before planning. (Cobourne cases; Hbk 22.1)", "answerPage": 222, "block": "V"}, {"n": 748, "page": 136, "stem": "Which single variable should choose the appliance in Class II treatment?", "options": ["The vertical dimension", "The anteroposterior discrepancy", "The overjet magnitude", "The patient’s age alone", "The molar relationship"], "key": "A", "type": "sba", "explanation": "The appliance is chosen from the vertical dimension: cervical pull for the hypodivergent, high pull or occipital for the hyperdivergent. (Mosby ch. on Class II; Hbk 22.1)", "answerPage": 222, "block": "V"}, {"n": 749, "page": 136, "stem": "The randomised trials of early Class II treatment showed which single benefit?", "options": ["Improved final skeletal outcome", "Improved final occlusal outcome", "Reduction in incisor trauma", "Shorter overall treatment", "Fewer total appointments"], "key": "C", "type": "sba", "explanation": "The only durable benefit was a reduction in incisor trauma, with a relative risk of 0.58, a 42 per cent reduction, though with wide confidence intervals. (Cobourne 2022; Hbk 22.2)", "answerPage": 222, "block": "V"}, {"n": 750, "page": 136, "stem": "Which caveat should accompany the trauma-reduction argument for early Class II treatment?", "options": ["Trauma is rare in children", "Headgear was less effective than a functional appliance", "Trauma affects only girls", "The relative risk is above 1", "Much incisor trauma occurs before age 9, so even early treatment may come too late"], "key": "E", "type": "sba", "explanation": "Much trauma occurs before age 9, and headgear was marginally more effective than a functional appliance at reducing it. (Cobourne 2022; Kallunki 2021; Hbk 22.2)", "answerPage": 222, "block": "V"}, {"n": 751, "page": 136, "stem": "O’Brien’s 2009 trial reported which finding about the late-treated group?", "options": ["They had a slightly better final occlusal result", "They had a worse final occlusal result", "They had more attendances", "They had a longer overall treatment", "They required surgery more often"], "key": "A", "type": "sba", "explanation": "The late-treated group had a slightly better final occlusal result, and early-treated children had more attendances and longer treatment. (O’Brien 2009; Hbk 22.2)", "answerPage": 222, "block": "V"}, {"n": 752, "page": 136, "stem": "Which patients should be treated early for Class II?", "options": ["All patients with an overjet above 6 mm", "All patients in the mixed dentition", "Children at high risk of trauma, with a very large overjet, vertical excess and incompetent lips, or where there is significant teasing", "All patients with a Class II skeletal base", "No patients under any circumstances"], "key": "C", "type": "sba", "explanation": "The pragmatic policy is to treat early only for trauma risk or significant teasing, and otherwise to treat in a single phase in the late mixed or early permanent dentition. (O’Brien 2009; Hbk 22.2)", "answerPage": 222, "block": "V"}, {"n": 753, "page": 137, "stem": "Lateral open bites developing during twin block treatment should be regarded in which way?", "options": ["As a complication requiring abandonment", "As a sign of condylar resorption", "As evidence of poor compliance", "As an indication for extraction", "As expected, because overjet reduction outpaces overbite reduction"], "key": "E", "type": "sba", "explanation": "Overjet reduction outpaces overbite reduction, so lateral open bites are expected and are managed by trimming the blocks. (Cobourne cases; Hbk 22.3)", "answerPage": 222, "block": "V"}, {"n": 754, "page": 137, "stem": "In a hyperdivergent Class II patient, which mechanics should be avoided?", "options": ["High-pull headgear", "Anything extrusive, including cervical headgear, Class II elastics and buccal segment extrusion", "Molar intrusion", "Skeletal anchorage", "Extraction"], "key": "B", "type": "sba", "explanation": "In a high-angle patient the mandible rotates down and back at the slightest provocation, so extrusive mechanics must be avoided. (Companion Ch 13; Hbk 22.4)", "answerPage": 222, "block": "V"}, {"n": 755, "page": 137, "stem": "In a hypodivergent Class II patient with a deep overbite, which manoeuvre is appropriate in a grower?", "options": ["True incisor intrusion with miniscrews", "Proclination of the upper incisors only", "Molar intrusion with TADs", "Levelling by relative intrusion, allowing buccal segment extrusion", "Class III elastics"], "key": "D", "type": "sba", "explanation": "In a growing patient, buccal segment extrusion produces relative incisor intrusion and is stable because condylar growth compensates. (Companion Ch 13; Hbk 22.4 and 25.1)", "answerPage": 222, "block": "V"}, {"n": 756, "page": 137, "stem": "The mechanical difficulty in Class II division 2 is which of the following?", "options": ["An excessive overjet", "A transverse discrepancy", "An increased interincisal angle with a deep, complete overbite", "An anterior open bite", "Severe crowding"], "key": "C", "type": "sba", "explanation": "The increased interincisal angle with a deep complete overbite is the mechanical difficulty. Retroclined upper centrals must be torqued labially at the root, not merely tipped. (Companion Ch 13; Hbk 22.4)", "answerPage": 222, "block": "V"}, {"n": 757, "page": 137, "stem": "Which sequence is correct in Class II division 2 treatment?", "options": ["Procline the upper labial segment to convert to a division 1 pattern, reduce the overbite, then retract if space has been created", "Retract, then procline, then reduce the overbite", "Reduce the overbite, then extract, then procline", "Extract first, then reduce the overbite", "Retract first, then torque"], "key": "A", "type": "sba", "explanation": "Proclination converts the case to a division 1 pattern, allowing overbite reduction and then retraction if space is available. (Companion Ch 13; Hbk 22.4)", "answerPage": 222, "block": "V"}, {"n": 758, "page": 137, "stem": "Why are many Class II division 2 cases treated non-extraction in the upper arch?", "options": ["Because the overbite prevents extraction", "Because the molars are Class I", "Because anchorage is always maximum", "Because the canines are always crowded", "Because there is often little or no overjet, so extraction space in the upper arch has nowhere to go"], "key": "E", "type": "sba", "explanation": "Where there is little overjet there is nowhere for upper extraction space to go, so many division 2 cases are treated non-extraction in the upper arch. (Companion Ch 13; Hbk 22.4)", "answerPage": 223, "block": "V"}, {"n": 759, "page": 137, "stem": "Which bracket prescription feature is required for the upper central incisors in Class II division 2?", "options": ["Increased labial root torque", "Reduced in and out", "Increased mesial tip", "Extra palatal root torque", "Zero torque"], "key": "D", "type": "sba", "explanation": "Extra palatal root torque is required on the upper centrals so that the roots are moved labially and the overbite can be held. (Companion Ch 13; Hbk 22.4)", "answerPage": 223, "block": "V"}, {"n": 760, "page": 138, "stem": "Which retainer is classically used to hold a corrected deep overbite?", "options": ["A vacuum-formed retainer", "A Hawley retainer with an anterior bite plane, worn long-term", "A bonded retainer alone", "A positioner", "A Begg wrap-around retainer"], "key": "B", "type": "sba", "explanation": "A Hawley retainer with an anterior bite plane, worn into the early twenties, is the classical answer for deep bite retention. (Mosby ch. on retention; Hbk 22.4 and 25.3)", "answerPage": 223, "block": "V"}, {"n": 761, "page": 138, "stem": "Which is Proffit’s threshold overjet above which surgery rather than camouflage is indicated in Class II?", "options": ["6 mm", "8 mm", "20 mm", "14 mm", "10 mm"], "key": "E", "type": "sba", "explanation": "An overjet greater than 10 mm is one of Proffit’s four cephalometric thresholds favouring surgery in Class II. (Proffit 1992; Hbk 22.5)", "answerPage": 223, "block": "V"}, {"n": 762, "page": 138, "stem": "Which mandibular body length favours surgery in Class II?", "options": ["Less than 80 mm", "Less than 70 mm", "Less than 90 mm", "More than 70 mm", "Mandibular body length is not used"], "key": "B", "type": "sba", "explanation": "A mandibular body length of less than 70 mm is one of Proffit’s thresholds. (Proffit 1992; Hbk 22.5)", "answerPage": 223, "block": "V"}, {"n": 763, "page": 138, "stem": "Which anterior face height favours surgery in Class II?", "options": ["Greater than 105 mm", "Greater than 115 mm", "Greater than 145 mm", "Greater than 125 mm", "Anterior face height is not used"], "key": "D", "type": "sba", "explanation": "An anterior face height greater than 125 mm is one of Proffit’s four thresholds. (Proffit 1992; Hbk 22.5)", "answerPage": 223, "block": "V"}, {"n": 764, "page": 138, "stem": "Which surgical procedure is usually performed for mandibular advancement?", "options": ["Bilateral sagittal split osteotomy", "Le Fort I osteotomy", "Vertical subsigmoid osteotomy", "Genioplasty alone", "Surgically assisted rapid palatal expansion"], "key": "A", "type": "sba", "explanation": "The bilateral sagittal split osteotomy is the standard mandibular advancement, with a recognised risk to the inferior alveolar nerve. (Proffit Ch 19; Hbk 22.5 and 27.3)", "answerPage": 223, "block": "V"}, {"n": 765, "page": 138, "stem": "Which is added to a mandibular advancement where there is vertical maxillary excess and a gummy smile?", "options": ["A genioplasty alone", "Surgically assisted rapid palatal expansion", "A Le Fort I impaction", "A vertical subsigmoid osteotomy", "Distraction osteogenesis"], "key": "C", "type": "sba", "explanation": "Le Fort I impaction corrects vertical maxillary excess and produces autorotation of the mandible. (Proffit Ch 19; Hbk 22.5 and 27.3)", "answerPage": 223, "block": "V"}, {"n": 766, "page": 139, "stem": "Pre-surgical orthodontics in a Class II case has which effect on the overjet?", "options": ["It reduces it", "It reverses it", "It has no effect", "It increases it, because decompensation removes the dental compensation", "It corrects the molar relationship"], "key": "D", "type": "sba", "explanation": "Decompensation deliberately makes the bite worse before surgery. Calling this aligning the arches is one of the costly slips. (Proffit Ch 19; Hbk 22.5 and 27.2)", "answerPage": 223, "block": "V"}, {"n": 767, "page": 139, "stem": "Which is the correct approach to a Class II patient who develops temporomandibular symptoms during treatment?", "options": ["Complete treatment as planned", "Pause active mechanics, counsel on natural history, and manage conservatively and reversibly", "Perform an occlusal adjustment", "Refer for surgery", "Debond immediately and discharge"], "key": "B", "type": "sba", "explanation": "Kandasamy’s guidance is to screen and document before treatment, counsel on natural history, suspend active mechanics if symptoms appear, and manage conservatively. (Kandasamy 2022; Hbk 22.6 and 26.2)", "answerPage": 223, "block": "V"}, {"n": 768, "page": 139, "stem": "What proportion of Caucasians have a Class II malocclusion, in the range usually quoted for adolescents?", "options": ["5 to 8 per cent", "Over 60 per cent", "30 to 40 per cent", "45 to 55 per cent", "15 to 27 per cent"], "key": "E", "type": "sba", "explanation": "Figures of 15 to 22 per cent for United States adolescents and up to 27 per cent in wider Caucasian samples are quoted. (Cobourne cases; Hbk 22.1)", "answerPage": 223, "block": "V"}, {"n": 769, "page": 139, "stem": "Which is the correct force and duration for headgear used for distalisation or an orthopaedic effect?", "options": ["450 to 500 g per side for 14 hours per day", "250 g per side for 10 hours per day", "150 g per side for 8 hours per day", "700 g per side for 6 hours per day", "100 g per side for 24 hours per day"], "key": "A", "type": "sba", "explanation": "Distalisation or an orthopaedic effect requires 450 to 500 g per side for 14 hours per day; anchorage support requires 250 to 350 g for 10 to 12 hours. (Companion Ch 6; Hbk 22.3)", "answerPage": 223, "block": "V"}, {"n": 770, "page": 139, "stem": "Molar distalisation corrects which type of Class II relationship?", "options": ["A skeletal Class II", "Any Class II", "A dentoalveolar Class II only", "A Class II with a vertical excess", "A Class II with a transverse deficiency"], "key": "C", "type": "sba", "explanation": "Distalisation corrects a dentoalveolar Class II only, and always buys reciprocal mesial premolar movement unless a TAD is used. (Nanda; Hbk 22.3)", "answerPage": 223, "block": "V"}, {"n": 771, "page": 139, "stem": "What distal force is appropriate for molar distalisation?", "options": ["50 g", "150 to 250 g", "400 g", "600 g", "Over 800 g"], "key": "B", "type": "sba", "explanation": "Nanda gives a distal molar force of 150 to 250 g, with molar derotation alone gaining 2 to 3 mm per side. (Nanda; Hbk 22.3)", "answerPage": 223, "block": "V"}, {"n": 772, "page": 139, "stem": "Molar derotation alone can gain approximately how much space per side?", "options": ["0.5 mm", "8 mm", "5 mm", "2 to 3 mm", "None"], "key": "D", "type": "sba", "explanation": "Derotation of a mesially rotated maxillary first molar can gain 2 to 3 mm of arch length per side. (Nanda; Hbk 22.3)", "answerPage": 223, "block": "V"}, {"n": 773, "page": 140, "stem": "Which single statement about transitioning from a functional appliance to a fixed appliance is correct?", "options": ["Overcorrect, then transition carefully, since the correction relapses if the posterior open bite is not settled", "The functional appliance can be abandoned as soon as the overjet is corrected", "Fixed appliances should be placed at the same time as the functional appliance", "The posterior open bite always resolves spontaneously without attention", "Retention is unnecessary after functional appliance therapy"], "key": "A", "type": "sba", "explanation": "Overcorrection and careful transition are required, either directly into a fixed appliance or with a period of night-time functional appliance wear. (Cobourne cases; Hbk 22.3)", "answerPage": 223, "block": "V"}, {"n": 774, "page": 140, "stem": "Which cephalometric measurement is used with pogonion in Proffit’s Class II surgical thresholds?", "options": ["The Frankfort plane", "The sella-nasion plane", "The nasion perpendicular", "The occlusal plane", "The mandibular plane"], "key": "C", "type": "sba", "explanation": "Pogonion to the nasion perpendicular of 18 mm or more is one of Proffit’s four thresholds. (Proffit 1992; Hbk 22.5)", "answerPage": 223, "block": "V"}, {"n": 775, "page": 140, "stem": "Which single feature of a Class II division 1 malocclusion perpetuates it?", "options": ["A deep overbite", "Crowding of the lower incisors", "A Class II molar relationship", "An increased lower face height", "A lower lip trap resting behind the upper incisors"], "key": "E", "type": "sba", "explanation": "The lip trap proclines the uppers and retroclines the lowers, perpetuating the malocclusion, and its elimination is one of the soft tissue effects of a functional appliance. (Companion Ch 12; Hbk 22.1)", "answerPage": 223, "block": "V"}, {"n": 776, "page": 140, "stem": "Which is the correct extraction pattern for a Class II case requiring maximum upper retraction and with mild lower crowding?", "options": ["Upper first premolars and lower second premolars", "Four first premolars", "Upper second premolars and lower first premolars", "Lower first premolars only", "Upper second molars"], "key": "A", "type": "sba", "explanation": "Class II requires extraction further back in the mandible, giving a greater maxillary space requirement to retract the upper labial segment. (Companion Ch 8; Hbk 22.4)", "answerPage": 223, "block": "V"}, {"n": 777, "page": 140, "stem": "Which single statement about the Class II division 2 lateral incisors is correct?", "options": ["They are retroclined with the centrals", "They are usually absent", "They are frequently proclined and mesiolabially rotated", "They are usually in crossbite", "They require no correction"], "key": "C", "type": "sba", "explanation": "The laterals are frequently proclined and mesiolabially rotated, requiring first and second order correction. (Companion Ch 2; Hbk 22.4)", "answerPage": 223, "block": "V"}, {"n": 778, "page": 140, "stem": "In a Class II patient with an increased lower face height, which extraction strategy may assist?", "options": ["Extraction of lower incisors", "Extraction to allow the mandible to rotate backwards", "Non-extraction with expansion", "Extraction of second molars only", "Extraction to allow the mandible to rotate forwards"], "key": "E", "type": "sba", "explanation": "In a high-angle case, extraction may allow the mandible to rotate forwards, reducing face height and improving the anteroposterior relationship. (Companion Ch 13; Hbk 22.4)", "answerPage": 224, "block": "V"}, {"n": 779, "page": 141, "stem": "Which single risk should be quoted at consent for bilateral sagittal split osteotomy?", "options": ["Loss of vitality of the incisors", "Altered sensation in the distribution of the inferior alveolar nerve, commonly transient and occasionally permanent", "Ankylosis of the temporomandibular joint", "Loss of the mandibular canine", "Failure of the maxillary graft"], "key": "B", "type": "sba", "explanation": "Inferior alveolar nerve injury is the risk to quote and consent for, together with relapse, infection, unfavourable split and condylar resorption. (Proffit Ch 19; Hbk 22.5 and 27.5)", "answerPage": 224, "block": "V"}, {"n": 780, "page": 141, "stem": "Which is the correct timing for functional appliance therapy in relation to skeletal maturation?", "options": ["CS1", "After growth is complete", "CS5", "CS2 to CS3, with the greatest response in the circumpubertal period", "Timing is immaterial"], "key": "D", "type": "sba", "explanation": "The greatest response occurs in the circumpubertal period, around CS3, with preparation from late CS2. (Baccetti; Hbk 22.3)", "answerPage": 224, "block": "V"}, {"n": 781, "page": 141, "stem": "Which is the correct approach when a Class II patient will not comply with a removable functional appliance?", "options": ["Abandon treatment", "Increase the prescribed wear time", "Consider a fixed functional appliance such as a Herbst, which does not depend on weartime compliance", "Extract four premolars immediately", "Refer for surgery"], "key": "C", "type": "sba", "explanation": "The Herbst is a fixed functional appliance with a 17 per cent failure rate against 37 per cent for the twin block, although it requires more visits. (Pacha 2023; Hbk 22.3)", "answerPage": 224, "block": "V"}, {"n": 782, "page": 141, "stem": "Which single statement about mandibular advancement surgery and stability is correct?", "options": ["It is very stable in the low- and average-angle patient", "It is the least stable of the common movements", "It is unstable in all patients", "Its stability depends only on the fixation used", "It is more stable than maxillary impaction"], "key": "A", "type": "sba", "explanation": "Mandibular advancement is very stable in the low- and average-angle patient. Maxillary down-grafting and surgical expansion are the least stable movements. (Proffit Ch 19; Hbk 27.4)", "answerPage": 224, "block": "V"}, {"n": 783, "page": 141, "stem": "A 9-year-old boy has an overjet of 12 mm, incompetent lips and vertical excess. Which single consideration most justifies early treatment?", "options": ["Improved final occlusal result", "Improved skeletal outcome", "Shorter overall treatment", "Fewer appointments", "Reduction in the risk of incisor trauma"], "key": "E", "type": "sba", "explanation": "Trauma reduction is the only durable benefit demonstrated, with a relative risk of 0.58, and is the accepted indication for early treatment. (Cobourne 2022; Hbk 22.2)", "answerPage": 224, "block": "V"}, {"n": 784, "page": 141, "stem": "Which single statement about promising TMD improvement from Class II correction is correct?", "options": ["It should be promised, since correction reliably improves symptoms", "It should be promised only in adults", "It should be promised only in division 2 cases", "It should not be promised, since there is no evidence that orthodontics reduces TMD signs or symptoms", "It should be promised only where a click is present"], "key": "D", "type": "sba", "explanation": "There is no evidence that orthodontic intervention reduces TMD signs and symptoms, and none that it causes them. (Macfarlane 2009; Luther 2010; Hbk 22.6)", "answerPage": 224, "block": "V"}, {"n": 785, "page": 142, "stem": "Which is the correct approach to documenting joint status in a Class II patient before treatment?", "options": ["No documentation is required", "Screen and document range of opening, deviation, joint sounds and tenderness before treatment begins", "Document only if the patient reports pain", "Refer all patients for MRI", "Document at debond only"], "key": "B", "type": "sba", "explanation": "Screening and documenting joint status before treatment is the recognised standard and protects both patient and clinician. (Kandasamy 2022; Hbk 22.6 and 26.3)", "answerPage": 224, "block": "V"}, {"n": 786, "page": 142, "stem": "Which single feature distinguishes a Class II division 2 face?", "options": ["An increased lower face height", "A prognathic mandible", "An anterior open bite", "A transverse maxillary deficiency", "A reduced lower face height with a forward mandibular growth rotation"], "key": "E", "type": "sba", "explanation": "Class II division 2 is characteristically associated with a reduced lower face height, a forward growth rotation, a high lower lip line and a deep overbite. (Companion Ch 2; Hbk 22.1)", "answerPage": 224, "block": "V"}, {"n": 787, "page": 143, "stem": "Which single fact makes Class III harder to manage than Class II?", "options": ["Class III is more common", "Residual mandibular growth helps in Class II and harms in Class III", "Class III patients are less compliant", "Class III cannot be camouflaged", "Class III has no skeletal component"], "key": "B", "type": "sba", "explanation": "Unfavourable growth persists in Class III. Residual mandibular growth assists correction in Class II and worsens the discrepancy in Class III. (Cobourne cases; Hbk 23.1)", "answerPage": 224, "block": "W"}, {"n": 788, "page": 143, "stem": "Before diagnosing a Class III malocclusion, which manoeuvre is essential?", "options": ["Taking a lateral cephalogram", "Taking a panoramic radiograph", "Measuring the overjet in intercuspal position", "Manipulating the mandible into centric relation", "Assessing the third molars"], "key": "D", "type": "sba", "explanation": "A pseudo-Class III manipulates back to an edge-to-edge incisor relationship in centric relation, and the prognosis is completely different. (Mosby ch. on Class III; Hbk 23.1)", "answerPage": 224, "block": "W"}, {"n": 789, "page": 143, "stem": "The characteristic dental compensation in Class III is which of the following?", "options": ["Upper incisors proclined, lower incisors retroclined", "Upper incisors retroclined, lower incisors proclined", "Both retroclined", "Both proclined", "No compensation occurs"], "key": "A", "type": "sba", "explanation": "Class III compensates by proclining the uppers and retroclining the lowers. The more compensated the case, the less room there is for camouflage. (Companion Ch 13; Hbk 23.1)", "answerPage": 224, "block": "W"}, {"n": 790, "page": 143, "stem": "Which finding in the mixed dentition favours early intervention in Class III?", "options": ["A reduced overbite", "Retroclined lower incisors", "An average or increased overbite with an anterior displacement on closing", "An increased lower face height", "Class III molars with no displacement"], "key": "C", "type": "sba", "explanation": "Favourable features are a mild skeletal base, average or reduced lower face height, average or increased overbite, little compensation and an anterior displacement on closing. (Companion Ch 8; Hbk 23.2)", "answerPage": 224, "block": "W"}, {"n": 791, "page": 143, "stem": "Which finding in the mixed dentition indicates monitoring rather than early intervention in Class III?", "options": ["An anterior displacement on closing", "An increased overbite", "A mild Class III skeletal base", "Retroclined lower incisors with proclined uppers and no displacement", "A reduced lower face height"], "key": "D", "type": "sba", "explanation": "Heavy compensation with no displacement, a moderate to severe skeletal base, increased lower face height and a reduced overbite are unfavourable features. (Companion Ch 8; Hbk 23.2)", "answerPage": 224, "block": "W"}, {"n": 792, "page": 143, "stem": "Facemask protraction therapy should ideally be started before which age?", "options": ["6 years", "10 years", "13 years", "16 years", "Age is immaterial"], "key": "B", "type": "sba", "explanation": "Facemask therapy is most effective before age 10. Bone-anchored maxillary protraction using Class III elastics to miniplates suits the 11 to 14 age range. (Mandall 2016; Hbk 23.3)", "answerPage": 224, "block": "W"}, {"n": 793, "page": 144, "stem": "Which is the correct daily wear time for a facemask?", "options": ["6 to 8 hours", "4 hours", "18 hours", "24 hours", "12 to 14 hours"], "key": "E", "type": "sba", "explanation": "Facemask therapy requires 12 to 14 hours per day, with an elastic force of approximately 400 g per side. (Companion Ch 9; Hbk 23.3)", "answerPage": 224, "block": "W"}, {"n": 794, "page": 144, "stem": "To what overjet should a Class III correction be overcorrected?", "options": ["Plus 3 to 4 mm", "Plus 1 mm", "0 mm", "Plus 8 mm", "Overcorrection is unnecessary"], "key": "A", "type": "sba", "explanation": "Overcorrection to a positive overjet of 3 to 4 mm is recommended, because relapse is expected as growth continues. (Mosby ch. on Class III; Hbk 23.3)", "answerPage": 224, "block": "W"}, {"n": 795, "page": 144, "stem": "Mandall reported what proportion of facemask-treated patients avoided surgery compared with untreated controls?", "options": ["Both groups 50 per cent", "36 per cent against 60 per cent", "Over 60 per cent against 36 per cent", "90 per cent against 70 per cent", "No difference"], "key": "C", "type": "sba", "explanation": "Over 60 per cent avoided surgery against 36 per cent without early treatment, although most of the initial skeletal effect is lost with growth. (Mandall 2016; Hbk 23.3)", "answerPage": 224, "block": "W"}, {"n": 796, "page": 144, "stem": "Proffit reports what proportion of facemask cases show recurrence of the anterior crossbite at 8 years?", "options": ["Under 5 per cent", "25 to 33 per cent", "10 per cent", "60 per cent", "90 per cent"], "key": "B", "type": "sba", "explanation": "Proffit reports 25 to 33 per cent recurrence at 8 years, mostly requiring surgery, which is the honest consent number. (Proffit Ch 13; Hbk 23.3)", "answerPage": 224, "block": "W"}, {"n": 797, "page": 144, "stem": "Bone-anchored maxillary protraction using Class III elastics to miniplates is suited to which age range?", "options": ["6 to 8 years", "8 to 10 years", "16 to 18 years", "11 to 14 years", "Adults only"], "key": "D", "type": "sba", "explanation": "Miniplate-anchored protraction works through the adolescent spurt at about half the force, and suits the 11 to 14 age range; facemask suits 8 to 10 years. (Proffit Ch 13; Hbk 23.3)", "answerPage": 225, "block": "W"}, {"n": 798, "page": 144, "stem": "A parent asks whether a chin cup will stop their child’s lower jaw growing forwards. Which reply is correct?", "options": ["That there is no agreement that it inhibits mandibular growth, and that it largely redirects the mandible downwards and backwards with no lasting gain", "That it reliably inhibits mandibular growth", "That it will shorten the mandible by 5 mm", "That it works only after the growth spurt", "That it is the treatment of choice for all Class III children"], "key": "A", "type": "sba", "explanation": "The chin cup’s short-term gain is not maintained after growth, and it increases face height by rotating the mandible down and back. (Nanda; Hbk 23.3)", "answerPage": 225, "block": "W"}, {"n": 799, "page": 144, "stem": "Which Wits appraisal value most strongly favours surgery in Class III?", "options": ["Minus 2 mm", "Minus 5 mm", "Minus 11 mm or worse", "Minus 8 mm", "Minus 1 mm"], "key": "C", "type": "sba", "explanation": "A Wits appraisal of minus 11 mm or worse is among the most important discriminators favouring surgery. (Kerr 1992; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 800, "page": 145, "stem": "Which ANB value forms part of the Class III surgical threshold set?", "options": ["Minus 1 degree", "ANB is not used", "Plus 2 degrees", "Minus 2 degrees", "Minus 4 degrees or worse"], "key": "E", "type": "sba", "explanation": "An ANB of minus 4 degrees or worse is one of the thresholds, alongside a Wits of minus 11 mm and a reverse overjet of minus 5 mm. (Kerr 1992; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 801, "page": 145, "stem": "Which gonial angle value forms part of the Class III surgical threshold set?", "options": ["120 degrees or less", "130 degrees or more", "110 degrees", "140 degrees", "Gonial angle is not used"], "key": "A", "type": "sba", "explanation": "A gonial angle of 120 degrees or less is one of the discriminant variables, with a lower anterior face height of 66 per cent or more. (Kerr 1992; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 802, "page": 145, "stem": "Which lower anterior face height proportion forms part of the Class III surgical threshold set?", "options": ["50 per cent or less", "55 per cent", "66 per cent or more", "60 per cent", "It is not used"], "key": "C", "type": "sba", "explanation": "A lower anterior face height of 66 per cent or more of total anterior face height is one of the discriminant variables. (Kerr 1992; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 803, "page": 145, "stem": "A Class III camouflage plan typically uses which extraction pattern?", "options": ["Upper first premolars and lower second premolars", "Upper first premolars only", "Four first premolars", "Four second premolars", "Upper second premolars and lower first premolars"], "key": "E", "type": "sba", "explanation": "Class III camouflage extracts further forward in the mandible, giving a greater mandibular space requirement to retract the lower labial segment. (Companion Ch 8; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 804, "page": 145, "stem": "Why should mandibular extractions be avoided in a Class III case where surgery is likely?", "options": ["They increase root resorption", "They consume the decompensation space the surgeon will need", "They cause anchorage loss", "They increase the overbite", "They prolong treatment"], "key": "B", "type": "sba", "explanation": "Mandibular extractions consume the space required for pre-surgical decompensation, which retroclines the lowers further. (Companion Ch 8; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 805, "page": 145, "stem": "Class III elastics should be avoided in which patient?", "options": ["A low-angle patient", "A patient with a deep overbite", "A growing patient", "A high-angle patient with an increased lower face height", "A patient with mild crowding"], "key": "D", "type": "sba", "explanation": "Class III elastics extrude the lower molars and rotate the mandible down and back, which is dangerous in a high-angle case. (Bennett and McLaughlin; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 806, "page": 145, "stem": "Pre-surgical orthodontics in a Class III case involves which movements?", "options": ["Proclining the uppers and retroclining the lowers", "Intruding the lowers only", "Retroclining the uppers and proclining the lowers, worsening the reverse overjet", "Expanding the mandible", "Levelling only"], "key": "C", "type": "sba", "explanation": "Decompensation reverses the natural compensation, retroclining the uppers and proclining the lowers, and makes the reverse overjet worse before surgery. (Proffit Ch 19; Hbk 23.4 and 27.2)", "answerPage": 225, "block": "W"}, {"n": 807, "page": 146, "stem": "When should orthognathic surgery be undertaken in a Class III patient?", "options": ["After growth is complete, confirmed by serial cephalometric superimposition", "At 14 years in girls and 16 in boys", "As soon as the diagnosis is made", "After the third molars erupt", "At 18 years in both sexes"], "key": "A", "type": "sba", "explanation": "Mandibular growth in Class III persists beyond adolescence and later in males, so surgery is deferred until serial superimposition confirms cessation. (Companion Ch 15; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 808, "page": 146, "stem": "Discriminant analysis of the Class III surgical threshold variables predicts the need for surgery with what accuracy?", "options": ["60 per cent", "75 per cent", "It cannot predict", "100 per cent", "Over 90 per cent"], "key": "E", "type": "sba", "explanation": "Kerr, Stellzig-Eisenhauer and Kochel reported over 90 per cent accuracy for discriminant analysis of these variables. (Kochel 2011; Hbk 23.4)", "answerPage": 225, "block": "W"}, {"n": 809, "page": 146, "stem": "Which population shows a markedly higher prevalence of Class III malocclusion?", "options": ["Northern European", "Indigenous Australian", "Sub-Saharan African", "East Asian", "South Asian"], "key": "D", "type": "sba", "explanation": "Class III prevalence is far higher in East Asian populations than the 5 to 6 per cent quoted for United States adolescents, with a worldwide figure of about 6.8 per cent. (Mosby ch. on classification; Hbk 23.1)", "answerPage": 225, "block": "W"}, {"n": 810, "page": 146, "stem": "Which single feature is characteristic of the Class III component in East Asian populations?", "options": ["Mandibular prognathism alone", "Maxillary retrusion is the more common component", "An anterior open bite in all cases", "A transverse deficiency in all cases", "A reduced lower face height"], "key": "B", "type": "sba", "explanation": "Maxillary retrusion is the commoner component in East Asian Class III, which is relevant to the choice between protraction and setback. (Mosby ch. on Class III; Hbk 23.1)", "answerPage": 225, "block": "W"}, {"n": 811, "page": 146, "stem": "An anterior crossbite in a 7-year-old with space available and a positive overbite anticipated corrects in approximately what period using an incline plane?", "options": ["It does not correct", "3 months", "6 months", "12 months", "3 to 4 weeks"], "key": "E", "type": "sba", "explanation": "An anterior crossbite corrects in 3 to 4 weeks with an incline plane, and a face mask corrects a dental crossbite in 1 to 3 months. (Nanda; Hbk 23.3)", "answerPage": 225, "block": "W"}, {"n": 812, "page": 146, "stem": "Which single family history feature is most relevant in Class III?", "options": ["A history of hypodontia", "A family history of Class III skeletal pattern", "A family history of caries", "A history of orthodontic treatment in a sibling", "A family history of periodontal disease"], "key": "B", "type": "sba", "explanation": "Class III has the strongest hereditary component of the three classes, so a family history should be taken specifically. (Proffit Ch 5; Hbk 23.1)", "answerPage": 225, "block": "W"}, {"n": 813, "page": 146, "stem": "Which is the correct approach to parents requesting immediate treatment of a Class III crossbite in a 7-year-old?", "options": ["Treat all cases immediately with a facemask", "Refer for immediate surgical assessment", "Refuse all treatment until 16 years", "Distinguish an anterior crossbite with a displacement, which is treated on diagnosis, from a skeletal Class III, where early treatment buys a 60 versus 36 per cent chance of avoiding surgery but most skeletal effect is lost", "Extract the lower incisors"], "key": "D", "type": "sba", "explanation": "The two must be separated: the displacement is treated now; the skeletal problem requires a discussion of what early treatment can and cannot achieve. (Mandall 2016; Hbk 23.3)", "answerPage": 225, "block": "W"}, {"n": 814, "page": 147, "stem": "Which single statement about rapid maxillary expansion combined with facemask therapy is correct?", "options": ["It may be used to disarticulate the maxilla and improve protraction", "It is contraindicated", "It replaces the facemask", "It prevents relapse entirely", "It is used only in adults"], "key": "A", "type": "sba", "explanation": "Rapid maxillary expansion may be used to disarticulate the maxilla and improve the response to protraction. (Companion Ch 9; Hbk 23.3)", "answerPage": 225, "block": "W"}, {"n": 815, "page": 147, "stem": "Which single statement about lower incisor extraction in Class III camouflage is correct?", "options": ["It is the first-line approach in all cases", "It is contraindicated in all cases", "It is occasionally used in a mild non-growing case, at the cost of a tooth-size discrepancy and a deepened overbite", "It creates 8 mm of space", "It improves the profile reliably"], "key": "C", "type": "sba", "explanation": "A single lower incisor extraction is occasionally used in mild Class III camouflage in a non-growing patient, with recognised costs. (Companion Ch 8; Hbk 13.4 and 23.4)", "answerPage": 225, "block": "W"}, {"n": 816, "page": 147, "stem": "A Class III patient with a reverse overjet of 4 mm, ANB of minus 5 degrees, Wits of minus 8 mm, lower incisors at 82 degrees and a chief complaint about the profile is best managed how?", "options": ["Camouflage with lower incisor extraction", "Facemask therapy", "Observation only", "Combined orthodontic and orthognathic treatment, with camouflage offered honestly and its limitations stated", "Rapid maxillary expansion alone"], "key": "D", "type": "sba", "explanation": "The existing decompensation leaves little room for camouflage, and the complaint concerns the profile, which camouflage cannot change. (Kerr 1992; Hbk Part 3 Drill 3)", "answerPage": 225, "block": "W"}, {"n": 817, "page": 148, "stem": "A unilateral posterior crossbite with a mandibular displacement most commonly represents which underlying problem?", "options": ["A true unilateral maxillary deficiency", "A bilateral maxillary constriction that the patient closes out of", "A mandibular asymmetry", "A dental crossbite of one tooth", "A vertical discrepancy"], "key": "B", "type": "sba", "explanation": "A displacement indicates a bilateral constriction with a lateral shift into a unilateral crossbite in intercuspation. (Companion Ch 12; Hbk 24.1)", "answerPage": 226, "block": "X"}, {"n": 818, "page": 148, "stem": "Which single finding determines the urgency of treating a posterior crossbite?", "options": ["The number of teeth involved", "The molar relationship", "The patient’s age", "The overbite", "The presence of a mandibular displacement"], "key": "E", "type": "sba", "explanation": "A crossbite with a displacement is treated on diagnosis; one without a displacement is treated when convenient within the overall plan. (Ugolini 2021; Hbk 24.1)", "answerPage": 226, "block": "X"}, {"n": 819, "page": 148, "stem": "Which appliance did Cochrane evidence favour for crossbite correction at ages 7 to 11?", "options": ["A quadhelix", "A removable expansion plate", "A rapid maxillary expander", "A transpalatal arch", "A twin block"], "key": "A", "type": "sba", "explanation": "Ugolini found high-certainty evidence that a quadhelix or expansion plate beats observation, that the quadhelix beats a plate, and that it is about 3 months faster. (Ugolini 2021; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 820, "page": 148, "stem": "Rapid maxillary expansion achieves approximately what proportion of the screw expansion at the suture?", "options": ["10 per cent", "25 per cent", "50 per cent", "85 per cent", "100 per cent"], "key": "C", "type": "sba", "explanation": "Rapid maxillary expansion achieves up to 4 mm at the suture, approximately 50 per cent of total screw expansion. (Liu 2015; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 821, "page": 148, "stem": "What proportion of the skeletal change achieved by rapid maxillary expansion relapses at 4 to 8 months?", "options": ["Approximately 2 per cent", "Approximately 10 per cent", "Approximately 30 per cent", "Approximately 60 per cent", "None"], "key": "B", "type": "sba", "explanation": "Approximately 10 per cent of the skeletal change relapses at 4 to 8 months post-retention. (Lo Giudice 2020; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 822, "page": 148, "stem": "What proportion of initial dental expansion is maintained with slow maxillary expansion compared with rapid expansion?", "options": ["Both 70 per cent", "85 per cent with slow and 95 per cent with rapid", "Both 90 per cent", "95 per cent with slow and 85 per cent with rapid", "Neither is maintained"], "key": "D", "type": "sba", "explanation": "Slow expansion retains approximately 95 per cent of the initial expansion against 85 per cent for rapid expansion, which produces slightly greater posterior skeletal expansion but more buccal tipping and more pain. (Bucci 2016; Rutili 2021; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 823, "page": 149, "stem": "Beyond approximately how much required expansion in a non-growing patient is surgically assisted expansion indicated?", "options": ["5 mm", "2 mm", "10 mm", "15 mm", "Surgery is never required"], "key": "A", "type": "sba", "explanation": "Beyond approximately 5 mm of required expansion in a non-growing patient, surgically assisted rapid palatal expansion or bone-borne expansion is indicated. (Companion Ch 13; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 824, "page": 149, "stem": "Which single statement about the timing of maxillary expansion is correct?", "options": ["Sutural fusion correlates closely with chronological age", "Expansion is impossible after 12 years", "Sutural fusion occurs by the late teens, but the correlation between sutural maturation and chronological age is poor", "Expansion is impossible before 7 years", "The suture never fuses"], "key": "C", "type": "sba", "explanation": "The suture should be assessed rather than the birthday, since the correlation between sutural maturation and chronological age is poor. (Companion Ch 9; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 825, "page": 149, "stem": "Proffit’s position on rapid versus slow expansion is which of the following?", "options": ["Rapid expansion produces a much greater skeletal component", "Only rapid expansion opens the suture", "Slow expansion produces no skeletal change", "Rapid expansion is contraindicated", "At 4 months, rapid and slow expansion have produced about the same skeletal to dental split"], "key": "E", "type": "sba", "explanation": "Proffit’s dissent is that rapid activation is not an effective way to minimise tooth movement, and that the net effect of rapid expansion is approximately equal skeletal and dental expansion. (Proffit Ch 13; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 826, "page": 149, "stem": "Slow expansion at a rate below which value matches the maximum speed of bone formation?", "options": ["2 mm per week", "0.5 mm per week", "4 mm per week", "1 mm per day", "There is no such rate"], "key": "A", "type": "sba", "explanation": "Proffit gives slow expansion at less than 2 mm per week as matching the maximum speed of bone formation. (Proffit Ch 13; Hbk 24.2)", "answerPage": 226, "block": "X"}, {"n": 827, "page": 149, "stem": "Rapid maxillary expansion is recommended as a treatment for which condition?", "options": ["Nasal obstruction", "Sleep-disordered breathing", "Neither nasal obstruction nor sleep-disordered breathing on current evidence", "Temporomandibular disorder", "Class II malocclusion"], "key": "C", "type": "sba", "explanation": "Rapid maxillary expansion is not recommended as a treatment for nasal breathing or obstructive sleep apnoea on current evidence. (Companion Ch 2; Hbk 24.2 and 26.5)", "answerPage": 226, "block": "X"}, {"n": 828, "page": 149, "stem": "In which order should crossbites be corrected?", "options": ["Anterior before posterior", "Neither should be corrected before alignment", "Simultaneously in all cases", "Whichever is more severe first", "Posterior before anterior"], "key": "E", "type": "sba", "explanation": "Correct posterior before anterior. Correct the anterior first and you lose it when you expand. (Mosby ch. on crossbite; Hbk 24.3)", "answerPage": 226, "block": "X"}, {"n": 829, "page": 150, "stem": "What makes an anterior crossbite correction self-retaining?", "options": ["A Class I molar relationship", "A positive overbite resulting from the correction", "A bonded retainer", "An increased overjet", "Extraction of the lower incisor"], "key": "B", "type": "sba", "explanation": "A positive overbite makes the correction self-retaining, and such corrections are usually stable without retention. (Wiedel and Bondemark 2015; Hbk 24.3)", "answerPage": 226, "block": "X"}, {"n": 830, "page": 150, "stem": "What proportion of the population has clinically significant asymmetric jaw development?", "options": ["25 per cent", "3 per cent", "10 per cent", "Under 0.5 per cent", "Over 40 per cent"], "key": "D", "type": "sba", "explanation": "Clinically significant asymmetric jaw development affects fewer than 0.5 per cent of the population, and the mandible is involved in 85 to 90 per cent of cases. (Proffit Ch 13; Hbk 24.4)", "answerPage": 226, "block": "X"}, {"n": 831, "page": 150, "stem": "Which is the commonest single cause of significant mandibular asymmetry?", "options": ["Hemifacial microsomia", "Condylar hyperplasia", "Condylar fracture in childhood", "Juvenile idiopathic arthritis", "Cleft lip and palate"], "key": "C", "type": "sba", "explanation": "A childhood condylar fracture is the commonest cause, not a syndrome. (Proffit Ch 13; Hbk 24.4 and 26.4)", "answerPage": 226, "block": "X"}, {"n": 832, "page": 150, "stem": "Which term describes a functional shift producing an apparent asymmetry?", "options": ["Laterocclusion", "Laterognathy", "Hemimandibular elongation", "Hemimandibular hyperplasia", "Plagiocephaly"], "key": "A", "type": "sba", "explanation": "Laterocclusion describes a functional shift; laterognathy describes a true skeletal asymmetry. (Mosby ch. on asymmetry; Hbk 24.4)", "answerPage": 226, "block": "X"}, {"n": 833, "page": 150, "stem": "Hemimandibular hyperplasia in the Obwegeser and Makek classification is characterised by which feature?", "options": ["A horizontal vector with the chin deviated to the unaffected side", "An anterior open bite only", "A purely transverse discrepancy", "Bilateral symmetrical enlargement", "A vertical vector with a true occlusal cant and a unilateral open bite"], "key": "E", "type": "sba", "explanation": "Hemimandibular hyperplasia, Type II, has a vertical vector with a true occlusal cant and often an undisturbed chin point and centreline. (Obwegeser and Makek 1986; Hbk 24.4)", "answerPage": 226, "block": "X"}, {"n": 834, "page": 150, "stem": "Hemimandibular elongation is characterised by which feature?", "options": ["A true occlusal cant", "Bilateral involvement", "A unilateral open bite", "Chin deviation to the unaffected side with a level occlusal plane", "Absence of any occlusal effect"], "key": "D", "type": "sba", "explanation": "Hemimandibular elongation, Type I, has a horizontal vector: the chin deviates to the unaffected side with a level occlusal plane. (Obwegeser and Makek 1986; Hbk 24.4)", "answerPage": 226, "block": "X"}, {"n": 835, "page": 150, "stem": "Which investigation for condylar hyperplasia is sensitive but non-specific?", "options": ["Panoramic radiography", "Bone scintigraphy", "Magnetic resonance imaging", "Posteroanterior cephalometry", "Cone beam computed tomography"], "key": "B", "type": "sba", "explanation": "Scintigraphy is sensitive but non-specific, with false positives. Serial three-dimensional facial superimposition is the non-invasive alternative. (Companion Ch 15; Hbk 24.4)", "answerPage": 226, "block": "X"}, {"n": 836, "page": 151, "stem": "Which findings suggest a progressive asymmetry requiring referral?", "options": ["A stable 2 mm chin deviation since childhood", "A Class II molar relationship on one side only", "A unilateral crossbite with a displacement", "A midline diastema", "Accelerating chin deviation, a new occlusal cant, or new temporomandibular symptoms in the teens"], "key": "E", "type": "sba", "explanation": "Progression is the key feature. Accelerating deviation, a new cant or new joint symptoms in the teens should prompt referral. (Companion Ch 15; Hbk 24.4)", "answerPage": 227, "block": "X"}, {"n": 837, "page": 151, "stem": "How many histological subtypes of condylar hyperplasia did Slootweg and Muller describe?", "options": ["Two", "Four", "Three", "Five", "Six"], "key": "B", "type": "sba", "explanation": "Slootweg and Muller described four histological subtypes of condylar hyperplasia. (Slootweg and Muller 1986; Hbk 24.4)", "answerPage": 227, "block": "X"}, {"n": 838, "page": 151, "stem": "Which is the appropriate management of a mild asymmetry in a growing child?", "options": ["Immediate surgery", "Chin cup therapy", "Immediate camouflage with fixed appliances", "Watch, with a defined review interval and records that can be superimposed", "Extraction of premolars"], "key": "D", "type": "sba", "explanation": "Mild asymmetry in a grower is a watch, not a treat, but the watching must be structured with defined reviews and superimposable records. (Cobourne cases; Hbk 24.4)", "answerPage": 227, "block": "X"}, {"n": 839, "page": 151, "stem": "Which single step should be taken early where an asymmetry is associated with a functional shift?", "options": ["Elimination of the shift, since it can drive asymmetric growth", "Surgical assessment", "Chin cup therapy", "Observation until growth is complete", "Extraction of the deviated side"], "key": "A", "type": "sba", "explanation": "A shift should be eliminated early, because it can drive asymmetric mandibular growth. (Cobourne cases; Hbk 24.4)", "answerPage": 227, "block": "X"}, {"n": 840, "page": 151, "stem": "Which is the correct clinical test to distinguish a true occlusal cant from a functional shift?", "options": ["Palpation of the condyles", "Measuring the overjet", "Asking the patient to bite on a spatula, and assessing the path of closure from retruded contact position", "Assessing the third molars", "Measuring maximum opening"], "key": "C", "type": "sba", "explanation": "Biting on a spatula reveals a true occlusal cant, and the path of closure reveals a functional displacement. (Companion Ch 15; Hbk 24.4)", "answerPage": 227, "block": "X"}, {"n": 841, "page": 151, "stem": "Which imaging modality is indicated for a significant transverse asymmetry?", "options": ["Lateral cephalogram", "Bitewings", "Periapical radiographs", "Posteroanterior cephalogram", "Occlusal view"], "key": "D", "type": "sba", "explanation": "A posteroanterior cephalogram is indicated for significant transverse asymmetry, although identifying the midsagittal plane is the principal difficulty. (Mosby ch. on asymmetry; Hbk 24.4)", "answerPage": 227, "block": "X"}, {"n": 842, "page": 152, "stem": "Which are the three mechanisms of overbite reduction?", "options": ["Extraction, expansion and distalisation", "Intrusion of incisors, extrusion of buccal segments, and proclination of the labial segments", "Torque, tip and rotation", "Anchorage, retention and settling", "Levelling, aligning and finishing"], "key": "B", "type": "sba", "explanation": "The three mechanisms are incisor intrusion, buccal segment extrusion and labial segment proclination, and which is stable depends entirely on growth status. (Companion Ch 13; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 843, "page": 152, "stem": "Buccal segment extrusion for overbite reduction is stable in which patient?", "options": ["A non-growing adult", "No patient", "A high-angle adult", "Any patient", "A growing patient, because condylar growth compensates"], "key": "E", "type": "sba", "explanation": "In a grower, condylar growth compensates for the increased posterior vertical dimension. In a non-grower the mandible rotates down and back, worsening the Class II and relapsing. (Companion Ch 13; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 844, "page": 152, "stem": "True incisor intrusion is required in which situation?", "options": ["A high-angle patient or an adult in whom face height must not increase", "A growing patient with a low mandibular plane angle", "A patient with an anterior open bite", "A patient with a transverse discrepancy", "A patient with a Class III skeletal base"], "key": "A", "type": "sba", "explanation": "True intrusion is required where face height must not increase, using a utility or bypass arch, segmental mechanics, or miniscrews. (Companion Ch 13; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 845, "page": 152, "stem": "Which force is appropriate for segmental intrusion of the four incisors?", "options": ["20 g total", "150 g total", "60 g total, at 15 g per tooth", "300 g total", "500 g total"], "key": "C", "type": "sba", "explanation": "Approximately 60 g total, at 15 g per tooth, is appropriate. Intrusion is the lightest movement in orthodontics. (Companion Ch 13; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 846, "page": 152, "stem": "Ng and colleagues reported what magnitude of incisor intrusion achievable with segmental mechanics in non-growing patients?", "options": ["0.5 mm maxillary and 0.6 mm mandibular", "1.5 mm maxillary and 1.9 mm mandibular", "3 mm maxillary and 4 mm mandibular", "5 mm in both arches", "Intrusion is not achievable"], "key": "B", "type": "sba", "explanation": "Approximately 1.5 mm maxillary and 1.9 mm mandibular intrusion is achievable with segmental mechanics in non-growing patients. (Ng 2005; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 847, "page": 152, "stem": "Miniscrews achieve how much more intrusion than segmental mechanics?", "options": ["0.1 to 0.2 mm", "4 to 5 mm", "2 to 3 mm", "0.67 to 0.95 mm", "No additional intrusion"], "key": "D", "type": "sba", "explanation": "Miniscrews give 0.67 to 0.95 mm more intrusion than segmental mechanics, with less molar extrusion, on low-quality evidence. (Sosly 2020; Shakti 2022; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 848, "page": 153, "stem": "Proclination of the incisors changes the overbite by approximately how much per degree?", "options": ["0.1 to 0.2 mm", "0.01 mm", "0.5 mm", "1 mm", "2 mm"], "key": "A", "type": "sba", "explanation": "Eberhart reported 0.1 to 0.2 mm of overbite change per degree of incisal angular change. (Eberhart 1990; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 849, "page": 153, "stem": "What single condition must be met for a corrected overbite to remain stable?", "options": ["A Class I molar relationship", "A bonded retainer", "Correction of the interincisal angle and establishment of an occlusal stop", "Extraction of four premolars", "A flat curve of Spee only"], "key": "C", "type": "sba", "explanation": "Houston’s rule is that overbite reduction relapses unless the interincisal angle is corrected and an occlusal stop established. (Houston 1989; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 850, "page": 153, "stem": "The Dahl concept re-establishes posterior occlusal contacts over approximately what period?", "options": ["2 weeks", "Contacts do not re-establish", "18 months", "3 years", "6 months"], "key": "E", "type": "sba", "explanation": "Localised supra-occlusion re-establishes contacts over an average of 6 months, with adverse events rare, minor and transient. (Dahl 1975; Poyser 2005; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 851, "page": 153, "stem": "Dake and Sinclair compared segmental with continuous reverse curve mechanics and reported what?", "options": ["Segmental mechanics gave greater true intrusion, with a Ricketts utility arch producing more lower incisor proclination", "Continuous mechanics gave greater intrusion", "Both were equivalent", "Neither produced intrusion", "Reverse curve mechanics caused root resorption"], "key": "A", "type": "sba", "explanation": "Segmental techniques give greater true intrusion; the Ricketts utility arch produces more lower incisor proclination. (Dake and Sinclair 1989; Weiland 1996; Hbk 25.1)", "answerPage": 227, "block": "Y"}, {"n": 852, "page": 153, "stem": "Burstone’s intrusion arch is best described as which type of system?", "options": ["A two-couple system", "A continuous archwire system", "A one-couple bypass system", "A tissue-borne system", "A self-ligating system"], "key": "C", "type": "sba", "explanation": "Burstone’s one-couple bypass intrusion arch is statically determinate, so the force system can be calculated and measured. (Burstone 1977; Hbk 14.3 and 25.1)", "answerPage": 227, "block": "Y"}, {"n": 853, "page": 153, "stem": "Which is the key soft tissue sign of a skeletal anterior open bite?", "options": ["A deep labiomental fold", "A prominent chin", "A thin upper lip", "An acute nasolabial angle", "An interlabial gap greater than 3 mm"], "key": "E", "type": "sba", "explanation": "An interlabial gap greater than 3 mm is the key soft tissue sign of a skeletal open bite. (Nanda; Hbk 25.2)", "answerPage": 227, "block": "Y"}, {"n": 854, "page": 153, "stem": "One millimetre of molar intrusion produces approximately how much anterior open bite reduction?", "options": ["0.5 mm", "3 mm", "1 mm", "6 mm", "No change"], "key": "B", "type": "sba", "explanation": "One millimetre of molar intrusion gives approximately 3 mm of open bite reduction, which is why TADs transformed open bite management. (Nanda; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 855, "page": 154, "stem": "One millimetre of molar extrusion reduces incisor overlap by approximately how much?", "options": ["0.2 mm", "6 mm", "4 mm", "1.5 to 2.5 mm", "No change"], "key": "D", "type": "sba", "explanation": "One millimetre of molar extrusion reduces overlap by 1.5 to 2.5 mm, which is why extrusion is contraindicated where the face is already long. (Nanda; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 856, "page": 154, "stem": "What proportion of anterior open bite corrections relapse, whether surgical or non-surgical?", "options": ["Under 5 per cent", "Approximately 50 per cent", "Approximately 20 per cent", "Approximately 80 per cent", "None"], "key": "C", "type": "sba", "explanation": "Open bites relapse in approximately 20 per cent of both surgical and non-surgical corrections, which is the number to state at consent. (Nanda; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 857, "page": 154, "stem": "A tongue thrust observed in a patient with an anterior open bite is most commonly which of the following?", "options": ["Adaptive to the open bite rather than causative", "The primary cause of the open bite", "An endogenous tongue thrust", "A sign of macroglossia", "A neurological disorder"], "key": "A", "type": "sba", "explanation": "Tongue posture is usually adaptive to the open bite rather than causative. An endogenous tongue thrust is rare, and such cases are unstable and need permanent retention. (Companion Ch 13; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 858, "page": 154, "stem": "Which single feature distinguishes a habit-related from a skeletal anterior open bite?", "options": ["Symmetry and increased lower face height in the habit-related type", "They cannot be distinguished clinically", "The habit-related type is always larger", "Only the skeletal type has a posterior crossbite", "Asymmetry, often localised to the digit, in the habit-related type, with a symmetrical open bite and increased face height in the skeletal type"], "key": "E", "type": "sba", "explanation": "A habit-related open bite is asymmetric and often localised, with an associated posterior crossbite, proclined uppers and retroclined lowers. A skeletal open bite is symmetrical with increased face height and a high mandibular plane angle. (Companion Ch 12; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 859, "page": 154, "stem": "Which iatrogenic cause of anterior open bite should be recognised in advance?", "options": ["Extraction of premolars", "Bonded retention", "Interproximal reduction", "Extrusive mechanics in a high-angle patient, including Class II elastics and untrimmed functional appliance blocks", "Rapid maxillary expansion"], "key": "D", "type": "sba", "explanation": "Extrusive mechanics in a high-angle patient are a recognised iatrogenic cause, and recognising the high-angle face before choosing the mechanics prevents it. (Companion Ch 13; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 860, "page": 154, "stem": "Approximately how much dentoalveolar height separates a deep bite face from an open bite face?", "options": ["1 mm", "5 mm", "12 mm", "20 mm", "There is no measurable difference"], "key": "B", "type": "sba", "explanation": "Approximately 5 mm of dentoalveolar height separates a deep bite face from an open bite face, which is why small vertical changes matter. (Mosby ch. on vertical control; Hbk 25.3)", "answerPage": 228, "block": "Y"}, {"n": 861, "page": 155, "stem": "A short face pattern is associated with which condylar growth direction?", "options": ["Posterior condylar growth", "Lateral condylar growth", "Vertical condylar growth only", "No condylar growth", "Forward condylar growth"], "key": "E", "type": "sba", "explanation": "Short face equals forward condylar growth and a deep bite. Long face equals posterior condylar growth, backward rotation and an open bite. (Mosby ch. on vertical control; Hbk 25.3)", "answerPage": 228, "block": "Y"}, {"n": 862, "page": 155, "stem": "Which instruction is used to record the lip at rest for vertical planning?", "options": ["Ask the patient to smile broadly", "Ask the patient to say Emma or Mississippi", "Ask the patient to open wide", "Ask the patient to clench", "Ask the patient to swallow"], "key": "B", "type": "sba", "explanation": "Rest position is recorded by asking the patient to say Emma or Mississippi; the posed smile is recorded by biting together and saying cheese. (Nanda; Hbk 25.3)", "answerPage": 228, "block": "Y"}, {"n": 863, "page": 155, "stem": "Which retainer is classically used to retain a corrected deep overbite?", "options": ["A vacuum-formed retainer", "A positioner", "A bonded retainer alone", "A Hawley retainer with an anterior bite plane, worn into the early twenties", "A quadhelix"], "key": "D", "type": "sba", "explanation": "A Hawley retainer with an anterior bite plane, worn into the early twenties, is the classical deep bite retention appliance. (Mosby ch. on retention; Hbk 25.3)", "answerPage": 228, "block": "Y"}, {"n": 864, "page": 155, "stem": "Which single decision should be made first in planning treatment of an open bite?", "options": ["Which occlusal plane the case will be treated to", "The bracket prescription", "The retention regimen", "The extraction pattern", "The archwire sequence"], "key": "A", "type": "sba", "explanation": "Nanda’s principle is to choose the treatment occlusal plane first, then design the force system to reach it. (Nanda; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 865, "page": 155, "stem": "In a growing patient with a deep overbite and a low mandibular plane angle, which appliance for overbite reduction is appropriate?", "options": ["A high-pull headgear", "A miniscrew-supported intrusion arch", "A flat anterior bite plane, allowing posterior eruption", "Posterior bite blocks", "A quadhelix"], "key": "C", "type": "sba", "explanation": "A flat anterior bite plane disoccludes the posterior teeth and allows them to erupt, giving relative incisor intrusion, which is stable in a grower. (Companion Ch 9; Hbk 25.1)", "answerPage": 228, "block": "Y"}, {"n": 866, "page": 155, "stem": "In a non-growing patient, buccal segment extrusion for overbite reduction produces which effect?", "options": ["Stable overbite reduction", "Forward mandibular rotation", "Reduced face height", "Downward and backward mandibular rotation, worsening the Class II and increasing face height", "No change in the mandibular position"], "key": "D", "type": "sba", "explanation": "In a non-grower the mandible rotates down and back, so the manoeuvre worsens the Class II, increases face height and relapses. (Companion Ch 13; Hbk 25.1)", "answerPage": 228, "block": "Y"}, {"n": 867, "page": 155, "stem": "Which is the appropriate approach to an anterior open bite in a 6-year-old with an active digit habit?", "options": ["Immediate surgical assessment", "Interrupt the habit before the permanent incisors are established, expecting spontaneous closure", "Fit a twin block", "Extract the primary molars", "Place a fixed appliance"], "key": "B", "type": "sba", "explanation": "A habit-related open bite usually closes spontaneously if the habit ceases before the permanent incisors are in occlusion. (Companion Ch 12; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 868, "page": 156, "stem": "Which single mechanical option is most efficient for correcting a skeletal anterior open bite non-surgically?", "options": ["Class II elastics", "Rapid maxillary expansion", "Buccal segment extrusion", "Anterior box elastics alone", "Molar intrusion with temporary anchorage devices"], "key": "E", "type": "sba", "explanation": "Molar intrusion with TADs is the most efficient lever available, giving approximately 3 mm of open bite reduction per millimetre of intrusion. (Nanda; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 869, "page": 156, "stem": "Which surgical procedure corrects a skeletal anterior open bite of maxillary vertical excess origin?", "options": ["Posterior maxillary impaction with mandibular autorotation", "Bilateral sagittal split advancement", "Genioplasty", "Surgically assisted rapid palatal expansion", "Vertical subsigmoid osteotomy"], "key": "A", "type": "sba", "explanation": "Posterior maxillary impaction with mandibular autorotation is the standard correction, undertaken once growth is complete. (Proffit Ch 19; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 870, "page": 156, "stem": "Which is the appropriate advice to a patient with a skeletal anterior open bite who asks about muscle exercises?", "options": ["That exercises will close the bite", "That exercises are the first-line treatment", "That there is no evidence that muscle exercises alone will close a skeletal open bite", "That exercises will prevent relapse", "That exercises replace surgery"], "key": "C", "type": "sba", "explanation": "There is no good evidence that muscle exercises alone correct a malocclusion. Do not blame the tongue reflexively or promise that exercises will help. (Companion Ch 12; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 871, "page": 156, "stem": "Which statement about extrusion in a long-face patient is correct?", "options": ["Extrusion is the treatment of choice", "Extrusion is contraindicated where the face is already long", "Extrusion has no vertical effect", "Extrusion reduces face height", "Extrusion is indicated only with TADs"], "key": "B", "type": "sba", "explanation": "Extrusion increases face height and rotates the mandible down and back, so it is contraindicated in the long-face patient. (Nanda; Hbk 25.2)", "answerPage": 228, "block": "Y"}, {"n": 872, "page": 157, "stem": "Which single position on orthodontics and temporomandibular disorder should be stated in an examination?", "options": ["Orthodontics causes TMD", "Orthodontics cures TMD", "Orthodontics prevents TMD if canine guidance is achieved", "Orthodontics neither causes nor prevents TMD, and only weak statistical associations exist", "The relationship is unstudied"], "key": "D", "type": "sba", "explanation": "Weak statistical associations exist but there is no evidence of causation in either direction. Orthodontics is TMJ-neutral. (Behrents and White 1992; Hbk 26.2)", "answerPage": 229, "block": "Z"}, {"n": 873, "page": 157, "stem": "Which body of work reported that orthodontic treatment does not cause temporomandibular disorder?", "options": ["The American Association of Orthodontists funded studies of 1992", "The Florida trial", "The Manchester twin block trial", "The 2021 Cochrane review on canine extraction", "The Royal London space analysis studies"], "key": "A", "type": "sba", "explanation": "Behrents and White reported the AAO-funded studies in 1992, showing no significant association and that TMD cannot be prevented by any intervention. (Behrents and White 1992; Hbk 26.2)", "answerPage": 229, "block": "Z"}, {"n": 874, "page": 157, "stem": "What was the outcome of Brimm versus Malloy in 1987?", "options": ["The case was dismissed", "An award of 85000 dollars", "An award of 850000 dollars following temporomandibular disorder after four-premolar extraction treatment", "A criminal conviction", "A finding that orthodontics prevents TMD"], "key": "C", "type": "sba", "explanation": "The 1987 Michigan lawsuit resulted in an award of 850000 dollars, and prompted the AAO-funded studies of 1992. (Companion Ch 2; Hbk 26.1)", "answerPage": 229, "block": "Z"}, {"n": 875, "page": 157, "stem": "Luecke and Johnstone in 1992 reported which finding?", "options": ["Incisor retraction displaces the condyles distally", "Occlusal adjustment repositions the condyles", "Extraction causes condylar resorption", "Class II elastics displace the condyles", "Conventional incisor retraction does not produce distal displacement of the condyles"], "key": "E", "type": "sba", "explanation": "Conventional incisor retraction does not produce distal condylar displacement, which was the mechanism alleged by the functional orthodontists. (Luecke and Johnstone 1992; Hbk 26.2)", "answerPage": 229, "block": "Z"}, {"n": 876, "page": 157, "stem": "Approximately what proportion of the population has at least one sign of temporomandibular disorder?", "options": ["75 per cent", "33 per cent", "50 per cent", "10 per cent", "95 per cent"], "key": "A", "type": "sba", "explanation": "Approximately 75 per cent have at least one sign and approximately 33 per cent at least one symptom, but only a small minority seek treatment. (Companion Ch 2; Hbk 26.2)", "answerPage": 229, "block": "Z"}, {"n": 877, "page": 158, "stem": "At what stage of life do temporomandibular symptoms most commonly begin?", "options": ["Early childhood", "Middle age", "Late adolescence to early adulthood", "Old age", "Symptoms have no typical onset"], "key": "C", "type": "sba", "explanation": "Symptoms commonly begin in late adolescence, exactly when orthodontic treatment is provided, which is the principal confounder in this literature. (Behrents and White 1992; Hbk 26.2)", "answerPage": 229, "block": "Z"}, {"n": 878, "page": 158, "stem": "Which single investigation is required to image the temporomandibular disc?", "options": ["Panoramic radiography", "Submentovertex view", "Cone beam computed tomography", "Arthrography of the joint space", "Magnetic resonance imaging"], "key": "E", "type": "sba", "explanation": "MRI images the disc, the retrodiscal tissues and effusion. CBCT images bone but cannot image the disc or muscle. (Mosby ch. on TMD; Hbk 26.3)", "answerPage": 229, "block": "Z"}, {"n": 879, "page": 158, "stem": "Which single measure of mouth opening is regarded as the lower limit of normal?", "options": ["25 mm", "40 mm", "30 mm", "50 mm", "60 mm"], "key": "B", "type": "sba", "explanation": "Maximum opening of at least 40 mm is regarded as normal, and deviation or deflection on opening should be recorded. (Companion Ch 2; Hbk 26.3)", "answerPage": 229, "block": "Z"}, {"n": 880, "page": 158, "stem": "Which management approach for temporomandibular disorder is best supported?", "options": ["Occlusal adjustment", "Immediate surgery", "Immediate orthodontic treatment", "Reassurance, explanation of the natural history, jaw rest, analgesia, physiotherapy and a stabilisation splint", "Full-mouth rehabilitation"], "key": "D", "type": "sba", "explanation": "Conservative and reversible care comes first. Occlusal adjustment has little beneficial value and is irreversible. (Kandasamy 2022; Hbk 26.3)", "answerPage": 229, "block": "Z"}, {"n": 881, "page": 158, "stem": "Which single systemic condition can destroy the condyle in a child, producing a progressive Class II with an open bite?", "options": ["Rheumatic fever", "Type 1 diabetes", "Juvenile idiopathic arthritis", "Coeliac disease", "Asthma"], "key": "C", "type": "sba", "explanation": "Juvenile idiopathic arthritis can destroy the condyle and produce a progressive Class II with an anterior open bite, and should be recognised. (Mosby ch. on TMD; Hbk 26.3)", "answerPage": 229, "block": "Z"}, {"n": 882, "page": 158, "stem": "Which is the correct management of a child with a condylar fracture?", "options": ["Conservative functional management with early mobilisation, soft diet, analgesia and physiotherapy", "Prolonged intermaxillary fixation", "Immediate open reduction in all cases", "Condylectomy", "No treatment at all"], "key": "A", "type": "sba", "explanation": "Conservative functional management is preferred in children. Prolonged immobilisation risks ankylosis, which is the outcome to avoid at all costs. (Companion Ch 15; Hbk 26.4)", "answerPage": 229, "block": "Z"}, {"n": 883, "page": 158, "stem": "A childhood condylar fracture is the commonest cause of which orthodontic problem?", "options": ["Anterior open bite", "Hypodontia", "Class III malocclusion", "Transverse maxillary deficiency", "Significant mandibular asymmetry"], "key": "E", "type": "sba", "explanation": "Because the condyle is the mandible’s principal growth site, a childhood fracture is the commonest cause of significant mandibular asymmetry. (Companion Ch 15; Hbk 26.4)", "answerPage": 229, "block": "Z"}, {"n": 884, "page": 159, "stem": "Which clinical sign is characteristic of a healed unilateral condylar injury with growth disturbance?", "options": ["Deviation to the contralateral side on opening", "An increased overjet only", "Bilateral posterior open bite", "Deviation to the affected side on opening, with reduced ramus height and an occlusal cant", "Symmetrical reduction in opening"], "key": "D", "type": "sba", "explanation": "Deviation to the affected side on opening, reduced ramus height and an occlusal cant develop as growth proceeds. (Companion Ch 15; Hbk 26.4)", "answerPage": 229, "block": "Z"}, {"n": 885, "page": 159, "stem": "The classic adenoid facies is associated with which combination?", "options": ["A broad maxilla and reduced face height", "A narrow maxilla, increased face height, backward mandibular rotation and an anterior open bite", "A prognathic mandible with a deep bite", "Bilateral scissors bite", "A Class II division 2 pattern"], "key": "B", "type": "sba", "explanation": "Chronic nasal obstruction is associated with mouth breathing, low tongue posture, lips apart and head extension, producing a narrow maxilla, increased face height and backward rotation. (Companion Ch 7; Hbk 26.5)", "answerPage": 229, "block": "Z"}, {"n": 886, "page": 159, "stem": "What is the correct position to state about nasal obstruction and facial form?", "options": ["Nasal obstruction causes long face syndrome", "Adenoidectomy normalises facial growth", "There is no association", "Nasal obstruction reliably causes Class III", "The association is real but weak, and causation is not established"], "key": "E", "type": "sba", "explanation": "The association should be stated without asserting the cause. Experimental work in primates is not human evidence of causation. (Companion Ch 7; Hbk 26.5)", "answerPage": 229, "block": "Z"}, {"n": 887, "page": 159, "stem": "Adenoid tissue peaks at approximately which age?", "options": ["1 year", "3 to 5 years", "8 to 10 years", "13 to 15 years", "It does not involute"], "key": "B", "type": "sba", "explanation": "Adenoid tissue peaks at approximately 3 to 5 years and involutes through adolescence, so many children grow out of the obstruction. (Mosby ch. on airway; Hbk 26.5)", "answerPage": 229, "block": "Z"}, {"n": 888, "page": 159, "stem": "Which is the approximate prevalence of obstructive sleep apnoea in children?", "options": ["0.1 per cent", "15 per cent", "8 per cent", "2 per cent", "25 per cent"], "key": "D", "type": "sba", "explanation": "Paediatric obstructive sleep apnoea affects approximately 2 per cent of children, and adenotonsillectomy is first-line treatment in most. (Companion Ch 2; Hbk 26.5)", "answerPage": 229, "block": "Z"}, {"n": 889, "page": 159, "stem": "Which single step is required before treating suspected obstructive sleep apnoea orthodontically?", "options": ["A sleep study and appropriate medical referral", "A lateral cephalogram", "A CBCT", "A panoramic radiograph", "Rapid maxillary expansion"], "key": "A", "type": "sba", "explanation": "Do not diagnose or treat obstructive sleep apnoea orthodontically without a sleep study and appropriate referral. (Companion Ch 2; Hbk 26.5)", "answerPage": 229, "block": "Z"}, {"n": 890, "page": 159, "stem": "Koretsi and colleagues in 2018 reported that mandibular advancement appliances are effective in which group?", "options": ["Severe obstructive sleep apnoea", "Children under 5 years", "Mild to moderate obstructive sleep apnoea", "Patients with central sleep apnoea", "Patients with a Class III skeletal pattern"], "key": "C", "type": "sba", "explanation": "Mandibular advancement appliances are effective in mild to moderate obstructive sleep apnoea; CPAP remains the gold standard in moderate to severe disease. (Koretsi 2018; Hbk 26.5)", "answerPage": 229, "block": "Z"}, {"n": 891, "page": 160, "stem": "Which is the most effective surgical treatment for severe adult obstructive sleep apnoea?", "options": ["Uvulopalatopharyngoplasty", "Rapid maxillary expansion", "Adenotonsillectomy", "Maxillomandibular advancement", "Genioplasty"], "key": "D", "type": "sba", "explanation": "Maxillomandibular advancement is the most effective surgical option for severe adult obstructive sleep apnoea. (Mosby ch. on airway; Hbk 26.5)", "answerPage": 229, "block": "Z"}, {"n": 892, "page": 160, "stem": "Which symptoms in a child should prompt referral to ENT or paediatrics?", "options": ["A midline diastema", "Snoring, witnessed apnoeas, restless sleep, daytime somnolence or behavioural problems", "A deep overbite", "An anterior crossbite", "Delayed eruption of the canines"], "key": "B", "type": "sba", "explanation": "These are the symptoms of sleep-disordered breathing and require proper assessment, not orthodontic treatment in the first instance. (Companion Ch 2; Hbk 26.5)", "answerPage": 230, "block": "Z"}, {"n": 893, "page": 160, "stem": "Which single statement about occlusal adjustment for temporomandibular disorder is correct?", "options": ["It is the treatment of choice", "It is recommended by Cochrane review", "It should precede orthodontic treatment", "It reliably eliminates clicking", "It has little beneficial value and is irreversible"], "key": "E", "type": "sba", "explanation": "Occlusal adjustment has little beneficial value and is irreversible, and should not be undertaken to treat temporomandibular disorder. (Mosby ch. on TMD; Hbk 26.3)", "answerPage": 230, "block": "Z"}, {"n": 894, "page": 160, "stem": "Manfredini and colleagues in 2017 concluded what about dental occlusion and temporomandibular disorder?", "options": ["There is a lack of evidence implicating dental occlusion in the pathophysiology of TMD", "Occlusion is the principal cause", "Occlusion causes TMD only in adults", "Occlusal interferences reliably predict TMD", "Occlusion prevents TMD"], "key": "A", "type": "sba", "explanation": "Manfredini found a lack of evidence implicating occlusion in the pathophysiology of temporomandibular disorder. (Manfredini 2017; Hbk 26.2)", "answerPage": 230, "block": "Z"}, {"n": 895, "page": 160, "stem": "Proffit’s strongest argument against an occlusal cause of temporomandibular disorder is which of the following?", "options": ["That TMD is untreatable", "That the occlusion cannot be measured", "That TMD is no more prevalent now than before modern orthodontics, and symptoms disappear long before any occlusal change could explain it", "That clicking is normal", "That MRI cannot image the disc"], "key": "C", "type": "sba", "explanation": "Prevalence has not changed and symptoms remit spontaneously, which no occlusal explanation accounts for. (Proffit Ch 1; Hbk 26.2)", "answerPage": 230, "block": "Z"}, {"n": 896, "page": 160, "stem": "Which single element should be documented before orthodontic treatment in every patient, in relation to the temporomandibular joints?", "options": ["A CBCT", "Range of opening, deviation, joint sounds and muscle tenderness", "An MRI", "A stabilisation splint prescription", "An occlusal adjustment record"], "key": "B", "type": "sba", "explanation": "Screening and documenting joint status before treatment is the recognised standard, and protects both patient and clinician. (Kandasamy 2022; Hbk 26.3)", "answerPage": 230, "block": "Z"}, {"n": 897, "page": 161, "stem": "Which is the correct management if temporomandibular symptoms appear during orthodontic treatment?", "options": ["Complete the treatment as planned", "Perform an occlusal adjustment", "Debond immediately and discharge", "Suspend active mechanics and manage conservatively and reversibly", "Refer for surgery"], "key": "D", "type": "sba", "explanation": "Kandasamy’s guidance is to suspend active mechanics if symptoms appear and manage with conservative, reversible therapies. (Kandasamy 2022; Hbk 26.3)", "answerPage": 230, "block": "Z"}, {"n": 898, "page": 161, "stem": "A parent asks whether tongue and lip exercises will correct their child’s malocclusion. Which reply is best supported?", "options": ["That there is no good evidence that muscle exercises alone correct a malocclusion, although interrupting a digit habit early does help", "That exercises reliably correct malocclusion", "That exercises will close a skeletal open bite", "That exercises replace appliance treatment", "That proprietary myofunctional systems have strong randomised evidence"], "key": "A", "type": "sba", "explanation": "Habit interruption before the permanent incisors are established has reasonable evidence; exercises alone do not, and the stronger claims made for proprietary systems are unsupported. (Companion Ch 12; Hbk 26.6)", "answerPage": 230, "block": "Z"}, {"n": 899, "page": 161, "stem": "A lip trap in a Class II division 1 malocclusion is best described in which way?", "options": ["An irrelevant finding", "A cause of temporomandibular disorder", "A soft tissue factor that perpetuates the malocclusion and is eliminated by a functional appliance", "A cause of anterior open bite", "A contraindication to treatment"], "key": "C", "type": "sba", "explanation": "A lower lip trap proclines the uppers and retroclines the lowers, perpetuating the malocclusion. Its elimination is one of the soft tissue effects of a functional appliance. (Companion Ch 12; Hbk 26.6)", "answerPage": 230, "block": "Z"}, {"n": 900, "page": 161, "stem": "Which single statement about temporomandibular disorder classification is correct?", "options": ["All cases are internal derangements", "Only degenerative disease is treatable", "All cases involve the disc", "Classification is not clinically useful", "The main categories are myofascial pain, internal derangement, degenerative joint disease and systemic inflammatory arthropathies"], "key": "E", "type": "sba", "explanation": "Broad classification into myofascial pain, internal derangement, degenerative disease and inflammatory arthropathy guides management and referral. (Mosby ch. on TMD; Hbk 26.3)", "answerPage": 230, "block": "Z"}, {"n": 901, "page": 161, "stem": "Which is the correct reply to a patient asking whether orthodontic treatment will cure their jaw clicking?", "options": ["There is no evidence that orthodontic treatment reduces temporomandibular signs and symptoms, and none that it causes them", "It usually will", "It will if canine guidance is established", "It will worsen the clicking", "Treatment is contraindicated with a click"], "key": "A", "type": "sba", "explanation": "Do not promise a cure, and do not let a click drive an irreversible occlusal change you would not otherwise make. (Macfarlane 2009; Luther 2010; Hbk 26.2)", "answerPage": 230, "block": "Z"}, {"n": 902, "page": 162, "stem": "Which single factor most changes the mechanics of tooth movement in a periodontally reduced dentition?", "options": ["The bracket prescription", "Increased bone density", "Apical migration of the centre of resistance, producing a larger moment for the same force", "Reduced periodontal ligament width", "Increased root surface area"], "key": "C", "type": "sba", "explanation": "The centre of resistance migrates apically, so the same force applied at the bracket produces a larger moment and more tipping. Lighter forces and higher moment-to-force ratios are required. (Companion Ch 6; Hbk 27.1)", "answerPage": 230, "block": "AA"}, {"n": 903, "page": 162, "stem": "Which single record should be made in every adult before appliance placement?", "options": ["A CBCT", "An MRI of the joints", "A sleep study", "A hand-wrist radiograph", "Probing of every tooth with recording of pre-existing recession"], "key": "E", "type": "sba", "explanation": "Probing every adult and recording pre-existing recession is essential clinically and medicolegally. (Nanda; Hbk 27.1)", "answerPage": 230, "block": "AA"}, {"n": 904, "page": 162, "stem": "Adjunctive orthodontic treatment is best defined as which of the following?", "options": ["Treatment that corrects the whole malocclusion", "Limited tooth movement serving a larger periodontal or restorative goal", "Treatment with removable appliances only", "Treatment without extraction", "Treatment in a growing patient"], "key": "B", "type": "sba", "explanation": "Adjunctive treatment serves a larger goal, such as uprighting a tipped molar before a bridge, and is often appropriate in general practice. (Proffit Ch 18; Hbk 27.1)", "answerPage": 230, "block": "AA"}, {"n": 905, "page": 162, "stem": "What force is appropriate for intrusion during molar uprighting?", "options": ["5 g per tooth", "100 g per tooth", "50 g per tooth", "10 to 15 g per tooth", "200 g per tooth"], "key": "D", "type": "sba", "explanation": "Intrusion during molar uprighting requires 10 to 15 g per tooth, and the uprighted tooth should be retained until the lamina dura reappears. (Mosby ch. on molar uprighting; Hbk 27.1)", "answerPage": 230, "block": "AA"}, {"n": 906, "page": 162, "stem": "Which patient is a poor candidate for molar uprighting?", "options": ["A brachycephalic patient with a deep bite", "A patient with a Class I molar relationship", "A dolichocephalic patient, because the mechanics are extrusive", "A patient with a shallow curve of Spee", "A patient with good periodontal support"], "key": "C", "type": "sba", "explanation": "Dolichocephalic, high-angle patients are poor candidates because uprighting mechanics tend to be extrusive and open the bite further. (Mosby ch. on molar uprighting; Hbk 27.1)", "answerPage": 230, "block": "AA"}, {"n": 907, "page": 162, "stem": "Until what endpoint should an uprighted molar be retained?", "options": ["Until the lamina dura reappears", "Six weeks", "Three months", "One year", "Retention is unnecessary"], "key": "A", "type": "sba", "explanation": "The uprighted molar should be retained until the lamina dura reappears radiographically. (Mosby ch. on molar uprighting; Hbk 27.1)", "answerPage": 230, "block": "AA"}, {"n": 908, "page": 163, "stem": "Which single principle governs the creation of alveolar bone at a deficient implant site?", "options": ["Bone can be grown by loading alone", "Only grafting can create alveolar bone", "Bone forms spontaneously after extraction", "Alveolar bone regenerates in adults without intervention", "Erupting and extruding teeth bring alveolar bone with them, so a tooth may be erupted through the site and then moved back"], "key": "E", "type": "sba", "explanation": "Proffit’s alveolar bone argument is that bone exists only where a tooth erupted, and can be developed by erupting a tooth through the site. (Proffit Ch 13; Hbk 27.1)", "answerPage": 230, "block": "AA"}, {"n": 909, "page": 163, "stem": "When must the camouflage-or-surgery decision be made?", "options": ["At the mid-treatment review", "After a trial of camouflage", "After alignment is complete", "Before treatment begins", "At debond"], "key": "D", "type": "sba", "explanation": "The decision must be made before treatment begins, because pre-surgical orthodontics decompensates in the opposite direction from camouflage. (Proffit Ch 19; Hbk 27.2)", "answerPage": 230, "block": "AA"}, {"n": 910, "page": 163, "stem": "Pre-surgical orthodontics typically lasts approximately how long?", "options": ["3 months", "12 to 18 months", "3 years", "6 weeks", "It is not required"], "key": "B", "type": "sba", "explanation": "Pre-surgical orthodontics typically takes 12 to 18 months, with a further 4 to 6 months of post-surgical detailing. (Proffit Ch 19; Hbk 27.2)", "answerPage": 231, "block": "AA"}, {"n": 911, "page": 163, "stem": "Which single statement best describes pre-surgical decompensation?", "options": ["It aligns the arches into a Class I relationship before surgery", "It is optional in most cases", "It levels the curve of Spee only", "It is performed after surgery", "It deliberately removes the dental compensation, making the occlusion worse, so that the surgeon has the movement needed to correct the face"], "key": "E", "type": "sba", "explanation": "Calling pre-surgical orthodontics aligning the arches is one of the twelve costly slips. Decompensation deliberately worsens the bite. (Proffit Ch 19; Hbk 27.2)", "answerPage": 231, "block": "AA"}, {"n": 912, "page": 163, "stem": "Which osteotomy is used to impact the maxilla and correct vertical maxillary excess?", "options": ["Bilateral sagittal split osteotomy", "Le Fort I osteotomy", "Vertical subsigmoid osteotomy", "Genioplasty", "Segmental mandibular osteotomy"], "key": "B", "type": "sba", "explanation": "Le Fort I impaction corrects vertical maxillary excess and a gummy smile, and produces autorotation of the mandible. (Proffit Ch 19; Hbk 27.3)", "answerPage": 231, "block": "AA"}, {"n": 913, "page": 163, "stem": "Which nerve is principally at risk during a bilateral sagittal split osteotomy?", "options": ["The lingual nerve", "The facial nerve", "The infraorbital nerve", "The inferior alveolar nerve", "The hypoglossal nerve"], "key": "D", "type": "sba", "explanation": "The inferior alveolar nerve is at risk, with altered sensation common transiently and occasionally permanent. It must be consented for specifically. (Proffit Ch 19; Hbk 27.3)", "answerPage": 231, "block": "AA"}, {"n": 914, "page": 163, "stem": "Which procedure is used for mandibular setback other than a sagittal split?", "options": ["Vertical subsigmoid osteotomy", "Le Fort I osteotomy", "Genioplasty", "Anterior segmental maxillary osteotomy", "Surgically assisted rapid palatal expansion"], "key": "A", "type": "sba", "explanation": "The vertical subsigmoid osteotomy, performed extra-orally or intra-orally, is used for mandibular setback. (Proffit Ch 19; Hbk 27.3)", "answerPage": 231, "block": "AA"}, {"n": 915, "page": 164, "stem": "Which statement about producing a chin prominence is correct?", "options": ["A chin can be produced by orthodontic tooth movement", "A chin is produced by functional appliance therapy", "A chin cannot be produced orthodontically; a genioplasty is required", "A chin is produced by extraction", "A chin develops with a growth spurt in all patients"], "key": "C", "type": "sba", "explanation": "You cannot orthodontically produce a chin. A genioplasty is required, and it is a very stable movement in any direction. (Mosby ch. on treatment planning; Hbk 27.3)", "answerPage": 231, "block": "AA"}, {"n": 916, "page": 164, "stem": "Which movement is the most stable in the hierarchy of orthognathic stability?", "options": ["Maxilla down", "Maxilla wide", "Mandible back", "Maxilla superiorly, that is impaction", "Mandible back with maxilla forward"], "key": "D", "type": "sba", "explanation": "Maxillary impaction, mandibular advancement in the low- and average-angle patient, and genioplasty in any direction are the most stable movements. (Proffit Ch 19; Hbk 27.4)", "answerPage": 231, "block": "AA"}, {"n": 917, "page": 164, "stem": "Which movement is the least stable in the hierarchy of orthognathic stability?", "options": ["Maxillary impaction", "Maxillary down-graft and surgical maxillary expansion", "Mandibular advancement", "Genioplasty", "Maxillary advancement"], "key": "B", "type": "sba", "explanation": "Maxillary down-grafting and surgical expansion are the least stable movements. (Proffit Ch 19; Hbk 27.4)", "answerPage": 231, "block": "AA"}, {"n": 918, "page": 164, "stem": "In the hierarchy of stability, which factor matters most?", "options": ["The fixation used", "The type of wafer", "The surgical technique", "The surgeon’s experience", "The direction of movement"], "key": "E", "type": "sba", "explanation": "Stability depends on direction, then fixation, then technique, in that order. Very stable means about a 90 per cent chance of no significant change. (Proffit Ch 19; Hbk 27.4)", "answerPage": 231, "block": "AA"}, {"n": 919, "page": 164, "stem": "Which patient group is at particular risk of condylar resorption after orthognathic surgery?", "options": ["Young women with a high-angle pattern and pre-existing joint disease", "Older men with a low-angle pattern", "Patients with Class III malocclusion", "Patients with a Class I skeletal base", "Patients undergoing genioplasty alone"], "key": "A", "type": "sba", "explanation": "Condylar resorption is a recognised risk particularly in young women with a high-angle pattern and pre-existing joint disease, and must be consented for. (Proffit Ch 19; Hbk 27.5)", "answerPage": 231, "block": "AA"}, {"n": 920, "page": 164, "stem": "Distraction osteogenesis follows which sequence?", "options": ["Corticotomy, immediate distraction, consolidation", "Immediate distraction at 3 mm per day", "Corticotomy, a latency period of about 5 to 7 days, distraction at about 1 mm per day, then consolidation", "Osteotomy with immediate rigid fixation", "Corticotomy with no distraction phase"], "key": "C", "type": "sba", "explanation": "The sequence is corticotomy, latency of about 5 to 7 days, distraction at approximately 1 mm per day, then consolidation. (Proffit Ch 19; Hbk 27.3)", "answerPage": 231, "block": "AA"}, {"n": 921, "page": 164, "stem": "Which is the appropriate first step in the orthognathic pathway?", "options": ["Placing a fixed appliance", "Joint assessment by the orthodontist and maxillofacial surgeon together, with the patient’s own concern recorded first", "Taking a CBCT", "Extracting premolars", "Fitting a surgical wafer"], "key": "B", "type": "sba", "explanation": "Joint assessment with the patient’s own concern recorded first is the correct first step, and the decision to operate is made at the planning stage. (Proffit Ch 19; Hbk 27.2)", "answerPage": 231, "block": "AA"}, {"n": 922, "page": 165, "stem": "Which single psychological screen should be performed before orthognathic surgery?", "options": ["Screening for depression only", "No screening is required", "Screening for anxiety only", "Screening for body dysmorphic disorder, which affects up to 17 per cent of orthognathic patients", "Screening for eating disorders only"], "key": "D", "type": "sba", "explanation": "Body dysmorphic disorder affects up to 17 per cent of those seeking orthognathic surgery and must be screened for. (Dons 2022; Hbk 27.5)", "answerPage": 231, "block": "AA"}, {"n": 923, "page": 165, "stem": "Which single feature distinguishes comprehensive from adjunctive orthodontic treatment in an adult?", "options": ["Comprehensive treatment corrects the whole malocclusion and requires the full diagnostic workup and a full appliance", "The use of fixed rather than removable appliances", "Comprehensive treatment is always surgical", "Adjunctive treatment always requires extraction", "Adjunctive treatment cannot be delivered in general practice"], "key": "A", "type": "sba", "explanation": "Comprehensive treatment corrects the malocclusion and requires the full workup. Adjunctive treatment serves a larger restorative or periodontal goal. (Proffit Ch 18; Hbk 27.1)", "answerPage": 231, "block": "AA"}, {"n": 924, "page": 165, "stem": "Which single statement about tooth movement rate in adults is correct?", "options": ["It is faster than in children", "It is identical to that in children", "It is slower, with more prolonged hyalinisation, and treatment takes longer", "It cannot be predicted", "It is faster in the maxilla only"], "key": "C", "type": "sba", "explanation": "Movement is slower in adults, hyalinisation is more prolonged, and treatment takes longer than in an adolescent. (Companion Ch 13; Hbk 27.1)", "answerPage": 231, "block": "AA"}, {"n": 925, "page": 165, "stem": "Which is the correct sequence when planning adult orthodontics with a restorative endpoint?", "options": ["Begin orthodontics and consult the restorative colleague later", "Debond before restorative planning", "Complete all restorative work first, then move the teeth", "Place implants before orthodontics", "Plan the restorative endpoint with the restorative colleague first, then plan the tooth movement to reach it"], "key": "E", "type": "sba", "explanation": "The restorative endpoint should be agreed first so that the tooth movement is designed to reach it. (Proffit Ch 18; Hbk 27.1)", "answerPage": 231, "block": "AA"}, {"n": 926, "page": 165, "stem": "Which single statement about bonding to porcelain restorations is correct?", "options": ["Surface preparation with hydrofluoric acid or air abrasion and a silane coupling agent is required", "Conventional enamel etching is sufficient", "Bonding to porcelain is impossible", "Bands must always be used", "Glass ionomer should be used"], "key": "A", "type": "sba", "explanation": "Porcelain requires surface preparation and silane coupling. Bands are an alternative where bonding is unreliable. (Proffit Ch 18; Hbk 27.1)", "answerPage": 231, "block": "AA"}, {"n": 927, "page": 165, "stem": "Which is the appropriate response when an adult patient with a severe skeletal discrepancy declines surgery?", "options": ["Proceed with the surgical plan regardless", "Discharge the patient", "Offer camouflage honestly, stating clearly what it can and cannot achieve, and record the discussion", "Begin decompensation in case they change their mind", "Refer to another surgeon without discussion"], "key": "C", "type": "sba", "explanation": "Camouflage should be offered honestly with its limitations stated, and the discussion recorded. Decompensation must not be started for a plan the patient has declined. (GDC Standards; Hbk 27.2)", "answerPage": 231, "block": "AA"}, {"n": 928, "page": 166, "stem": "Which surgical procedure is used for transverse expansion in a non-growing patient requiring more than about 5 mm?", "options": ["Le Fort I osteotomy alone", "Vertical subsigmoid osteotomy", "Bilateral sagittal split osteotomy", "Genioplasty", "Surgically assisted rapid palatal expansion"], "key": "E", "type": "sba", "explanation": "Surgically assisted rapid palatal expansion, or bone-borne expansion, is indicated beyond approximately 5 mm in the non-growing patient. (Companion Ch 13; Hbk 24.2 and 27.3)", "answerPage": 231, "block": "AA"}, {"n": 929, "page": 166, "stem": "Which is the correct approach to the lower centre line during pre-surgical orthodontics?", "options": ["It should be aligned to the upper centre line", "It should be held on the chin", "It should be ignored until after surgery", "It should be deliberately displaced", "It should be aligned to the facial midline of the maxilla"], "key": "B", "type": "sba", "explanation": "The lower centre line is held on the chin during pre-surgical orthodontics, since the mandible will be moved as a unit at surgery. (Cobourne cases; Hbk 27.2)", "answerPage": 231, "block": "AA"}, {"n": 930, "page": 166, "stem": "Which is the correct duration of post-surgical orthodontics?", "options": ["1 to 2 weeks", "3 years", "18 months", "4 to 6 months", "None is required"], "key": "D", "type": "sba", "explanation": "Post-surgical orthodontics typically takes 4 to 6 months to settle the occlusion, detail and finish. (Proffit Ch 19; Hbk 27.2)", "answerPage": 232, "block": "AA"}, {"n": 931, "page": 166, "stem": "Which single statement about anterior segmental osteotomies is correct?", "options": ["They are used for mandibular advancement", "They are used only in cleft patients", "They are used for bimaxillary protrusion and for closing an anterior open bite, and are described by Wunderer and Kole", "They are used for transverse expansion", "They have been abandoned"], "key": "C", "type": "sba", "explanation": "Anterior maxillary segmental osteotomy is described by Wunderer and the mandibular equivalent by Kole; both are used for bimaxillary protrusion and open bite correction. (Proffit Ch 19; Hbk 27.3)", "answerPage": 232, "block": "AA"}, {"n": 932, "page": 167, "stem": "At what age is lip repair conventionally performed?", "options": ["3 to 6 months", "At birth", "9 to 12 months", "18 months", "3 years"], "key": "A", "type": "sba", "explanation": "Lip repair is performed at 3 to 6 months, and palate repair at 6 to 12 months, before speech develops. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 933, "page": 167, "stem": "What does the rule of tens refer to in cleft lip repair?", "options": ["10 hours of fasting", "10 months of age and 10 kg in weight", "10 days of age", "A 10 mm cleft width", "10 weeks of age, 10 pounds in weight and haemoglobin of 10 g per dL"], "key": "E", "type": "sba", "explanation": "The rule of tens is 10 weeks of age, 10 pounds in weight and a haemoglobin of 10 grams per decilitre. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 934, "page": 167, "stem": "At what age is alveolar bone grafting performed?", "options": ["3 to 6 months", "6 to 12 months", "14 to 16 years", "8 to 10 years", "After growth is complete"], "key": "D", "type": "sba", "explanation": "Alveolar bone grafting is performed at 8 to 10 years, before the canine erupts, when about two thirds of its root is formed. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 935, "page": 167, "stem": "Alveolar bone grafting should be performed at what stage of canine root development?", "options": ["Before root formation begins", "When about two thirds of the root is formed", "After the root is complete", "After the canine has erupted", "Root development is irrelevant"], "key": "B", "type": "sba", "explanation": "The graft is placed before the canine erupts, when approximately two thirds of its root is formed, so that the canine erupts into grafted bone. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 936, "page": 167, "stem": "Which is the correct sequence of arch expansion and alveolar bone grafting?", "options": ["Graft first, then expand", "Expansion is contraindicated in clefts", "Both simultaneously in all cases", "Neither is required", "Expand first, then graft"], "key": "E", "type": "sba", "explanation": "Expand before grafting: the graft needs access and the arch needs form. (Mosby ch. on clefts; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 937, "page": 167, "stem": "Which bone is most commonly used for an alveolar bone graft?", "options": ["Cortical bone from the mandible", "Cancellous bone from the iliac crest", "Calvarial bone", "Rib", "Synthetic substitute only"], "key": "B", "type": "sba", "explanation": "Cancellous bone, usually harvested from the iliac crest, is the standard graft material. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 938, "page": 168, "stem": "Which of the following is not a purpose of alveolar bone grafting?", "options": ["Providing bone for the canine to erupt into", "Stabilising the maxillary segments", "Closing the oronasal fistula", "Correcting the skeletal Class III relationship", "Supporting the alar base"], "key": "D", "type": "sba", "explanation": "The graft does not correct a skeletal Class III relationship; that requires orthognathic surgery once growth is complete. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 939, "page": 168, "stem": "Which dental anomaly is commonest in a patient with a unilateral cleft lip and palate?", "options": ["A missing lateral incisor on the cleft side", "An additional premolar", "A missing first molar", "An impacted second molar", "Macrodontia of the central incisor"], "key": "A", "type": "sba", "explanation": "The missing lateral incisor on the cleft side is the commonest anomaly, alongside supernumerary and malformed teeth, often on both sides of the cleft. (Companion Ch 16; Hbk 28.3)", "answerPage": 232, "block": "AB"}, {"n": 940, "page": 168, "stem": "The central incisor adjacent to a cleft is characteristically which of the following?", "options": ["Absent", "Macrodont", "Rotated and tipped towards the cleft, and often hypoplastic", "In crossbite only", "Unaffected"], "key": "C", "type": "sba", "explanation": "The central incisor adjacent to the cleft is characteristically rotated and tipped towards the cleft, and is often hypoplastic. (Companion Ch 16; Hbk 28.3)", "answerPage": 232, "block": "AB"}, {"n": 941, "page": 168, "stem": "Dental anomalies in clefting are more common in which group?", "options": ["Unilateral cases", "Submucous clefts", "Isolated cleft palate", "Bilateral cases", "They occur equally in all groups"], "key": "D", "type": "sba", "explanation": "Dental anomalies are commoner in bilateral cases. (Cobourne cases; Hbk 28.3)", "answerPage": 232, "block": "AB"}, {"n": 942, "page": 168, "stem": "Glue ear in cleft palate patients requires which single measure?", "options": ["No intervention", "Hearing monitoring, with grommets as required", "Immediate antibiotics", "Adenoidectomy", "Tonsillectomy"], "key": "B", "type": "sba", "explanation": "Hearing must be monitored, since middle ear effusion is near-universal in cleft palate, and grommets are inserted as required. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 943, "page": 168, "stem": "Velopharyngeal incompetence after palate repair may require which procedure?", "options": ["A second palate repair only", "Adenoidectomy", "Alveolar bone grafting", "Le Fort I osteotomy", "A pharyngoplasty"], "key": "E", "type": "sba", "explanation": "Velopharyngeal incompetence may require a pharyngoplasty, following speech assessment and therapy. (Companion Ch 16; Hbk 28.2)", "answerPage": 232, "block": "AB"}, {"n": 944, "page": 168, "stem": "Which single feature distinguishes Apert from Crouzon syndrome?", "options": ["Syndactyly of the hands and feet", "Craniosynostosis", "Midface hypoplasia", "Exophthalmos", "Relative mandibular prognathism"], "key": "A", "type": "sba", "explanation": "Both involve FGFR2 mutations with craniosynostosis and midface hypoplasia. Syndactyly distinguishes Apert. (Companion Ch 16; Hbk 28.4)", "answerPage": 232, "block": "AB"}, {"n": 945, "page": 169, "stem": "Pierre Robin is correctly described as which of the following?", "options": ["A syndrome", "An association", "A sequence, in which micrognathia causes glossoptosis and a U-shaped cleft palate", "A dysplasia", "A malformation of unknown origin"], "key": "C", "type": "sba", "explanation": "Pierre Robin is a sequence: the small mandible causes the glossoptosis and the cleft palate, and airway obstruction is the principal early concern. (Companion Ch 16; Hbk 28.4)", "answerPage": 232, "block": "AB"}, {"n": 946, "page": 169, "stem": "Treacher Collins syndrome is caused by a mutation in which gene?", "options": ["FGFR2", "TCOF1", "RUNX2", "PTH1R", "MSX1"], "key": "B", "type": "sba", "explanation": "Treacher Collins syndrome results from TCOF1 mutation, and is autosomal dominant. (Companion Ch 16; Hbk 28.4)", "answerPage": 232, "block": "AB"}, {"n": 947, "page": 169, "stem": "Which combination is characteristic of Treacher Collins syndrome?", "options": ["Upward-sloping palpebral fissures and mandibular prognathism", "Syndactyly and craniosynostosis", "Absent clavicles and supernumerary teeth", "Downward-sloping palpebral fissures, malar and mandibular hypoplasia, ear anomalies and conductive deafness", "Macroglossia and midface hypoplasia"], "key": "D", "type": "sba", "explanation": "Downward-sloping palpebral fissures, malar and mandibular hypoplasia, ear anomalies and conductive deafness are characteristic, with cleft palate in about 30 per cent. (Companion Ch 16; Hbk 28.4)", "answerPage": 232, "block": "AB"}, {"n": 948, "page": 169, "stem": "Cleidocranial dysplasia characteristically produces which dental features?", "options": ["Multiple supernumerary teeth and failure of eruption of permanent teeth", "Hypodontia and conical teeth", "Macrodontia and early eruption", "Anodontia", "Amelogenesis imperfecta"], "key": "A", "type": "sba", "explanation": "Cleidocranial dysplasia, from RUNX2 mutation, produces multiple supernumeraries and failure of eruption, along with absent or hypoplastic clavicles and delayed fontanelle closure. (Companion Ch 16; Hbk 28.4)", "answerPage": 232, "block": "AB"}, {"n": 949, "page": 169, "stem": "Which classification is used for the mandibular ramus in hemifacial microsomia?", "options": ["Obwegeser and Makek", "Veau", "Pruzansky", "Slootweg and Muller", "Angle"], "key": "C", "type": "sba", "explanation": "The Pruzansky classification grades the mandibular ramus in hemifacial microsomia. (Companion Ch 16; Hbk 28.4)", "answerPage": 233, "block": "AB"}, {"n": 950, "page": 169, "stem": "Which additional features distinguish Goldenhar syndrome from isolated hemifacial microsomia?", "options": ["Cleft palate and hearing loss", "Multiple supernumeraries", "Syndactyly and craniosynostosis", "Absent clavicles", "Epibulbar dermoid and vertebral anomalies"], "key": "E", "type": "sba", "explanation": "Epibulbar dermoid and vertebral anomalies distinguish Goldenhar from isolated hemifacial microsomia. (Companion Ch 16; Hbk 28.4)", "answerPage": 233, "block": "AB"}, {"n": 951, "page": 169, "stem": "Which is the correct distinction between a Turner tooth and Turner syndrome?", "options": ["A Turner tooth is a localised enamel hypoplasia caused by infection or trauma to the primary predecessor; Turner syndrome is 45,X", "They are the same condition", "A Turner tooth occurs only in Turner syndrome", "Turner syndrome causes Turner teeth in all cases", "Both are caused by RUNX2 mutation"], "key": "A", "type": "sba", "explanation": "Examiners use both terms in the same paper. A Turner tooth is a localised hypoplasia; Turner syndrome is a chromosomal disorder. (Companion Ch 16; Hbk 28.4)", "answerPage": 233, "block": "AB"}, {"n": 952, "page": 170, "stem": "Which craniofacial features are characteristic of Down syndrome?", "options": ["Maxillary excess and mandibular retrognathia", "Craniosynostosis and syndactyly", "Midface hypoplasia, relative mandibular prognathism, macroglossia, hypodontia and delayed eruption", "Absent clavicles", "Downward-sloping palpebral fissures with malar hypoplasia"], "key": "C", "type": "sba", "explanation": "Midface hypoplasia with relative mandibular prognathism, macroglossia, hypodontia, delayed eruption and periodontal disease are characteristic, alongside cardiac anomalies. (Companion Ch 16; Hbk 28.4)", "answerPage": 233, "block": "AB"}, {"n": 953, "page": 170, "stem": "The 22q11 deletion syndrome characteristically includes which feature?", "options": ["Absent clavicles", "Epibulbar dermoid", "Syndactyly", "Multiple supernumeraries", "Cleft palate or velopharyngeal incompetence with cardiac anomalies and learning difficulties"], "key": "E", "type": "sba", "explanation": "The 22q11 deletion, also known as DiGeorge or velocardiofacial syndrome, includes cleft palate or velopharyngeal incompetence, cardiac anomalies, a characteristic facies and learning difficulties. (Companion Ch 16; Hbk 28.4)", "answerPage": 233, "block": "AB"}, {"n": 954, "page": 170, "stem": "The Veau classification of clefts uses how many classes?", "options": ["Two", "Four", "Three", "Five", "Six"], "key": "B", "type": "sba", "explanation": "Veau described four classes: soft palate only, soft and hard palate, unilateral complete lip and palate, and bilateral complete. (Companion Ch 16; Hbk Part 2 Card 5)", "answerPage": 233, "block": "AB"}, {"n": 955, "page": 170, "stem": "The LAHSHAL notation records which structures?", "options": ["The nasal structures only", "Lip and palate only", "The dental arches only", "Lip, alveolus, hard palate and soft palate on both sides", "The velopharyngeal mechanism"], "key": "D", "type": "sba", "explanation": "LAHSHAL records lip, alveolus, hard palate and soft palate on both sides, giving a reproducible description of the cleft. (Companion Ch 16; Hbk Part 2 Card 5)", "answerPage": 233, "block": "AB"}, {"n": 956, "page": 170, "stem": "Which single organisational change measurably improved cleft outcomes?", "options": ["Introduction of presurgical orthopaedics", "Earlier lip repair", "Centralisation of cleft care into multidisciplinary teams with national audit", "Use of resorbable sutures", "Introduction of CBCT"], "key": "C", "type": "sba", "explanation": "Centralisation of cleft care with multidisciplinary team working and national audit measurably improved outcomes. (Companion Ch 16; Hbk 28.2)", "answerPage": 233, "block": "AB"}, {"n": 957, "page": 170, "stem": "Orthognathic surgery in a cleft patient is characteristically required for which problem?", "options": ["Maxillary hypoplasia", "Mandibular prognathism", "Transverse mandibular excess", "Vertical maxillary excess", "An anterior open bite alone"], "key": "A", "type": "sba", "explanation": "Maxillary hypoplasia is common in cleft patients, and distraction osteogenesis is used for large advancements. (Companion Ch 16; Hbk 28.2)", "answerPage": 233, "block": "AB"}, {"n": 958, "page": 170, "stem": "Retention in the cleft patient is characteristically which of the following?", "options": ["Not required", "Required only in bilateral cases", "Six weeks", "Twelve months", "Prolonged, and usually permanent"], "key": "E", "type": "sba", "explanation": "Retention is prolonged and permanent retention is usual, because of scarring, the transverse deficiency and the tendency to relapse. (Companion Ch 16; Hbk 28.3)", "answerPage": 233, "block": "AB"}, {"n": 959, "page": 171, "stem": "Presurgical orthopaedics, including naso-alveolar moulding, is best described in which way?", "options": ["Standard of care in all centres with strong evidence", "Performed after palate repair", "Contraindicated", "Used in some centres, with contested evidence", "Performed at 8 to 10 years"], "key": "D", "type": "sba", "explanation": "Presurgical orthopaedics is used in some centres but the evidence remains contested. (Companion Ch 16; Hbk 28.2)", "answerPage": 233, "block": "AB"}, {"n": 960, "page": 171, "stem": "Which is the approximate risk of an orofacial cleft where one parent and one sibling are affected?", "options": ["Unchanged from the population risk", "Substantially increased above the population risk, rising with the number of affected relatives", "Reduced", "100 per cent", "Only relevant in isolated cleft palate"], "key": "B", "type": "sba", "explanation": "Recurrence risk rises with the number of affected relatives, reflecting the multifactorial aetiology. (Companion Ch 16; Hbk 28.1)", "answerPage": 233, "block": "AB"}, {"n": 961, "page": 171, "stem": "Which maternal exposure is associated with an increased risk of orofacial clefting?", "options": ["Folic acid", "Calcium supplementation", "Vitamin C", "Iron supplementation", "Maternal smoking"], "key": "E", "type": "sba", "explanation": "Maternal smoking, alcohol, folate deficiency, anticonvulsants, retinoids, corticosteroids and maternal diabetes all increase risk; folic acid reduces it. (Companion Ch 16; Hbk 28.1)", "answerPage": 233, "block": "AB"}, {"n": 962, "page": 172, "stem": "Which benefit of orthodontic treatment has the strongest evidence?", "options": ["Improved periodontal health", "Dental aesthetics and trauma prevention", "Reduced caries", "Improved speech", "Improved masticatory efficiency"], "key": "B", "type": "sba", "explanation": "Dental aesthetics and trauma prevention have strong evidence. Periodontal health, caries, speech and mastication all require qualifiers. (Companion Ch 2; Hbk 29.1)", "answerPage": 233, "block": "AC"}, {"n": 963, "page": 172, "stem": "The evidence that orthodontic treatment improves periodontal health is best described how?", "options": ["Strong", "Conclusive for adults only", "Moderate", "Weak or absent", "Conclusive for children only"], "key": "D", "type": "sba", "explanation": "Bollen and Papageorgiou found a lack of evidence that orthodontic treatment improves periodontal health. (Bollen 2008; Hbk 29.1)", "answerPage": 233, "block": "AC"}, {"n": 964, "page": 172, "stem": "The evidence that orthodontic treatment reduces caries is best described how?", "options": ["Weak", "Strong", "Moderate", "Conclusive", "Absent for all age groups"], "key": "A", "type": "sba", "explanation": "Macey found weak evidence that crowding is a caries risk factor or that treatment reduces later caries incidence. (Macey 2020; Hbk 29.1)", "answerPage": 233, "block": "AC"}, {"n": 965, "page": 172, "stem": "Which four risks should be named when discussing complications of orthodontic treatment?", "options": ["Pain, breakage, cost and time", "Ankylosis, impaction, transposition and infection", "Demineralisation, root resorption, recession and relapse", "Caries, periodontal disease, halitosis and staining", "Allergy, ulceration, bleeding and swelling"], "key": "C", "type": "sba", "explanation": "Demineralisation, root resorption, recession and relapse are the four that Cobourne’s cases specify. (Cobourne cases; Hbk 29.2)", "answerPage": 233, "block": "AC"}, {"n": 966, "page": 172, "stem": "Orthodontic pain peaks at approximately what interval after appliance activation?", "options": ["6 hours", "10 days", "5 days", "48 hours", "It does not peak"], "key": "D", "type": "sba", "explanation": "Pain peaks at 48 hours and returns to baseline by 7 days. Analgesics may be taken preemptively. (Monk 2017; Hbk 29.2)", "answerPage": 233, "block": "AC"}, {"n": 967, "page": 173, "stem": "Which analgesic is generally preferred during orthodontic treatment?", "options": ["Ibuprofen", "Paracetamol", "Aspirin", "Diclofenac", "Codeine"], "key": "B", "type": "sba", "explanation": "Paracetamol is generally preferred, since prostaglandin inhibitors may slow tooth movement, although the effect is small and clinically debated. (Proffit Ch 8; Hbk 29.2)", "answerPage": 233, "block": "AC"}, {"n": 968, "page": 173, "stem": "Severe root resorption affects approximately what proportion of treated teeth?", "options": ["Under 0.5 per cent", "Over 30 per cent", "10 per cent", "20 per cent", "1 to 5 per cent"], "key": "E", "type": "sba", "explanation": "Sameshima and Sinclair reported severe root resorption in 1 to 5 per cent of treated teeth, greatest in the anterior maxilla. (Sameshima and Sinclair 2004; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 969, "page": 173, "stem": "Which single risk factor should be identified before treatment because it increases the likelihood of severe root resorption?", "options": ["Previous trauma or previously identified resorption", "A Class II molar relationship", "A deep overbite", "Poor oral hygiene", "A high mandibular plane angle"], "key": "A", "type": "sba", "explanation": "Previous trauma and previously identified resorption are among the factors that should be identified before treatment, alongside abnormal root morphology. (Companion Ch 6; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 970, "page": 173, "stem": "Gingival hyperplasia during fixed appliance treatment is best managed how?", "options": ["Immediate excision", "Debonding immediately", "Oral hygiene measures, with excision reserved for persistence after debond", "Antibiotics", "Chlorhexidine indefinitely"], "key": "C", "type": "sba", "explanation": "Gingival hyperplasia is common with poor hygiene and usually recovers after debond, so excision is reserved for persistent cases. (Companion Ch 2; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 971, "page": 173, "stem": "NICE guidance on antibiotic prophylaxis for dental procedures states which of the following?", "options": ["It should be given to all patients with a heart murmur", "It should not routinely be provided solely to prevent infective endocarditis", "It should be given for band placement only", "It should be given for all extractions", "It should be given to all children"], "key": "B", "type": "sba", "explanation": "NICE advises against routine antibiotic prophylaxis solely to prevent infective endocarditis, although this conflicts with AHA and ESC guidance for the highest-risk patients. (NICE; Thornhill 2016; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 972, "page": 173, "stem": "Mortality from infective endocarditis is approximately which value?", "options": ["2 per cent", "8 per cent", "45 per cent", "21 per cent", "70 per cent"], "key": "D", "type": "sba", "explanation": "Mortality from infective endocarditis is approximately 21 per cent, which is why the NICE position remains contested. (Companion Ch 7; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 973, "page": 173, "stem": "Which appliance type should be avoided in a patient with epilepsy?", "options": ["Removable appliances", "Fixed labial appliances", "Bonded retainers", "Transpalatal arches", "Aligners"], "key": "A", "type": "sba", "explanation": "Removable appliances should be avoided in epilepsy because of the risk of displacement and inhalation during a seizure. (Companion Ch 7; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 974, "page": 174, "stem": "A patient taking phenytoin, or one who has undergone organ transplantation, is best managed with which appliance feature?", "options": ["Bands on all molars", "A palatal arch", "Bonded tubes rather than bands", "A removable appliance", "Aligners exclusively"], "key": "C", "type": "sba", "explanation": "Gingival hyperplasia associated with phenytoin and with transplant immunosuppression makes bonded tubes preferable to bands. (Companion Ch 7; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 975, "page": 174, "stem": "Which appliance feature should be avoided in a patient with asthma?", "options": ["Bonded tubes", "A bonded retainer", "A fixed labial appliance", "A transpalatal arch", "A palate-covering removable appliance"], "key": "E", "type": "sba", "explanation": "Palate-covering removable appliances should be avoided in asthma. (Companion Ch 7; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 976, "page": 174, "stem": "Bisphosphonate therapy has which effect on orthodontic tooth movement?", "options": ["It slows or inhibits tooth movement and delays eruption", "It accelerates tooth movement", "It has no effect", "It increases the risk of relapse only", "It increases the rate of eruption"], "key": "A", "type": "sba", "explanation": "Zymperdikas found that bisphosphonates slow or inhibit tooth movement and delay eruption. Aims should be kept simple and stopping the drug does not help. (Zymperdikas 2020; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 977, "page": 174, "stem": "Which single change should be made in a patient with sickle cell disease?", "options": ["Avoid all orthodontic treatment", "Use heavier forces to shorten treatment", "Use light forces and avoid extractions where possible", "Use only removable appliances", "Prescribe antibiotic prophylaxis"], "key": "C", "type": "sba", "explanation": "Light forces and avoidance of extractions where possible are appropriate in sickle cell disease, thalassaemia, childhood malignancy and diabetes. (Companion Ch 7; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 978, "page": 174, "stem": "How long should elective orthodontic treatment be deferred after organ transplantation?", "options": ["2 weeks", "3 months", "Indefinitely", "2 years", "At least 6 months"], "key": "E", "type": "sba", "explanation": "Elective orthodontic treatment should be deferred for at least 6 months after transplantation, and until malignancy is in remission. (Companion Ch 7; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 979, "page": 174, "stem": "A patient with a documented nickel allergy should avoid which material?", "options": ["Stainless steel", "Nickel titanium", "Beta titanium", "Cobalt chromium after heat treatment", "Elastomeric modules"], "key": "B", "type": "sba", "explanation": "Nickel titanium should be avoided. Stainless steel is safe because the nickel is bound within the austenitic lattice. (Chakravarthi 2012; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 980, "page": 174, "stem": "Which single statement about orthodontic treatment during pregnancy is correct?", "options": ["It is absolutely contraindicated", "Radiographs are contraindicated in all circumstances", "It should proceed unchanged", "Elective treatment should be deferred, with urgent care provided ideally in the second trimester", "Fixed appliances must be removed"], "key": "D", "type": "sba", "explanation": "Elective treatment is deferred. Where urgent care is required, the second trimester is preferred, and radiographs are taken only where justified. (Companion Ch 7; Hbk 29.3)", "answerPage": 234, "block": "AC"}, {"n": 981, "page": 175, "stem": "Which single measure most reduces the risk of demineralisation during fixed appliance treatment?", "options": ["Chlorhexidine mouthwash", "Fluoride varnish at debond only", "Selecting patients on the basis of demonstrated plaque control, and not starting until it is adequate", "Using ceramic brackets", "Shortening the archwire sequence"], "key": "C", "type": "sba", "explanation": "Patient selection and deferral until hygiene is adequate is the single most effective measure, since demineralisation in elective treatment is foreseeable. (Companion Ch 2; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 982, "page": 175, "stem": "Which fluoride regimen is recommended during fixed appliance treatment in a patient at risk?", "options": ["High-fluoride toothpaste at 2800 or 5000 parts per million daily, with professional fluoride every 6 to 8 weeks", "1450 parts per million toothpaste alone", "Fluoride mouthwash weekly", "Fluoride varnish annually", "Silver diamine fluoride monthly"], "key": "A", "type": "sba", "explanation": "Daily high-fluoride toothpaste plus professional high-concentration fluoride every 6 to 8 weeks is the recommended regimen. (Benson 2019; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 983, "page": 175, "stem": "Which single statement about recession and incisor movement is supported by the evidence?", "options": ["Proclination reliably causes recession", "Recession is prevented by bonded retention", "Recession is unrelated to tooth movement", "Recession occurs only in adults", "Recession relates more to retroclination in high-angle Class III cases with a narrow symphysis and thin biotype"], "key": "E", "type": "sba", "explanation": "Joss-Vassalli, Aziz and Tepedino associate recession more with retroclination in highangle Class III cases than with proclination. (Joss-Vassalli 2010; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 984, "page": 175, "stem": "Which is the correct management of white spot lesions identified at debond?", "options": ["Immediate restoration of all affected teeth", "Immediate bleaching", "Immediate microabrasion", "Explain and record, institute intensive prevention, and review over several months before considering restorative intervention", "No action"], "key": "D", "type": "sba", "explanation": "Many early lesions arrest and remineralise superficially. Explanation, recording, intensive prevention and review precede any restorative intervention. (Companion Ch 2; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 985, "page": 175, "stem": "Klaus and colleagues reported high discontinuation rates with which appliance type?", "options": ["Fixed labial appliances", "Removable appliances", "Bonded retainers", "Lingual appliances", "Aligners"], "key": "B", "type": "sba", "explanation": "Klaus reported high discontinuation rates in children and adolescents, especially with removable appliances. (Klaus 2017; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 986, "page": 175, "stem": "Which single statement about headgear safety should be recorded in the notes?", "options": ["That the patient was shown how to fit the appliance", "That the appliance was CE marked", "That the force was measured", "That the patient’s parent was present", "That the patient was warned in writing about injury, given two safety mechanisms, and instructed to stop and attend if the bow disengages"], "key": "E", "type": "sba", "explanation": "The warning, the two mandatory safety mechanisms and the instruction to stop and attend if the bow disengages must all be recorded. (Samuels 1996; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 987, "page": 176, "stem": "Which single statement about enamel loss at debond is correct?", "options": ["No enamel is removed", "Debonding and clean-up removes a small but real thickness of enamel", "All enamel damage is reversible", "Only ceramic brackets remove enamel", "Enamel loss occurs only with self-etching primers"], "key": "B", "type": "sba", "explanation": "A small but real thickness of enamel is lost, which is minimised by using a tungsten carbide bur at low speed and polishing. (Companion Ch 10; Hbk 29.2)", "answerPage": 234, "block": "AC"}, {"n": 988, "page": 176, "stem": "Which single statement about the risk of failing to achieve the treatment aim is correct?", "options": ["It need not be discussed", "It arises only in surgical cases", "It arises only with removable appliances", "It is a real risk that must be consented for, together with what would be done if it occurred", "It is covered by the practice indemnity"], "key": "D", "type": "sba", "explanation": "Failure to achieve the aim is a real and consentable risk, and the discussion should include what would be done in that event. (GDC Standards; Hbk 29.2)", "answerPage": 235, "block": "AC"}, {"n": 989, "page": 176, "stem": "A patient reports a possible allergy to latex. Which single change is required?", "options": ["Latex-free elastics, gloves and rubber dam", "No change", "Avoidance of nickel titanium", "Antibiotic prophylaxis", "Avoidance of fixed appliances"], "key": "A", "type": "sba", "explanation": "Latex-free elastics, gloves and dam are required. Latex allergy affects approximately 4.3 per cent of the general population. (Wu 2016; Hbk 29.3)", "answerPage": 235, "block": "AC"}, {"n": 990, "page": 176, "stem": "Which is the correct statement about orthodontic treatment in a patient with an active eating disorder?", "options": ["Treatment should proceed normally", "Treatment is absolutely contraindicated for life", "Elective treatment should be deferred while the disorder is active, with liaison, prevention and management of erosion", "Only removable appliances may be used", "Antibiotic prophylaxis is required"], "key": "C", "type": "sba", "explanation": "Elective treatment is deferred while the disorder is active, with liaison, preventive care and management of erosion in the interim. (Companion Ch 7; Hbk 29.3)", "answerPage": 235, "block": "AC"}, {"n": 991, "page": 176, "stem": "Which single statement about the psychosocial benefit of orthodontic treatment is most defensible?", "options": ["It reliably improves long-term psychological health", "It benefits only adults", "It has no measurable benefit", "It improves the emotional and social domains of oral health related quality of life, but there is little objective evidence of long-term psychological benefit", "It benefits only patients with severe malocclusion"], "key": "D", "type": "sba", "explanation": "Javidi reported improvement in the emotional and social domains of OHRQoL, while Kenealy found little objective evidence of long-term psychological benefit. (Javidi 2017; Kenealy 2007; Hbk 29.1)", "answerPage": 235, "block": "AC"}, {"n": 992, "page": 177, "stem": "Which is the correct sequence for instrument decontamination?", "options": ["Sterilise, clean, inspect, store", "Clean, inspect, sterilise, store in the sterile pouch, and track by batch to the patient", "Inspect, store, clean, sterilise", "Clean, store, sterilise, inspect", "Sterilise, store, clean, track"], "key": "B", "type": "sba", "explanation": "The sequence is clean, inspect, sterilise, store and track. Cycles must be validated and recorded daily. (Local decontamination guidance; Hbk 30.1)", "answerPage": 235, "block": "AD"}, {"n": 993, "page": 177, "stem": "At what temperature range does a vacuum or non-vacuum autoclave sterilise instruments?", "options": ["100 to 110 degrees Celsius", "121 degrees Celsius only", "160 degrees Celsius", "150 degrees Celsius", "134 to 137 degrees Celsius"], "key": "E", "type": "sba", "explanation": "Steam sterilisation is performed at 134 to 137 degrees Celsius, with daily validation and recording of cycles. (Local decontamination guidance; Hbk 30.1)", "answerPage": 235, "block": "AD"}, {"n": 994, "page": 177, "stem": "Which single statement about single-use items is correct?", "options": ["They must never be reprocessed", "They may be reprocessed if visibly clean", "They may be reprocessed once", "They may be reprocessed if autoclaved", "Reprocessing is permitted for orthodontic bands only"], "key": "A", "type": "sba", "explanation": "Single-use items must never be reprocessed. This includes prophylaxis cups and brushes, saliva ejectors, needles and cartridges. (Local decontamination guidance; Hbk 30.1)", "answerPage": 235, "block": "AD"}, {"n": 995, "page": 177, "stem": "Bands removed from stock during band sizing should be managed how?", "options": ["Returned to stock after wiping", "Returned to stock after autoclaving", "Not returned to stock; a band-sizing kit sterilised between patients should be used", "Discarded only if fitted", "Returned to stock if not fitted"], "key": "C", "type": "sba", "explanation": "Bands removed from stock cannot be returned. A dedicated band-sizing kit, sterilised between patients, is used instead. (Local decontamination guidance; Hbk 30.1)", "answerPage": 235, "block": "AD"}, {"n": 996, "page": 177, "stem": "Impressions and appliances returning from the laboratory should be managed how?", "options": ["Fitted directly", "Rinsed, disinfected and labelled before dispatch and on receipt, with the process documented", "Autoclaved", "Discarded and remade", "No action is required"], "key": "B", "type": "sba", "explanation": "Impressions and appliances must be rinsed, disinfected and labelled both before dispatch and on receipt, and the process documented. (Local decontamination guidance; Hbk 30.1)", "answerPage": 235, "block": "AD"}, {"n": 997, "page": 177, "stem": "Which single procedure in orthodontics generates significant aerosol?", "options": ["Archwire placement", "Elastic module placement", "Impression taking", "Debonding and adhesive clean-up", "Study cast trimming in the surgery"], "key": "D", "type": "sba", "explanation": "Debonding and clean-up generate aerosol, requiring high-volume aspiration and eye protection for both patient and operator. (Local decontamination guidance; Hbk 30.1)", "answerPage": 235, "block": "AD"}, {"n": 998, "page": 178, "stem": "Cut archwire ends should be regarded as which category?", "options": ["Sharps", "Clinical waste", "Domestic waste", "Recyclable metal", "Amalgam waste"], "key": "A", "type": "sba", "explanation": "Wire ends are sharps. A distal end cutter that retains the fragment should be used and every wire end accounted for. (Local decontamination guidance; Hbk 30.1)", "answerPage": 235, "block": "AD"}, {"n": 999, "page": 178, "stem": "The three principles governing every radiographic exposure are which of the following?", "options": ["Referral, consent and record keeping", "Indication, exposure and reporting", "Justification, optimisation and limitation", "Frequency, dose and duration", "Screening, diagnosis and audit"], "key": "C", "type": "sba", "explanation": "Justification for the individual patient, optimisation of dose and limitation of the number of exposures govern every radiograph. (Companion Ch 7; Hbk 30.2)", "answerPage": 235, "block": "AD"}, {"n": 1000, "page": 178, "stem": "Which single statement about radiation dose is correct?", "options": ["There is a safe threshold dose below which no risk exists", "Only CBCT carries a measurable risk", "Doses below 1 mSv carry no risk", "Children may receive higher doses safely", "Stochastic risk means there is no threshold dose, only a justified exposure"], "key": "E", "type": "sba", "explanation": "Stochastic risk means there is no safe threshold. Every exposure must be individually justified. (Companion Ch 7; Hbk 30.2)", "answerPage": 235, "block": "AD"}, {"n": 1001, "page": 178, "stem": "Which named role justifies a radiographic exposure?", "options": ["The practitioner", "The referrer", "The operator", "The legal person", "The dental nurse"], "key": "A", "type": "sba", "explanation": "The practitioner justifies the exposure, the referrer requests it, the operator carries it out, and the legal person holds overall responsibility. (Ionising radiation regulations; Hbk 30.2)", "answerPage": 235, "block": "AD"}, {"n": 1002, "page": 178, "stem": "Which single record must accompany every radiograph taken?", "options": ["The exposure time only", "The manufacturer of the equipment", "A written justification and a report on the film", "The patient’s consent form", "The batch number of the receptor"], "key": "C", "type": "sba", "explanation": "Both the justification and the report must be recorded. A radiograph taken is a radiograph that must be reported. (Companion Ch 7; Hbk 30.2)", "answerPage": 235, "block": "AD"}, {"n": 1003, "page": 178, "stem": "Which single element of the consent discussion must be recorded?", "options": ["The time the appointment started", "The next appointment date", "The bracket prescription", "The archwire size", "What was discussed, what was warned about, what was given in writing, who was present, and that the patient agreed"], "key": "E", "type": "sba", "explanation": "A signed form is evidence of consent, not consent itself. The content of the discussion must be recorded. (GDC Standards; Hbk 30.3)", "answerPage": 235, "block": "AD"}, {"n": 1004, "page": 178, "stem": "Which items should be recorded at every routine orthodontic adjustment visit?", "options": ["The patient’s mood only", "What was done, wire sizes and sequence, elastics prescribed, oral hygiene status, breakages, instructions given and the next interval", "The name of the nurse only", "The room used", "The fee charged only"], "key": "B", "type": "sba", "explanation": "Contemporaneous notes must record the clinical detail, the hygiene status, breakages, instructions and the appointment interval. (GDC Standards; Hbk 30.3)", "answerPage": 235, "block": "AD"}, {"n": 1005, "page": 179, "stem": "Which outcome measure is most appropriate for auditing an orthodontic service across many cases?", "options": ["Patient satisfaction alone", "Treatment duration alone", "IOTN Dental Health Component", "PAR or ICON scores", "Number of appointments"], "key": "D", "type": "sba", "explanation": "PAR or ICON is used to audit an operator or service over many cases. IOTN measures need, not outcome. (Companion Ch 2; Hbk 30.3)", "answerPage": 235, "block": "AD"}, {"n": 1006, "page": 179, "stem": "Which of the following should form part of an orthodontic practice audit?", "options": ["Staff attendance", "The number of new patients only", "Failure and breakage rates, decalcification rates, treatment duration, discontinuation rates and radiograph rejects", "Stock levels", "Appointment book utilisation only"], "key": "C", "type": "sba", "explanation": "Clinical audit covers case outcomes, failure and breakage rates, decalcification, duration, discontinuation, radiograph rejects and decontamination records. (GDC Standards; Hbk 30.3)", "answerPage": 235, "block": "AD"}, {"n": 1007, "page": 179, "stem": "Which case type should a Diploma holder normally refer rather than treat?", "options": ["A severe skeletal discrepancy where surgery is likely", "A Class I case with 5 mm of crowding", "An anterior crossbite with a displacement in a child", "A simple posterior crossbite", "A mild Class II division 1 in a growing child"], "key": "A", "type": "sba", "explanation": "Severe skeletal discrepancies, likely surgical cases, complex impactions, cleft and craniofacial cases, significant asymmetry, severe hypodontia and reduced periodontium cases should be referred. (Hbk 30.4)", "answerPage": 236, "block": "AD"}, {"n": 1008, "page": 179, "stem": "Which single statement demonstrates judgement most effectively in an oral examination?", "options": ["Describing the most sophisticated available technique", "Avoiding any mention of limits", "Quoting the largest number of references", "Describing the appliance in the greatest detail", "Stating what you would treat yourself and the point at which you would refer"], "key": "E", "type": "sba", "explanation": "Volunteering the boundary before being asked is the single most reliable way of demonstrating judgement. (Hbk 30.4 and Part 5)", "answerPage": 236, "block": "AD"}, {"n": 1009, "page": 179, "stem": "Which single element must be recorded at the assessment visit?", "options": ["The appointment interval", "The bracket prescription to be used", "The laboratory to be used", "The complaint in the patient’s own words", "The archwire sequence"], "key": "D", "type": "sba", "explanation": "The complaint in the patient’s own words, the history, the examination in three planes, IOTN, the provisional problem list and the records justified and taken must all be recorded. (GDC Standards; Hbk 30.3)", "answerPage": 236, "block": "AD"}, {"n": 1010, "page": 179, "stem": "Which single item should be recorded when a plan changes materially during treatment?", "options": ["Nothing, provided the outcome is achieved", "The reason for the change and evidence that the consent discussion was revisited", "The date only", "The new appliance only", "The patient’s verbal agreement without detail"], "key": "B", "type": "sba", "explanation": "A material change of plan requires the consent discussion to be repeated and both the reason and the discussion recorded. (GDC Standards; Hbk 30.3)", "answerPage": 236, "block": "AD"}, {"n": 1011, "page": 179, "stem": "Which single measure protects against Legionella in dental unit water lines?", "options": ["Annual autoclaving", "No measure is required", "Boiling the water supply", "Using bottled water only for impressions", "Flushing, water treatment and monitoring in accordance with local guidance, with a risk assessment"], "key": "E", "type": "sba", "explanation": "Dental unit water lines require flushing, treatment and monitoring in line with local guidance, with a Legionella risk assessment. (Local decontamination guidance; Hbk 30.1)", "answerPage": 236, "block": "AD"}, {"n": 1012, "page": 180, "stem": "Which waste streams must be segregated in an orthodontic practice?", "options": ["Clinical and domestic only", "Clinical, sharps, amalgam and domestic", "Sharps only", "Amalgam only", "No segregation is required"], "key": "B", "type": "sba", "explanation": "Clinical, sharps, amalgam and domestic waste must be segregated, with consignment notes retained. (Local decontamination guidance; Hbk 30.1)", "answerPage": 236, "block": "AD"}, {"n": 1013, "page": 180, "stem": "Intra-oral scanner wands should be managed between patients how?", "options": ["Wiped only", "Immersed in disinfectant", "Autoclaved whole", "A disposable or sterilisable tip sleeve should be used and the wand wiped between patients", "No measure is required"], "key": "D", "type": "sba", "explanation": "A disposable or sterilisable tip sleeve is used and the wand wiped between patients, in accordance with the manufacturer’s instructions. (Local decontamination guidance; Hbk 30.1)", "answerPage": 236, "block": "AD"}, {"n": 1014, "page": 180, "stem": "Which single record should be made at debond?", "options": ["Final records, the retention issued, the instructions given and the review arranged", "The bracket prescription used", "The number of visits only", "The total fee", "The archwire sequence used"], "key": "A", "type": "sba", "explanation": "Final records, retention issued, instructions given and review arranged must all be recorded at debond. (GDC Standards; Hbk 30.3)", "answerPage": 236, "block": "AD"}, {"n": 1015, "page": 180, "stem": "Which single statement about a radiograph quality assurance programme is correct?", "options": ["It is optional", "It applies only to CBCT", "It should include audit of rejected films, staff training and dose monitoring", "It applies only in hospital settings", "It is required only every five years"], "key": "C", "type": "sba", "explanation": "A quality assurance programme with reject audit, staff training and dose monitoring is required. (Ionising radiation regulations; Hbk 30.2)", "answerPage": 236, "block": "AD"}, {"n": 1016, "page": 180, "stem": "Which is the correct approach where a Diploma holder identifies a case beyond their competence mid-treatment?", "options": ["Continue and hope for the best", "Refer without informing the patient", "Debond and discharge without explanation", "Stop, explain to the patient, record the discussion and refer", "Complete the treatment and refer at debond"], "key": "D", "type": "sba", "explanation": "Recognising the limit, explaining it, recording the discussion and referring is the required response, and it is what the examiners are testing. (GDC Standards; Hbk 30.4)", "answerPage": 236, "block": "AD"}], "blocks": [{"id": "A", "title": "Concepts of growth and development", "start": 1, "end": 25}, {"id": "B", "title": "Craniofacial growth, prenatal and postnatal", "start": 26, "end": 55}, {"id": "C", "title": "Development of the dentition", "start": 56, "end": 95}, {"id": "D", "title": "The biology of tooth movement, eruption and root resorption", "start": 96, "end": 140}, {"id": "E", "title": "Occlusion, malocclusion and aetiology", "start": 141, "end": 170}, {"id": "F", "title": "Treatment need, indices and epidemiology", "start": 171, "end": 195}, {"id": "G", "title": "Evidence-based orthodontics", "start": 196, "end": 225}, {"id": "H", "title": "Ethics, consent, communication and the psychosocial patient", "start": 226, "end": 255}, {"id": "I", "title": "Clinical examination and records", "start": 256, "end": 285}, {"id": "J", "title": "Imaging and cephalometrics", "start": 286, "end": 325}, {"id": "K", "title": "Study models, space analysis and the digital set-up", "start": 326, "end": 350}, {"id": "L", "title": "Diagnosis, the problem list and treatment planning", "start": 351, "end": 390}, {"id": "M", "title": "Extraction decisions and space management", "start": 391, "end": 430}, {"id": "N", "title": "Biomechanics, force control and anchorage", "start": 431, "end": 481}, {"id": "O", "title": "Orthodontic materials, wires, bonding and instruments", "start": 482, "end": 525}, {"id": "P", "title": "Removable and functional appliances", "start": 526, "end": 566}, {"id": "Q", "title": "Fixed appliances — labial, lingual and aligners", "start": 567, "end": 606}, {"id": "R", "title": "Treatment mechanics: Stage I, II and III", "start": 607, "end": 641}, {"id": "S", "title": "Retention, relapse and stability", "start": 642, "end": 676}, {"id": "T", "title": "Interceptive orthodontics and the developing dentition", "start": 677, "end": 721}, {"id": "U", "title": "Class I malocclusion and bimaxillary protrusion", "start": 722, "end": 746}, {"id": "V", "title": "Class II malocclusion", "start": 747, "end": 786}, {"id": "W", "title": "Class III malocclusion", "start": 787, "end": 816}, {"id": "X", "title": "Transverse problems and facial asymmetry", "start": 817, "end": 841}, {"id": "Y", "title": "Vertical problems: deep bite and open bite", "start": 842, "end": 871}, {"id": "Z", "title": "TMD, condylar trauma, the airway and myofunctional therapy", "start": 872, "end": 901}, {"id": "AA", "title": "Adult orthodontics and orthognathic surgery", "start": 902, "end": 931}, {"id": "AB", "title": "Cleft lip and palate and craniofacial syndromes", "start": 932, "end": 961}, {"id": "AC", "title": "Risks of orthodontic treatment and the medical history", "start": 962, "end": 991}, {"id": "AD", "title": "Orthodontic practice, infection control and governance", "start": 992, "end": 1016}]};